import type { Storage } from '../storage/types';

/**
 * Adapter that persists session and key material in the iOS Keychain / Android
 * Keystore via [`expo-secure-store`](https://docs.expo.dev/versions/latest/sdk/securestore/).
 *
 * `expo-secure-store` is an optional peer dependency; install it in your Expo
 * project with `npx expo install expo-secure-store`.
 *
 * The module is loaded lazily via dynamic `import('expo-secure-store')` so web
 * bundlers strip the dependency from web builds entirely.
 */

/**
 * Minimal structural type for the parts of `expo-secure-store` we use. We
 * type the surface here instead of importing the package's types because the
 * package is an optional peer dependency and may not be installed when this
 * SDK is type-checked (e.g. web-only consumers).
 */
type SecureStoreApi = {
  getItemAsync: (key: string) => Promise<string | null>;
  setItemAsync: (key: string, value: string, options?: { keychainAccessible?: number }) => Promise<void>;
  deleteItemAsync: (key: string) => Promise<void>;
  /**
   * Default we use: requires the device to be unlocked and disables iCloud
   * Keychain backup of the value (so a stolen iCloud backup cannot exfiltrate
   * the SDK's private key material to another device).
   */
  WHEN_UNLOCKED_THIS_DEVICE_ONLY?: number;
};

/**
 * Hard cap per stored value. Generously above what the SDK actually writes
 * (sessions ~ 600-800 bytes, private scalars ~ 43 chars), and well within
 * iOS Keychain's practical limit. Refuses oversized writes loudly rather
 * than letting the platform truncate or silently fail.
 */
export const SECURE_STORE_MAX_VALUE_BYTES = 4096;

/**
 * Map a logical storage key onto one Expo SecureStore accepts. SecureStore keys
 * must match `[A-Za-z0-9._-]`, but the SDK namespaces its keys with `:`
 * (`pollar:<apiKeyHash>:session`, `pollar:dpop-key:<apiKeyHash>`, ...), which
 * SecureStore rejects with an `Invalid key` error. Replace every disallowed
 * character with `_`. The transform is deterministic and collision-free for the
 * SDK's fixed key templates - their only variable segment is a hex hash - so a
 * given logical key always resolves to the same SecureStore key.
 */
export function sanitizeKey(key: string): string {
  return key.replace(/[^A-Za-z0-9._-]/g, '_');
}

export interface SecureStoreAdapterOptions {
  /**
   * Override the iOS Keychain accessibility class. Defaults to
   * `WHEN_UNLOCKED_THIS_DEVICE_ONLY` when available on the loaded module.
   * On Android this is a no-op (the platform manages access via Keystore).
   */
  keychainAccessible?: number;
}

async function loadSecureStore(): Promise<SecureStoreApi> {
  try {
    // @ts-expect-error -- optional peer dep; not present when the SDK is built or
    // when the SDK runs on web. Resolved at runtime in Expo / RN apps.
    const mod = await import('expo-secure-store');
    return mod as unknown as SecureStoreApi;
  } catch (error) {
    const message =
      `[PollarClient:storage] Failed to load 'expo-secure-store'. ` +
      `Install it in your Expo app: \`npx expo install expo-secure-store\`. ` +
      `Original error: ${error instanceof Error ? error.message : String(error)}`;
    throw new Error(message, { cause: error });
  }
}

function utf8ByteLength(value: string): number {
  if (typeof TextEncoder !== 'undefined') return new TextEncoder().encode(value).length;
  // Fallback: count UTF-8 bytes manually for environments without TextEncoder.
  let bytes = 0;
  for (let i = 0; i < value.length; i++) {
    const code = value.charCodeAt(i);
    if (code < 0x80) bytes += 1;
    else if (code < 0x800) bytes += 2;
    else if (code >= 0xd800 && code <= 0xdbff) {
      // Surrogate pair -> 4 bytes; advance the index.
      bytes += 4;
      i++;
    } else bytes += 3;
  }
  return bytes;
}

/**
 * Create a `Storage` adapter backed by Expo SecureStore.
 *
 * Throws (via the returned Promise) at construction time if
 * `expo-secure-store` cannot be loaded.
 */
export async function createSecureStoreAdapter(options: SecureStoreAdapterOptions = {}): Promise<Storage> {
  const SecureStore = await loadSecureStore();

  const accessible =
    options.keychainAccessible !== undefined ? options.keychainAccessible : SecureStore.WHEN_UNLOCKED_THIS_DEVICE_ONLY;

  return {
    async get(key) {
      return SecureStore.getItemAsync(sanitizeKey(key));
    },
    async set(key, value) {
      const size = utf8ByteLength(value);
      if (size > SECURE_STORE_MAX_VALUE_BYTES) {
        throw new Error(
          `[PollarClient:storage] Value for "${key}" is ${size} bytes, exceeds SecureStore limit ${SECURE_STORE_MAX_VALUE_BYTES}`,
        );
      }
      await SecureStore.setItemAsync(
        sanitizeKey(key),
        value,
        accessible !== undefined ? { keychainAccessible: accessible } : undefined,
      );
    },
    async remove(key) {
      await SecureStore.deleteItemAsync(sanitizeKey(key));
    },
  };
}

import type { VisibilityProvider } from '../visibility/types';

/**
 * `AppState`-backed {@link VisibilityProvider} for React Native.
 *
 * Wire it into the silent-refresh scheduler so proactive token renewals are
 * skipped while the app is backgrounded and run the moment it returns to the
 * foreground - matching the web `visibilitychange` behavior and sidestepping
 * RN's aggressive background timer throttling.
 *
 * `react-native` is the consumer's framework (not a dependency of this SDK),
 * so the module is loaded lazily via dynamic `import('react-native')`. That
 * keeps web/Node bundles from ever resolving it. Because loading is async, the
 * factory is async too - mirror the `createSecureStoreAdapter` usage:
 *
 *   import { createAppStateVisibilityProvider } from '@pollar/core/adapters/react-native-appstate';
 *   const visibilityProvider = await createAppStateVisibilityProvider();
 *   new PollarClient({ apiKey, storage, visibilityProvider });
 */

/**
 * Minimal structural type for the slice of `react-native`'s `AppState` we use.
 * Typed here instead of importing the package's types because `react-native`
 * is an optional peer the SDK is not type-checked against.
 */
type AppStateApi = {
  currentState: string;
  addEventListener: (type: 'change', handler: (state: string) => void) => { remove: () => void };
};

async function loadAppState(): Promise<AppStateApi> {
  try {
    const mod = await import('react-native');
    const AppState =
      (mod as { AppState?: AppStateApi }).AppState ?? (mod as { default?: { AppState?: AppStateApi } }).default?.AppState;
    if (!AppState) {
      throw new Error("'react-native' loaded but exposes no AppState export");
    }
    return AppState;
  } catch (error) {
    const message =
      `[PollarClient:visibility] Failed to load 'react-native' AppState. ` +
      `This adapter only runs inside a React Native app. ` +
      `Original error: ${error instanceof Error ? error.message : String(error)}`;
    throw new Error(message, { cause: error });
  }
}

/**
 * Create a `VisibilityProvider` backed by React Native's `AppState`.
 *
 * Throws (via the returned Promise) if `react-native` cannot be loaded.
 */
export async function createAppStateVisibilityProvider(): Promise<VisibilityProvider> {
  const AppState = await loadAppState();

  const isActive = (state: string): boolean => state === 'active';

  return {
    isVisible: () => isActive(AppState.currentState),
    onChange: (cb) => {
      // Filter duplicate notifications - listeners only see real transitions,
      // matching the web provider's contract. RN also emits 'inactive'
      // (iOS transition state) which we collapse into "not visible".
      let last = isActive(AppState.currentState);
      const subscription = AppState.addEventListener('change', (state) => {
        const next = isActive(state);
        if (next !== last) {
          last = next;
          cb(next);
        }
      });
      return () => subscription.remove();
    },
  };
}

import type { Storage } from '../storage/types';

/**
 * Adapter that persists session and key material in the iOS Keychain / Android
 * Keystore via [`react-native-keychain`](https://github.com/oblador/react-native-keychain).
 *
 * `react-native-keychain` is an optional peer dependency; install it in your
 * React Native project with `npm i react-native-keychain` (and follow its
 * iOS pod-install / Android linking instructions).
 *
 * The module is loaded lazily via dynamic `import('react-native-keychain')`
 * so web bundlers strip the dependency from web builds entirely.
 *
 * Storage model: one Keychain `service` per logical key. Each `Storage.set(k, v)`
 * call writes a separate Keychain entry under `service = k`; this keeps the
 * adapter simple but means the number of distinct keys you write should stay
 * bounded (the SDK uses 2-3 keys per `apiKeyHash`).
 */

type KeychainOptions = {
  service?: string;
  accessible?: string;
};

type KeychainCredentials = {
  username: string;
  password: string;
  service: string;
  storage?: string;
};

type KeychainApi = {
  setGenericPassword: (
    username: string,
    password: string,
    options?: KeychainOptions,
  ) => Promise<false | { service: string; storage?: string }>;
  getGenericPassword: (options?: KeychainOptions) => Promise<false | KeychainCredentials>;
  resetGenericPassword: (options?: KeychainOptions) => Promise<boolean>;
  ACCESSIBLE?: Record<string, string | undefined>;
};

/**
 * Hard cap per stored value. iOS Keychain has no formal byte limit but
 * practical limits sit a few KB; we refuse oversized writes loudly.
 */
export const KEYCHAIN_MAX_VALUE_BYTES = 4096;

export interface KeychainAdapterOptions {
  /**
   * Override the iOS Keychain accessibility class. Defaults to
   * `ACCESSIBLE.WHEN_UNLOCKED_THIS_DEVICE_ONLY` when available on the loaded
   * module - that prevents iCloud Keychain backup from carrying the SDK's
   * private key material to another device.
   */
  accessible?: string;
}

async function loadKeychain(): Promise<KeychainApi> {
  try {
    // @ts-expect-error -- optional peer dep; not present when the SDK is built or
    // when the SDK runs on web. Resolved at runtime in React Native apps.
    const mod = await import('react-native-keychain');
    return mod as unknown as KeychainApi;
  } catch (error) {
    const message =
      `[PollarClient:storage] Failed to load 'react-native-keychain'. ` +
      `Install it in your React Native app: \`npm i react-native-keychain\` ` +
      `(plus iOS pod install). Original error: ${error instanceof Error ? error.message : String(error)}`;
    throw new Error(message, { cause: error });
  }
}

function utf8ByteLength(value: string): number {
  if (typeof TextEncoder !== 'undefined') return new TextEncoder().encode(value).length;
  let bytes = 0;
  for (let i = 0; i < value.length; i++) {
    const code = value.charCodeAt(i);
    if (code < 0x80) bytes += 1;
    else if (code < 0x800) bytes += 2;
    else if (code >= 0xd800 && code <= 0xdbff) {
      bytes += 4;
      i++;
    } else bytes += 3;
  }
  return bytes;
}

/**
 * Create a `Storage` adapter backed by `react-native-keychain`.
 *
 * Throws (via the returned Promise) at construction time if the package
 * cannot be loaded.
 */
export async function createKeychainAdapter(options: KeychainAdapterOptions = {}): Promise<Storage> {
  const Keychain = await loadKeychain();

  const accessible: string | undefined =
    options.accessible !== undefined ? options.accessible : Keychain.ACCESSIBLE?.['WHEN_UNLOCKED_THIS_DEVICE_ONLY'];

  function buildOptions(key: string): KeychainOptions {
    const opts: KeychainOptions = { service: key };
    if (accessible !== undefined) opts.accessible = accessible;
    return opts;
  }

  return {
    async get(key) {
      const result = await Keychain.getGenericPassword({ service: key });
      if (result === false) return null;
      return result.password;
    },
    async set(key, value) {
      const size = utf8ByteLength(value);
      if (size > KEYCHAIN_MAX_VALUE_BYTES) {
        throw new Error(
          `[PollarClient:storage] Value for "${key}" is ${size} bytes, exceeds Keychain limit ${KEYCHAIN_MAX_VALUE_BYTES}`,
        );
      }
      // Use the storage key as both the username and the service so a
      // (service, account) lookup is unambiguous on both platforms.
      await Keychain.setGenericPassword(key, value, buildOptions(key));
    },
    async remove(key) {
      await Keychain.resetGenericPassword({ service: key });
    },
  };
}

import createClient from 'openapi-fetch';
import type { paths } from './schema';
import type { PollarRetryConfig } from '../types';
import { PollarNetworkError } from '../types';
import { anySignal, timeoutController } from '../lib/abort';

export type PollarApiClient = ReturnType<typeof createApiClient>;

export interface ApiClientOptions {
  /** Per-attempt timeout in ms. `0`/`undefined` disables the timeout. */
  timeoutMs?: number | undefined;
  /** Retry policy for transport-level failures. */
  retry?: PollarRetryConfig | undefined;
  /**
   * Re-signs a request that is about to be RE-SENT by the transport retry below.
   *
   * A DPoP proof is single-use: the server remembers each `jti` and answers a
   * replay with `SDK_AUTH_DPOP_INVALID` / `jti-replay` (401). A retry built with
   * `request.clone()` carries the very same `DPoP` header, so without this hook
   * the retry of a proof-carrying request is guaranteed to fail - and its 401
   * then looks like an expired token, triggering a pointless refresh.
   *
   * Returns a request with a freshly-minted proof, or `null` when it cannot be
   * signed (no session / no key), in which case the retry is abandoned and the
   * original transport error propagates. Only ever called for GET/HEAD, so it
   * never has to carry a body across.
   */
  resignRetry?: ((request: Request) => Promise<Request | null>) | undefined;
}

const DEFAULT_TIMEOUT_MS = 10_000;
const DEFAULT_ATTEMPTS = 2;
const DEFAULT_BASE_DELAY_MS = 300;

/** `true` for a transport-level failure (timeout / dropped connection) - the
 *  only class of error worth retrying. An HTTP response, even a 5xx, is NOT an
 *  error here: openapi-fetch resolves it, so it never reaches this path. */
function isRetryableTransportError(err: unknown): boolean {
  // A timeout we raised, an AbortError from the timeout signal, or fetch's
  // generic network failure (a `TypeError` like "Network request failed").
  if (err instanceof PollarNetworkError) return true;
  if (err instanceof Error && err.name === 'AbortError') return true;
  if (err instanceof TypeError) return true;
  return false;
}

function backoffDelay(attempt: number, baseDelayMs: number): number {
  // attempt is 1-based; first retry waits ~baseDelayMs, then doubles, with
  // [0.5, 1) jitter so concurrent clients don't retry in lockstep.
  const exp = baseDelayMs * 2 ** (attempt - 1);
  return Math.round(exp * (0.5 + Math.random() * 0.5));
}

/**
 * Run a single fetch bounded by `timeoutMs`, combining the timeout with the
 * request's own abort signal (e.g. a caller's cancellation, or `destroy()`).
 * Rejects with {@link PollarNetworkError} when the timeout - not the caller -
 * fired, so the reason is distinguishable downstream.
 *
 * Exported so the DPoP-nonce retry inside the client (which rebuilds the Request
 * and calls `fetch` directly, bypassing openapi-fetch's configured fetch) gets
 * the same timeout protection.
 */
export async function fetchWithTimeout(request: Request, timeoutMs: number): Promise<Response> {
  if (!timeoutMs || timeoutMs <= 0) return fetch(request);

  const timeout = timeoutController(timeoutMs);
  // Abort the underlying fetch when the timeout (or the caller) fires so a
  // well-behaved runtime frees the socket instead of leaking it.
  const combined = anySignal([request.signal, timeout.signal]);
  const fetchPromise = fetch(request, { signal: combined.signal });

  try {
    // Race the fetch against the timeout. The abort above is the clean path, but
    // some runtimes (older React Native / Hermes fetch polyfills) ignore an
    // `init.signal` override on a Request argument - there the abort never
    // reaches the socket and the promise would hang forever. Racing a rejection
    // GUARANTEES the call settles regardless of how the runtime treats the
    // signal, which is the whole point: a stalled refresh must never trap the
    // caller. (On a runtime that DID honor the abort, the fetch rejection is
    // swallowed below since the race already settled.)
    return await new Promise<Response>((resolve, reject) => {
      fetchPromise.then(resolve, reject);
      const onTimeout = () => reject(new PollarNetworkError(`Request timed out after ${timeoutMs}ms`));
      if (timeout.signal.aborted) onTimeout();
      else timeout.signal.addEventListener('abort', onTimeout);
    });
  } catch (err) {
    // The timeout fired (not the caller's own cancellation) - normalize the
    // failure to a typed, catchable error so callers can branch on the code.
    if (timeout.signal.aborted && !request.signal?.aborted) {
      throw err instanceof PollarNetworkError ? err : new PollarNetworkError(`Request timed out after ${timeoutMs}ms`, err);
    }
    throw err;
  } finally {
    timeout.clear();
    combined.cleanup();
    // If the race settled via the timeout, the aborted fetch will reject shortly
    // after - swallow it so it doesn't surface as an unhandled rejection.
    fetchPromise.catch(() => {});
  }
}

/**
 * The `fetch` openapi-fetch is configured with: each attempt is timeout-bounded
 * by {@link fetchWithTimeout}, and transport failures retry with backoff. The
 * Request is cloned per attempt so a consumed/aborted body can be replayed
 * (a Request body is single-use).
 *
 * Only **idempotent** methods (GET/HEAD) are transparently retried. A
 * transport error (timeout / dropped connection) does not tell us whether the
 * server received and processed the request - only that we did not get the
 * response. Re-sending a POST/PUT/PATCH/DELETE that already landed can duplicate
 * its effect, and for a DPoP-bound request it also replays a single-use proof
 * (same `jti`), which the server rejects with `SDK_AUTH_DPOP_INVALID` /
 * `jti-replay`. So a non-idempotent request is attempted exactly once here; a
 * genuine failure is the caller's to retry (that path rebuilds a fresh proof).
 *
 * The same proof-replay applies to the GET/HEAD retries this function DOES make:
 * a clone copies the `DPoP` header verbatim. So a proof-carrying request is only
 * retried when `resignRetry` can mint a fresh proof for the new attempt;
 * without that hook it is attempted exactly once, like a POST.
 */
function makeRetryingFetch(
  timeoutMs: number,
  retry: Required<PollarRetryConfig>,
  resignRetry?: ApiClientOptions['resignRetry'],
) {
  const attempts = Math.max(1, retry.attempts);
  return async function retryingFetch(request: Request): Promise<Response> {
    const method = request.method.toUpperCase();
    const isIdempotent = method === 'GET' || method === 'HEAD';
    // A replayed proof is a guaranteed 401, so retrying without re-signing would
    // turn a recoverable network blip into an auth failure (and, upstream, into
    // a spurious token refresh).
    const carriesProof = request.headers.has('DPoP');
    const canRetry = isIdempotent && (!carriesProof || resignRetry !== undefined);
    const maxAttempts = canRetry ? attempts : 1;
    // Per-request timeout override (set by slow submit-family calls via the
    // `x-pollar-timeout-ms` header). Read it, then STRIP it so this internal
    // control header never travels to the server. Fall back to the client
    // default when absent or malformed.
    let effectiveTimeoutMs = timeoutMs;
    const timeoutOverride = request.headers.get('x-pollar-timeout-ms');
    if (timeoutOverride !== null) {
      request.headers.delete('x-pollar-timeout-ms');
      const parsed = Number(timeoutOverride);
      if (Number.isFinite(parsed) && parsed > 0) effectiveTimeoutMs = parsed;
    }
    let lastErr: unknown;
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      // Clone before each try (except a single-attempt fetch) so the body
      // survives a re-send; the original stays unconsumed for the next clone.
      let attemptReq = maxAttempts > 1 ? request.clone() : request;
      // Re-sign every attempt after the first: the clone above still carries the
      // proof the previous attempt already spent.
      if (attempt > 1 && carriesProof && resignRetry) {
        const resigned = await resignRetry(attemptReq);
        // Cannot re-sign (session gone, key unavailable): abandon the retry
        // rather than replay stale credentials.
        if (!resigned) throw lastErr;
        attemptReq = resigned;
      }
      try {
        return await fetchWithTimeout(attemptReq, effectiveTimeoutMs);
      } catch (err) {
        lastErr = err;
        // The CALLER aborted (cancellation / destroy) - never retry, propagate.
        if (request.signal?.aborted) throw err;
        // A real HTTP response never lands here; only transport errors do.
        if (!isRetryableTransportError(err) || attempt >= maxAttempts) throw err;
        await new Promise((r) => setTimeout(r, backoffDelay(attempt, retry.baseDelayMs)));
      }
    }
    // Unreachable (the loop returns or throws), but satisfies the type checker.
    throw lastErr;
  };
}

export function createApiClient(baseUrl: string, options: ApiClientOptions = {}) {
  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  const retry: Required<PollarRetryConfig> = {
    attempts: options.retry?.attempts ?? DEFAULT_ATTEMPTS,
    baseDelayMs: options.retry?.baseDelayMs ?? DEFAULT_BASE_DELAY_MS,
  };
  return createClient<paths>({ baseUrl, fetch: makeRetryingFetch(timeoutMs, retry, options.resignRetry) });
}

import type { PollarApiClient } from '../client';
