  api: PollarApiClient,
  providerId?: string,
  corridorId?: string,
  cardProviderId?: string,
): Promise<KycStatusContent> {
  const query = {
    ...(providerId ? { providerId } : {}),
    ...(corridorId ? { corridorId } : {}),
