import { computeJwkThumbprint } from '../../keys/thumbprint';
import { AUTH_ERROR_CODES } from '../../types';
import { isValidSession } from '../session';
import { SessionStatusError, waitForSessionReady } from '../stream';
import { FlowDeps } from './deps';
import { logApiError } from './logging';

export async function authenticate(clientSessionId: string, deps: FlowDeps, expectedWallet?: string): Promise<void> {
  const { api, logger, basePath, useStreaming, signal, setAuthState, storeSession, clearSession, loginTimeoutMs } = deps;

  setAuthState({ step: 'authenticating' });

  try {
    await waitForSessionReady({
      api,
      baseUrl: basePath,
      clientSessionId,
      check: (data) => data?.status === 'READY',
      useStreaming,
      signal,
      logger,
    });
  } catch (err) {
    // Terminal session-status condition (invalid / expired). Reset to an error
    // state and clear any partial session so the user can start a fresh login.
    // Other errors (AbortError from cancelLogin, etc.) bubble to the flow's
    // generic handler unchanged.
    if (err instanceof SessionStatusError) {
      // App-level terminal session status rides on a 2xx stream, so the central
      // HTTP middleware can't classify it - log it here.
      logApiError(logger, 'session status', { data: err });
      const { message, errorCode } =
        err.code === 'LOGIN_TIMEOUT'
          ? { message: 'Login timed out — please try again', errorCode: AUTH_ERROR_CODES.LOGIN_TIMEOUT }
          : err.code === 'EXPIRED_CLIENT_ID'
            ? { message: 'Login session expired — please try again', errorCode: AUTH_ERROR_CODES.SESSION_EXPIRED }
            : { message: 'Login session is no longer valid — please try again', errorCode: AUTH_ERROR_CODES.SESSION_INVALID };
      // Clear the partial session FIRST, then emit the error. clearSession emits
      // `idle`, so emitting the error AFTER makes it the final state a consumer
      // sees - otherwise the error (LOGIN_TIMEOUT / SESSION_EXPIRED / ...) is
      // immediately overwritten by idle and lost.
      await clearSession();
      setAuthState({ step: 'error', previousStep: 'authenticating', message, errorCode });
      return;
    }
    throw err;
  }

  // Pass `dpopJwk` so the server mints DPoP-bound tokens (`cnf.jkt`).
  const dpopJwk = await deps.getPublicJwk();
  // Thumbprint of the JWK we are about to bind - threaded into storeSession so
  // the persisted `dpopJkt` records the key the server actually bound, even if
  // the local key rotates between this bind and the store (see FlowDeps).
  // Best-effort: a thumbprint failure must not fail the login.
  const boundDpopJkt = await computeJwkThumbprint(dpopJwk).catch(() => undefined);
  // HTTP-level `error` is not handled here; the `else` branch below catches
  // both "request failed" (data === undefined) and "request OK but body
  // wasn't a valid session" via the same generic path.
  const body = {
    clientSessionId,
    dpopJwk,
    ...(deps.deviceLabel ? { deviceLabel: deps.deviceLabel } : {}),
  };
  // The login budget, not the client default: this call does the server-side
  // work the rest of the flow only waited for. The header is read and stripped
  // by the transport (see `makeRetryingFetch`), so it never reaches the server.
  const { data, error } = await api.POST('/auth/login', {
    body,
    signal,
    headers: { 'x-pollar-timeout-ms': String(loginTimeoutMs) },
  });

  if (data?.code === 'SDK_LOGIN_SUCCESS' && isValidSession(data?.content, logger)) {
    // `isValidSession` doesn't validate the `data` (PII) subtree, so reach into
    // it defensively - a contract-drifted response missing `data`/`providers`
    // should surface as a clean wallet-mismatch error, not a raw TypeError.
    const sessionWallet = data.content.data?.providers?.wallet?.address;
    if (expectedWallet && sessionWallet !== expectedWallet) {
      // Clear first, then emit error (see the LOGIN_TIMEOUT branch above).
      await clearSession();
      setAuthState({
        step: 'error',
        previousStep: 'authenticating',
        message: 'Wallet mismatch: session wallet does not match connected wallet',
        errorCode: AUTH_ERROR_CODES.WALLET_AUTH_FAILED,
      });
      return;
    }
    // The login was cancelled (cancelLogin) or superseded by a newer attempt
    // (_newController) while POST /auth/login was in flight - its `signal` is now
    // aborted. Don't resurrect `authenticated` over the idle/new state. (The
    // intervening error/clearSession writes above are intentionally NOT guarded.)
    if (signal.aborted) return;
    await storeSession(data.content, boundDpopJkt);
  } else {
    if (!error) logApiError(logger, 'POST /auth/login', { body, data });
    // Clear first, then emit error (see the LOGIN_TIMEOUT branch above).
    await clearSession();
    setAuthState({
      step: 'error',
      previousStep: 'authenticating',
      message: 'Failed to load session',
      errorCode: AUTH_ERROR_CODES.AUTH_FAILED,
    });
  }
}

import { PollarApiClient } from '../../api/client';
import type { PublicEcJwk } from '../../keys/types';
import type { PollarLogger } from '../../lib/logger';
import { AUTH_ERROR_CODES, AuthState, PasskeyCeremony, PollarApplicationConfigContent } from '../../types';
import { WalletAdapter, WalletId } from '../../wallets';
import { logApiError } from './logging';

export type FlowDeps = {
  api: PollarApiClient;
  /** Level-gated logger from the owning `PollarClient`. */
  logger: PollarLogger;
  /** API origin + version prefix (e.g. `https://sdk.api.pollar.xyz/v2`). Used to
   *  build the non-streaming status-poll URL on runtimes without fetch streaming. */
  basePath: string;
  /**
   * Stellar network passphrase for the app's network. Used to sign the SEP-10
   * wallet challenge transaction on the correct network (the backend builds the
   * challenge with the matching passphrase).
   */
  networkPassphrase: string;
  /**
   * Whether the runtime supports `fetch` response-body streaming (web). When
   * `true` the SDK consumes the SSE status stream; when `false` (React Native,
   * whose `fetch` exposes no `response.body.getReader()`) it polls the
   * non-streaming `/auth/session/status/{id}/poll` endpoint instead.
   */
  useStreaming: boolean;
  /**
   * Per-request budget for the final `POST /auth/login`, in ms.
   *
   * It is not the client's default: that call is the one place a login does real
   * server-side work (minting tokens, resolving the wallet, and - for an app on
   * the inline path - creating the account on-chain), so the 10s that protects
   * every other request would cut a login that is actually succeeding.
   */
  loginTimeoutMs: number;
  signal: AbortSignal;
  setAuthState: (state: AuthState) => void;
  /**
   * Persist the authenticated session. `boundDpopJkt` is the RFC 7638
   * thumbprint of the JWK the flow actually sent as `dpopJwk` to /auth/login -
   * i.e. the key the server bound the tokens to (`cnf.jkt`). Pass it so the
   * persisted `dpopJkt` records the BOUND key, not whatever key happens to be
   * loaded at store time (they differ if the key rotated mid-login).
   */
  storeSession: (session: PollarApplicationConfigContent, boundDpopJkt?: string) => void | Promise<void>;
  clearSession: () => void | Promise<void>;
  /** Persists the connected adapter (in memory + the stored wallet id) so a
   *  returning session restores it. Keyed by `adapter.type`. */
  storeWalletAdapter: (adapter: WalletAdapter, id: WalletId) => void | Promise<void>;
  /**
   * The passkey (WebAuthn) ceremony for `loginSmartWallet()`, injected from the
   * client config. Undefined when the consumer didn't configure passkey support.
   */
  passkey?: PasskeyCeremony;
  /**
   * Returns the public JWK of the SDK's per-session DPoP keypair. Auth
   * completion calls (`/auth/login`) pass it as `dpopJwk` so the server
   * can mint DPoP-bound tokens (`cnf.jkt`).
   */
  getPublicJwk: () => Promise<PublicEcJwk>;
  /**
   * Optional UI label persisted on the server-side refresh-token row so the
   * sessions UI can show "iPhone - Safari" instead of a raw user-agent.
   */
  deviceLabel?: string;
};

export async function createAuthSession(deps: FlowDeps): Promise<string | null> {
  const { api, logger, signal, setAuthState } = deps;

  setAuthState({ step: 'creating_session' });

  const { data, error } = await api.POST('/auth/session', { signal });

  if (error || !data?.success) {
    // HTTP-level errors are logged by the central middleware; only log the
    // 2xx-with-no-success case here.
    if (!error) logApiError(logger, 'POST /auth/session', { data });
    setAuthState({
      step: 'error',
      previousStep: 'creating_session',
      message: 'Failed to create session',
      errorCode: AUTH_ERROR_CODES.SESSION_CREATE_FAILED,
    });
    return null;
  }

  return data.content.clientSessionId;
}

import { AUTH_ERROR_CODES, AuthProviderContext } from '../../types';
import { logApiError } from './logging';

/**
 * Mint an auth session and move to the email-entry step. Returns the
 * `clientSessionId` so a one-shot caller can chain straight into
 * {@link sendEmailCode}; returns `null` if session creation failed (the error
 * state is already set by `ctx.createSession()`).
 */
export async function initEmailSession(ctx: AuthProviderContext): Promise<string | null> {
  const clientSessionId = await ctx.createSession();
  if (!clientSessionId) return null;
  ctx.setAuthState({ step: 'entering_email', clientSessionId });
  return clientSessionId;
}

export async function sendEmailCode(email: string, clientSessionId: string, ctx: AuthProviderContext): Promise<void> {
  const { api, logger, signal, setAuthState } = ctx;

  // Validate before hitting the API - an empty email/session (e.g. login()
  // called without an `email`, or an action with a missing payload) would
  // otherwise POST blanks to /auth/email and get an opaque 400.
  if (!email?.trim() || !clientSessionId) {
    setAuthState({
      step: 'error',
      previousStep: 'sending_email',
      message: 'A valid email address is required',
      errorCode: AUTH_ERROR_CODES.EMAIL_SEND_FAILED,
    });
    return;
  }

  setAuthState({ step: 'sending_email', email });

  const body = { clientSessionId, email };
  const { data, error } = await api.POST('/auth/email', { body, signal });

  if (error || !data?.success) {
    if (!error) logApiError(logger, 'POST /auth/email', { body, data });
    setAuthState({
      step: 'error',
      previousStep: 'sending_email',
      message: 'Failed to send code',
      errorCode: AUTH_ERROR_CODES.EMAIL_SEND_FAILED,
    });
    return;
  }

  setAuthState({ step: 'entering_code', clientSessionId, email });
}

export async function verifyAndAuthenticate(
  code: string,
  clientSessionId: string,
  email: string,
  ctx: AuthProviderContext,
): Promise<void> {
  const { api, logger, signal, setAuthState } = ctx;

  // Validate before hitting the API - a blank code/session would otherwise POST
  // blanks to /auth/email/verify-code for an opaque 400.
  if (!code?.trim() || !clientSessionId) {
    setAuthState({
      step: 'error',
      previousStep: 'verifying_email_code',
      message: 'A verification code is required',
      errorCode: AUTH_ERROR_CODES.EMAIL_CODE_INVALID,
    });
    return;
  }

  setAuthState({ step: 'verifying_email_code', clientSessionId, email });

  const body = { clientSessionId, code };
  const { data, error } = await api.POST('/auth/email/verify-code', { body, signal });

  if (data?.code === 'SDK_EMAIL_CODE_VERIFIED') {
    await ctx.authenticate(clientSessionId);
    return;
  }

  // Extract error code from either the 4xx error body or the 200 body
  const errCode =
    (error as unknown as { error?: string } | undefined)?.error ?? (data as unknown as { code?: string } | undefined)?.code;

  if (errCode === 'SDK_EMAIL_CODE_EXPIRED') {
    if (!error) logApiError(logger, 'POST /auth/email/verify-code', { body, data });
    setAuthState({
      step: 'error',
      previousStep: 'verifying_email_code',
      message: 'Code expired — request a new one',
      errorCode: AUTH_ERROR_CODES.EMAIL_CODE_EXPIRED,
      clientSessionId,
      email,
    });
    return;
  }

  if (errCode === 'INVALID_EMAIL_CODE' || errCode === 'SDK_EMAIL_CODE_INVALID') {
    if (!error) logApiError(logger, 'POST /auth/email/verify-code', { body, data });
    setAuthState({
      step: 'error',
      previousStep: 'verifying_email_code',
      message: 'Invalid code — try again',
      errorCode: AUTH_ERROR_CODES.EMAIL_CODE_INVALID,
      clientSessionId,
      email,
    });
    return;
  }

  if (!error) logApiError(logger, 'POST /auth/email/verify-code', { body, data });
  // Carry `clientSessionId`/`email` so this generic failure (transient 5xx,
  // contract drift) stays RETRYABLE - the message says "try again" and the
  // session is usually still alive, so `verifyEmailCode()` must be able to
  // re-submit without restarting the whole flow.
  setAuthState({
    step: 'error',
    previousStep: 'verifying_email_code',
    message: 'Failed to verify code — try again',
    errorCode: AUTH_ERROR_CODES.EMAIL_VERIFY_FAILED,
    clientSessionId,
    email,
  });
}

import { AUTH_ERROR_CODES, type AuthErrorCode } from '../../types';

/**
 * Maps a backend error `code` (the `ErrorCode` enum returned by sdk-api /
 * wallet-service in `{ code, success: false }`) to a user-facing message and
 * the SDK's coarse `AuthErrorCode` bucket.
 *
 * The backend stays code-only by design - this catalog is the single place the
 * SDK turns those codes into human-readable English. Consumers that need i18n
 * can switch on `state.errorCode` (the bucket) or the raw `code` instead of the
 * message string.
 */
interface ResolvedAuthError {
  message: string;
  errorCode: AuthErrorCode;
}

const CATALOG: Record<string, ResolvedAuthError> = {
  // -- Smart-account deploy / sponsor wallet ----------------------------------
  SPONSOR_NOT_FUNDED: {
    message: "This app can't create your wallet yet — its sponsor account isn't funded. Please contact the app's developer.",
    errorCode: AUTH_ERROR_CODES.PASSKEY_FAILED,
  },
  APP_WALLET_NOT_FOUND: {
    message: "This app isn't fully set up to create wallets yet. Please contact the app's developer.",
    errorCode: AUTH_ERROR_CODES.PASSKEY_FAILED,
  },
  WALLET_NOT_FOUND: {
    message: "This app isn't fully set up to create wallets yet. Please contact the app's developer.",
    errorCode: AUTH_ERROR_CODES.PASSKEY_FAILED,
  },
  PASSKEY_DEPLOY_FAILED: {
    message: "We couldn't finish creating your wallet. Please try again in a moment.",
    errorCode: AUTH_ERROR_CODES.PASSKEY_FAILED,
  },

  // -- Passkey ceremony --------------------------------------------------------
  PASSKEY_ALREADY_REGISTERED: {
    message: 'A passkey is already registered for this account. Try signing in instead.',
    errorCode: AUTH_ERROR_CODES.PASSKEY_FAILED,
  },
  PASSKEY_UNKNOWN_CREDENTIAL: {
    message: "We don't recognize this passkey. Try creating a new one.",
    errorCode: AUTH_ERROR_CODES.PASSKEY_FAILED,
  },
  PASSKEY_VERIFICATION_FAILED: {
    message: "We couldn't verify your passkey. Please try again.",
    errorCode: AUTH_ERROR_CODES.PASSKEY_FAILED,
  },
  PASSKEY_CHALLENGE_MISSING: {
    message: 'Your passkey session expired. Please start again.',
    errorCode: AUTH_ERROR_CODES.PASSKEY_FAILED,
  },

  // -- On-chain transaction failures (surfaced during deploy/transfer) ---------
  // These map to the TX_FAILED bucket (not PASSKEY_FAILED) - the precise reason
  // is the entry key itself, surfaced as the raw `code` on the tx outcome.
  TX_INSUFFICIENT_BALANCE: {
    message: 'Insufficient balance to complete this transaction.',
    errorCode: AUTH_ERROR_CODES.TX_FAILED,
  },
  TX_INSUFFICIENT_FEE: {
    message: 'Not enough XLM to cover the network fee. Add more XLM to your wallet and try again.',
    errorCode: AUTH_ERROR_CODES.TX_FAILED,
  },
  TX_FEE_LIMIT_EXCEEDED: {
    message: 'The transaction fee is above the allowed limit. Please try again.',
    errorCode: AUTH_ERROR_CODES.TX_FAILED,
  },
  TX_CONTRACT_FAILED: {
    message: 'The contract rejected this operation. Check the operation is allowed right now and try again.',
    errorCode: AUTH_ERROR_CODES.TX_FAILED,
  },
  TX_DESTINATION_NOT_FOUND: {
    message: "The destination account doesn't exist on the network yet.",
    errorCode: AUTH_ERROR_CODES.TX_FAILED,
  },
  TX_NO_TRUSTLINE: {
    message: "The destination can't receive this asset yet (no trustline).",
    errorCode: AUTH_ERROR_CODES.TX_FAILED,
  },
  TX_BAD_SEQUENCE: {
    message: 'Something went out of sync. Please try again.',
    errorCode: AUTH_ERROR_CODES.TX_FAILED,
  },
};

/**
 * Resolves a backend error `code` to a friendly message + bucket. Falls back to
 * the supplied default message when the code is unknown or absent, bucketing by
 * the code's domain prefix (`TX_`/`SDK_TX_` -> `TX_FAILED`, else `PASSKEY_FAILED`).
 */
export function resolveAuthError(code: string | undefined, fallbackMessage: string): ResolvedAuthError {
  if (code && CATALOG[code]) return CATALOG[code];
  // Bucket an UNKNOWN code by its domain prefix so a transaction code isn't
  // mislabeled as a passkey failure.
  const errorCode =
    code && (code.startsWith('TX_') || code.startsWith('SDK_TX_'))
      ? AUTH_ERROR_CODES.TX_FAILED
      : AUTH_ERROR_CODES.PASSKEY_FAILED;
  return { message: fallbackMessage, errorCode };
}

/**
 * Extracts the backend error `code` from an openapi-fetch result. On a non-2xx
 * response the body lands in `error`; some endpoints also return a code in a
 * 200 `data` body with `success: false`.
 */
export function extractErrorCode(error: unknown, data: unknown): string | undefined {
  return (error as { code?: string } | undefined)?.code ?? (data as { code?: string } | undefined)?.code ?? undefined;
}

import type { PollarLogger } from '../../lib/logger';
import { redactBody, redactDeep } from '../../lib/logging';

/**
 * Logs an auth failure that the central HTTP middleware can't see - namely an
 * *application-level* failure riding on a `2xx` response (e.g. `200` with
 * `{ success: false }`, or `/auth/email/verify-code` returning
 * `INVALID_EMAIL_CODE` in a `200` body). Transport / HTTP-status errors are
 * logged once by the middleware in `client.ts`; call this only on the no-HTTP-
 * error branch so nothing double-logs. Records the route, the redacted request
 * body (when present) and the underlying `data`/`error` payload.
 */
export function logApiError(
  logger: PollarLogger,
  route: string,
  detail: { body?: unknown; error?: unknown; data?: unknown } = {},
  level: 'warn' | 'error' = 'error',
): void {
  const { body, error, data } = detail;
  logger[level](`[PollarClient:auth] ${route} failed`, {
    route,
    ...(body !== undefined ? { body: redactBody(body) } : {}),
    // The cause is a server `data`/`error` envelope that can carry nested token
    // material - redact it recursively rather than logging it raw.
    cause: redactDeep(error ?? data),
  });
}

import type { AuthUrlOpener } from '../../types';
import { authenticate } from './authenticate';
import { createAuthSession, FlowDeps } from './deps';

type OAuthDeps = FlowDeps & {
  basePath: string;
  apiKey: string;
  /** Platform strategy for surfacing the hosted-OAuth URL (popup on web, in-app browser on RN). */
  openAuthUrl: AuthUrlOpener;
  /** Sent to the backend as `redirect_uri`; where the provider returns the user afterwards. */
  redirectUri: string;
};

/**
 * Break the popup's `window.opener` back-reference so the OAuth window
 * cannot navigate the parent. Best-effort - older browsers expose the
 * property as read-only.
 */
function severOpener(popup: Window | null): void {
  if (!popup) return;
  try {
    popup.opener = null;
  } catch {
    // ignore
  }
}

/**
 * Default web opener: reserve a blank popup synchronously (before any await)
 * so popup blockers - which only honor `window.open` inside the original
 * user-gesture tick - don't swallow it, then navigate it to the OAuth URL.
 *
 * React Native consumers replace this via `PollarClientConfig.openAuthUrl`
 * (typically wrapping `expo-web-browser`'s `openAuthSessionAsync`).
 */
export const defaultWebOAuthOpener: AuthUrlOpener = async ({ getUrl }) => {
  const popup = typeof window !== 'undefined' ? window.open('about:blank', '_blank') : null;
  severOpener(popup);

  const url = await getUrl();
  if (!url) {
    popup?.close();
    return;
  }

  if (popup) {
    popup.location.href = url;
    severOpener(popup);
  } else if (typeof window !== 'undefined') {
    window.open(url, '_blank', 'noopener,noreferrer');
  }
};

export async function loginOAuth(provider: 'google' | 'github', deps: OAuthDeps): Promise<void> {
  const { setAuthState, basePath, apiKey, openAuthUrl, redirectUri, signal } = deps;

  // The auth session is minted lazily inside `getUrl` so the web opener can
  // reserve its popup window *before* this async call runs. We capture the
  // resulting id here so `authenticate` can poll it once the opener returns.
  let clientSessionId: string | null = null;
  const getUrl = async (): Promise<string | null> => {
    clientSessionId = await createAuthSession(deps);
    if (!clientSessionId) return null;

    setAuthState({ step: 'opening_oauth', provider });

    const url = new URL(`${basePath}/auth/${provider}`);
    url.searchParams.set('api_key', apiKey);
    url.searchParams.set('client_session_id', clientSessionId);
    url.searchParams.set('redirect_uri', redirectUri);
    return url.toString();
  };

  await openAuthUrl({ provider, getUrl, redirectUri, signal });

  // Opener never called `getUrl`, or session creation failed - nothing to poll.
  if (!clientSessionId) return;

  await authenticate(clientSessionId, deps);
}

import { AUTH_ERROR_CODES, PasskeyMode } from '../../types';
import { authenticate } from './authenticate';
import { createAuthSession, FlowDeps } from './deps';
import { extractErrorCode, resolveAuthError } from './errorMessages';
import { logApiError } from './logging';

/**
 * "Smart Wallet" auth via passkey (WebAuthn).
 *
 * `mode` is chosen by the caller's button: `'login'` for a returning user
 * (`/auth/passkey/login`) and `'register'` for a brand-new wallet
 * (`/auth/passkey/register`, which also deploys the C-address server-side).
 *
 * 1. Create the auth session.
 * 2. Ask the server for a challenge bound to that session.
 * 3. Run the device ceremony (injected `deps.passkey`) in `mode`.
 * 4. Post the result to the matching endpoint.
 * 5. Hand off to `authenticate()` for the READY -> `/auth/login` token exchange.
 */
export async function smartWalletFlow(deps: FlowDeps, mode: PasskeyMode): Promise<void> {
  const { api, logger, signal, setAuthState, passkey } = deps;

  if (!passkey) {
    logger.error('[PollarClient:auth] passkey ceremony not configured');
    setAuthState({
      step: 'error',
      previousStep: 'creating_session',
      message: 'Passkey support is not configured',
      errorCode: AUTH_ERROR_CODES.PASSKEY_FAILED,
    });
    return;
  }

  const clientSessionId = await createAuthSession(deps);
  if (!clientSessionId) return;

  try {
    // 1. Server challenge.
    const challengeBody = { clientSessionId };
    const { data: challengeData, error: challengeError } = await api.POST('/auth/passkey/challenge', {
      body: challengeBody,
      signal,
    });
    const challenge = challengeData?.content?.challenge;
    if (!challengeData?.success || !challenge) {
      // HTTP-level errors are logged by the central middleware; only log the
      // 2xx-with-no-success case here.
      if (!challengeError) logApiError(logger, 'POST /auth/passkey/challenge', { body: challengeBody, data: challengeData });
      return failPasskey(setAuthState, extractErrorCode(challengeError, challengeData), 'Failed to start passkey');
    }

    // 2. Device ceremony (Touch ID / biometric) - runtime-injected.
    setAuthState({ step: 'creating_passkey' });
    const ceremony = await passkey({ challenge, mode });
    // openapi-fetch types the WebAuthn payload as a loose object; the browser
    // PublicKeyCredential JSON satisfies it.
    const response = ceremony.response as { [key: string]: unknown };

    // 3. New user -> register (deploys the C-address); returning -> login.
    if (ceremony.kind === 'register') {
      setAuthState({ step: 'deploying_smart_account' });
      const body = { clientSessionId, response };
      const { data, error } = await api.POST('/auth/passkey/register', { body, signal });
      // Map the backend code (e.g. SPONSOR_NOT_FUNDED) to a friendly message
      // via the catalog; unknown codes keep the generic fallback.
      if (!data?.success) {
        if (!error) logApiError(logger, 'POST /auth/passkey/register', { body, data });
        return failPasskey(setAuthState, extractErrorCode(error, data), 'Passkey registration failed');
      }
    } else {
      const body = { clientSessionId, response };
      const { data, error } = await api.POST('/auth/passkey/login', { body, signal });
      if (!data?.success) {
        if (!error) logApiError(logger, 'POST /auth/passkey/login', { body, data });
        return failPasskey(setAuthState, extractErrorCode(error, data), 'Passkey authentication failed');
      }
    }
  } catch (err) {
    // A cancel (cancelLogin / destroy / new login) aborts the signal -> the
    // WebAuthn/ceremony call rejects with an AbortError. Rethrow it so the flow's
    // handler maps it to `idle`, instead of mislabeling a user cancel as
    // PASSKEY_FAILED. (Mirrors walletFlow.)
    if ((err as { name?: string })?.name === 'AbortError') throw err;
    logApiError(logger, 'passkey ceremony', { error: err });
    return failPasskey(setAuthState, undefined, 'Passkey login failed');
  }

  // 4. Session is READY -> exchange for DPoP-bound tokens.
  await authenticate(clientSessionId, deps);
}

function failPasskey(setAuthState: FlowDeps['setAuthState'], code: string | undefined, fallbackMessage: string): void {
  const { message, errorCode } = resolveAuthError(code, fallbackMessage);
  setAuthState({ step: 'error', previousStep: 'creating_passkey', message, errorCode });
}

import { AUTH_ERROR_CODES, PollarAuthProvider } from '../../types';
import { initEmailSession, sendEmailCode, verifyAndAuthenticate } from './emailFlow';

/**
 * Built-in hosted-OAuth provider (`google` / `github`). The whole popup +
 * status-poll dance lives in `ctx.startHostedOAuth`, so the provider is a
 * one-liner - and any custom provider can reuse the same helper.
 */
export function oauthProvider(provider: 'google' | 'github'): PollarAuthProvider {
  return {
    id: provider,
    login: (ctx) => ctx.startHostedOAuth(provider),
  };
}

/**
 * Built-in email OTP provider. `login` is the one-shot entry point used by
 * `login({ provider: 'email', email })` (create session + send the first code).
 * The interactive continuation (resend / verify) is exposed both as the
 * dedicated `PollarClient` methods and here as `actions`, so a generic consumer
 * can drive it through `providerAction('email', ...)` too.
 */
export function emailProvider(): PollarAuthProvider {
  return {
    id: 'email',
    login: async (ctx, options) => {
      const email = (options as { email?: string }).email ?? '';
      // Reject a blank email BEFORE minting a server session, so an `email`-less
      // login() doesn't create an orphaned session that then errors. sendEmailCode
      // validates too (the real safety net) - this just fails faster and avoids
      // the wasted /auth/session round-trip.
      if (!email.trim()) {
        ctx.setAuthState({
          step: 'error',
          previousStep: 'sending_email',
          message: 'A valid email address is required',
          errorCode: AUTH_ERROR_CODES.EMAIL_SEND_FAILED,
        });
        return;
      }
      const clientSessionId = await initEmailSession(ctx);
      if (clientSessionId) await sendEmailCode(email, clientSessionId, ctx);
    },
    actions: {
      begin: async (ctx) => {
        await initEmailSession(ctx);
      },
      sendCode: (ctx, payload) => {
        const { email, clientSessionId } = (payload ?? {}) as { email: string; clientSessionId: string };
        return sendEmailCode(email, clientSessionId, ctx);
      },
      verifyCode: (ctx, payload) => {
        const { code, clientSessionId, email } = (payload ?? {}) as {
          code: string;
          clientSessionId: string;
          email: string;
        };
        return verifyAndAuthenticate(code, clientSessionId, email, ctx);
      },
    },
  };
}

/**
 * SEP-10 challenge sanity-check - pure JS, ZERO external dependencies.
 *
 * Hardening for the wallet-login flow: before asking the user's wallet to sign
 * the server's "challenge transaction", we cheaply verify it actually looks like
 * a SEP-10 challenge and not a real, submittable transaction smuggled in by a
 * compromised or MITM'd challenge endpoint.
 *
 * The single most important invariant - and the one this checks - is
 * `sequenceNumber === 0`. A genuine SEP-10 challenge ALWAYS has sequence 0, so it
 * can never be applied to the ledger; a non-zero sequence means it's a live
 * transaction that, once signed, could authorize a real operation. Asserting
 * seq == 0 blocks the most dangerous class of "sign this to log in" attacks.
 *
 * This is deliberately NOT a full SEP-10 verification: it does not check the
 * server signature, home domain, or operation source - that would need a full
 * XDR + crypto library (`@stellar/stellar-base`). The real security boundary
 * remains the server-side `verifyChallengeTxSigners`; this is client-side
 * defense-in-depth, kept dependency-free on purpose.
 *
 * -- Why hand-parsing is safe here --------------------------------------------
 * The field we read (the transaction `seqNum`) sits at a fixed offset because it
 * comes right after the transaction SOURCE account, which in a SEP-10 challenge
 * is always the SERVER's account: a plain ed25519 G-address. It is never muxed
 * (M-address) and never a contract (C-address) - the user's account appears only
 * as the source of the inner `manageData` operation, which we never touch. So
 * the byte layout up to `seqNum` is fixed. Anything that does NOT match the
 * expected shape - a muxed source, a fee-bump envelope, truncated bytes - makes
 * this return `false`: it FAILS CLOSED and the challenge is rejected before the
 * user can sign it.
 *
 * Smart-account (C-address / passkey) logins do NOT use this SEP-10 path at all
 * (they use the passkey flow), so this check never runs for them.
 *
 * XDR layout (all integers big-endian). `TransactionEnvelope` is an XDR union
 * over `EnvelopeType`:
 *
 *   v1  (ENVELOPE_TYPE_TX = 2):
 *     [envelopeType u32=2][MuxedAccount source][fee u32][seqNum i64] ...
 *     MuxedAccount = [keyType u32][...]; KEY_TYPE_ED25519 (0) -> 32-byte key.
 *     seqNum offset = 4 (env) + 4 (keyType) + 32 (key) + 4 (fee) = 44.
 *
 *   v0  (ENVELOPE_TYPE_TX_V0 = 0):
 *     [envelopeType u32=0][ed25519 32 (raw, no keyType)][fee u32][seqNum i64] ...
 *     seqNum offset = 4 (env) + 32 (key) + 4 (fee) = 40.
 */
import { base64urlDecode } from '../../lib/base64url';

const ENVELOPE_TYPE_TX_V0 = 0;
const ENVELOPE_TYPE_TX = 2;
const KEY_TYPE_ED25519 = 0;

// seqNum byte offsets (see layout above).
const SEQ_OFFSET_V1 = 44;
const SEQ_OFFSET_V0 = 40;

/** Decode standard base64 (`+/`, padded) to bytes via the pure-JS base64url decoder. */
function base64ToBytes(b64: string): Uint8Array {
  // Remap the standard alphabet onto url-safe; padding `=` is stripped by the decoder.
  return base64urlDecode(b64.replace(/\+/g, '-').replace(/\//g, '_'));
}

/** True iff `view` holds a zero 64-bit big-endian int at `offset` (no BigInt; RN-safe). */
function isI64Zero(view: DataView, offset: number): boolean {
  return view.getUint32(offset, false) === 0 && view.getUint32(offset + 4, false) === 0;
}

/**
 * Returns `true` only if `challengeXdr` parses as a SEP-10 challenge transaction
 * with `sequenceNumber === 0` and the expected (ed25519 server source) envelope
 * shape. Any parse error or unexpected structure returns `false` (fail closed),
 * so the caller can safely refuse to sign.
 */
export function isValidSep10Challenge(challengeXdr: string): boolean {
  try {
    const bytes = base64ToBytes(challengeXdr.trim());
    // Need at least the discriminant + a MuxedAccount keyType to classify.
    if (bytes.length < 8) return false;

    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    const envelopeType = view.getUint32(0, false);

    let seqOffset: number;
    if (envelopeType === ENVELOPE_TYPE_TX) {
      // v1: source is a MuxedAccount - require a plain ed25519 key (reject muxed).
      if (view.getUint32(4, false) !== KEY_TYPE_ED25519) return false;
      seqOffset = SEQ_OFFSET_V1;
    } else if (envelopeType === ENVELOPE_TYPE_TX_V0) {
      // v0: raw 32-byte ed25519 source, no key-type prefix.
      seqOffset = SEQ_OFFSET_V0;
    } else {
      // Fee-bump or anything else is never a SEP-10 challenge.
      return false;
    }

    if (bytes.length < seqOffset + 8) return false;
    return isI64Zero(view, seqOffset);
  } catch {
    return false;
  }
}

import { abortError } from '../../lib/abort';
import { base64urlEncode } from '../../lib/base64url';
import { AUTH_ERROR_CODES } from '../../types';
import { WalletAdapter } from '../../wallets';
import { authenticate } from './authenticate';
import { createAuthSession, FlowDeps } from './deps';
import { logApiError } from './logging';

function withSignal<T>(promise: Promise<T>, signal: AbortSignal): Promise<T> {
  return Promise.race([
    promise,
    new Promise<never>((_, reject) => {
      if (signal.aborted) {
        reject(abortError());
        return;
      }
      signal.addEventListener('abort', () => reject(abortError()), { once: true });
    }),
  ]);
}

/**
 * Sign In With Solana (SIWS) login for a `chain: 'SOLANA'` adapter - the Solana
 * counterpart of {@link loginWithAdapter} (which is SEP-10, Stellar). Solana has no
 * challenge TRANSACTION (its signature binds an expiring blockhash), so the server
 * issues a SIWS INPUT, the wallet signs the rendered message (`solana:signIn`), and
 * the server verifies the ed25519 signature. Both endpoints
 * (`/auth/wallet/solana/challenge` and `/auth/wallet/solana`) are part of the typed
 * openapi paths, so the shared api client is used directly (it runs the DPoP / auth
 * / retry middleware on both).
 */
export async function loginWithSolanaAdapter(adapter: WalletAdapter, deps: FlowDeps): Promise<void> {
  const { api, logger, signal, setAuthState } = deps;
  const type = adapter.type;

  let connectedWallet: string;
  let clientSessionId: string;
  let currentStep: 'connecting_wallet' | 'signing_wallet_challenge' | 'authenticating_wallet' = 'connecting_wallet';

  try {
    setAuthState({ step: 'connecting_wallet', walletType: type });

    const available = await withSignal(adapter.isAvailable(), signal);
    if (!available) {
      setAuthState({ step: 'wallet_not_installed', walletType: type });
      return;
    }

    // Phase 1 requires native SIWS (`solana:signIn`). A `signMessage`-only fallback
    // (build the SIWS message text ourselves) is a planned follow-up.
    if (!adapter.signIn) {
      logApiError(logger, 'solana login', { error: `adapter "${type}" has no signIn (SIWS) capability` });
      setAuthState({
        step: 'error',
        previousStep: 'connecting_wallet',
        message: 'Wallet does not support Sign In With Solana',
        errorCode: AUTH_ERROR_CODES.WALLET_CONNECT_FAILED,
      });
      return;
    }

    const sid = await createAuthSession(deps);
    if (!sid) return;
    clientSessionId = sid;

    const { address } = await withSignal(adapter.connect(), signal);
    connectedWallet = address;

    currentStep = 'signing_wallet_challenge';
    setAuthState({ step: 'signing_wallet_challenge', walletType: type });

    // 1. Ask the server for a SIWS input bound to this session.
    const challengeRes = await api.POST('/auth/wallet/solana/challenge', {
      body: { clientSessionId, walletAddress: address },
      signal,
    });
    const input = challengeRes.data?.content?.input;
    if (challengeRes.error || !challengeRes.data?.success || !input) {
      if (!challengeRes.error) logApiError(logger, 'POST /auth/wallet/solana/challenge', { data: challengeRes.data });
      setAuthState({
        step: 'error',
        previousStep: 'signing_wallet_challenge',
        message: 'Failed to obtain a Solana sign-in challenge',
        errorCode: AUTH_ERROR_CODES.WALLET_AUTH_FAILED,
      });
      return;
    }

    // 2. The wallet renders + signs the SIWS message.
    const output = await withSignal(adapter.signIn(input), signal);

    currentStep = 'authenticating_wallet';
    setAuthState({ step: 'authenticating_wallet' });

    // 3. Send the signed message + signature (base64url) for ed25519 verification.
    const authRes = await api.POST('/auth/wallet/solana', {
      body: {
        clientSessionId,
        walletAddress: address,
        signedMessage: base64urlEncode(output.signedMessage),
        signature: base64urlEncode(output.signature),
      },
      signal,
    });
    if (authRes.error || !authRes.data?.success) {
      if (!authRes.error) logApiError(logger, 'POST /auth/wallet/solana', { data: authRes.data });
      setAuthState({
        step: 'error',
        previousStep: 'authenticating_wallet',
        message: 'Solana wallet authentication failed',
        errorCode: AUTH_ERROR_CODES.WALLET_AUTH_FAILED,
      });
      return;
    }

    // Key control is proven - persist the adapter (and its walletType) now, so a
    // failure above never strands one (mirrors the Stellar flow).
    await deps.storeWalletAdapter(adapter, type);
  } catch (err) {
    if ((err as { name?: string })?.name === 'AbortError') throw err;
    logApiError(logger, `solana wallet connect (${currentStep})`, { error: err });
    setAuthState({
      step: 'error',
      previousStep: currentStep,
      message: 'Wallet connection failed',
      errorCode: AUTH_ERROR_CODES.WALLET_CONNECT_FAILED,
    });
    return;
  }

  await authenticate(clientSessionId, deps, connectedWallet);
}

import { abortError } from '../../lib/abort';
import { AUTH_ERROR_CODES } from '../../types';
import { WalletAdapter } from '../../wallets';
import { authenticate } from './authenticate';
import { createAuthSession, FlowDeps } from './deps';
import { logApiError } from './logging';
import { isValidSep10Challenge } from './sep10-challenge';

function withSignal<T>(promise: Promise<T>, signal: AbortSignal): Promise<T> {
  return Promise.race([
    promise,
    new Promise<never>((_, reject) => {
      if (signal.aborted) {
        reject(abortError());
        return;
      }
      signal.addEventListener('abort', () => reject(abortError()), { once: true });
    }),
  ]);
}

/**
 * Request a SEP-10 challenge transaction (XDR) for `walletAddress`, bound to the
 * client session. The wallet counter-signs it to prove key control. Returns
 * `null` on failure. Shared by the built-in wallet flow and custom providers
 * (via `AuthProviderContext.requestChallenge`).
 */
export async function requestWalletChallenge(
  clientSessionId: string,
  walletAddress: string,
  deps: FlowDeps,
): Promise<string | null> {
  const { api, logger, signal } = deps;
  const body = { clientSessionId, walletAddress };
  const { data, error } = await api.POST('/auth/wallet/challenge', { body, signal });
  if (error || !data?.success) {
    if (!error) logApiError(logger, 'POST /auth/wallet/challenge', { body, data });
    return null;
  }
  const challengeXdr = data.content.challengeXdr;
  // Defense-in-depth before ANY consumer hands this to a real wallet to sign -
  // the built-in flow AND custom providers (via `ctx.requestChallenge`). Refuse
  // anything that isn't a real SEP-10 challenge (e.g. a live, submittable tx with
  // sequence != 0 from a compromised/MITM'd challenge endpoint). The server's
  // verifyChallengeTxSigners is still authoritative; this blocks the worst case.
  if (!isValidSep10Challenge(challengeXdr)) {
    logApiError(logger, 'SEP-10 challenge validation', { error: 'unexpected challenge structure (sequence != 0?)' });
    return null;
  }
  return challengeXdr;
}

export async function loginWithAdapter(adapter: WalletAdapter, deps: FlowDeps): Promise<void> {
  const { api, logger, signal, setAuthState } = deps;
  const type = adapter.type;

  let connectedWallet: string;
  // Assigned after the wallet is confirmed installed (see below) - declared here
  // so it's in scope for the `authenticate()` call after the try/catch.
  let clientSessionId: string;
  // Track the phase so the catch reports where the failure ACTUALLY happened
  // (connect vs sign vs the /auth/wallet call) instead of always blaming
  // 'connecting_wallet'.
  let currentStep: 'connecting_wallet' | 'signing_wallet_challenge' | 'authenticating_wallet' = 'connecting_wallet';

  try {
    setAuthState({ step: 'connecting_wallet', walletType: type });

    const available = await withSignal(adapter.isAvailable(), signal);
    if (!available) {
      setAuthState({ step: 'wallet_not_installed', walletType: type });
      return;
    }

    // Mint the server session only AFTER confirming the wallet is installed, so
    // tapping "connect" without the extension doesn't orphan an unauthenticated
    // /auth/session each time.
    const sid = await createAuthSession(deps);
    if (!sid) return;
    clientSessionId = sid;

    const { address } = await withSignal(adapter.connect(), signal);
    connectedWallet = address;

    // SEP-10 challenge-response: prove control of the wallet key. Get a
    // server-signed challenge tx, have the wallet counter-sign it, and send the
    // signed XDR to /auth/wallet.
    currentStep = 'signing_wallet_challenge';
    setAuthState({ step: 'signing_wallet_challenge', walletType: type });
    // requestWalletChallenge now runs the SEP-10 validation internally (so custom
    // providers get it too) and returns null on a missing OR malformed challenge.
    const challengeXdr = await requestWalletChallenge(clientSessionId, address, deps);
    if (!challengeXdr) {
      setAuthState({
        step: 'error',
        previousStep: 'signing_wallet_challenge',
        message: 'Failed to obtain a valid wallet challenge',
        errorCode: AUTH_ERROR_CODES.WALLET_AUTH_FAILED,
      });
      return;
    }
    // A STELLAR adapter MUST implement signTransaction (SEP-10 counter-signs the
    // challenge tx). This flow is only dispatched for Stellar adapters, so a
    // missing method is a programming error, not a user-facing state.
    if (!adapter.signTransaction) {
      throw new Error(`[PollarClient] wallet adapter "${type}" cannot sign a SEP-10 challenge (no signTransaction)`);
    }
    const { signedTxXdr } = await withSignal(
      adapter.signTransaction(challengeXdr, { networkPassphrase: deps.networkPassphrase }),
      signal,
    );

    currentStep = 'authenticating_wallet';
    setAuthState({ step: 'authenticating_wallet' });

    const body = { clientSessionId, walletAddress: address, signedChallengeXdr: signedTxXdr };
    const { data: walletData, error: walletError } = await api.POST('/auth/wallet', { body, signal });

    if (walletError || !walletData?.success) {
      if (!walletError) logApiError(logger, 'POST /auth/wallet', { body, data: walletData });
      setAuthState({
        step: 'error',
        previousStep: 'authenticating_wallet',
        message: 'Wallet authentication failed',
        errorCode: AUTH_ERROR_CODES.WALLET_AUTH_FAILED,
      });
      return;
    }

    // Key control is proven - NOW persist the adapter (and its walletType).
    // Storing it at connect time left a dangling adapter + walletType row with
    // NO session whenever any step above failed; doing it here means a failure
    // never strands one. If the `authenticate()` call below fails, it runs
    // `clearSession()` which clears the adapter again.
    await deps.storeWalletAdapter(adapter, type);
  } catch (err) {
    // A cancel (cancelLogin / destroy / new login) aborts the signal -> withSignal
    // rejects with an AbortError. Rethrow it so the flow's handler maps it to
    // `idle`, instead of mislabeling a user cancel as WALLET_CONNECT_FAILED.
    // (Mirrors how the other flows let AbortError propagate.)
    if ((err as { name?: string })?.name === 'AbortError') throw err;
    // Tag the route with the phase that actually threw (connect vs sign vs the
    // /auth/wallet call) so the log pinpoints it without expanding `cause`. The
    // raw `err` (incl. its non-enumerable Error message/stack) is preserved by
    // `redactDeep`'s Error handling.
    logApiError(logger, `wallet connect (${currentStep})`, { error: err });
    setAuthState({
      step: 'error',
      previousStep: currentStep,
      message: 'Wallet connection failed',
      errorCode: AUTH_ERROR_CODES.WALLET_CONNECT_FAILED,
    });
    return;
  }

  await authenticate(clientSessionId, deps, connectedWallet);
}

