  /** Credit limit, spending power and balance due, read live from the provider. */
  async getCardBalance(params: CardProviderParams = {}): Promise<CardBalance | null> {
    return (await getCardBalance(this._api, params.cardProviderId)).balance;
  }

  /** Deposits, purchases and fees, newest first. */
  async getCardTransactions(
    params: CardProviderParams & { cardId?: string; limit?: number; offset?: number } = {},
  ): Promise<CardTransactionsPage> {
    return getCardTransactions(this._api, params);
  }

  /** Where the card's collateral is deposited, one address per network the provider accepts. */
  async getCardDepositAddresses(params: CardProviderParams = {}): Promise<CardDepositAddress[]> {
    return (await getCardDepositAddresses(this._api, params.cardProviderId)).depositAddresses;
  }

  /**
   * Move USDC from the user's Stellar wallet to the card's collateral. A
   * custodial wallet pays at once; an external wallet is asked to sign the
   * payment here, and `cancelled` means it declined. The returned funding then
   * advances on its own; follow it with {@link getCardFunding}.
   */
  async fundCard(params: CardProviderParams & { amount: string }): Promise<CardFundingOutcome> {
    const started = await createCardFunding(this._api, params);
    if (!started.pendingSignature) return { status: 'ok', funding: started.funding };
    const signed = await this.signTx(started.pendingSignature.unsignedXdr);
    if (signed.status !== 'signed') return { status: 'cancelled', funding: started.funding };
    const { funding } = await submitCardFundingSignature(this._api, started.funding.id, { signedXdr: signed.signedXdr });
    return { status: 'ok', funding };
  }

  async getCardFunding(fundingId: string): Promise<CardFunding> {
    return (await getCardFunding(this._api, fundingId)).funding;
  }

  /** The user's fundings, newest first. */
  async listCardFundings(params: CardProviderParams = {}): Promise<CardFunding[]> {
    return (await listCardFundings(this._api, params.cardProviderId)).fundings;
  }

  /**
   * The full card number and CVC, decrypted on this device with a one-shot key
   * the server never sees. Show them and drop them: never store or log the
   * result. On WebCrypto where the runtime has it, in plain JavaScript on React
   * Native.
   */
  async revealCardSecrets(cardId: string, params: CardProviderParams = {}): Promise<CardSecrets> {
    const { publicKeyPem } = await getCardSecretsPublicKey(this._api, params.cardProviderId);
    const session = await createCardSecretsSession(publicKeyPem);
    const encrypted = await getCardSecrets(this._api, cardId, { ...params, sessionId: session.sessionId });
    return openCardSecrets(session, encrypted);
  }

  private _setTxHistoryState(next: TxHistoryState): void {
    this._txHistoryState = next;
    for (const cb of this._txHistoryStateListeners) cb(next);
  }

  private _setSessionsState(next: SessionsState): void {
    this._sessionsState = next;
    for (const cb of this._sessionsStateListeners) cb(next);
  }

  private _setWalletBalanceState(next: WalletBalanceState): void {
    this._walletBalanceState = next;
    for (const cb of this._walletBalanceStateListeners) cb(next);
  }

  private _setEnabledAssetsState(next: EnabledAssetsState): void {
    this._enabledAssetsState = next;
    for (const cb of this._enabledAssetsStateListeners) cb(next);
  }

  // --- Private --------------------------------------------------------------

  private _newController(): AbortController {
    this._loginController?.abort();
    this._loginController = new AbortController();
    return this._loginController;
  }

  /**
   * Signal for a continuation of the current login (e.g. `sendEmailCode`,
   * `providerAction`). Reuses the active login controller, but mints a fresh one
   * if there's none OR the existing one is already aborted - a prior terminal
   * flow can leave `_loginController` set-but-aborted, and reusing that dead
   * signal would make the continuation's first request reject immediately and
   * drop the user to `idle`.
   */
  private _activeLoginSignal(): AbortSignal {
    if (this._loginController && !this._loginController.signal.aborted) return this._loginController.signal;
    return this._newController().signal;
  }

  /**
   * Build the {@link AuthProviderContext} facade for one login attempt. Wraps
   * the internal `FlowDeps` so providers get only the curated primitives -
   * `createSession`, `authenticate`, `requestChallenge`, `startHostedOAuth` -
   * while storage / wallet-adapter / key-manager internals stay private. All
   * legs share the same `signal`, so `cancelLogin()` aborts the whole chain.
   */
  private _providerContext(signal: AbortSignal): AuthProviderContext {
    const deps = this._flowDeps(signal);
    return {
      signal,
      api: this._api,
      basePath: this.basePath,
      apiKey: this.apiKey,
      logger: this._log,
      // Use the signal-guarded wrapper from `deps` (see `_flowDeps`) so a
      // cancelled/superseded provider flow can't clobber the active state.
      setAuthState: deps.setAuthState,
      createSession: () => createAuthSession(deps),
      authenticate: (clientSessionId: string) => authenticate(clientSessionId, deps),
      requestChallenge: (clientSessionId: string, walletAddress: string) =>
        requestWalletChallenge(clientSessionId, walletAddress, deps),
      startHostedOAuth: (provider) =>
        loginOAuth(provider, {
          ...deps,
          basePath: this.basePath,
          apiKey: this.apiKey,
          openAuthUrl: this._openAuthUrl,
          redirectUri: this._oauthRedirectUri,
        }),
    };
  }

  private _flowDeps(signal: AbortSignal) {
    return {
      api: this._api,
      logger: this._log,
      basePath: this.basePath,
      networkPassphrase: this._networkPassphrase(),
      // SSE status streaming works on web; React Native's `fetch` has no
      // readable `response.body`, so those clients poll the non-streaming
      // status endpoint instead. `isBrowser` is false in RN and SSR alike.
      useStreaming: isBrowser,
      loginTimeoutMs: this._loginTimeoutMs,
      signal,
      // Suppress terminal writes from a flow that was CANCELLED or SUPERSEDED
      // (its `signal` is aborted) so a late-resolving loser can't clobber the
      // active flow's state or, via clearSession, tear down a newer session.
      // The active flow's signal is never aborted, so the
      // happy path is unchanged. (Completes the cancelled-flow guard - covers error/clear
      // writes, not just storeSession.)
      setAuthState: (state: AuthState) => {
        if (!signal.aborted) this._setAuthState(state);
      },
      storeSession: (session: PollarApplicationConfigContent, boundDpopJkt?: string) =>
        signal.aborted ? Promise.resolve() : this._storeSession(session, boundDpopJkt),
      clearSession: async () => {
        if (!signal.aborted) await this._clearSession();
      },
      getPublicJwk: async () => {
        const jwk = await this._keyManager.getPublicJwk();
        // The login is about to bind its tokens to this key (`cnf.jkt`). Verify
        // the key is durably persisted (re-writing it if needed) and warn loudly
        // when it isn't: a non-persisted key means the session cannot survive a
        // reload - every resume/refresh will 401 with `thumbprint-mismatch`.
        // Previously this failure was swallowed inside the key manager and only
        // surfaced as an unexplained logout on the next page load. Best-effort
        // and optional: custom KeyManager implementations without
        // `ensurePersisted` behave as before.
        try {
          // `undefined` (method not implemented) intentionally does not warn.
          if ((await this._keyManager.ensurePersisted?.()) === false) {
            this._log.warn(
              '[PollarClient] The DPoP keypair could not be persisted (IndexedDB/secure storage ' +
                'unavailable?). Login will work, but the session will NOT survive a reload — the ' +
                'user will be logged out on the next page load.',
            );
          }
        } catch (err) {
          this._log.warn('[PollarClient] DPoP keypair persistence check failed', err);
        }
        return jwk;
      },
      storeWalletAdapter: async (adapter: WalletAdapter, id: WalletId) => {
        // A cancelled/superseded flow must not leave a dangling adapter +
        // persisted walletType row with no session (the same reason the other
        // flow deps no-op on an aborted signal). The active flow is never
        // aborted, so the happy path is unchanged.
        if (signal.aborted) return;
        this._walletAdapter = adapter;
        try {
          await writeWalletType(this._storage, this.apiKeyHash, id);
        } catch (err) {
          // The adapter is set in memory and works for this session; persistence
          // is best-effort (the wallet just won't auto-restore on next cold
          // start). Never let a storage failure break the login.
          this._log.warn('[PollarClient] Could not persist wallet type', err);
        }
      },
      ...(this._passkey ? { passkey: this._passkey } : {}),
      ...(this._deviceLabel ? { deviceLabel: this._deviceLabel } : {}),
    };
  }

  private _handleFlowError(error: unknown, signal?: AbortSignal): void {
    // A cancelled/superseded flow's signal is aborted - drop its terminal write
    // so it can't clobber the active flow (e.g. flash `idle`/`error` over a new
    // login). cancelLogin already set the right state.
    if (signal?.aborted) return;
    if (error instanceof Error && error.name === 'AbortError') {
      this._log.debug('[PollarClient] Login cancelled');
      this._setAuthState({ step: 'idle' });
      return;
    }
    if (error instanceof Error && (error as { code?: string }).code === AUTH_ERROR_CODES.WALLET_RESOLVER_TIMEOUT) {
      this._log.error('[PollarClient] Wallet resolver timeout', error.message);
      this._setAuthState({
        step: 'error',
        previousStep: this._authState.step,
        message: error.message,
        errorCode: AUTH_ERROR_CODES.WALLET_RESOLVER_TIMEOUT,
      });
      return;
    }
    this._log.error('[PollarClient] Unexpected error in auth flow', error);
    this._setAuthState({
      step: 'error',
      previousStep: this._authState.step,
      message: 'An unexpected error occurred',
      errorCode: AUTH_ERROR_CODES.UNEXPECTED_ERROR,
    });
  }

  /**
   * Every branch below that surfaces a session arms the provisioning watch.
   *
   * The watch is what ends a "preparing your account" screen, and each branch
   * can restore a wallet mid-creation: a cross-tab rotation, an expired token
   * refreshed inline (which never reaches `_resume`), and the optimistic path
   * (whose `_resume` can fail on a flaky network and back off for 30s).
   * `_startProvisioningWatch` is idempotent per session, so arming it here and
   * again from `_doResume` costs nothing.
   */
  private async _restoreSession(): Promise<void> {
    if (this._destroyed) return;
    // Capture the pre-restore state so we can tell a genuine restore (cold
    // start, or another user's session) apart from a cross-tab token ROTATION
    // of the session we already have verified.
    const prevState = this._authState;
    const prevSession = this._session;
    this._session = await readStorage(this._storage, this.apiKeyHash, this._log);
    if (this._session) {
      this._recordOwnedSession(this._session.clientSessionId);
      // A DIFFERENT session was restored (e.g. a cross-tab login as another user
      // overwrote storage): invalidate any refresh/resume still in flight against
      // the OLD session, so its rotated token can't be written over the
      // newly-restored one. (A same-session cross-tab rotation keeps the same
      // clientSessionId and is handled by the verified fast path below - no bump,
      // so it doesn't disturb an in-flight refresh of the very same session.)
      if (prevSession && prevSession.clientSessionId !== this._session.clientSessionId) {
        this._sessionGeneration++;
      }

      // DPoP key binding precheck: the persisted session records the thumbprint
      // of the keypair its tokens are bound to (`dpopJkt`, = the token's
      // `cnf.jkt`). If the keypair we just loaded is a DIFFERENT one - the
      // stored key was lost (IndexedDB evicted, unavailable, or reset by
      // another tab) and a fresh key was generated - then EVERY proof-bound
      // call is guaranteed to 401 (`thumbprint-mismatch`): resume, refresh,
      // signing, all of them. Converge to logged-out locally, with a diagnostic
      // that names the real cause, instead of burning a doomed resume round
      // trip that can only fail with an opaque 401. Sessions persisted by older
      // SDKs have no `dpopJkt` and skip
      // this - their resume decides, as before. If the thumbprint can't be
      // computed (key manager init failed), skip too: the Bearer fallback may
      // still be able to use the session.
      if (this._session.dpopJkt) {
        // A thumbprint that can't be computed (key manager unavailable) reads
        // as null and skips the check - the resume path decides, as before.
        const readJkt = (): Promise<string | null> => this._keyManager.getThumbprint().catch(() => null);
        let currentJkt = await readJkt();
        if (currentJkt !== null && currentJkt !== this._session.dpopJkt && this._keyManager.resync) {
          // The cached key may simply be stale: another tab can rotate the
          // shared persisted key (logout -> fresh login) and then write the
          // session this restore is picking up. Re-read persistent storage
          // and re-compare before concluding the key is really lost -
          // without this, a stale cache would clear the session the other
          // tab just created.
          this._keyManager.resync();
          currentJkt = await readJkt();
        }
        if (currentJkt !== null && currentJkt !== this._session.dpopJkt) {
          this._log.error(
            '[PollarClient] Stored session is bound to a DPoP key that no longer exists locally ' +
              '(key persistence failed or the key was reset). The session cannot be resumed or ' +
              'refreshed — clearing it. The user must log in again.',
            { expectedJkt: this._session.dpopJkt, currentJkt },
          );
          await this._clearSession();
          return;
        }
      }
      // Only restore an adapter for an EXTERNAL session - those are the only ones
      // signed via an adapter. `internal` is embedded (server-signed) and `smart`
      // is passkey-signed; attaching an adapter to either (from a stale walletType
      // row left by a prior external login that was switched away from without a
      // logout) would mis-route their signing to the wrong key. (`_storeSession`
      // nulls the in-memory adapter on a switch but doesn't remove the persisted
      // row, so guard on the SESSION type here, not the row's presence.)
      const storedType =
        this._session.wallet?.type === 'external' ? await readWalletType(this._storage, this.apiKeyHash) : null;
      if (storedType) {
        // Look the adapter up in the registry. If it's no longer registered
        // (e.g. the consumer dropped the kit-adapter package), the session stays
        // valid; signing stays unavailable until the user reconnects the wallet.
        const restored = this._walletAdapters.get(storedType);
        if (restored) this._walletAdapter = restored;
        else this._log.warn('[PollarClient] No registered wallet adapter for stored id', { id: storedType });
      }

      // Cross-tab token rotation of the SAME already-verified session: another
      // tab just refreshed and wrote a fresh token. The server issued that
      // token, so the session is still valid - keep `verified: true`, pick up
      // the new token, and skip the redundant `/auth/session/resume`. Without
      // this, every sibling tab's rotation would flap `verified` true->false->true
      // and fire an extra resume round-trip.
      // Key on `clientSessionId` - the canonical per-session identity, always
      // present. Do NOT also require `userId`: a valid session can have
      // `userId: null` (isValidSession allows it), and gating on it would make
      // those sessions miss this fast path and keep flapping `verified` on every
      // cross-tab rotation. Two different users can't share a clientSessionId.
      const isSameVerifiedSession =
        prevState.step === 'authenticated' &&
        prevState.verified &&
        prevSession != null &&
        !!prevSession.clientSessionId &&
        prevSession.clientSessionId === this._session.clientSessionId;
      if (isSameVerifiedSession) {
        this._log.info('[PollarClient] Session token rotated (cross-tab); keeping verified');
        this._setAuthState({ step: 'authenticated', session: this._session, verified: true });
        // The row may carry more than a token: a sibling tab's watch writes the
        // provisioning value it found, and this tab's own poll will find nothing
        // left to report once the row is adopted.
        this._emitWalletStateIfChanged(prevSession, this._session);
        this._scheduleNextRefresh();
        this._startProvisioningWatch();
        return;
      }

      // If the stored access token is ALREADY expired, refresh inline BEFORE
      // surfacing the session - otherwise a consumer reading `session.token` in
      // the optimistic `verified:false` window forwards a token we already know is
      // dead. A successful refresh both rotates the token AND proves the session
      // is alive server-side, so emit `verified:true` and skip the resume.
      // `_doRefresh` already re-armed the proactive timer and, on failure, cleared
      // the session (so we just return).
      if (this._session.token.expiresAt * 1000 < Date.now()) {
        this._log.info('[PollarClient] Restored session has an expired access token; refreshing before surfacing it');
        try {
          await this.refresh();
        } catch {
          return; // refresh failed -> session was cleared; stay logged out
        }
        if (this._session) {
          this._setAuthState({ step: 'authenticated', session: this._session, verified: true });
          this._emitWalletStateIfChanged(prevSession, this._session);
          this._startProvisioningWatch();
        }
        return;
      }

      this._log.info('[PollarClient] Session restored from storage');
      // Emit through the setter so listeners that subscribe after
      // _initialize() resolves still get notified. A direct assignment to
      // _authState would race past any onAuthStateChange subscription that
      // hasn't run yet (e.g. PollarProvider's useEffect).
      // Optimistic: storage is trusted enough to show `authenticated`, but the
      // server hasn't confirmed the session is still alive (it may have been
      // revoked elsewhere), so `verified: false`.
      this._setAuthState({ step: 'authenticated', session: this._session, verified: false });
      this._emitWalletStateIfChanged(prevSession, this._session);
      this._scheduleNextRefresh();
      this._startProvisioningWatch();
      // Fire-and-forget: revalidate + repopulate the profile in the background.
      // Deliberately NOT awaited so `_initialized` resolves immediately and the
      // UI never blocks on a network round-trip at startup.
      void this._resume();
    } else {
      this._log.info('[PollarClient] No session in storage');
      // Another tab (or this one) wiped the session key. If we were
      // authenticated, propagate the logout: tear down in-memory state, the
      // refresh timer, and emit `idle` (the DPoP keypair survives - see
      // `_clearSession`). Guarded so the cold-start
      // call (step already `idle`) is a no-op and we never recurse - the
      // `removeStorage` inside `_clearSession` targets an already-removed key.
      if (this._authState.step !== 'idle') {
        await this._clearSession();
      }
    }
  }

  /**
   * Validate the restored session against the server and repopulate the
   * in-memory profile (PII is never persisted, so it's null after a cold
   * reload). Goes through the normal authed client, so it coalesces with any
   * in-flight refresh (onRequest awaits `_refreshPromise`) and, being a GET,
   * is auto-retried after a 401-triggered refresh.
   *
   * - 200            -> store profile, mark the session `verified`.
   * - 401            -> the refresh-on-401 path already ran; if the family was
   *                    revoked, refresh failed and `_clearSession()` took us to
   *                    idle. We also clear here as a belt-and-suspenders.
   * - 403 / 410      -> the session was revoked elsewhere while its access token
   *                    is still unexpired (so the 401->refresh path never fired).
   *                    Definitive: converge to logged-out.
   * - 404/429/5xx    -> endpoint mismatch / rate limit / transient: do NOT log
   *                    out; keep the optimistic session for a later retry.
   * - network error  -> stay optimistic; revalidated on `visibilitychange`/use.
   */
  private _resume(): Promise<void> {
    // Coalesce: a resume already in flight IS the validation every caller
    // wants - join it instead of aborting and restarting (which multiplied one
    // failure into a burst when the startup restore and visibility handler
    // fired together).
    if (this._resumePromise) return this._resumePromise;
    // Backoff after non-terminal failures (network, 5xx, 429): a visibility
    // flap must not hammer the endpoint. Terminal outcomes (verified, or the
    // session cleared) reset this.
    if (Date.now() < this._resumeBackoffUntil) return Promise.resolve();
    this._resumePromise = this._doResume().finally(() => {
      this._resumePromise = null;
    });
    return this._resumePromise;
  }

  /** Record a retryable resume failure: exponential backoff, 1s -> 30s cap. */
  private _noteResumeFailure(): void {
    this._resumeFailStreak++;
    const delayMs = Math.min(1_000 * 2 ** (this._resumeFailStreak - 1), 30_000);
    this._resumeBackoffUntil = Date.now() + delayMs;
  }

  private _resetResumeBackoff(): void {
    this._resumeFailStreak = 0;
    this._resumeBackoffUntil = 0;
  }

  private async _doResume(): Promise<void> {
    if (!this._session) return;
    const gen = this._sessionGeneration;
    const controller = new AbortController();
    this._resumeController = controller;
    try {
      const { data, error, response } = await this._api.GET('/auth/session/resume', { signal: controller.signal });
      // Bail if the session was cleared/replaced (logout / refresh / new login)
      // or the client destroyed while resume was in flight - don't emit over, or
      // clear, a session that's no longer the one we started with.
      if (this._destroyed || this._sessionGeneration !== gen || !this._session) return;

      if (error || !data) {
        // Only treat statuses that unambiguously mean "this session is gone" as a
        // logout. A 404 (deploy/endpoint mismatch), 429 (rate limit) or 5xx
        // (transient) must NOT strand the user logged-out.
        const status = response?.status ?? 0;
        if (status === 401 || status === 403 || status === 410) {
          await this._clearSession();
        } else {
          this._noteResumeFailure();
        }
        return;
      }

      const content = (data as { content?: PollarUserProfile }).content;
      if (!content) return;
      this._profile = { ...content };
      this._resetResumeBackoff();
      this._setAuthState({ step: 'authenticated', session: this._session, verified: true });
      // A wallet restored mid-creation resumes its watch here. The server's own
      // resume re-enqueues a creation that never landed, so by the time the
      // first check fires there is something to wait for again.
      this._startProvisioningWatch();
    } catch (err) {
      if ((err as { name?: string })?.name === 'AbortError') return;
      // Network failure (no response) - keep the optimistic (unverified) session
      // and retry (with backoff) when the app next becomes visible or on the
      // next authed request.
      this._noteResumeFailure();
      this._log.warn('[PollarClient] resume failed (network); will retry', err);
    } finally {
      if (this._resumeController === controller) this._resumeController = null;
    }
  }

  private async _storeSession(session: PollarApplicationConfigContent, boundDpopJkt?: string): Promise<void> {
    this._log.info('[PollarClient] Session stored');

    // The wire response still carries the legacy `publicKey` alias (kept for
    // older SDKs); the persisted session standardizes on `address` only.
    // `type` needs no remap: the wire speaks the same vocabulary as the SDK
    // surface ('internal' | 'smart' | 'external').
    //
    // Applied identically to `wallet` and to every entry of `wallets[]` so the
    // back-compat field and the array can't end up describing the same wallet
    // differently.

    // Record which DPoP key this session's tokens are bound to (= the token's
    // `cnf.jkt`) so a later restore can detect key loss up front instead of
    // discovering it through a burst of thumbprint-mismatch 401s.
    //
    // Prefer `boundDpopJkt` - the thumbprint of the JWK the login flow ACTUALLY
    // sent to /auth/login. Re-reading `getThumbprint()` here records whatever
    // key is loaded NOW, which is the wrong key if it rotated between the bind
    // and this store (a reset racing the login, a cross-tab rotation): the
    // field would then vouch for a key the server never bound, and the restore
    // precheck would wave through a session guaranteed to 401. The fallback
    // read covers the refresh path and custom flows that don't thread the
    // bound value; best-effort - if the key manager is unavailable (Bearer
    // fallback), omit the field and the restore-time check is skipped.
    const dpopJkt = boundDpopJkt ?? (await this._keyManager.getThumbprint().catch(() => null));

    const persisted: PollarPersistedSession = {
      clientSessionId: session.clientSessionId,
      userId: session.userId ?? null,
      status: session.status,
      token: session.token,
      user: session.user,
      ...(dpopJkt ? { dpopJkt } : {}),
      wallet: toPersistedWallet(session.wallet),
      // Absent on logins against an sdk-api that predates `wallets[]` - persist
      // nothing rather than an empty array, so consumers can tell "not reported"
      // apart from "genuinely none".
      ...(session.wallets ? { wallets: session.wallets.map(toPersistedWallet) } : {}),
    };
    // A fresh login replaces the session: invalidate any refresh/resume still
    // in flight against the previous one, and drop any resume backoff the old
    // session accumulated.
    this._sessionGeneration++;
    this._resetResumeBackoff();
    const gen = this._sessionGeneration;
    const prevSession = this._session;
    this._session = persisted;
    this._recordOwnedSession(persisted.clientSessionId);

    if (session.data) {
      this._profile = {
        mail: session.data.mail,
        first_name: session.data.first_name,
        last_name: session.data.last_name,
        avatar: session.data.avatar,
        providers: session.data.providers,
      };
    }

    await this._persistSession(gen, persisted);
    // A logout / destroy / newer login landed DURING the persist await - bail so
    // we don't emit `authenticated` (resurrecting a session that was just
    // cleared) or re-arm the refresh timer for a session this call no longer
    // owns. Mirrors the generation guard in `_doRefresh`.
    if (this._destroyed || this._sessionGeneration !== gen) return;
    // Drop a stale external adapter when switching to a non-external session
    // (e.g. external-wallet login -> later email/passkey login). The wallet flow
    // sets `_walletAdapter` BEFORE calling us (storeWalletAdapter -> authenticate
    // -> storeSession), so only clear it when the NEW session isn't external -
    // that preserves the adapter an external login just stored for itself, while
    // fixing getWalletType()/signing reporting a stale wallet after a switch.
    if (persisted.wallet.type !== 'external') {
      this._walletAdapter = null;
    }
    // Account switch without a logout (login-over-login) bypasses _clearSession,
    // so reset the read/tx stores here too - otherwise the previous user's
    // balance/history/tx-state would linger and an in-flight fetch could land
    // their data in the new session's store. On a first login (from idle) the
    // stores are already idle, so this is a harmless no-op.
    this._resetReactiveStores();
    // Fresh login/refresh response came straight from the server, so the
    // session is already server-validated -> `verified: true`.
    this._setAuthState({ step: 'authenticated', session: persisted, verified: true });
    this._emitWalletStateIfChanged(prevSession, persisted);
    this._scheduleNextRefresh();
    // A login that returned before the account was on the ledger leaves the
    // wallet CREATING. Nothing else would tell the app when that ends.
    this._startProvisioningWatch();
  }

  /**
   * Tear down the local session and converge to `idle`.
   *
   * Returns whether this client actually removed the shared persisted row -
   * i.e. whether it still owned the session it was clearing. `logout()` gates
   * the DPoP keypair rotation on that answer: the keypair is the most shared
   * piece of state on the origin, so a client that was not entitled to drop the
   * row is not entitled to destroy the key either.
   */
  private async _clearSession(): Promise<boolean> {
    this._log.info('[PollarClient] Session cleared');
    this._stopProvisioningWatch();
    // Identify the session being torn down BEFORE dropping it: the persisted
    // row is shared by every document (and every client instance) on this
    // origin using this API key, so it may only be removed by the client that
    // actually owns it. See `_persistSession`.
    const owned = this._session?.clientSessionId ?? null;
    // Invalidate any in-flight refresh/resume so a result that lands after this
    // clear (e.g. a refresh racing a logout) is discarded instead of
    // resurrecting the session, and abort the resume so it can't re-emit
    // `authenticated` after we go `idle`.
    this._sessionGeneration++;
    const gen = this._sessionGeneration;
    this._resumeController?.abort();
    this._resumeController = null;
    this._resetResumeBackoff();
    this._clearRefreshTimer();
    this._session = null;
    this._profile = null;
    this._walletAdapter = null;
    // The DPoP keypair deliberately SURVIVES this teardown. It is device-scoped,
    // not session-scoped: nothing about a dropped session invalidates the key,
    // and `_clearSession` also runs on failure paths (a rejected resume, a
    // failed refresh, a cross-tab clear, a login attempt superseding another).
    // Resetting it here made every such failure destructive - any session still
    // bound to the key (persisted, or a token a consumer held elsewhere) became
    // permanently unverifiable, and a stale clear racing a fresh login could
    // discard the very key the login had just bound (persisting a session that
    // could never resume). The keypair is rotated ONLY on explicit `logout()`.
    // The in-memory CACHE is dropped, though: the persisted key is shared per
    // origin across tabs, and a cross-tab logout (one of the paths that land
    // here) deletes/rotates it - the next use must re-read storage instead of
    // signing with a stale cached copy. Persistent storage is untouched, so
    // after a same-tab failure clear the next init re-loads the very same key.
    this._keyManager.resync?.();
    // `_dpopNonce` likewise survives, in memory AND in storage: it is
    // origin-scoped server state, not session state. sdk-api nonces verify for
    // days (24h active + a 3-day rotation overlap, see its lib/dpop-nonce.ts),
    // so the stored one stays usable across page loads and saves the guaranteed
    // `use_dpop_nonce` 401 on the next first proof. See `dpopNonceStorageKey`.
    const droppedOwnRow = await this._persistSession(gen, null, owned);
    this._resetReactiveStores();
    this._setAuthState({ step: 'idle' });
    // Only now tell the same-document siblings, and only if we actually dropped
    // the shared row. They never see the `storage` event that removal emits -
    // browsers fire it at OTHER documents only - so a second instance in this
    // document would otherwise keep its session and re-persist the row a moment
    // later. (`PollarProvider` reuses one client per config under StrictMode,
    // but a consumer can still hold two clients, and non-React callers always
    // could.) This mirrors the cross-document handler.
    //
    // It runs AFTER the teardown above on purpose: announcing first put the
    // siblings' handlers between this client and its own terminal state, so
    // anything that went wrong inside one of them left this client mid-teardown.
    if (droppedOwnRow) notifySiblingClients(this, this.apiKey, this._log);
    return droppedOwnRow;
  }

  /**
   * A sibling client in THIS document dropped the shared session row. Same
   * reasoning as the cross-document `storage` handler: propagate the logout
   * from the notification without re-reading storage, and guard on holding a
   * session rather than on the auth step, so a login in flight (which owns no
   * session yet) is left alone.
   */
  private _onSiblingSessionCleared(): void {
    if (this._destroyed || !this._session) return;
    this._log.info('[PollarClient] Session cleared by another client in this document');
    void this._clearSession().catch((err) => this._log.error('[PollarClient] Same-document logout failed', err));
  }

  /** Record a session this instance held; bounded so a long-lived SPA cannot grow it unboundedly. */
  private _recordOwnedSession(id: string): void {
    if (this._ownedSessionIds.has(id)) return;
    this._ownedSessionIds.add(id);
    if (this._ownedSessionIds.size > 10) {
      const oldest = this._ownedSessionIds.values().next().value;
      if (oldest !== undefined) this._ownedSessionIds.delete(oldest);
    }
  }

  /**
   * Single writer for the shared `pollar:<apiKeyHash>:session` row.
   *
   * Every document on the origin - and every client instance inside one
   * document - writes that same row, and each mutation is preceded by an await
   * (the network round-trip, the storage adapter itself). Without this queue two
   * hazards are reachable:
   *
   *   - ORDERING: two overlapping writes land in the order their adapter
   *     resolves, so an older session can win over a newer one.
   *   - RESURRECTION: a write that started before a logout lands after it and
   *     re-creates a row the user just cleared. Re-checking the generation only
   *     *after* the write would skip the state emission but leave the row
   *     behind, so the session would come back on the next reload and the
   *     write's own `storage` event could log other documents back in.
   *
   * So the generation is re-checked HERE, immediately before the mutation, with
   * writes serialized against each other. `gen` is the caller's snapshot of
   * `_sessionGeneration`; a mismatch means a logout or a newer login superseded
   * this write while it was queued and the mutation is dropped.
   *
   * `session === null` removes the row, but only when it still holds the
   * session named by `ownedId` - a client must never delete a row that now
   * belongs to a newer login in another document or another instance. Without
   * the ownership check, a second client sitting on a stale session would
   * delete the row a fresh login had just written, about one round trip after
   * "Session stored".
   *
   * Returns whether the mutation was applied.
   */
  private async _persistSession(
    gen: number,
    session: PollarPersistedSession | null,
    ownedId: string | null = null,
  ): Promise<boolean> {
    const run = this._persistQueue.then(async (): Promise<boolean> => {
      // `destroy()` does not bump the generation, so check it explicitly: a
      // write still queued when the client is torn down must not land.
      if (this._destroyed || this._sessionGeneration !== gen) {
        this._log.debug('[PollarClient] Session write dropped: superseded before it reached storage');
        return false;
      }
      if (session) {
        await writeStorage(this._storage, this.apiKeyHash, session);
        return true;
      }
      if (!ownedId) return false;
      let current: string | null;
      try {
        current = await this._storage.get(sessionStorageKey(this.apiKeyHash));
      } catch {
        current = null;
      }
      // Already gone (another document removed it, or a foreign clear wiped
      // the area): there is nothing of ours left to drop.
      if (current === null) return false;
      let owns: boolean;
      try {
        const rowId = (JSON.parse(current) as { clientSessionId?: unknown }).clientSessionId;
        // Membership in the instance's session history, not equality with the
        // one being cleared - see `_ownedSessionIds` for the race this covers.
        owns = typeof rowId === 'string' && (rowId === ownedId || this._ownedSessionIds.has(rowId));
      } catch {
        // Unparseable row inside our own namespace: nobody can use it, so it is
        // ours to clean up.
        owns = true;
      }
      if (!owns) {
        this._log.debug('[PollarClient] Session row now belongs to a newer session; leaving shared storage untouched');
        return false;
      }
      await removeStorage(this._storage, this.apiKeyHash);
      return true;
    });
    // Keep the chain resolved: a rejected mutation must not poison every write
    // queued behind it. The rejection still reaches this call's caller.
    this._persistQueue = run.then(
      () => undefined,
      () => undefined,
    );
    return run;
  }

  private _networkPassphrase(): string {
    return this.getNetwork() === 'mainnet'
      ? 'Public Global Stellar Network ; September 2015'
      : 'Test SDF Network ; September 2015';
  }

  private _setNetworkState(next: NetworkState): void {
    this._networkState = next;
    const label = next.step === 'connected' ? next.network : next.step;
    this._log.debug(`[PollarClient] network:${label}`);
    for (const cb of this._networkStateListeners) cb(next);
  }

  private _setAuthState(next: AuthState): void {
    this._authState = next;
    this._log.debug(`[PollarClient] auth:${next.step}`);
    // Dispatch a clone: `next.session` is the live `_session` the middleware
    // signs with, so a subscriber that mutates `state.session.token` would
    // otherwise corrupt it. `getAuthState()` already clones; this makes the
    // push path symmetric. (`@pollar/react` dedupes by value, so a fresh object
    // per emission is safe - verified no useSyncExternalStore / ref-dedupe.)
    const snapshot = this._cloneAuthState(next);
    for (const cb of this._authStateListeners) cb(snapshot);
  }

  private _setTransactionState(next: TransactionState): void {
    // Drop a write from a tx whose session was torn down (logout) or replaced
    // (new login) after it started - see `_txStartGen`.
    if (this._sessionGeneration !== this._txStartGen) return;
    this._transactionState = next;
    this._log.debug(`[PollarClient] transaction:${next.step}`);
    for (const cb of this._transactionStateListeners) cb(next);
  }

  /**
   * Reset the tx store + the 4 reactive read stores (txHistory / balance /
   * assets / sessions) to idle and bump their generations. Called on ANY session
   * change - logout (`_clearSession`) AND login-over-login (`_storeSession`, a
   * no-logout account switch) - so the previous user's balance/history/sessions
   * and the last tx's terminal state can't linger or be repopulated by an
   * in-flight fetch that resolves into the new session's store.
   *
   * The tx store is dispatched DIRECTLY (not via `_setTransactionState`) on
   * purpose: re-arming `_txStartGen` to satisfy that method's session-generation guard
   * would also let an in-flight tx's late write through. Leaving `_txStartGen`
   * untouched keeps a late tx write dropped by the guard. Callers must bump
   * `_sessionGeneration` BEFORE calling this (both already do).
   */
  private _resetReactiveStores(): void {
    this._transactionState = { step: 'idle' };
    for (const cb of this._transactionStateListeners) cb(this._transactionState);
    this._txHistoryGen++;
    this._walletBalanceGen++;
    this._enabledAssetsGen++;
    this._sessionsGen++;
    this._setTxHistoryState({ step: 'idle' });
    this._setWalletBalanceState({ step: 'idle' });
    this._setEnabledAssetsState({ step: 'idle' });
    this._setSessionsState({ step: 'idle' });
  }

  /**
   * Threads `buildData` through state transitions. When the user has already
   * called `buildTx`, every subsequent state (signing, signed, submitting,
   * submitted, success, error) should carry the build summary so modal UIs
   * can keep showing "Send 5 USDC to G..." through the whole flow.
   */
  private _currentBuildData(): TxBuildContent | undefined {
    const s = this._transactionState;
    if (!s) return undefined;
    // A terminal step belongs to a FINISHED tx. Between txs the state machine is
    // only reset by `resetTransactionState()` (modal open) or a session change
    // (`_resetReactiveStores`), so without this a standalone signTx/submitTx
    // (no preceding buildTx) would thread the previous tx's buildData into the
    // new one - mislabeling its UI summary. Only carry buildData forward from
    // live, in-progress steps; the composed paths (buildTx->signTx->submitTx) read
    // it while non-terminal (`built`/`signed`), so they're unaffected.
    if (s.step === 'success' || s.step === 'submitted' || s.step === 'error') return undefined;
    if ('buildData' in s && s.buildData) return s.buildData;
    return undefined;
  }
}

import type { PollarLogger } from '../lib/logger';
import type { Storage } from '../storage/types';
import type { PollarPersistedSession, WalletProvisioning } from '../types';

/**
 * Persisted session shape (stored via the injected `Storage` adapter).
 *
 * Compared to the full `/auth/login` response:
 *   - `data.{mail,first_name,last_name,avatar,providers}` is dropped - that
 *     PII is held in memory only on `PollarClient`, fetched from
 *     `/applications/config` after auth.
 *   - All string fields are length-bounded as defense-in-depth: even though
 *     JWT/UUID/Stellar-pubkey shapes are bounded by their own grammars,
 *     bounding here catches hostile or buggy inputs before they hit downstream.
 *
 * Storage keys are namespaced per-`apiKeyHash` so swapping API keys can't
 * cross-contaminate sessions.
 */

const SESSION_SUFFIX = ':session';
const WALLET_TYPE_SUFFIX = ':walletType';
const DPOP_NONCE_SUFFIX = ':dpopNonce';
const DPOP_CLOCK_OFFSET_SUFFIX = ':dpopClockOffset';

/**
 * The only values `wallet.provisioning` may hold.
 *
 * `isValidSession` rejects a session carrying anything else, so a value that
 * reaches storage unchecked costs the user their session on the next reload -
 * every writer runs it through here first.
 */
export function isWalletProvisioning(value: unknown): value is WalletProvisioning {
  return value === 'READY' || value === 'CREATING' || value === 'FAILED' || value === 'NONE';
}

export function sessionStorageKey(apiKeyHash: string): string {
  return `pollar:${apiKeyHash}${SESSION_SUFFIX}`;
}

/**
 * Key for the last server-issued `DPoP-Nonce`.
 *
 * Deliberately NOT removed by `removeStorage`: the nonce is origin-scoped
 * server state, not session state. It is a stateless HMAC that sdk-api accepts
 * for days (24h active + a 3-day rotation overlap, see its lib/dpop-nonce.ts),
 * carries no user identity and grants nothing on its own, so keeping it across
 * page loads and logouts is safe - and it spares every cold start the
 * guaranteed 401 `use_dpop_nonce` challenge it otherwise pays before its first
 * authenticated request. A stale one costs exactly what having none costs: the
 * server answers with a fresh nonce and the middleware retries once.
 */
export function dpopNonceStorageKey(apiKeyHash: string): string {
  return `pollar:${apiKeyHash}${DPOP_NONCE_SUFFIX}`;
}

/**
 * Key for the learned DPoP clock offset (`serverTime - localTime`, in seconds).
 *
 * Kept out of `removeStorage` for the same reason as the nonce: it is a property
 * of the server's clock, not of the session - it carries no user identity and
 * grants nothing on its own. Persisting it means only a genuine cold start pays
 * one rejected proof before the offset is learned; every later load signs its
 * first proof already corrected.
 */
export function dpopClockOffsetStorageKey(apiKeyHash: string): string {
  return `pollar:${apiKeyHash}${DPOP_CLOCK_OFFSET_SUFFIX}`;
}

export function walletTypeStorageKey(apiKeyHash: string): string {
  return `pollar:${apiKeyHash}${WALLET_TYPE_SUFFIX}`;
}

// Bounds are defense-in-depth against a hostile/buggy blob, not a spec limit:
// exceeding one makes the whole session unreadable, so leave real headroom over
// the ~1-2 KB a DPoP-bound JWT actually costs.
const MAX_ACCESS_TOKEN = 8192;
const MAX_REFRESH_TOKEN = 8192;
const MAX_USER_ID = 64;
const MAX_CLIENT_SESSION_ID = 64;
const MAX_STATUS = 64;
const MAX_WALLET_PUBLIC_KEY = 128;
const MAX_WALLET_TYPE = 32;
// base64url(SHA-256) is exactly 43 chars; bound with headroom.
const MAX_DPOP_JKT = 64;
/** Bounds what we accept back from storage as a nonce (sdk-api mints ~60 chars). */
export const MAX_DPOP_NONCE = 512;
/**
 * Bounds the clock offset read back from storage. A day is orders of magnitude
 * past any real skew, so a larger value is a corrupt/hostile blob - and signing
 * with it would push every `iat` outside the server's window, wedging auth until
 * a response re-learns the true offset.
 */
export const MAX_DPOP_CLOCK_OFFSET_SEC = 86_400;
// One wallet per supported chain, with headroom. Bounds the persisted blob so a
// hostile or buggy `wallets[]` can't blow up storage or the validation loop.
const MAX_WALLETS = 16;

const KNOWN_WALLET_TYPES = new Set(['internal', 'smart', 'external']);
const KNOWN_CHAINS = new Set(['STELLAR', 'POLYGON', 'SOLANA']);

/**
 * "Does this build understand the entry at all?" Deliberately NOT the full
 * shape guard - it looks only at the two closed vocabularies a newer server can
 * extend (`type`, `chain`), so `readStorage` can prune entries from the future
 * instead of failing validation on the whole session.
 */
function isKnownWalletShape(value: unknown): boolean {
  if (typeof value !== 'object' || value === null) return false;
  const w = value as Record<string, unknown>;
  if (typeof w['type'] === 'string' && !KNOWN_WALLET_TYPES.has(w['type'])) return false;
  if (typeof w['chain'] === 'string' && !KNOWN_CHAINS.has(w['chain'])) return false;
  return true;
}

function isBoundedString(v: unknown, max: number, allowEmpty = false): v is string {
  if (typeof v !== 'string') return false;
  if (!allowEmpty && v.length === 0) return false;
  return v.length <= max;
}

export function isValidSession(value: unknown, logger: PollarLogger = console): value is PollarPersistedSession {
  if (typeof value !== 'object' || value === null) {
    logger.debug('[PollarClient:session] Invalid session — value is not an object');
    return false;
  }
  const s = value as Record<string, unknown>;

  if (!isBoundedString(s['clientSessionId'], MAX_CLIENT_SESSION_ID)) {
    logger.debug('[PollarClient:session] Invalid session — clientSessionId missing/empty/too long');
    return false;
  }
  if (s['userId'] !== null && !isBoundedString(s['userId'], MAX_USER_ID)) {
    logger.debug('[PollarClient:session] Invalid session — userId must be string|null');
    return false;
  }
  if (!isBoundedString(s['status'], MAX_STATUS)) {
    logger.debug('[PollarClient:session] Invalid session — status must be string');
    return false;
  }

  const token = s['token'];
  if (typeof token !== 'object' || token === null) {
    logger.debug('[PollarClient:session] Invalid session — token missing or not an object');
    return false;
  }
  const t = token as Record<string, unknown>;
  if (!isBoundedString(t['accessToken'], MAX_ACCESS_TOKEN)) {
    logger.debug('[PollarClient:session] Invalid session — token.accessToken missing/empty/too long');
    return false;
  }
  if (!isBoundedString(t['refreshToken'], MAX_REFRESH_TOKEN)) {
    logger.debug('[PollarClient:session] Invalid session — token.refreshToken missing/empty/too long');
    return false;
  }
  if (typeof t['expiresAt'] !== 'number' || !Number.isFinite(t['expiresAt'])) {
    logger.debug('[PollarClient:session] Invalid session — token.expiresAt must be a finite number');
    return false;
  }

  // Optional DPoP key binding (see PollarPersistedSession.dpopJkt). Absent on
  // sessions persisted by older SDKs - never required.
  if (s['dpopJkt'] !== undefined && !isBoundedString(s['dpopJkt'], MAX_DPOP_JKT)) {
    logger.debug('[PollarClient:session] Invalid session — dpopJkt must be a non-empty string if present');
    return false;
  }

  const user = s['user'];
  if (typeof user !== 'object' || user === null) {
    logger.debug('[PollarClient:session] Invalid session — user missing or not an object');
    return false;
  }
  const u = user as Record<string, unknown>;
  if (u['id'] !== undefined && !isBoundedString(u['id'], MAX_USER_ID)) {
    logger.debug('[PollarClient:session] Invalid session — user.id must be string if present');
    return false;
  }
  if (typeof u['ready'] !== 'boolean') {
    logger.debug('[PollarClient:session] Invalid session — user.ready must be boolean');
    return false;
  }

  // The wallet object is always present; `type` discriminates internal (G,
  // platform-managed), smart/passkey (C), and external wallets. `address` is
  // the on-chain address for all types.
  //
  // This guard runs against BOTH the persisted shape and the raw `/auth/login`
  // wire response; both speak the same vocabulary (`internal`), so no alias is
  // accepted here. Sessions persisted by older SDKs carry the legacy
  // `'custodial'` type and a legacy `publicKey` alias - `readStorage` remaps
  // the type and backfills `address` before validation, so those upgrade
  // instead of being rejected.
  if (!isValidWallet(s['wallet'], 'wallet', logger)) return false;

  // `wallets` is optional - sessions persisted before the field existed, and
  // logins against an sdk-api that predates it, simply have none. When present
  // it must be a bounded array whose entries satisfy the same shape as
  // `wallet`, so a caller reading either field gets the same guarantees.
  const wallets = s['wallets'];
  if (wallets !== undefined) {
    if (!Array.isArray(wallets)) {
      logger.debug('[PollarClient:session] Invalid session — wallets must be an array if present');
      return false;
    }
    if (wallets.length > MAX_WALLETS) {
      logger.debug('[PollarClient:session] Invalid session — wallets exceeds the maximum entry count');
      return false;
    }
    for (let i = 0; i < wallets.length; i++) {
      if (!isValidWallet(wallets[i], `wallets[${i}]`, logger)) return false;
    }
  }

  return true;
}

/**
 * Shape guard for a single persisted wallet, used for both the back-compat
 * `wallet` field and every entry of `wallets[]`. `label` only names the field
 * in the debug log.
 */
function isValidWallet(value: unknown, label: string, logger: PollarLogger): boolean {
  if (typeof value !== 'object' || value === null) {
    logger.debug(`[PollarClient:session] Invalid session — ${label} missing or not an object`);
    return false;
  }
  const w = value as Record<string, unknown>;
  if (w['type'] !== 'internal' && w['type'] !== 'smart' && w['type'] !== 'external') {
    logger.debug(`[PollarClient:session] Invalid session — ${label}.type must be internal|smart|external`);
    return false;
  }
  if (w['provider'] !== undefined && typeof w['provider'] !== 'string') {
    logger.debug(`[PollarClient:session] Invalid session — ${label}.provider must be a string if present`);
    return false;
  }
  if (w['address'] !== null && !isBoundedString(w['address'], MAX_WALLET_PUBLIC_KEY)) {
    logger.debug(`[PollarClient:session] Invalid session — ${label}.address must be string|null`);
    return false;
  }
  if (w['chain'] !== undefined && w['chain'] !== 'STELLAR' && w['chain'] !== 'POLYGON' && w['chain'] !== 'SOLANA') {
    logger.debug(`[PollarClient:session] Invalid session — ${label}.chain must be STELLAR|POLYGON|SOLANA if present`);
    return false;
  }
  if (w['existsOnStellar'] !== undefined && typeof w['existsOnStellar'] !== 'boolean') {
    logger.debug(`[PollarClient:session] Invalid session — ${label}.existsOnStellar must be boolean if present`);
    return false;
  }
  if (w['provisioning'] !== undefined && !isWalletProvisioning(w['provisioning'])) {
    logger.debug(
      `[PollarClient:session] Invalid session — ${label}.provisioning must be READY|CREATING|FAILED|NONE if present`,
    );
    return false;
  }
  if (w['createdAt'] !== undefined && (typeof w['createdAt'] !== 'number' || !Number.isFinite(w['createdAt']))) {
    logger.debug(`[PollarClient:session] Invalid session — ${label}.createdAt must be a finite number if present`);
    return false;
  }
  if (w['linkedAt'] !== undefined && (typeof w['linkedAt'] !== 'number' || !Number.isFinite(w['linkedAt']))) {
    logger.debug(`[PollarClient:session] Invalid session — ${label}.linkedAt must be a finite number if present`);
    return false;
  }
  return true;
}

export async function readStorage(
  storage: Storage,
  apiKeyHash: string,
  logger: PollarLogger = console,
): Promise<PollarPersistedSession | null> {
  const raw = await storage.get(sessionStorageKey(apiKeyHash));
  if (!raw) return null;

  try {
    const session = JSON.parse(raw) as unknown;
    // Migrate sessions persisted by older SDKs (<=0.8.x): they stored the wallet
    // address under the legacy `publicKey` key, and persisted the old wire type
    // `'custodial'` (the wire now emits `'internal'` directly). Backfill
    // `address` and remap the type so they pass validation and survive the
    // upgrade instead of forcing a re-login.
    if (typeof session === 'object' && session !== null) {
      const w = (session as { wallet?: Record<string, unknown> }).wallet;
      if (w && w['address'] == null && typeof w['publicKey'] === 'string') {
        w['address'] = w['publicKey'];
      }
      if (w && w['type'] === 'custodial') {
        w['type'] = 'internal';
      }
      // Forward compatibility: a row written by a NEWER SDK - or by a login
      // against a newer sdk-api - can carry `wallets[]` entries for a chain or
      // wallet type this build does not model. Pruning the unknown entries keeps
      // the session usable; rejecting the whole row would strand the user
      // logged-out on nothing worse than a vocabulary it has never seen.
      const list = (session as { wallets?: unknown }).wallets;
      if (Array.isArray(list)) {
        const known = list.filter((entry) => isKnownWalletShape(entry));
        if (known.length !== list.length) {
          logger.warn('[PollarClient:session] Pruned wallets[] entries this SDK does not recognize', {
            dropped: list.length - known.length,
          });
          (session as { wallets?: unknown }).wallets = known;
        }
      }
    }
    if (!isValidSession(session, logger)) {
      // Deliberately NOT removed. The row is shared by every document on the
      // origin, and in a browser the removal emits a `storage` event that tears
      // the session down in all of them - so one document running an older
      // build, or hitting a bound, would log everybody out. A row this build
      // cannot read is simply ignored; the next login overwrites it.
      logger.warn('[PollarClient:session] Stored session is invalid — ignoring it (left in storage)');
      return null;
    }
    if (session.token.expiresAt * 1000 < Date.now()) {
      // AT expired - keep the session row so we can attempt /refresh; the
      // caller's refresh path will clear if refresh itself fails.
      return session;
    }
    return session;
  } catch (error) {
    // Same reasoning as the invalid-session branch: never delete a shared row we
    // merely failed to read.
    logger.error('[PollarClient:session] Failed to parse session from storage', error);
    return null;
  }
}

export async function writeStorage(storage: Storage, apiKeyHash: string, session: PollarPersistedSession): Promise<void> {
  await storage.set(sessionStorageKey(apiKeyHash), JSON.stringify(session));
}

export async function removeStorage(storage: Storage, apiKeyHash: string): Promise<void> {
  await storage.remove(sessionStorageKey(apiKeyHash));
  await storage.remove(walletTypeStorageKey(apiKeyHash));
}

export async function writeWalletType(storage: Storage, apiKeyHash: string, type: string): Promise<void> {
  if (type.length > MAX_WALLET_TYPE) {
    throw new Error(`[PollarClient:session] walletType too long: ${type.length} > ${MAX_WALLET_TYPE}`);
  }
  await storage.set(walletTypeStorageKey(apiKeyHash), type);
}

export async function readWalletType(storage: Storage, apiKeyHash: string): Promise<string | null> {
  return storage.get(walletTypeStorageKey(apiKeyHash));
}

import { PollarApiClient } from '../api/client';
import { abortError, throwIfAborted } from '../lib/abort';
import type { PollarLogger } from '../lib/logger';

/** Terminal session-status conditions, surfaced identically by the SSE stream
 *  (as `error` events) and the poll endpoint (as 404 / 410). When either occurs
 *  the session can never become ready, so the wait stops and the auth flow
 *  resets to an error state instead of retrying forever. */
export type SessionStatusErrorCode = 'INVALID_CLIENT_SESSION_ID' | 'EXPIRED_CLIENT_ID' | 'LOGIN_TIMEOUT';

/**
 * Overall deadline for an interactive login to reach a ready session. Bounds an
 * abandoned flow (OAuth popup closed, user walked away, backend stuck in a
 * non-terminal status) so the poll/stream can't run forever. 5 minutes is
 * generous for a hosted login with 2FA while still failing a dead flow.
 */
export const LOGIN_FLOW_TIMEOUT_MS = 5 * 60 * 1000;

export class SessionStatusError extends Error {
  constructor(readonly code: SessionStatusErrorCode) {
    super(`[PollarClient] Session status terminal: ${code}`);
    this.name = 'SessionStatusError';
  }
}

/** Returns the terminal code if `parsed` is an SSE `error` event payload
 *  (`{ error: '...' }`), otherwise null. */
function terminalStatusCode(parsed: unknown): SessionStatusErrorCode | null {
  const err = (parsed as { error?: unknown } | null)?.error;
  if (err === 'INVALID_CLIENT_SESSION_ID' || err === 'EXPIRED_CLIENT_ID') return err;
  return null;
}

function abortableDelay(ms: number, signal: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    const t = setTimeout(resolve, ms);
    signal.addEventListener(
      'abort',
      () => {
        clearTimeout(t);
        reject(abortError());
      },
      { once: true },
    );
  });
}

const MAX_BACKOFF_MS = 5_000;

/**
 * Poll the session-status SSE stream until `check` returns true.
 *
 * On consecutive failures the retry delay doubles up to a 5 s cap; any
 * received chunk resets it to the floor. The happy path is unchanged.
 */
export async function streamUntilFound(
  api: PollarApiClient,
  clientSessionId: string,
  check: (data: Record<string, unknown>) => boolean,
  retryDelayMs = 200,
  signal?: AbortSignal,
  logger: PollarLogger = console,
): Promise<Record<string, unknown>> {
  let backoff = retryDelayMs;
  const sleep = async (ms: number): Promise<void> => {
    if (ms <= 0) return;
    if (signal) await abortableDelay(ms, signal);
    else await new Promise((r) => setTimeout(r, ms));
  };

  while (true) {
    throwIfAborted(signal);

    let data, error;
    try {
      ({ data, error } = await api.GET('/auth/session/status/{clientSessionId}', {
        params: { path: { clientSessionId } },
        parseAs: 'stream',
        signal: signal ?? null,
      }));
    } catch (e) {
      if (e instanceof Error && e.name === 'AbortError') throw e;
      logger.debug('[PollarClient:stream] session-status request failed; will retry', e);
    }

    if (error || !data) {
      await sleep(backoff);
      backoff = Math.min(backoff * 2, MAX_BACKOFF_MS);
      continue;
    }

    const reader = data.getReader();
    const decoder = new TextDecoder();
    let sawAnyChunk = false;

    try {
      while (true) {
        throwIfAborted(signal);
        const { done, value } = await reader.read();
        if (done) break;
        sawAnyChunk = true;

        const chunk = decoder.decode(value);
        for (const message of chunk.split('\n\n').filter(Boolean)) {
          const dataLine = message.split('\n').find((l) => l.startsWith('data:'));
          if (!dataLine) continue;
          let parsed: Record<string, unknown>;
          try {
            parsed = JSON.parse(dataLine.slice('data:'.length).trim());
          } catch {
            // partial chunk - keep reading
            continue;
          }
          // Terminal `error` event (invalid / expired session): stop and surface.
          const terminal = terminalStatusCode(parsed);
          if (terminal) throw new SessionStatusError(terminal);
          if (check(parsed)) {
            return parsed;
          }
        }
      }
    } catch (e) {
      if (e instanceof Error && e.name === 'AbortError') throw e;
      if (e instanceof SessionStatusError) throw e;
      logger.debug('[PollarClient:stream] session-status stream read failed; will retry', e);
    } finally {
      reader.releaseLock();
    }

    // A connection that delivered real data resets the backoff; a stream
    // that opened and immediately closed counts as failure.
    if (sawAnyChunk) backoff = retryDelayMs;
    else backoff = Math.min(backoff * 2, MAX_BACKOFF_MS);

    // Always wait the computed backoff before reconnecting. A data-bearing
    // close already reset it to the floor (retryDelayMs), so the happy-path
    // reconnect stays snappy; the failure paths - including a mid-stream read
    // error caught above - now back off instead of spinning in a tight
    // reconnect loop that hammers the server.
    await sleep(backoff);
  }
}

/** Success envelope shape of `GET /auth/session/status/{id}/poll`. */
interface StatusPollEnvelope {
  success?: boolean;
  code?: string;
  content?: Record<string, unknown>;
}

/**
 * Non-streaming counterpart to {@link streamUntilFound}. Repeatedly GETs the
 * one-shot `/auth/session/status/{clientSessionId}/poll` endpoint until `check`
 * returns true on the response `content`.
 *
 * Used on runtimes where `fetch` does not expose a readable `response.body`
 * (React Native / Hermes), so the SSE reader in `streamUntilFound` is
 * unavailable. Uses the global `fetch` directly (not `openapi-fetch`) because
 * the status endpoint is public/pre-auth and needs no DPoP middleware.
 *
 * Backoff matches the SSE path: the delay doubles on transient failures up to a
 * 5 s cap and resets to the floor after any successful response.
 */
export async function pollUntilFound(
  baseUrl: string,
  clientSessionId: string,
  check: (data: Record<string, unknown>) => boolean,
  intervalMs = 500,
  signal?: AbortSignal,
  logger: PollarLogger = console,
): Promise<Record<string, unknown>> {
  const url = `${baseUrl}/auth/session/status/${encodeURIComponent(clientSessionId)}/poll`;
  let backoff = intervalMs;
  const sleep = async (ms: number): Promise<void> => {
    if (ms <= 0) return;
    if (signal) await abortableDelay(ms, signal);
    else await new Promise((r) => setTimeout(r, ms));
  };

  while (true) {
    throwIfAborted(signal);

    let envelope: StatusPollEnvelope | null = null;
    let httpStatus = 0;
    try {
      const response = await fetch(url, { headers: { accept: 'application/json' }, signal: signal ?? null });
      httpStatus = response.status;
      envelope = (await response.json().catch(() => null)) as StatusPollEnvelope | null;
    } catch (e) {
      if (e instanceof Error && e.name === 'AbortError') throw e;
      logger.debug('[PollarClient:stream] session-status poll failed; will retry', e);
    }

    // Terminal: the session is gone (404 / INVALID) or expired (410 / EXPIRED).
    // It can never become ready, so stop and surface - the caller resets the
    // login to an error state. Mirrors the SSE stream's terminal `error` events.
    if (httpStatus === 404 || envelope?.code === 'INVALID_CLIENT_SESSION_ID') {
      throw new SessionStatusError('INVALID_CLIENT_SESSION_ID');
    }
    if (httpStatus === 410 || envelope?.code === 'EXPIRED_CLIENT_ID') {
      throw new SessionStatusError('EXPIRED_CLIENT_ID');
    }

    if (envelope?.success && envelope.content && check(envelope.content)) {
      return envelope.content;
    }

    // A response (even a transient non-terminal error) resets the backoff floor;
    // a network failure (no response) backs off up to the cap.
    if (envelope) backoff = intervalMs;
    else backoff = Math.min(backoff * 2, MAX_BACKOFF_MS);
    await sleep(backoff);
  }
}

/**
 * Wait until the client session reaches a state where `check` passes, using the
 * transport appropriate to the runtime: the SSE stream on web (`useStreaming`),
 * or one-shot polling on React Native. Both resolve with the matched status
 * `content` payload; the calling auth flow does not care which transport ran.
 */
export function waitForSessionReady(args: {
  api: PollarApiClient;
  baseUrl: string;
  clientSessionId: string;
  check: (data: Record<string, unknown>) => boolean;
  useStreaming: boolean;
  retryDelayMs?: number;
  signal?: AbortSignal;
  logger?: PollarLogger;
  timeoutMs?: number;
}): Promise<Record<string, unknown>> {
  const { api, baseUrl, clientSessionId, check, useStreaming, retryDelayMs, signal, logger = console } = args;
  const timeoutMs = args.timeoutMs ?? LOGIN_FLOW_TIMEOUT_MS;

  // Combine the caller's signal with an overall deadline: the underlying
  // poll/stream loops only stop on a terminal status, success, or abort, so
  // without this an abandoned login would run forever. We abort a derived
  // controller on timeout (which unblocks the in-flight fetch / SSE read and
  // the backoff sleep) and re-surface that abort as a `LOGIN_TIMEOUT` terminal,
  // distinct from a user-initiated cancel (which stays an AbortError).
  const controller = new AbortController();
  const onExternalAbort = (): void => controller.abort();
  if (signal) {
    if (signal.aborted) controller.abort();
    else signal.addEventListener('abort', onExternalAbort, { once: true });
  }
  let timedOut = false;
  const timer = setTimeout(() => {
    timedOut = true;
    controller.abort();
  }, timeoutMs);

  const run = useStreaming
    ? streamUntilFound(api, clientSessionId, check, retryDelayMs ?? 200, controller.signal, logger)
    : pollUntilFound(baseUrl, clientSessionId, check, retryDelayMs ?? 500, controller.signal, logger);

  return run
    .catch((err: unknown) => {
      if (timedOut && err instanceof Error && err.name === 'AbortError') {
        throw new SessionStatusError('LOGIN_TIMEOUT');
      }
      throw err;
    })
    .finally(() => {
      clearTimeout(timer);
      if (signal) signal.removeEventListener('abort', onExternalAbort);
    });
}

import { base64urlEncode, base64urlEncodeString } from './lib/base64url';
import { randomUUID } from './lib/random-uuid';
import { sha256 } from './lib/sha256';
import type { KeyManager, PublicEcJwk } from './keys/types';

/**
 * RFC 9449 DPoP proof builder.
 *
 * Produces a compact JWS that the consumer attaches as the `DPoP` HTTP
 * header. The header `jwk` is the public part of the SDK's per-session
 * keypair; the server verifies the signature, validates the `htm` / `htu` /
 * `iat` / `jti` / optional `nonce` / optional `ath` claims, and matches the
 * proof's JWK thumbprint against the access token's `cnf.jkt` claim.
 *
 * Server-issued nonce flow (RFC 9449 section 8/section 9): the server may respond with
 * `WWW-Authenticate: DPoP ... error="use_dpop_nonce"` plus a `DPoP-Nonce`
 * header. The client should re-build the proof with the new nonce and retry.
 * `buildProof` accepts an optional nonce; the SDK client tracks it across
 * requests and feeds it back here.
 *
 * The last seen `DPoP-Nonce` is stored verbatim and embedded in the next
 * proof. The server validates it as an HMAC token, so an attacker who
 * injects an arbitrary nonce cannot escalate - verification fails and the
 * server replies with a fresh nonce on the next request.
 */

export interface BuildProofArgs {
  /** HTTP method, e.g. `"GET"`. Will be uppercased before signing. */
  htm: string;
  /**
   * HTTP target URI. Will be normalized per RFC 3986 section 6.2 (lowercase scheme
   * + host, default port elided, query+fragment+userinfo stripped, path
   * dot-segments resolved, trailing slash preserved exactly as provided).
   */
  htu: string;
  /**
   * Access token to bind the proof to (its base64url(SHA-256) goes in the
   * `ath` claim). Omit for proofs sent to the token endpoint per RFC 9449
   * section 5 / section 6.1 (those proofs MUST NOT include `ath`).
   */
  accessToken?: string;
  /**
   * Server-issued DPoP nonce, if the server has previously challenged this
   * client with `WWW-Authenticate: DPoP ... error="use_dpop_nonce"`. RFC
   * 9449 section 8.
   */
  nonce?: string;
  /**
   * Seconds to add to the local clock when stamping `iat`, to compensate for a
   * skewed device clock (`serverTime - localTime`, learned from the `Date`
   * response header). Defaults to 0. Keeps `iat` inside the server's acceptance
   * window even when the device clock is wrong, avoiding proof rejections.
   */
  clockOffsetSec?: number;
}

interface ProofHeader {
  typ: 'dpop+jwt';
  alg: 'ES256';
  jwk: PublicEcJwk;
}

interface ProofPayload {
  jti: string;
  htm: string;
  htu: string;
  iat: number;
  ath?: string;
  nonce?: string;
}

/**
 * Build a DPoP proof JWS for the given request. Returns the compact-form
 * JWS string (`<header>.<payload>.<signature>`).
 */
export async function buildProof(args: BuildProofArgs, keyManager: KeyManager): Promise<string> {
  const jwk = await keyManager.getPublicJwk();

  const header: ProofHeader = {
    typ: 'dpop+jwt',
    alg: 'ES256',
    jwk,
  };

  // Sanitize the offset before it reaches `iat`: a NaN/Infinity/fractional value
  // (`Math.max(1, NaN) === NaN`) would serialize to a `null`/invalid `iat` and
  // break verification. Coerce to a finite integer, else 0.
  const offsetSec = Number.isFinite(args.clockOffsetSec) ? Math.trunc(args.clockOffsetSec as number) : 0;
  const payload: ProofPayload = {
    jti: randomUUID(),
    htm: args.htm.toUpperCase(),
    htu: normalizeHtu(args.htu),
    // Floor at 1 so a pathological offset can never produce a zero/negative iat.
    iat: Math.max(1, Math.floor(Date.now() / 1000) + offsetSec),
  };

  if (args.accessToken !== undefined && args.accessToken !== '') {
    payload.ath = base64urlEncode(await sha256(new TextEncoder().encode(args.accessToken)));
  }
  if (args.nonce !== undefined && args.nonce !== '') {
    payload.nonce = args.nonce;
  }

  const encodedHeader = base64urlEncodeString(JSON.stringify(header));
  const encodedPayload = base64urlEncodeString(JSON.stringify(payload));
  const signingInput = `${encodedHeader}.${encodedPayload}`;

  const signature = await keyManager.sign(new TextEncoder().encode(signingInput));
  const encodedSignature = base64urlEncode(signature);

  return `${signingInput}.${encodedSignature}`;
}

/**
 * Normalize an HTTP URI for use as the `htu` claim.
 *
 * RFC 9449 section 4.3 + RFC 3986 section 6.2:
 *  - lowercase scheme + host
 *  - elide default port (`:443` for https, `:80` for http)
 *  - strip userinfo (never appears in `htu`)
 *  - strip query + fragment
 *  - apply path dot-segment removal (handled by the URL constructor)
 *  - **preserve trailing slash exactly** - `/foo` and `/foo/` are distinct
 *    paths per RFC 3986 section 6 and must round-trip identically.
 *  - preserve IPv6 brackets in host
 *
 * Both client and server must apply the same normalization so the `htu`
 * claim matches deterministically.
 */
export function normalizeHtu(rawUrl: string): string {
  let url: URL;
  try {
    url = new URL(rawUrl);
  } catch {
    // Defensive fallback: strip query + fragment but otherwise return
    // unchanged. A poorly-formed URL is the caller's bug.
    return rawUrl.split('#')[0]!.split('?')[0]!;
  }
  const scheme = url.protocol.toLowerCase(); // includes trailing ':'
  const host = url.hostname.toLowerCase(); // already includes brackets for IPv6
  let port = url.port;
  if ((scheme === 'https:' && port === '443') || (scheme === 'http:' && port === '80')) {
    port = '';
  }
  const portPart = port ? `:${port}` : '';
  return `${scheme}//${host}${portPart}${url.pathname}`;
}

// React Native entry point. Always uses `NobleKeyManager` (pure-JS ECDSA via
// `@noble/curves`) backed by the injected `Storage` adapter (Keychain /
// SecureStore).
//
// Why not WebCrypto, even when `crypto.subtle` is present? A polyfill like
// react-native-quick-crypto exposes `crypto.subtle.generateKey/sign`, but
// `WebCryptoKeyManager` persists the keypair in IndexedDB and generates
// non-extractable keys - and in React Native there is no IndexedDB AND
// non-extractable keys can't be serialized to the Storage adapter. Picking it
// here would mean a brand-new DPoP keypair on every app launch: the JWK
// thumbprint changes each start, so every sender-constrained access/refresh
// token gets rejected - a forced logout loop. Noble persists the 32-byte
// private scalar through `Storage`, so the key survives restarts. On RN,
// Noble is the only manager that can persist.
//
// Resolved automatically by Metro and other RN-aware bundlers via the
// `"react-native"` condition in `package.json#exports`.

import { _setDefaultKeyManagerFactory } from './keys/factory';
import { NobleKeyManager } from './keys/noble';

_setDefaultKeyManagerFactory((storage, apiKey) => {
  return new NobleKeyManager(storage, apiKey);
});

export * from './public';
export { NobleKeyManager } from './keys/noble';

// Web/Node/Workers entry point. Registers a `WebCryptoKeyManager`-only
// factory at module load so `PollarClient` resolves the WebCrypto-backed
// manager without importing `NobleKeyManager` (and transitively
// `@noble/curves`). Bundlers targeting browsers pick this entry via the
// default `"import"` / `"require"` conditions in `package.json#exports` and
// produce a noble-free bundle.
//
// React Native applications resolve `index.rn.ts` instead via the
// `"react-native"` condition.

import { _setDefaultKeyManagerFactory } from './keys/factory';
import { WebCryptoKeyManager } from './keys/web-crypto';

_setDefaultKeyManagerFactory((_storage, apiKey) => new WebCryptoKeyManager(apiKey));

export * from './public';

import type { Storage } from '../storage/types';
import type { KeyManager } from './types';

/**
 * Module-level registry for the platform-default `KeyManager` factory. Each
 * entry point (web `index.ts`, RN `index.rn.ts`) registers its own factory
 * at module-load time, so that `PollarClient` can resolve a default manager
 * without statically importing both implementations into every bundle.
 *
 * The split exists because `NobleKeyManager` pulls in `@noble/curves`, which
 * we don't want to ship to browser bundles when WebCrypto's ECDSA is
 * already available natively. Bundlers tree-shake the unused entry's noble
 * import; the RN entry keeps the pure-JS fallback.
 */

type KeyManagerFactory = (storage: Storage, apiKey: string) => KeyManager;

let _factory: KeyManagerFactory | null = null;

/**
 * Register the platform-default factory. Called as a top-level side effect
 * from the entry-point module (`src/index.ts` or `src/index.rn.ts`).
 * Intentionally underscore-prefixed: not part of the public API.
 */
export function _setDefaultKeyManagerFactory(factory: KeyManagerFactory): void {
  _factory = factory;
}

/**
 * Construct the default `KeyManager` for the current runtime. Throws if no
 * factory has been registered - that only happens if `@pollar/core` was
 * imported in a way that bypassed the entry-point module (a bundler or
 * test setup bug).
 */
export function defaultKeyManager(storage: Storage, apiKey: string): KeyManager {
  if (!_factory) {
    throw new Error(
      '[PollarClient] No default KeyManager factory registered. ' +
        'Did you import from "@pollar/core" via a non-standard path?',
    );
  }
  return _factory(storage, apiKey);
}

import { p256 } from '@noble/curves/nist';
import { hashApiKey } from '../lib/api-key-hash';
import { base64urlDecode, base64urlEncode } from '../lib/base64url';
import { sha256 } from '../lib/sha256';
import type { Storage } from '../storage/types';
import { computeJwkThumbprint } from './thumbprint';
import type { KeyManager, PublicEcJwk } from './types';

/**
 * `KeyManager` backed by `@noble/curves` (pure-JS ECDSA P-256) + an injected
 * `Storage` adapter. Used in React Native, where `WebCryptoKeyManager` can't
 * be: its non-extractable keys can't be serialized to the `Storage` adapter
 * (and RN has no IndexedDB), so the keypair would be regenerated every launch
 * - see the rationale in `index.rn.ts`. The 32-byte private scalar is
 * base64url-encoded and stored through the `Storage` adapter (Keychain /
 * SecureStore in production).
 *
 * React Native: requires `react-native-get-random-values` to be imported at
 * app entry so `crypto.getRandomValues` is available for `randomPrivateKey`.
 *
 * Threat-model note: unlike `WebCryptoKeyManager`, the private scalar lives
 * as raw bytes inside the storage adapter. A device-level compromise that
 * can read Keychain (jailbreak / root / debug bridge) can exfiltrate the
 * key. For higher assurance, ship a hardware-backed key adapter that holds
 * the key inside Secure Enclave / StrongBox (planned for a future minor).
 */

// Prefix of the storage key; the value stored under it is the base64url-encoded
// private scalar (32 bytes -> ~43 chars).
const STORAGE_KEY_PREFIX = 'pollar:dpop-key:';

export class NobleKeyManager implements KeyManager {
  private readonly storage: Storage;
  private readonly apiKey: string;
  private apiKeyHash: string | null = null;
  private privateKey: Uint8Array | null = null;
  private publicJwk: PublicEcJwk | null = null;
  private thumbprint: string | null = null;
  /** Cached in-flight init - see `WebCryptoKeyManager` for the rationale. */
  private _initPromise: Promise<void> | null = null;

  constructor(storage: Storage, apiKey: string) {
    this.storage = storage;
    this.apiKey = apiKey;
  }

  private get storageKey(): string {
    if (!this.apiKeyHash) {
      throw new Error('[PollarClient:keys] init() must be called before storage access');
    }
    return `${STORAGE_KEY_PREFIX}${this.apiKeyHash}`;
  }

  /**
   * Idempotent and safe under concurrency. Other methods auto-await this so
   * the manager is self-healing if `init()` was never explicitly invoked.
   */
  async init(): Promise<void> {
    // All three fields, not just the scalar - see `WebCryptoKeyManager.init`:
    // `_doInit` assigns `privateKey`/`publicJwk` and only then awaits the
    // thumbprint, so a caller in that window must join the in-flight init
    // instead of early-returning into a half-built manager.
    if (this.privateKey && this.publicJwk && this.thumbprint) return;
    if (!this._initPromise) {
      this._initPromise = this._doInit().catch((err) => {
        // Clear the promise so the next call retries. The error propagates to
        // the caller - `PollarClient` logs it through its configured logger, so
        // we don't double-log (raw, ungated) here.
        this._initPromise = null;
        throw err;
      });
    }
    return this._initPromise;
  }

  private async _doInit(): Promise<void> {
    if (!this.apiKeyHash) {
      this.apiKeyHash = await hashApiKey(this.apiKey);
    }

    let priv: Uint8Array | null = null;
    try {
      const stored = await this.storage.get(this.storageKey);
      if (stored) {
        const decoded = base64urlDecode(stored);
        if (decoded.length === 32) priv = decoded;
      }
    } catch {
      priv = null;
    }

    if (!priv) {
      priv = p256.utils.randomPrivateKey();
      try {
        await this.storage.set(this.storageKey, base64urlEncode(priv));
      } catch {
        // Persistence failed; in-memory key still works for the current session.
      }
    }

    this.privateKey = priv;

    // Uncompressed public key: 65 bytes, 0x04 || X(32) || Y(32).
    const pub = p256.getPublicKey(priv, false);
    if (pub.length !== 65 || pub[0] !== 0x04) {
      throw new Error('[PollarClient:keys] Unexpected public key format from @noble/curves');
    }

    this.publicJwk = {
      kty: 'EC',
      crv: 'P-256',
      x: base64urlEncode(pub.slice(1, 33)),
      y: base64urlEncode(pub.slice(33, 65)),
    };
    this.thumbprint = await computeJwkThumbprint(this.publicJwk);
  }

  async reset(): Promise<void> {
    try {
      if (this.apiKeyHash) await this.storage.remove(this.storageKey);
    } catch {
      // Best-effort.
    }
    this.privateKey = null;
    this.publicJwk = null;
    this.thumbprint = null;
    this._initPromise = null;
  }

  /**
   * Re-persist the private scalar and verify it actually landed in storage.
   * Mirrors `WebCryptoKeyManager.ensurePersisted` - see there for rationale.
   * Returns `false` when the adapter can't durably hold the key, so the login
   * flow can warn that the session will not survive a relaunch.
   */
  async ensurePersisted(): Promise<boolean> {
    if (!this.privateKey) await this.init();
    if (!this.privateKey) return false;
    try {
      const encoded = base64urlEncode(this.privateKey);
      await this.storage.set(this.storageKey, encoded);
      return (await this.storage.get(this.storageKey)) === encoded;
    } catch {
      return false;
    }
  }

  /**
   * Drop the in-memory cache; the next operation re-runs `init()` and adopts
   * whatever the storage adapter holds. Never touches persistent storage -
   * that's `reset()`. Mirrors `WebCryptoKeyManager.resync`.
   */
  resync(): void {
    this.privateKey = null;
    this.publicJwk = null;
    this.thumbprint = null;
    this._initPromise = null;
  }

  async getPublicJwk(): Promise<PublicEcJwk> {
    if (!this.publicJwk) await this.init();
    if (!this.publicJwk) {
      throw new Error('[PollarClient:keys] Keypair initialization failed; getPublicJwk unavailable');
    }
    return { kty: this.publicJwk.kty, crv: this.publicJwk.crv, x: this.publicJwk.x, y: this.publicJwk.y };
  }

  async getThumbprint(): Promise<string> {
    if (!this.thumbprint) await this.init();
    if (!this.thumbprint) {
      throw new Error('[PollarClient:keys] Keypair initialization failed; getThumbprint unavailable');
    }
    return this.thumbprint;
  }

  async sign(payload: Uint8Array): Promise<Uint8Array> {
    if (!this.privateKey) await this.init();
    if (!this.privateKey) {
      throw new Error('[PollarClient:keys] Keypair initialization failed; sign unavailable');
    }
    // Two-step: hash with `@noble/hashes` SHA-256, then sign the digest with
    // `prehash: false`. `p256.sign(msg)` with default prehash uses noble's
    // own internal preprocessing whose output is not bit-equivalent to a
    // simple SHA-256, so we explicitly compute the digest ourselves to
    // match standard JOSE ES256 verification.
    const digest = await sha256(payload);
    const signature = p256.sign(digest, this.privateKey, { prehash: false });
    // 64-byte r||s, exactly the JOSE/IEEE P1363 format JWS ES256 expects.
    return signature.toCompactRawBytes();
  }
}

import { base64urlEncode } from '../lib/base64url';
import { sha256 } from '../lib/sha256';
import type { PublicEcJwk } from './types';

/**
 * Compute the RFC 7638 JWK thumbprint for an EC P-256 public JWK.
 *
 * Algorithm (RFC 7638 section 3):
 *  1. Build a JSON object containing ONLY the required members of the JWK,
 *     ordered lexicographically by member name (Unicode code point).
 *     For EC keys, that's exactly {crv, kty, x, y}.
 *  2. Serialize to UTF-8 with no whitespace and no line breaks.
 *  3. Hash with SHA-256.
 *  4. Base64url-encode the hash (no padding).
 *
 * Common bugs guarded against:
 * - Including extra fields (`alg`, `use`, `kid`, `ext`, `key_ops`).
 * - Wrong member ordering (must be lex by Unicode code point).
 * - Padded base64 instead of base64url unpadded.
 * - Using `JSON.stringify(jwk)` of an arbitrary-key-order object - we build
 *   a fresh literal in canonical order to make the order explicit and not
 *   rely on V8's insertion-order semantics.
 */
export async function computeJwkThumbprint(jwk: PublicEcJwk): Promise<string> {
  if (jwk.kty !== 'EC' || jwk.crv !== 'P-256' || !jwk.x || !jwk.y) {
    throw new Error('[PollarClient:thumbprint] Expected EC P-256 JWK with x and y');
  }
  // Build the canonical string by hand so member order is unambiguous.
  // Lex order of EC required members: 'crv' < 'kty' < 'x' < 'y'.
  const canonical = `{"crv":"${jwk.crv}","kty":"${jwk.kty}","x":"${jwk.x}","y":"${jwk.y}"}`;
  const digest = await sha256(new TextEncoder().encode(canonical));
  return base64urlEncode(digest);
}

/**
 * Normalize a base64 string to unpadded base64url. Web Crypto's
 * `exportKey('jwk')` is spec'd to return base64url, but some React Native
 * `crypto.subtle` polyfills diverge: standard base64 (`+`/`/`), `=` padding,
 * or - in the case of `react-native-quick-crypto` - a stray `.` in the
 * padding position (observed: `"...dy_c."`). Any of those characters is invalid
 * in a JWK member: RFC 7638 thumbprinting and servers that validate `x`/`y`
 * as base64url (`^[A-Za-z0-9_-]+$`) reject them, and the `cnf.jkt` thumbprint
 * silently diverges from the server's. Real browsers already return base64url,
 * so this is a no-op there.
 *
 * We map `+`/`/` to their url-safe equivalents, then strip every remaining
 * character outside the base64url alphabet (`=` padding, `.`, whitespace).
 * Valid base64url never contains those, so a global strip can't corrupt a
 * well-formed value.
 */
function toBase64url(value: string): string {
  return value
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/[^A-Za-z0-9_-]/g, '');
}

/**
 * Strip a JWK to only the four required EC public members and normalize the
 * coordinates to unpadded base64url. Useful when the input came from
 * `crypto.subtle.exportKey('jwk', publicKey)` which adds `ext` / `key_ops`
 * (and, under some RN polyfills, non-base64url coordinates). Returns a fresh
 * object - never mutates input.
 */
export function canonicalEcJwk(jwk: { kty?: string; crv?: string; x?: string; y?: string }): PublicEcJwk {
  if (jwk.kty !== 'EC' || jwk.crv !== 'P-256' || typeof jwk.x !== 'string' || typeof jwk.y !== 'string') {
    throw new Error('[PollarClient:thumbprint] Source JWK is not an EC P-256 public key');
  }
  return { kty: 'EC', crv: 'P-256', x: toBase64url(jwk.x), y: toBase64url(jwk.y) };
}

/**
 * Public JWK shape for an EC P-256 key. Only the four required members for
 * RFC 7638 thumbprint computation; never includes private fields or extras
 * like `alg` / `use` / `kid`.
 */
export interface PublicEcJwk {
  kty: 'EC';
  crv: 'P-256';
  /** Base64url-encoded big-endian X coordinate (32 bytes). */
  x: string;
  /** Base64url-encoded big-endian Y coordinate (32 bytes). */
  y: string;
}

/**
 * Manages the per-session ECDSA P-256 keypair used to sign DPoP proofs.
 *
 * Implementations:
 * - `WebCryptoKeyManager` (web): non-extractable `CryptoKey` persisted in
 *   IndexedDB. Private key bytes never leave the browser's crypto context.
 * - `NobleKeyManager` (React Native): private scalar bytes stored through an
 *   injected `Storage` adapter (Keychain / SecureStore). Pure-JS ECDSA via
 *   `@noble/curves`.
 */
export interface KeyManager {
  /**
   * Load an existing key for this session or generate a new one. Idempotent.
   * Must be called before `getPublicJwk`, `getThumbprint`, or `sign`.
   */
  init(): Promise<void>;

  /**
   * Destroy the key. Removes it from persistent storage and clears any
   * cached state. Used on logout.
   */
  reset(): Promise<void>;

  /**
   * The public JWK that goes into the DPoP proof header. Returns a fresh
   * object every call (callers may mutate without affecting the manager).
   */
  getPublicJwk(): Promise<PublicEcJwk>;

  /**
   * RFC 7638 JWK thumbprint, base64url(SHA-256(canonical JWK)). The server
   * compares this to the access token's `cnf.jkt` claim.
   */
  getThumbprint(): Promise<string>;

  /**
   * Sign the given bytes with ECDSA-P256-SHA256. Returns 64-byte raw r||s
   * (IEEE P1363 / JOSE format), NOT DER. Suitable for direct base64url
   * encoding into the JWS signature segment.
   */
  sign(payload: Uint8Array): Promise<Uint8Array>;

  /**
   * OPTIONAL. Best-effort check that the current keypair is durably persisted
   * (re-writing it if needed) and will therefore survive a reload/relaunch.
   * Returns `false` when persistence is unavailable (e.g. IndexedDB blocked),
   * meaning any DPoP-bound token minted against this key will stop verifying
   * on the next cold start. `PollarClient` calls this right before binding a
   * login to the key so it can warn loudly instead of failing silently later.
   * Optional so custom `KeyManager` implementations remain source-compatible.
   */
  ensurePersisted?(): Promise<boolean>;

  /**
   * OPTIONAL. Drop the in-memory cached key WITHOUT touching persistent
   * storage, so the next operation re-loads whatever is persisted. The
   * persisted key is shared per origin/API key across tabs; after another tab
   * rotates it (logout -> fresh login), this instance's cached copy is stale
   * and would sign proofs the server rejects - and would trip the restore-time
   * `dpopJkt` binding check against the session the other tab just wrote.
   * `PollarClient` calls this on session teardown and before concluding that
   * a binding mismatch means the key is really lost. Optional so custom
   * `KeyManager` implementations remain source-compatible.
   */
  resync?(): void;
}

import { base64urlEncode } from '../lib/base64url';
import { hashApiKey } from '../lib/api-key-hash';
import { canonicalEcJwk, computeJwkThumbprint } from './thumbprint';
import type { KeyManager, PublicEcJwk } from './types';

/**
 * `KeyManager` backed by Web Crypto + IndexedDB. The ECDSA P-256 keypair is
 * generated with `extractable: false` for the private key - its bytes never
 * leave the browser's crypto subsystem. The `CryptoKeyPair` is persisted in
 * IndexedDB via structured clone (browsers serialize non-extractable keys
 * without exposing material).
 *
 * Per the W3C WebCrypto ECDSA spec, the public key is always extractable
 * regardless of the `extractable` argument, so `exportKey('jwk', publicKey)`
 * works for building the DPoP proof header.
 *
 * Residual XSS risk: an in-page script can still call `crypto.subtle.sign()`
 * on the same key handle to mint proofs. Non-extractable storage prevents
 * key exfiltration, not signing-oracle attacks. See SECURITY.md.
 */

const DB_NAME = 'pollar-keys';
const DB_VERSION = 1;
const STORE_NAME = 'keys';

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') {
      reject(new Error('[PollarClient:keys] IndexedDB not available'));
      return;
    }
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onerror = (): void => reject(req.error ?? new Error('[PollarClient:keys] IDB open failed'));
    req.onsuccess = (): void => resolve(req.result);
    req.onupgradeneeded = (): void => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME);
      }
    };
  });
}

function awaitTx<T>(req: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    req.onsuccess = (): void => resolve(req.result);
    req.onerror = (): void => reject(req.error ?? new Error('[PollarClient:keys] IDB request failed'));
  });
}

/**
 * Await a WRITE durably: a put/delete request's `onsuccess` fires before the
 * transaction actually commits, and a commit-time failure (quota, private-mode
 * eviction, serialization) aborts the transaction silently after that. Waiting
 * for the transaction's own `complete` event turns those silent losses into
 * caught errors - critical here, because a DPoP keypair that only *appeared*
 * to persist guarantees a thumbprint-mismatch logout on the next page load.
 */
function awaitWriteTx(tx: IDBTransaction, req: IDBRequest): Promise<void> {
  return new Promise((resolve, reject) => {
    req.onerror = (): void => reject(req.error ?? new Error('[PollarClient:keys] IDB write request failed'));
    tx.oncomplete = (): void => resolve();
    tx.onerror = (): void => reject(tx.error ?? new Error('[PollarClient:keys] IDB write transaction failed'));
    tx.onabort = (): void => reject(tx.error ?? new Error('[PollarClient:keys] IDB write transaction aborted'));
  });
}

async function dbGet<T>(key: string): Promise<T | undefined> {
  const db = await openDb();
  try {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const result = (await awaitTx(tx.objectStore(STORE_NAME).get(key))) as T | undefined;
    return result;
  } finally {
    db.close();
  }
}

async function dbPut(key: string, value: unknown): Promise<void> {
  const db = await openDb();
  try {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    await awaitWriteTx(tx, tx.objectStore(STORE_NAME).put(value, key));
  } finally {
    db.close();
  }
}

async function dbDelete(key: string): Promise<void> {
  const db = await openDb();
  try {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    await awaitWriteTx(tx, tx.objectStore(STORE_NAME).delete(key));
  } finally {
    db.close();
  }
}

function isCryptoKeyPair(v: unknown): v is CryptoKeyPair {
  if (typeof v !== 'object' || v === null) return false;
  const obj = v as { privateKey?: unknown; publicKey?: unknown };
  return obj.privateKey !== undefined && obj.publicKey !== undefined;
}

export class WebCryptoKeyManager implements KeyManager {
  private readonly apiKey: string;
  private apiKeyHash: string | null = null;
  private keyPair: CryptoKeyPair | null = null;
  private publicJwk: PublicEcJwk | null = null;
  private thumbprint: string | null = null;
  /**
   * Cached in-flight init. Lets `init()` be called concurrently (or implicitly
   * from `getPublicJwk` / `sign`) without doing the work twice. Cleared on
   * failure so callers can retry, and cleared on `reset()`.
   */
  private _initPromise: Promise<void> | null = null;

  constructor(apiKey: string) {
    if (typeof globalThis.crypto === 'undefined' || !globalThis.crypto.subtle) {
      throw new Error('[PollarClient:keys] SubtleCrypto is unavailable. DPoP requires a secure context (HTTPS or localhost).');
    }
    this.apiKey = apiKey;
  }

  /**
   * Idempotent and safe under concurrency. The first call kicks off the real
   * init; subsequent (and concurrent) calls return the same in-flight promise.
   * Other methods (`getPublicJwk`, `getThumbprint`, `sign`) auto-await this so
   * the manager is self-healing if `init()` was never explicitly invoked.
   */
  async init(): Promise<void> {
    // All three fields, not just the pair: `_doInit` assigns `keyPair` and only
    // THEN awaits the JWK export + thumbprint. A caller landing in that window
    // would early-return on `keyPair` alone and find `publicJwk`/`thumbprint`
    // still null - `getThumbprint()` then threw "initialization failed" while
    // init was, in fact, mid-flight. Requiring all three makes such a caller
    // fall through and join the in-flight `_initPromise` instead.
    if (this.keyPair && this.publicJwk && this.thumbprint) return;
    if (!this._initPromise) {
      this._initPromise = this._doInit().catch((err) => {
        // Clear the promise so the next call retries instead of permanently
        // returning a rejected promise. The error propagates to the caller -
        // `PollarClient` logs it through its configured logger, so we don't
        // double-log (raw, ungated) here.
        this._initPromise = null;
        throw err;
      });
    }
    return this._initPromise;
  }

  private async _doInit(): Promise<void> {
    if (!this.apiKeyHash) {
      this.apiKeyHash = await hashApiKey(this.apiKey);
    }

    let pair: CryptoKeyPair | undefined;
    try {
      pair = await dbGet<CryptoKeyPair>(this.apiKeyHash);
      if (pair && !isCryptoKeyPair(pair)) pair = undefined;
    } catch {
      // IDB unavailable (Safari private mode, sandboxed iframe, partitioned
      // storage in a 3rd-party iframe). Fall through to fresh keygen - we
      // lose persistence across reloads but the current session can sign.
      pair = undefined;
    }

    if (!pair) {
      pair = (await globalThis.crypto.subtle.generateKey(
        { name: 'ECDSA', namedCurve: 'P-256' },
        // false -> private key non-extractable; per W3C ECDSA spec the public
        // key is always extractable regardless of this flag.
        false,
        ['sign', 'verify'],
      )) as CryptoKeyPair;
      try {
        await dbPut(this.apiKeyHash, pair);
      } catch {
        // Persistence failed but the in-memory pair still works for this session.
      }
    }

    this.keyPair = pair;
    this.publicJwk = await this._exportPublicJwk(pair.publicKey);
    this.thumbprint = await computeJwkThumbprint(this.publicJwk);
  }

  /**
   * Derive the public JWK from a `CryptoKey`. Prefers the `'raw'` export (the
   * 65-byte uncompressed point `0x04 || X(32) || Y(32)`) and base64url-encodes
   * the coordinates ourselves - that sidesteps polyfills whose `exportKey('jwk')`
   * emits non-base64url `x`/`y` (standard base64, `=` padding, or - as seen with
   * `react-native-quick-crypto` - a stray `.`). Real browsers and most polyfills
   * support `'raw'` for public EC keys.
   *
   * Falls back to the `'jwk'` export (normalized via `canonicalEcJwk`) if `'raw'`
   * is unsupported or returns an unexpected shape, so this can't regress on a
   * runtime that only implements the JWK path. Both routes yield identical
   * coordinate bytes, so the `cnf.jkt` thumbprint is unchanged either way.
   */
  private async _exportPublicJwk(publicKey: CryptoKey): Promise<PublicEcJwk> {
    try {
      const raw = new Uint8Array(await globalThis.crypto.subtle.exportKey('raw', publicKey));
      // Uncompressed P-256 point: 65 bytes, leading 0x04 tag.
      if (raw.length !== 65 || raw[0] !== 0x04) {
        throw new Error(`[PollarClient:keys] Unexpected raw EC point (len=${raw.length}, tag=${raw[0]})`);
      }
      return {
        kty: 'EC',
        crv: 'P-256',
        x: base64urlEncode(raw.slice(1, 33)),
        y: base64urlEncode(raw.slice(33, 65)),
      };
    } catch {
      // 'raw' unsupported (or odd) on this runtime - fall back to the JWK export
      // and normalize its coordinates to unpadded base64url.
      const jwk = (await globalThis.crypto.subtle.exportKey('jwk', publicKey)) as JsonWebKey;
      return canonicalEcJwk(jwk);
    }
  }

  async reset(): Promise<void> {
    try {
      if (this.apiKeyHash) await dbDelete(this.apiKeyHash);
    } catch {
      // Best-effort cleanup; if IDB is unavailable there's nothing persisted to clear.
    }
    this.keyPair = null;
    this.publicJwk = null;
    this.thumbprint = null;
    this._initPromise = null;
  }

  /**
   * Re-persist the in-memory pair and verify that the pair IndexedDB holds is
   * that same key, by thumbprint. Idempotent and cheap (one put + one get).
   * Returns `false` when persistence is unavailable - or when the stored key is
   * someone else's - so the caller (the login flow) can warn that the session
   * will not survive a reload rather than letting a silent `dbPut` failure
   * surface later as an unexplained thumbprint-mismatch logout on the next
   * page load. Re-putting (rather than only probing) also heals
   * the case where another tab's `reset()` deleted the row this instance still
   * signs with - the key a new login binds is guaranteed to be the stored one.
   */
  async ensurePersisted(): Promise<boolean> {
    // The thumbprint too, not just the pair: it is what the read-back is checked
    // against, and `_doInit` publishes it one await after `keyPair`.
    if (!this.keyPair || !this.thumbprint) await this.init();
    if (!this.keyPair || !this.thumbprint || !this.apiKeyHash) return false;
    try {
      await dbPut(this.apiKeyHash, this.keyPair);
      const readBack = await dbGet<CryptoKeyPair>(this.apiKeyHash);
      if (!isCryptoKeyPair(readBack)) return false;
      // Compare thumbprints, not shapes: another tab can write its own pair
      // between the put and the get, and a shape check would accept it. The
      // login would then bind a key IndexedDB no longer holds, which is exactly
      // the thumbprint-mismatch logout this call exists to rule out.
      const storedThumbprint = await computeJwkThumbprint(await this._exportPublicJwk(readBack.publicKey));
      return storedThumbprint === this.thumbprint;
    } catch {
      return false;
    }
  }

  /**
   * Drop the in-memory cache; the next operation re-runs `init()` and adopts
   * whatever IndexedDB holds (another tab may have rotated the shared key).
   * Never touches persistent storage - that's `reset()`.
   */
  resync(): void {
    this.keyPair = null;
    this.publicJwk = null;
    this.thumbprint = null;
    this._initPromise = null;
  }

  async getPublicJwk(): Promise<PublicEcJwk> {
    if (!this.publicJwk) await this.init();
    if (!this.publicJwk) {
      throw new Error('[PollarClient:keys] Keypair initialization failed; getPublicJwk unavailable');
    }
    // Return a fresh copy so callers cannot mutate our cached state.
    return { kty: this.publicJwk.kty, crv: this.publicJwk.crv, x: this.publicJwk.x, y: this.publicJwk.y };
  }

  async getThumbprint(): Promise<string> {
    if (!this.thumbprint) await this.init();
    if (!this.thumbprint) {
      throw new Error('[PollarClient:keys] Keypair initialization failed; getThumbprint unavailable');
    }
    return this.thumbprint;
  }

  async sign(payload: Uint8Array): Promise<Uint8Array> {
    if (!this.keyPair) await this.init();
    if (!this.keyPair) {
      throw new Error('[PollarClient:keys] Keypair initialization failed; sign unavailable');
    }
    // Cast through BufferSource: TypeScript 5.7's strict typing distinguishes
    // Uint8Array<ArrayBuffer> from Uint8Array<SharedArrayBuffer>, but every
    // payload we pass here is regular-ArrayBuffer-backed.
    const sig = await globalThis.crypto.subtle.sign(
      { name: 'ECDSA', hash: 'SHA-256' },
      this.keyPair.privateKey,
      payload as unknown as BufferSource,
    );
    // For ECDSA P-256 with SHA-256, WebCrypto returns 64-byte raw r||s
    // (IEEE P1363 / JOSE format). No DER conversion needed.
    return new Uint8Array(sig);
  }
}

/**
 * Abort helpers that don't assume a browser-grade runtime.
 *
 * Two primitives we rely on are missing or partial on some React Native /
 * Hermes builds:
 *   - `DOMException` is not a global on Hermes, so `new DOMException(...)`
 *     throws `ReferenceError` instead of producing an AbortError.
 *   - `AbortSignal.prototype.throwIfAborted` is absent on older RN AbortSignal
 *     polyfills, so calling it (even via optional chaining, which only guards a
 *     null/undefined signal - not a missing method) throws `TypeError`.
 *
 * These shims keep the abort path working everywhere while preserving the
 * `error.name === 'AbortError'` contract the rest of the SDK checks against.
 */

/**
 * Build an AbortError. Uses the native `DOMException` when present (browsers,
 * Node >=17) and falls back to a plain `Error` tagged `name = 'AbortError'`
 * where `DOMException` is undefined (Hermes).
 */
export function abortError(): Error {
  if (typeof DOMException !== 'undefined') {
    return new DOMException('Aborted', 'AbortError');
  }
  const err = new Error('Aborted');
  err.name = 'AbortError';
  return err;
}

/**
 * Throw an AbortError if `signal` is already aborted. Replacement for
 * `signal.throwIfAborted()` that doesn't depend on the method existing on the
 * runtime's `AbortSignal`.
 */
export function throwIfAborted(signal?: AbortSignal): void {
  if (signal?.aborted) throw abortError();
}

/**
 * An `AbortSignal` that aborts after `ms` milliseconds, plus a `clear()` to
 * cancel the pending timer once the work finishes (so a completed request never
 * leaves a dangling timeout).
 *
 * We don't use the native `AbortSignal.timeout(ms)` even where it exists: it's
 * absent on Hermes / older RN, and it gives no handle to cancel the timer early.
 * A plain `AbortController` + `setTimeout` works uniformly across every runtime.
 */
export function timeoutController(ms: number): { signal: AbortSignal; clear: () => void } {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ms);
  // `unref` keeps a pending timeout from holding a Node process open; it's
  // absent in browsers / RN, so guard the call.
  (timer as { unref?: () => void }).unref?.();
  return { signal: controller.signal, clear: () => clearTimeout(timer) };
}

/**
 * Combine several `AbortSignal`s into one that aborts as soon as ANY input does.
 * RN-safe replacement for `AbortSignal.any` (absent on Hermes). Returns the
 * combined signal plus a `cleanup()` that detaches the listeners - call it once
 * the awaited work settles so finished requests don't leak listeners on a
 * long-lived caller signal.
 */
export function anySignal(signals: (AbortSignal | undefined)[]): { signal: AbortSignal; cleanup: () => void } {
  const controller = new AbortController();
  const present = signals.filter((s): s is AbortSignal => !!s);

  const onAbort = () => {
    controller.abort();
    cleanup();
  };
  const cleanup = () => {
    for (const s of present) s.removeEventListener?.('abort', onAbort);
  };

  for (const s of present) {
    if (s.aborted) {
      controller.abort();
      cleanup();
      return { signal: controller.signal, cleanup };
    }
    s.addEventListener?.('abort', onAbort);
  }
  return { signal: controller.signal, cleanup };
}

import { sha256 } from './sha256';

/**
 * Stable per-API-key namespace tag used to scope persisted storage keys and
 * keypairs. First 32 hex chars (16 bytes / 128 bits) of SHA-256(apiKey) - two
 * distinct keys collide with probability ~1/2^64 (negligible).
 *
 * NOTE: the tag width is baked into every storage key, so changing it orphans
 * every persisted session (the row is simply never found) and logs every user
 * out once on upgrade. There is deliberately NO migration between widths - do
 * not change it without weighing that one-time logout. (Sessions written by
 * SDKs older than 0.10 use an 8-hex tag and are intentionally left orphaned.)
 *
 * Async only to match the `sha256` wrapper's signature - the underlying
 * `@noble/hashes` digest is synchronous. Compute once during client
 * initialization and cache.
 */
export async function hashApiKey(apiKey: string): Promise<string> {
  const digest = await sha256(new TextEncoder().encode(apiKey));
  let hex = '';
  for (let i = 0; i < 16; i++) hex += digest[i]!.toString(16).padStart(2, '0');
  return hex;
}

/**
 * Base64url encoder/decoder (RFC 4648 section 5), pure JS - no `btoa`, no `Buffer`.
 * Used everywhere we need to encode/decode JWS segments, JWK fields, hashes,
 * private scalars, etc. Output is unpadded ("=" stripped).
 */

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

const REVERSE: ReadonlyMap<string, number> = (() => {
  const m = new Map<string, number>();
  for (let i = 0; i < ALPHABET.length; i++) m.set(ALPHABET[i] as string, i);
  return m;
})();

/** Encode raw bytes to base64url (no padding). */
export function base64urlEncode(bytes: Uint8Array): string {
  let result = '';
  let i = 0;
  for (; i + 2 < bytes.length; i += 3) {
    const b1 = bytes[i] as number;
    const b2 = bytes[i + 1] as number;
    const b3 = bytes[i + 2] as number;
    result += ALPHABET[b1 >> 2];
    result += ALPHABET[((b1 & 0x03) << 4) | (b2 >> 4)];
    result += ALPHABET[((b2 & 0x0f) << 2) | (b3 >> 6)];
    result += ALPHABET[b3 & 0x3f];
  }
  if (i < bytes.length) {
    const b1 = bytes[i] as number;
    if (i + 1 === bytes.length) {
      result += ALPHABET[b1 >> 2];
      result += ALPHABET[(b1 & 0x03) << 4];
    } else {
      const b2 = bytes[i + 1] as number;
      result += ALPHABET[b1 >> 2];
      result += ALPHABET[((b1 & 0x03) << 4) | (b2 >> 4)];
      result += ALPHABET[(b2 & 0x0f) << 2];
    }
  }
  return result;
}

/** Decode a base64url string (with or without "=" padding) to raw bytes. */
export function base64urlDecode(input: string): Uint8Array {
  const clean = input.replace(/=+$/, '');
  const out = new Uint8Array(Math.floor((clean.length * 3) / 4));
  let byteIdx = 0;
  for (let i = 0; i < clean.length; i += 4) {
    const c1 = REVERSE.get(clean[i] as string);
    const c2 = REVERSE.get(clean[i + 1] as string);
    const c3 = i + 2 < clean.length ? REVERSE.get(clean[i + 2] as string) : undefined;
    const c4 = i + 3 < clean.length ? REVERSE.get(clean[i + 3] as string) : undefined;
    if (c1 === undefined || c2 === undefined) {
      throw new Error('[PollarClient] Invalid base64url input');
    }
    out[byteIdx++] = (c1 << 2) | (c2 >> 4);
    if (c3 !== undefined) {
      out[byteIdx++] = ((c2 & 0x0f) << 4) | (c3 >> 2);
      if (c4 !== undefined) {
        out[byteIdx++] = ((c3 & 0x03) << 6) | c4;
      }
    }
  }
  return out.slice(0, byteIdx);
}

/** Encode a UTF-8 string to base64url. */
export function base64urlEncodeString(s: string): string {
  return base64urlEncode(new TextEncoder().encode(s));
}

/** Decode base64url to a UTF-8 string. */
export function base64urlDecodeString(s: string): string {
  return new TextDecoder().decode(base64urlDecode(s));
}

// Card number reveal, end to end encrypted (Coral's scheme). The device makes a
// one-shot AES-128 key, wraps it with the provider's RSA public key into a
// `sessionId`, and decrypts the PAN and CVC the provider encrypted with that
// key. The key never leaves this module; the server only relays ciphertext.
//
// Two engines, same output: WebCrypto where the runtime has it (browsers,
// Node), and plain JavaScript (`rsa-oaep.ts` + @noble/ciphers) on React Native,
// which has no `crypto.subtle`.

import { gcm } from '@noble/ciphers/aes';
import { randomBytes } from '@noble/hashes/utils';
import type { EncryptedCardSecrets } from '../api/endpoints/cards';
import { rsaOaepSha1Encrypt } from './rsa-oaep';

export type CardSecretsEngine = 'auto' | 'webcrypto' | 'js';

export interface CardSecretsSession {
  /** Wrapped key for `POST /cards/:id/secrets`. */
  sessionId: string;
  /** Decrypts one `{ iv, data }` from the provider's answer. */
  open(value: { iv: string; data: string }): Promise<string>;
}

function b64encode(bytes: Uint8Array): string {
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin);
}

function b64decode(s: string): Uint8Array<ArrayBuffer> {
  const bin = atob(s);
  const out = new Uint8Array(new ArrayBuffer(bin.length));
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function pemToDer(pem: string): Uint8Array<ArrayBuffer> {
  return b64decode(pem.replace(/-----[A-Z ]+-----/g, '').replace(/\s+/g, ''));
}

async function webCryptoSession(publicKeyPem: string, subtle: SubtleCrypto): Promise<CardSecretsSession> {
  const rawKey = globalThis.crypto.getRandomValues(new Uint8Array(new ArrayBuffer(16)));
  const aesKey = await subtle.importKey('raw', rawKey, { name: 'AES-GCM' }, false, ['decrypt']);
  const rsaKey = await subtle.importKey('spki', pemToDer(publicKeyPem), { name: 'RSA-OAEP', hash: 'SHA-1' }, false, [
    'encrypt',
  ]);
  // The provider expects the base64 text of the key as the RSA plaintext, not the raw bytes.
  const wrapped = await subtle.encrypt({ name: 'RSA-OAEP' }, rsaKey, new TextEncoder().encode(b64encode(rawKey)));
  rawKey.fill(0);
  return {
    sessionId: b64encode(new Uint8Array(wrapped)),
    async open(value) {
      const plain = await subtle.decrypt(
        { name: 'AES-GCM', iv: b64decode(value.iv), tagLength: 128 },
        aesKey,
        b64decode(value.data),
      );
      return new TextDecoder().decode(plain);
    },
  };
}

function jsSession(publicKeyPem: string): CardSecretsSession {
  const rawKey = randomBytes(16);
  const wrapped = rsaOaepSha1Encrypt(pemToDer(publicKeyPem), new TextEncoder().encode(b64encode(rawKey)));
  return {
    sessionId: b64encode(wrapped),
    async open(value) {
      // noble's GCM takes ciphertext with the 16-byte tag appended, which is how the provider sends it.
      const plain = gcm(rawKey, b64decode(value.iv)).decrypt(b64decode(value.data));
      return new TextDecoder().decode(plain);
    },
  };
}

/**
 * Make the one-shot session key and wrap it with the provider's public key
 * (RSA-OAEP, SHA-1). `engine` is for tests; `auto` picks WebCrypto when present.
 */
export async function createCardSecretsSession(
  publicKeyPem: string,
  options: { engine?: CardSecretsEngine } = {},
): Promise<CardSecretsSession> {
  const engine = options.engine ?? 'auto';
  const subtle = globalThis.crypto?.subtle;
  if (engine === 'webcrypto' || (engine === 'auto' && subtle)) {
    if (!subtle) throw new Error('Card secrets need WebCrypto, which this runtime does not provide');
    return webCryptoSession(publicKeyPem, subtle);
  }
  return jsSession(publicKeyPem);
}

/** Decrypt both values of a provider answer with the session that produced its `sessionId`. */
export async function openCardSecrets(session: CardSecretsSession, encrypted: EncryptedCardSecrets) {
  const [pan, cvc] = await Promise.all([session.open(encrypted.encryptedPan), session.open(encrypted.encryptedCvc)]);
  return { pan, cvc, last4: encrypted.last4, expMonth: encrypted.expMonth, expYear: encrypted.expYear };
}

/**
 * Log levels in increasing verbosity. Setting a level emits that level and
 * every more-important one; `silent` disables all SDK logging.
 *
 *   silent < error < warn < info < debug
 */
export type LogLevel = 'silent' | 'error' | 'warn' | 'info' | 'debug';

/**
 * Sink the SDK writes logs to. The global `console` already satisfies this
 * shape, so it's the default. Inject your own (pino, Sentry breadcrumbs, a test
 * spy...) via `PollarClientConfig.logger` to route SDK logs wherever you want.
 */
export interface PollarLogger {
  error(...args: unknown[]): void;
  warn(...args: unknown[]): void;
  info(...args: unknown[]): void;
  debug(...args: unknown[]): void;
}

const RANK: Record<LogLevel, number> = { silent: 0, error: 1, warn: 2, info: 3, debug: 4 };

/**
 * Build a level-gated logger over a sink. The returned object has the same
 * method surface as {@link PollarLogger}; each call is silently dropped when its
 * level is more verbose than the configured `level`. Messages keep their own
 * `[PollarClient...]` prefixes, so this only adds filtering + sink routing.
 *
 * Defaults: `level = 'info'`, `sink = console`.
 */
export function createLogger(level: LogLevel = 'info', sink: PollarLogger = console): PollarLogger {
  const threshold = RANK[level];
  const gate =
    (lvl: Exclude<LogLevel, 'silent'>) =>
    (...args: unknown[]): void => {
      if (threshold >= RANK[lvl]) sink[lvl](...args);
    };
  return { error: gate('error'), warn: gate('warn'), info: gate('info'), debug: gate('debug') };
}

/**
 * Request-body keys whose values are PII or secrets and must never reach a log
 * sink in the clear. Their values are replaced with `'[redacted]'` while the key
 * itself is kept, so logs still show the request *shape* for debugging.
 */
export const SENSITIVE_BODY_KEYS = new Set([
  'email',
  'code',
  'walletAddress',
  'dpopJwk',
  'response',
  'refreshToken',
  // Token material that can appear in RESPONSE envelopes (e.g. `content.token`):
  'accessToken',
  'token',
  // SEP-10 challenge envelopes: a counter-signed challenge is a live, replayable
  // auth credential - never log it in the clear.
  'signedChallengeXdr',
  'challengeXdr',
  'signedTxXdr',
  'signedXdr',
  'signedAuthEntry',
  // Defensive: generic token/secret key names, in case the wire ever nests one
  // under an unexpected field (the redactor is allow-by-default, so an unknown
  // key would otherwise pass through in the clear).
  'bearer',
  'jwt',
  'authorization',
  'secret',
  'privateKey',
  'seed',
]);

/**
 * Returns a shallow copy of an API request body with sensitive values masked.
 * Non-object bodies (and `undefined`) pass through untouched.
 */
export function redactBody(body: unknown): unknown {
  if (!body || typeof body !== 'object') return body;
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(body as Record<string, unknown>)) {
    out[key] = SENSITIVE_BODY_KEYS.has(key) ? '[redacted]' : value;
  }
  return out;
}

/**
 * Sensitive keys for a RESPONSE / error-cause envelope. Same as
 * {@link SENSITIVE_BODY_KEYS} but WITHOUT `code` - in a request body `code` is
 * the email OTP (a secret), but in a response/cause it's the diagnostic error
 * code (`TX_FEE_LIMIT_EXCEEDED`, `INVALID_EMAIL_CODE`, ...) that you need in logs.
 * Token/PII/XDR keys stay masked.
 */
const SENSITIVE_RESPONSE_KEYS = new Set([...SENSITIVE_BODY_KEYS].filter((k) => k !== 'code'));

/**
 * Like {@link redactBody} but RECURSIVE - masks sensitive keys at any depth. Use
 * for RESPONSE bodies / error causes, where token material is nested (e.g.
 * `{ content: { token: { accessToken, refreshToken } } }`) and the shallow
 * `redactBody` would leak it. Keeps the diagnostic `code` visible (see
 * {@link SENSITIVE_RESPONSE_KEYS}). Depth-bounded so a pathological/cyclic
 * object can't blow the stack.
 */
export function redactDeep(value: unknown, depth = 0): unknown {
  if (depth > 8 || !value || typeof value !== 'object') return value;
  if (Array.isArray(value)) return value.map((v) => redactDeep(v, depth + 1));
  // A thrown `Error` carries its useful data (`name`/`message`/`stack`) on
  // NON-enumerable props, so `Object.entries` below would yield `{}` and the real
  // failure reason would vanish from logs. Project those fields explicitly (then
  // still redact any enumerable custom props the error may carry, e.g. `cause`).
  if (value instanceof Error) {
    return {
      name: value.name,
      message: value.message,
      stack: value.stack,
      ...(redactDeep({ ...value }, depth + 1) as Record<string, unknown>),
    };
  }
  const out: Record<string, unknown> = {};
  for (const [key, v] of Object.entries(value as Record<string, unknown>)) {
    out[key] = SENSITIVE_RESPONSE_KEYS.has(key) ? '[redacted]' : redactDeep(v, depth + 1);
  }
  return out;
}

/**
 * Generate a RFC 4122 v4 UUID. Prefers the secure-context `crypto.randomUUID`
 * when available; falls back to a manual v4 build via `crypto.getRandomValues`
 * for environments where `randomUUID` is missing (older RN/Hermes - where the
 * `react-native-get-random-values` polyfill provides `getRandomValues` but not
 * `randomUUID` - and insecure HTTP origins).
 *
 * Throws only when no secure random source exists at all, in which case DPoP
 * (and the SDK) cannot operate anyway.
 */
export function randomUUID(): string {
  const c = globalThis.crypto;
  if (c && typeof c.randomUUID === 'function') {
    return c.randomUUID();
  }
  if (c && typeof c.getRandomValues === 'function') {
    const bytes = new Uint8Array(16);
    c.getRandomValues(bytes);
    bytes[6] = ((bytes[6] as number) & 0x0f) | 0x40; // version 4
    bytes[8] = ((bytes[8] as number) & 0x3f) | 0x80; // RFC 4122 variant
    const hex: string[] = [];
    for (let i = 0; i < 16; i++) hex.push((bytes[i] as number).toString(16).padStart(2, '0'));
    return `${hex.slice(0, 4).join('')}-${hex.slice(4, 6).join('')}-${hex.slice(6, 8).join('')}-${hex.slice(8, 10).join('')}-${hex.slice(10, 16).join('')}`;
  }
  throw new Error(
    '[PollarClient] No secure random source available (crypto.randomUUID / crypto.getRandomValues). ' +
      'DPoP requires a secure context (HTTPS) or, in React Native, the `react-native-get-random-values` polyfill.',
  );
}

// RSA-OAEP encryption (RFC 8017 section 7.1.1) with SHA-1 and MGF1-SHA1, in
// plain JavaScript on BigInt. Used where WebCrypto is missing (React Native):
// the only operation needed is wrapping a short session key with a provider's
// public key, so a full RSA library would be weight for nothing. Encrypt-only:
// no private keys ever exist on the device.

import { sha1 } from '@noble/hashes/sha1';
import { randomBytes } from '@noble/hashes/utils';

const H_LEN = 20;

interface RsaPublicKey {
  n: bigint;
  e: bigint;
  /** Modulus length in bytes (k). */
  k: number;
}

/** One DER element: its tag, and where its content starts and ends. */
function derElement(der: Uint8Array, at: number): { tag: number; start: number; end: number } {
  const tag = der[at]!;
  let len = der[at + 1]!;
  let p = at + 2;
  if (len & 0x80) {
    const bytes = len & 0x7f;
    len = 0;
    for (let i = 0; i < bytes; i++) len = (len << 8) | der[p++]!;
  }
  return { tag, start: p, end: p + len };
}

function bytesToBigInt(bytes: Uint8Array): bigint {
  let v = 0n;
  for (const b of bytes) v = (v << 8n) | BigInt(b);
  return v;
}

function bigIntToBytes(v: bigint, length: number): Uint8Array {
  const out = new Uint8Array(length);
  for (let i = length - 1; i >= 0; i--) {
    out[i] = Number(v & 0xffn);
    v >>= 8n;
  }
  return out;
}

/**
 * Read `n` and `e` out of a SubjectPublicKeyInfo (the body of a
 * `-----BEGIN PUBLIC KEY-----` block): SEQUENCE { AlgorithmIdentifier,
 * BIT STRING { SEQUENCE { INTEGER n, INTEGER e } } }.
 */
export function parseRsaSpki(der: Uint8Array): RsaPublicKey {
  const spki = derElement(der, 0);
  const algorithm = derElement(der, spki.start);
  const bitString = derElement(der, algorithm.end);
  if (spki.tag !== 0x30 || bitString.tag !== 0x03) throw new Error('Not a SubjectPublicKeyInfo');
  // The BIT STRING starts with the count of unused bits, always 0 here.
  const rsaKey = derElement(der, bitString.start + 1);
  const nEl = derElement(der, rsaKey.start);
  const eEl = derElement(der, nEl.end);
  if (rsaKey.tag !== 0x30 || nEl.tag !== 0x02 || eEl.tag !== 0x02) throw new Error('Not an RSA public key');
  // A leading 0x00 only keeps the INTEGER positive; it is not part of the modulus.
  let nStart = nEl.start;
  while (nStart < nEl.end - 1 && der[nStart] === 0) nStart++;
  const nBytes = der.subarray(nStart, nEl.end);
  return { n: bytesToBigInt(nBytes), e: bytesToBigInt(der.subarray(eEl.start, eEl.end)), k: nBytes.length };
}

function modPow(base: bigint, exp: bigint, mod: bigint): bigint {
  let result = 1n;
  base %= mod;
  while (exp > 0n) {
    if (exp & 1n) result = (result * base) % mod;
    exp >>= 1n;
    base = (base * base) % mod;
  }
  return result;
}

/** MGF1 with SHA-1: the mask the OAEP padding is built from. */
function mgf1(seed: Uint8Array, length: number): Uint8Array {
  const out = new Uint8Array(length);
  const counter = new Uint8Array(4);
  const input = new Uint8Array(seed.length + 4);
  input.set(seed);
  for (let i = 0, filled = 0; filled < length; i++) {
    counter[0] = (i >>> 24) & 0xff;
    counter[1] = (i >>> 16) & 0xff;
    counter[2] = (i >>> 8) & 0xff;
    counter[3] = i & 0xff;
    input.set(counter, seed.length);
    const block = sha1(input);
    const take = Math.min(H_LEN, length - filled);
    out.set(block.subarray(0, take), filled);
    filled += take;
  }
  return out;
}

/** Encrypt `message` for the given SPKI public key. Empty label, as the providers expect. */
export function rsaOaepSha1Encrypt(spkiDer: Uint8Array, message: Uint8Array): Uint8Array {
  const { n, e, k } = parseRsaSpki(spkiDer);
  if (message.length > k - 2 * H_LEN - 2) throw new Error('Message too long for RSA-OAEP');

  // DB = lHash || PS || 0x01 || M, with lHash = SHA-1 of the empty label.
  const db = new Uint8Array(k - H_LEN - 1);
  db.set(sha1(new Uint8Array(0)));
  db[db.length - message.length - 1] = 0x01;
  db.set(message, db.length - message.length);

  const seed = randomBytes(H_LEN);
  const dbMask = mgf1(seed, db.length);
  for (let i = 0; i < db.length; i++) db[i]! ^= dbMask[i]!;
  const seedMask = mgf1(db, H_LEN);
  for (let i = 0; i < H_LEN; i++) seed[i]! ^= seedMask[i]!;

  const em = new Uint8Array(k);
  em.set(seed, 1);
  em.set(db, 1 + H_LEN);
  return bigIntToBytes(modPow(bytesToBigInt(em), e, n), k);
}

/**
 * Decimal <-> base-unit conversion for on-chain amounts.
 *
 * Chains disagree on what an "amount" is. Stellar's API takes a decimal string
 * ("1.5"); Solana and EVM take integer base units (1500000000 lamports). Balances
 * are always shown to the user as decimals, so a UI that sends to a base-unit
 * chain has to convert - and getting it wrong silently sends the wrong amount.
 *
 * The arithmetic is string + BigInt, never float: `parseFloat('0.1') * 1e9` is
 * 100000000.00000001, and at 18 decimals a float cannot represent the value at
 * all. Money must not round.
 */

/**
 * "1.5" with 9 decimals -> "1500000000".
 *
 * Throws on anything that is not a plain non-negative decimal, and on more
 * fractional digits than the asset has - silently truncating there would send
 * less than the user typed.
 */
export function toBaseUnits(amount: string, decimals: number): string {
  const trimmed = amount.trim();
  if (!/^\d+(\.\d+)?$/.test(trimmed)) {
    throw new Error(`Invalid amount "${amount}": expected a non-negative decimal number.`);
  }
  if (!Number.isInteger(decimals) || decimals < 0) {
    throw new Error(`Invalid decimals "${decimals}".`);
  }

  const [whole = '0', fraction = ''] = trimmed.split('.');
  if (fraction.length > decimals) {
    throw new Error(`Amount "${amount}" has more than ${decimals} decimal places.`);
  }

  // Right-pad the fraction to exactly `decimals` digits, then the whole thing is
  // one integer literal - no division, so nothing to round.
  const padded = fraction.padEnd(decimals, '0');
  return BigInt(whole + padded).toString();
}

/** "1500000000" with 9 decimals -> "1.5". Inverse of {@link toBaseUnits}. */
export function fromBaseUnits(base: string, decimals: number): string {
  const trimmed = base.trim();
  if (!/^\d+$/.test(trimmed)) {
    throw new Error(`Invalid base-unit amount "${base}": expected a non-negative integer.`);
  }
  if (decimals === 0) return trimmed;

  const padded = trimmed.padStart(decimals + 1, '0');
  const whole = padded.slice(0, -decimals);
  const fraction = padded.slice(-decimals).replace(/0+$/, '');
  return fraction ? `${whole}.${fraction}` : whole;
}

