import { RampChain, type RampRoute, type RampTerms, type RampsTransactionResponse } from '../types';

/** Reject unknown or incorrectly cased values without silently changing their meaning. */
export function assertRampChain(value: unknown): asserts value is RampChain {
  if (value !== RampChain.STELLAR && value !== RampChain.POLYGON && value !== RampChain.SOLANA)
    throw new Error('Unsupported ramp chain. Expected STELLAR, POLYGON or SOLANA.');
}

export function assertRampRouteChain(route: RampRoute): void {
  assertRampChain(route.asset.chain);
}

export function assertRampTermsChain(terms: RampTerms): void {
  assertRampChain(terms.assetChain);
}

/** Validate only contract fields; user-provided form values may have arbitrary names. */
export function checkedRampSnapshot<T extends Pick<RampsTransactionResponse, 'chain' | 'terms' | 'nextAction'>>(
  snapshot: T,
): T {
  if (snapshot.chain !== undefined) assertRampChain(snapshot.chain);
  if (snapshot.terms) assertRampTermsChain(snapshot.terms);
  const action = snapshot.nextAction;
  if (action?.kind === 'sign_transaction' || action?.kind === 'chain_transfer') assertRampChain(action.chain);
  if (action?.kind === 'chain_transfer') assertRampChain(action.asset.chain);
  return snapshot;
}

import { assertRampChain } from './chains';
import type { RampChain, RampAction, RampRoute, RampCountry, RampsTransactionResponse } from '../types';
export type RampSigningAction = Extract<RampAction, { kind: 'sign_transaction' }>;
/**
 * The integration must validate the payload, required account and network before
 * signing. Reject invalid requests or cancellation; return the signed payload
 * without broadcasting. Core treats the chain's payload encoding as opaque.
 */
export type RampSigningHandler = (action: RampSigningAction) => Promise<string>;
export class RampSigningRegistry {
  private readonly handlers = new Map<string, RampSigningHandler>();
  register(chain: RampChain, encoding: string, handler: RampSigningHandler) {
    assertRampChain(chain);
    const key = JSON.stringify([chain, encoding]);
    if (this.handlers.has(key)) throw new Error('Ramp signing handler already registered');
    this.handlers.set(key, handler);
    return () => {
      if (this.handlers.get(key) === handler) this.handlers.delete(key);
    };
  }
  resolve(chain: RampChain, encoding: string) {
    assertRampChain(chain);
    return this.handlers.get(JSON.stringify([chain, encoding]));
  }
}
export type RampSnapshot = Pick<
  RampsTransactionResponse,
  'txId' | 'status' | 'nextAction' | 'transactionVersion' | 'reconciliationRequired' | 'lifecycleState' | 'terms' | 'milestones'
>;
/** Responses from another transaction or an older revision cannot replace progress. */
export function mergeRampSnapshot<T extends RampSnapshot>(previous: T | null | undefined, incoming: T): T {
  if (previous && (previous.txId !== incoming.txId || (previous.transactionVersion ?? 0) > (incoming.transactionVersion ?? 0)))
    return previous;
  return incoming;
}
export function safeRampUrl(value: string): string | null {
  try {
    const url = new URL(value);
    return url.protocol === 'https:' && !url.username && !url.password ? url.href : null;
  } catch {
    return null;
  }
}
/** Capabilities also supply countries for providers outside the legacy catalog. */
export function mergeRampCountries(legacy: RampCountry[], routes: RampRoute[]): RampCountry[] {
  const countries = new Map(legacy.map((country) => [country.code, country]));
  for (const route of routes)
    if (!countries.has(route.country)) countries.set(route.country, { code: route.country, currency: route.fiatCurrency });
  return [...countries.values()];
}
/** Shared interpretation; platforms supply controls, links and QR rendering. */
export function describeRampAction(snapshot: RampSnapshot) {
  const action = snapshot.nextAction;
  const blocked =
    snapshot.reconciliationRequired === true ||
    ['completed', 'failed', 'refunded'].includes(snapshot.lifecycleState ?? snapshot.status);
  const base = {
    action,
    canContinue: false,
    canSign: false,
    title: 'Waiting for the next step',
    details: [] as Array<{ label: string; value: string }>,
    links: [] as Array<{ label: string; url: string }>,
    qr: null as string | null,
  };
  if (snapshot.reconciliationRequired)
    return { ...base, title: 'We are checking your transfer. You do not need to start again.' };
  if (snapshot.lifecycleState === 'completed' || snapshot.status === 'completed')
    return { ...base, title: 'Transfer completed' };
  if (!action) return base;
  if ('expiresAt' in action && action.expiresAt !== null && !(Date.parse(action.expiresAt) > Date.now()))
    return { ...base, title: 'These instructions have expired. Refresh the transfer status.' };
  switch (action.kind) {
    case 'verification':
      return {
        ...base,
        title: 'Complete verification',
        canContinue: !blocked,
        details: action.steps.map((step) => ({ label: step.purpose, value: step.instructions + ' (' + step.status + ')' })),
        links: action.steps
          .filter(
            (step, index) =>
              step.status === 'required' &&
              step.url &&
              (action.order === 'parallel' ||
                action.steps.slice(0, index).every((previous) => previous.status === 'completed')),
          )
          .flatMap((step) => {
            const url = safeRampUrl(step.url!);
            return url ? [{ label: step.purpose === 'terms' ? 'Review terms' : 'Open verification', url }] : [];
          }),
      };
    case 'sign_transaction':
      return {
        ...base,
        title:
          action.purpose === 'authentication'
            ? 'Authorize verification'
            : action.purpose === 'onramp_claim'
              ? 'Authorize receipt of your assets'
              : 'Authorize your transfer',
        canSign: !blocked && Date.parse(action.expiresAt) > Date.now(),
      };
    case 'user_ready':
      return { ...base, title: 'Ready to continue', canContinue: !blocked };
    case 'hosted_redirect': {
      const url = safeRampUrl(action.url);
      return {
        ...base,
        title: action.purpose === 'payment' ? 'Open payment instructions' : 'Open verification',
        links: url ? [{ label: 'Open', url }] : [],
      };
    }
    case 'qr_payment':
      return {
        ...base,
        title: `Pay ${action.amount} ${action.currency}`,
        qr: action.payload,
        details: [{ label: 'Payment code', value: action.payload }],
      };
    case 'bank_transfer':
      return {
        ...base,
        title: `Pay ${action.amount} ${action.currency}`,
        details: [...action.details, ...(action.reference ? [{ label: 'Reference', value: action.reference }] : [])],
      };
    case 'chain_transfer':
      return {
        ...base,
        title: `Transfer ${action.amount} ${action.asset.code}`,
        details: [
          { label: 'Chain', value: action.chain },
          { label: 'Destination', value: action.destination },
          ...(action.memo ? [{ label: action.memo.type, value: action.memo.value }] : []),
        ],
      };
    case 'collect_information':
      return { ...base, title: 'Provide the required information', canContinue: !blocked };
    case 'wait':
      return {
        ...base,
        title: {
          verification_pending: 'Verification is under review',
          provider_processing: 'Transfer is processing',
          settlement_verification: 'Confirming settlement',
          reconciliation: 'Checking your transfer',
        }[action.reason],
      };
    default:
      return { ...base, title: `This action is unsupported. Reference: ${snapshot.txId}` };
  }
}

export type StellarNetwork = 'mainnet' | 'testnet';

const HORIZON_URLS: Record<StellarNetwork, string> = {
  mainnet: 'https://horizon.stellar.org',
  testnet: 'https://horizon-testnet.stellar.org',
};

export type StellarClientConfig = StellarNetwork | { horizonUrl: string };

export interface StellarBalance {
  asset: string;
  balance: string;
  assetIssuer?: string;
}

export class StellarClient {
  private readonly horizonUrl: string;

  constructor(config: StellarClientConfig) {
    this.horizonUrl = typeof config === 'string' ? HORIZON_URLS[config] : config.horizonUrl;
  }

  async submitTransaction(signedXdr: string): Promise<{ success: true; hash: string } | { success: false; errorCode: string }> {
    try {
      const response = await fetch(`${this.horizonUrl}/transactions`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({ tx: signedXdr }),
      });
      if (!response.ok) {
        const body = (await response.json().catch(() => ({}))) as { extras?: { result_codes?: { transaction?: string } } };
        return { success: false, errorCode: body.extras?.result_codes?.transaction ?? 'HORIZON_ERROR' };
      }
      const data = (await response.json()) as { hash: string };
      return { success: true, hash: data.hash };
    } catch {
      return { success: false, errorCode: 'NETWORK_ERROR' };
    }
  }
}

import { createLocalStorageAdapter, createMemoryAdapter, type LocalStorageAdapterOptions } from './web';
import type { Storage } from './types';

const PROBE_KEY = '__pollar_storage_probe__';

/**
 * Returns `localStorage`-backed storage when it works, otherwise an in-memory
 * fallback. The probe writes-reads-removes a sentinel; any throw, value
 * mismatch, or missing `localStorage` (SSR / disabled storage) falls back.
 *
 * Run-time degrade still happens inside `createLocalStorageAdapter` - see its
 * docstring for the rationale.
 */
export function defaultStorage(options: LocalStorageAdapterOptions = {}): Storage {
  if (typeof globalThis === 'undefined' || typeof globalThis.localStorage === 'undefined') {
    options.onDegrade?.('unavailable');
    return createMemoryAdapter();
  }

  try {
    const probeValue = String(Date.now());
    globalThis.localStorage.setItem(PROBE_KEY, probeValue);
    const read = globalThis.localStorage.getItem(PROBE_KEY);
    globalThis.localStorage.removeItem(PROBE_KEY);
    if (read !== probeValue) {
      options.onDegrade?.('probe-failed');
      return createMemoryAdapter();
    }
  } catch (error) {
    options.onDegrade?.('probe-failed', error);
    return createMemoryAdapter();
  }

  return createLocalStorageAdapter(options);
}

/**
 * Pluggable storage interface used by `PollarClient` to persist session and
 * key material. All operations are async to accommodate native backends like
 * Expo SecureStore and react-native-keychain whose underlying APIs are async.
 */
export interface Storage {
  get(key: string): Promise<string | null>;
  set(key: string, value: string): Promise<void>;
  remove(key: string): Promise<void>;
}

/**
 * Reasons emitted via `onStorageDegrade` when a primary storage backend
 * silently degrades to in-memory mode (e.g. Safari private mode quota errors,
 * sandboxed iframes without `allow-same-origin`, disabled storage).
 */
export type StorageDegradeReason =
  | 'unavailable'
  | 'probe-failed'
  | 'read-failed'
  | 'write-failed'
  | 'remove-failed'
  | 'quota-exceeded';

export type OnStorageDegrade = (reason: StorageDegradeReason, error?: unknown) => void;

import type { PollarLogger } from '../lib/logger';
import type { OnStorageDegrade, Storage, StorageDegradeReason } from './types';

const LOG_PREFIX = '[PollarClient:storage]';

/**
 * In-memory storage backed by a `Map`. Always available, never throws.
 * Used as the default fallback for SSR, private browsing, sandboxed iframes
 * without `allow-same-origin`, or any environment where `localStorage` is
 * unusable.
 */
export function createMemoryAdapter(): Storage {
  const store = new Map<string, string>();

  return {
    async get(key) {
      const value = store.get(key);
      return value === undefined ? null : value;
    },
    async set(key, value) {
      store.set(key, value);
    },
    async remove(key) {
      store.delete(key);
    },
  };
}

export interface LocalStorageAdapterOptions {
  /**
   * Optional callback invoked the first time the adapter degrades to its
   * in-memory fallback (e.g. quota exceeded, throwing `localStorage`).
   */
  onDegrade?: OnStorageDegrade;
  /**
   * Logger for the one-shot degrade warning. Defaults to the global `console`;
   * `PollarClient` passes its level-gated logger so `logLevel` applies here too.
   */
  logger?: PollarLogger;
}

/**
 * `localStorage`-backed adapter that wraps every operation in try/catch and
 * silently degrades to an in-memory fallback for the rest of the process
 * lifetime on any throw. A single warning is logged when the degrade happens.
 *
 * Why every op (not just the probe): Safari private mode and sandboxed iframes
 * may expose `localStorage` but throw `QuotaExceededError` / `SecurityError`
 * on the first write - a successful probe at construction time isn't enough.
 *
 * Tokens persisted here are DPoP-bound to a non-extractable WebCrypto
 * keypair, so XSS exposure is limited to a signing-oracle attack (the key
 * itself never leaves the browser's crypto subsystem). Consumers who need
 * stricter isolation can inject a custom `Storage` adapter - e.g. one that
 * proxies to an httpOnly cookie on a host origin.
 */
export function createLocalStorageAdapter(options: LocalStorageAdapterOptions = {}): Storage {
  const fallback = createMemoryAdapter();
  let degraded = false;

  function degrade(reason: StorageDegradeReason, error?: unknown): void {
    if (degraded) return;
    degraded = true;
    (options.logger ?? console).warn(`${LOG_PREFIX} localStorage unavailable (${reason}); degrading to in-memory storage`);
    options.onDegrade?.(reason, error);
  }

  return {
    async get(key) {
      if (degraded) return fallback.get(key);
      try {
        return globalThis.localStorage.getItem(key);
      } catch (error) {
        degrade('read-failed', error);
        return fallback.get(key);
      }
    },
    async set(key, value) {
      if (degraded) return fallback.set(key, value);
      try {
        globalThis.localStorage.setItem(key, value);
      } catch (error) {
        const reason: StorageDegradeReason = isQuotaError(error) ? 'quota-exceeded' : 'write-failed';
        degrade(reason, error);
        await fallback.set(key, value);
      }
    },
    async remove(key) {
      if (degraded) return fallback.remove(key);
      try {
        globalThis.localStorage.removeItem(key);
      } catch (error) {
        degrade('remove-failed', error);
        await fallback.remove(key);
      }
    },
  };
}

function isQuotaError(error: unknown): boolean {
  if (typeof error !== 'object' || error === null) return false;
  const name = (error as { name?: unknown }).name;
  const code = (error as { code?: unknown }).code;
  // Chrome/Edge: DOMException name 'QuotaExceededError' (code 22).
  // Firefox: 'NS_ERROR_DOM_QUOTA_REACHED' (code 1014).
  // Safari private mode: 'QuotaExceededError'.
  return name === 'QuotaExceededError' || name === 'NS_ERROR_DOM_QUOTA_REACHED' || code === 22 || code === 1014;
}

import { pollarPaths, StellarNetwork } from './index';
import type { PollarApiClient } from './api/client';
import type { KeyManager } from './keys/types';
import type { LogLevel, PollarLogger } from './lib/logger';
import type { OnStorageDegrade, Storage } from './storage/types';
