/**
 * Login methods this adapter drives through Privy and renders in the Pollar
 * login sub-modal. Intentionally a narrow subset of Privy's `loginMethods`
 * (email + the two social providers Pollar surfaces today); widen as needed.
 */
export type PrivyLoginMethod = 'email' | 'google' | 'github';

/**
 * Appearance hints forwarded to Privy. Same shape/intent as the relevant slice
 * of Privy's `PrivyClientConfig.appearance`, kept slim so this package never
 * needs to import a type from `@privy-io/react-auth`.
 */
export interface PollarPrivyAppearance {
  theme?: 'light' | 'dark';
  /** Accent color (hex) for Privy-owned surfaces (the embedded-wallet iframe UI). */
  accentColor?: string;
  /** Logo URL shown in Privy-owned surfaces. */
  logo?: string;
}

/**
 * Config for {@link createPrivyAdapter}. Shaped to feel familiar to anyone who
 * knows Privy's `PrivyClientConfig`, but defined locally so consumers never
 * install `@privy-io/react-auth` just for the types.
 */
export interface PollarPrivyConfig {
  /** Your Privy app id (Privy dashboard -> app settings). */
  appId: string;
  /** Optional Privy app client id, for apps scoped to a specific client key. */
  clientId?: string;
  /**
   * Login methods to surface, in render order. Mirrors the intent of Privy's
   * `PrivyClientConfig.loginMethods`, narrowed to what this adapter drives.
   */
  loginMethods: PrivyLoginMethod[];
  /**
   * Optional appearance hints. Mirrors `PrivyClientConfig.appearance`. Applied on
   * web only; the React Native (Expo) entry does not forward it.
   */
  appearance?: PollarPrivyAppearance;
  /**
   * Reserved. Not currently applied to the OAuth flow (the web bridge uses
   * Privy's default redirect handling). Kept for forward compatibility.
   */
  redirectUri?: string;
  /**
   * Button label/icon shown in the Pollar login UI. Defaults to
   * `{ label: 'Privy' }`. Leave `meta.group` unset so Privy renders as its own
   * root button (not collapsed behind a wallet gateway).
   */
  meta?: WalletAdapterMeta;
  /**
   * Verbose `[privy-adapter]` console logging of the login/sign flow. Off by
   * default; turn on to trace why a login isn't reaching Pollar.
   */
  debug?: boolean;
  /**
   * After a web OAuth redirect returns, strip Privy's `privy_oauth_*` query
   * params from the URL (via `history.replaceState`, no reload) so the host
   * app's URL stays clean. On by default; set `false` to keep them.
   */
  cleanupOAuthRedirect?: boolean;
}

/**
 * Environment support guard.
 *
 * Privy ships official client SDKs only for React (`@privy-io/react-auth`),
 * React Native / Expo (`@privy-io/expo`), and the native mobile / game engines.
 * There is **no** Privy SDK for Angular, Vue, Svelte or vanilla JS. So this
 * adapter supports exactly two hosts: React (web) and Expo / React Native.
 *
 * We can't reliably fingerprint the host framework at build time - Angular, Vue
 * and React web all resolve the same "web" bundle (only the `react-native`
 * export condition is distinguishable). The support boundary is therefore
 * enforced at runtime: the adapter only works once a platform bridge
 * (`<PrivyAdapterProvider>` on web, the Expo provider on RN) mounts and attaches
 * its runtime. If none ever does - the typical Angular/Vue case - the first use
 * fails with {@link PrivyAdapterUnsupportedError} instead of hanging or throwing
 * a cryptic "react-auth not found".
 */
export class PrivyAdapterUnsupportedError extends Error {
  constructor(message: string = UNSUPPORTED_MESSAGE) {
    super(message);
    this.name = 'PrivyAdapterUnsupportedError';
  }
}

export const UNSUPPORTED_MESSAGE =
  '[privy-adapter] Unsupported environment: no Privy runtime was attached. This ' +
  'adapter currently supports only React (web, via @privy-io/react-auth) and ' +
  'Expo / React Native (via @privy-io/expo). Privy has no Angular or Vue SDK, so ' +
  'Privy login is not available there yet. On web/RN, make sure you mount ' +
  '<PrivyAdapterProvider> (web) or the Expo provider around your app. For non-React ' +
  'frameworks, use server-side signing via @pollar/privy-server-adapter instead.';

/** How long a method waits for a platform bridge to attach before giving up. */
export const RUNTIME_ATTACH_TIMEOUT_MS = 5_000;

import type { InteractiveAuthAdapter } from '@pollar/core';
import type { PollarPrivyConfig } from './config';
import { buildPrivyAdapter, type PrivyAdapterHandle } from './runtime';

/**
 * Maps the public adapter back to its internal handle (with `_attachRuntime` and
 * `config`), so a platform bridge/provider can wire Privy's runtime into it
 * without exposing those internals on the adapter's public type.
 */
const handlesByAdapter = new WeakMap<InteractiveAuthAdapter, PrivyAdapterHandle>();

/**
 * Create a Privy-backed wallet adapter for `@pollar/core`. Platform-agnostic; the
 * returned adapter is inert until a platform provider (web `PrivyAdapterProvider`
 * or the Expo one) mounts and attaches Privy's runtime. See each entry point.
 */
export function createPrivyAdapter(config: PollarPrivyConfig): InteractiveAuthAdapter {
  const handle = buildPrivyAdapter(config);
  handlesByAdapter.set(handle, handle);
  return handle;
}

/** Recover the internal handle for an adapter created by {@link createPrivyAdapter}. */
export function getPrivyHandle(adapter: InteractiveAuthAdapter): PrivyAdapterHandle | undefined {
  return handlesByAdapter.get(adapter);
}

import { type ReactNode, useEffect, useRef } from 'react';
import { PrivyProvider, useLoginWithEmail, useLoginWithOAuth, usePrivy } from '@privy-io/expo';
import { useCreateWallet, useSignRawHash } from '@privy-io/expo/extended-chains';
import type { User } from '@privy-io/api-types';
import type { InteractiveAuthAdapter } from '@pollar/core';
import type { PollarPrivyConfig } from './config';
import type { PrivyRuntime } from './runtime';
import { getPrivyHandle } from './factory';
import { log } from './log';

export { createPrivyAdapter } from './factory';
export type { PollarPrivyConfig, PollarPrivyAppearance, PrivyLoginMethod } from './config';
export type { AuthOption, InteractiveAuthAdapter, PrivyRuntime } from './runtime';
export { PrivyAdapterUnsupportedError } from './environment';

/** The Stellar `chainType` Privy uses for extended-chain (raw-hash) signing. */
const STELLAR_CHAIN = 'stellar';

/** Find the user's Privy embedded **Stellar** wallet address, if any. */
function findStellarAddress(user: User | null): string | null {
  if (!user) return null;
  for (const account of user.linked_accounts) {
    if (
      account.type === 'wallet' &&
      account.wallet_client_type === 'privy' &&
      // `chain_type` is typed to the public chain union (no `stellar`); the
      // extended-chains wallet carries it at runtime, so compare as a string.
      (account.chain_type as string) === STELLAR_CHAIN
    ) {
      return account.address;
    }
  }
  return null;
}

interface BridgeProps {
  adapter: InteractiveAuthAdapter;
}

/**
 * Inner bridge: runs inside Expo's `<PrivyProvider>`, captures Privy's hooks and
 * attaches them to the adapter as a {@link PrivyRuntime}. Renders nothing.
 */
function PrivyRuntimeBridge({ adapter }: BridgeProps) {
  const handle = getPrivyHandle(adapter);
  const privy = usePrivy();
  const { sendCode, loginWithCode } = useLoginWithEmail();
  const { login } = useLoginWithOAuth();
  const { createWallet } = useCreateWallet();
  const { signRawHash } = useSignRawHash();

  // Hooks return fresh closures each render; keep the latest in a ref so the
  // (stable) runtime object below always calls the current ones.
  const api = useRef({ privy, sendCode, loginWithCode, login, createWallet, signRawHash });
  api.current = { privy, sendCode, loginWithCode, login, createWallet, signRawHash };

  // Trace Privy's auth state + notify subscribers (the host auto-login).
  useEffect(() => {
    const authenticated = !!privy.user;
    const address = findStellarAddress(privy.user);
    log('native: privy state', { authenticated, userId: privy.user?.id ?? null, stellarAddress: address });
    handle?._notifyAuthState({ authenticated, address });
  }, [privy.user, handle]);

  useEffect(() => {
    if (!handle) return;
    log('native: bridge mounted — attaching runtime');
    const runtime: PrivyRuntime = {
      sendEmailCode: async (email) => {
        await api.current.sendCode({ email });
      },
      verifyEmailCode: async (code) => {
        await api.current.loginWithCode({ code });
      },
      loginWithOAuth: async (provider) => {
        // On RN, Expo opens an in-app browser and resolves in-session (no
        // redirect round-trip), so the await completes once the user authenticates.
        log('native: login({ provider }) via in-app browser', { provider });
        await api.current.login({ provider });
      },
      ensureStellarWallet: async () => {
        const existing = findStellarAddress(api.current.privy.user);
        if (existing) {
          log('native: ensureStellarWallet — existing wallet', { address: existing });
          return existing;
        }
        log('native: ensureStellarWallet — none found, creating Stellar wallet');
        const { wallet } = await api.current.createWallet({ chainType: STELLAR_CHAIN });
        log('native: ensureStellarWallet — created', { address: wallet.address });
        return wallet.address;
      },
      signRawHash: async (address, hashHex) => {
        const { signature } = await api.current.signRawHash({
          address,
          chainType: STELLAR_CHAIN,
          hash: `0x${hashHex}`,
        });
        return signature;
      },
      getAddress: () => findStellarAddress(api.current.privy.user),
      logout: () => api.current.privy.logout(),
    };
    handle._attachRuntime(runtime);
    return () => handle._detachRuntime();
  }, [handle]);

  return null;
}

interface PrivyAdapterProviderProps {
  /** The adapter returned by {@link createPrivyAdapter}. */
  adapter: InteractiveAuthAdapter;
  config?: PollarPrivyConfig;
  children: ReactNode;
}

/**
 * Mounts `@privy-io/expo`'s `PrivyProvider` and the runtime bridge around your
 * app. Place it above `<PollarProvider>`. The `config` defaults to the one passed
 * to {@link createPrivyAdapter}; pass it again only to override.
 *
 * Your Expo app must have `@privy-io/expo`'s peer deps installed (including
 * `react-native-webview`, which hosts Privy's secure signer).
 */
export function PrivyAdapterProvider({ adapter, config, children }: PrivyAdapterProviderProps) {
  const handle = getPrivyHandle(adapter);
  const effective = config ?? handle?.config;
  if (!effective) {
    throw new Error(
      '[privy-adapter] PrivyAdapterProvider needs a config — pass `config` or an adapter from createPrivyAdapter.',
    );
  }
  return (
    <PrivyProvider appId={effective.appId} {...(effective.clientId ? { clientId: effective.clientId } : {})}>
      <PrivyRuntimeBridge adapter={adapter} />
      {children}
    </PrivyProvider>
  );
}

import { type ReactNode, useEffect, useRef } from 'react';
import {
  PrivyProvider,
  type PrivyClientConfig,
  type User,
  useLoginWithEmail,
  useLoginWithOAuth,
  usePrivy,
} from '@privy-io/react-auth';
import { useCreateWallet, useSignRawHash } from '@privy-io/react-auth/extended-chains';
import type { InteractiveAuthAdapter } from '@pollar/core';
import type { PollarPrivyConfig } from './config';
import type { PrivyRuntime } from './runtime';
import { getPrivyHandle } from './factory';
import { log } from './log';

export { createPrivyAdapter } from './factory';
export type { PollarPrivyConfig, PollarPrivyAppearance, PrivyLoginMethod } from './config';
export type { AuthOption, InteractiveAuthAdapter, PrivyRuntime } from './runtime';
export { PrivyAdapterUnsupportedError } from './environment';

/** The Stellar `chainType` Privy uses for extended-chain (raw-hash) signing. */
const STELLAR_CHAIN = 'stellar';

/** Find the user's Privy embedded **Stellar** wallet address, if any. */
function findStellarAddress(user: User | null): string | null {
  if (!user) return null;
  for (const account of user.linkedAccounts) {
    if (
      account.type === 'wallet' &&
      account.walletClientType === 'privy' &&
      // `chainType` is typed to the public chain union (no `stellar`); the
      // extended-chains wallet carries it at runtime, so compare as a string.
      (account.chainType as string) === STELLAR_CHAIN
    ) {
      return account.address;
    }
  }
  return null;
}

/** Map the slim Pollar config onto Privy's `PrivyClientConfig`. */
function toPrivyClientConfig(config: PollarPrivyConfig): PrivyClientConfig {
  const cfg: PrivyClientConfig = {
    loginMethods: config.loginMethods as NonNullable<PrivyClientConfig['loginMethods']>,
    // We create the Stellar wallet explicitly via `useCreateWallet`, so disable
    // Privy's automatic EVM/Solana wallet provisioning on login.
    embeddedWallets: {
      ethereum: { createOnLogin: 'off' },
      solana: { createOnLogin: 'off' },
    },
  };
  // Build appearance only from defined fields - `exactOptionalPropertyTypes`
  // forbids assigning `undefined` to optional props.
  const a = config.appearance;
  if (a) {
    const appearance: NonNullable<PrivyClientConfig['appearance']> = {};
    if (a.theme) appearance.theme = a.theme;
    if (a.accentColor) appearance.accentColor = a.accentColor as `#${string}`;
    if (a.logo) appearance.logo = a.logo;
    cfg.appearance = appearance;
  }
  return cfg;
}

interface BridgeProps {
  adapter: InteractiveAuthAdapter;
}

/**
 * Inner bridge: runs inside `<PrivyProvider>`, captures Privy's hooks and
 * attaches them to the adapter as a {@link PrivyRuntime}. Renders nothing.
 */
function PrivyRuntimeBridge({ adapter }: BridgeProps) {
  const handle = getPrivyHandle(adapter);
  const privy = usePrivy();
  const { sendCode, loginWithCode } = useLoginWithEmail();
  const oauthPending = useRef<{ resolve: () => void; reject: (e: unknown) => void } | null>(null);
  const { initOAuth } = useLoginWithOAuth({
    onComplete: () => {
      log('web: useLoginWithOAuth onComplete (OAuth finished)');
      oauthPending.current?.resolve();
      oauthPending.current = null;
    },
    onError: (error) => {
      log('web: useLoginWithOAuth onError', error);
      oauthPending.current?.reject(error);
      oauthPending.current = null;
    },
  });
  const { createWallet } = useCreateWallet();
  const { signRawHash } = useSignRawHash();

  // Hooks return fresh closures each render; keep the latest in a ref so the
  // (stable) runtime object below always calls the current ones.
  const api = useRef({ privy, sendCode, loginWithCode, initOAuth, createWallet, signRawHash });
  api.current = { privy, sendCode, loginWithCode, initOAuth, createWallet, signRawHash };

  // Trace Privy's auth state. If this logs `authenticated: true` but Pollar still
  // shows logged-out, the handoff (login({ provider:'privy' })) never ran - e.g.
  // an OAuth redirect that lost the in-page promise.
  useEffect(() => {
    const address = findStellarAddress(privy.user);
    log('web: privy state', {
      ready: privy.ready,
      authenticated: privy.authenticated,
      userId: privy.user?.id ?? null,
      stellarAddress: address,
    });
    // Notify subscribers (the host auto-login) of the provider's auth state.
    handle?._notifyAuthState({ authenticated: privy.authenticated, address });
  }, [privy.ready, privy.authenticated, privy.user, handle]);

  // Keep the host app's URL clean: once authenticated, strip Privy's OAuth
  // redirect params. react-auth usually does this, but skips it when the user
  // was already logged in - so we always do it ourselves. `replaceState` does
  // not reload or add a history entry.
  useEffect(() => {
    if (!privy.authenticated || typeof window === 'undefined') return;
    if (handle?.config.cleanupOAuthRedirect === false) return;
    const url = new URL(window.location.href);
    const before = url.search;
    for (const param of ['privy_oauth_state', 'privy_oauth_provider', 'privy_oauth_code']) {
      url.searchParams.delete(param);
    }
    if (url.search !== before) {
      log('web: cleaned Privy OAuth params from the URL');
      window.history.replaceState(window.history.state, '', url.toString());
    }
  }, [privy.authenticated, handle]);

  useEffect(() => {
    if (!handle) return;
    log('web: bridge mounted — attaching runtime');
    const runtime: PrivyRuntime = {
      sendEmailCode: (email) => api.current.sendCode({ email }),
      verifyEmailCode: async (code) => {
        await api.current.loginWithCode({ code });
      },
      loginWithOAuth: (provider) =>
        new Promise<void>((resolve, reject) => {
          oauthPending.current = { resolve, reject };
          // On web, `initOAuth` redirects (or opens a popup); completion arrives
          // via the onComplete callback above - after the redirect round-trip,
          // which the Pollar sub-modal resumes once Privy reports authenticated.
          log('web: initOAuth invoked (web uses a redirect/popup)', { provider });
          api.current.initOAuth({ provider }).catch((error) => {
            log('web: initOAuth threw', error);
            oauthPending.current = null;
            reject(error);
          });
        }),
      ensureStellarWallet: async () => {
        const existing = findStellarAddress(api.current.privy.user);
        if (existing) {
          log('web: ensureStellarWallet — existing wallet', { address: existing });
          return existing;
        }
        log('web: ensureStellarWallet — none found, creating Stellar wallet');
        const { wallet } = await api.current.createWallet({ chainType: STELLAR_CHAIN });
        log('web: ensureStellarWallet — created', { address: wallet.address });
        return wallet.address;
      },
      signRawHash: async (address, hashHex) => {
        const { signature } = await api.current.signRawHash({
          address,
          chainType: STELLAR_CHAIN,
          hash: `0x${hashHex}`,
        });
        return signature;
      },
      getAddress: () => findStellarAddress(api.current.privy.user),
      logout: () => api.current.privy.logout(),
    };
    handle._attachRuntime(runtime);
    return () => handle._detachRuntime();
  }, [handle]);

  return null;
}

interface PrivyAdapterProviderProps {
  /** The adapter returned by {@link createPrivyAdapter}. */
  adapter: InteractiveAuthAdapter;
  config?: PollarPrivyConfig;
  /**
   * Optional. In the classic "wrapper" usage you place this above
   * `<PollarProvider>` and pass your app as children, so they sit inside
   * `<PrivyProvider>`'s context. In the "sibling" usage you only need Privy +
   * the runtime bridge mounted (the bridge wires the runtime onto the shared
   * adapter by reference), so children can be omitted entirely.
   */
  children?: ReactNode;
}

/**
 * Mounts `@privy-io/react-auth`'s `PrivyProvider` and the runtime bridge around
 * your app. Place it above `<PollarProvider>`. The `config` defaults to the one
 * passed to {@link createPrivyAdapter}; pass it again only to override.
 */
export function PrivyAdapterProvider({ adapter, config, children }: PrivyAdapterProviderProps) {
  const handle = getPrivyHandle(adapter);
  const effective = config ?? handle?.config;
  if (!effective) {
    throw new Error(
      '[privy-adapter] PrivyAdapterProvider needs a config — pass `config` or an adapter from createPrivyAdapter.',
    );
  }
  return (
    <PrivyProvider
      appId={effective.appId}
      {...(effective.clientId ? { clientId: effective.clientId } : {})}
      config={toPrivyClientConfig(effective)}
    >
      <PrivyRuntimeBridge adapter={adapter} />
      {children}
    </PrivyProvider>
  );
}

// Tiny, opt-in trace logger for debugging the Privy login/sign flow. Off by
// default; enable via `createPrivyAdapter({ debug: true })`. Logs carry the
// `[privy-adapter]` prefix so they're easy to filter in the browser console.

let DEBUG = false;

/** Toggle verbose adapter logging. Called by the adapter factory from config. */
export function setPrivyAdapterDebug(on: boolean): void {
  DEBUG = on;
}

/** Verbose trace log - a no-op unless debug is enabled. */
export function log(message: string, data?: unknown): void {
  if (!DEBUG) return;
  if (data !== undefined) {
    console.log(`[privy-adapter] ${message}`, data);
  } else {
    console.log(`[privy-adapter] ${message}`);
  }
}

