/**
 * @pollar/privy-server-adapter - SERVER-SIDE ONLY.
 *
 * This package binds an HTTP listener via `@hono/node-server` and consumes
 * `PRIVY_APP_SECRET` + `POLLAR_API_SECRET` from the host environment. Do not
 * import it in a browser bundle, a React Native app, or any other client-side
 * runtime - credentials would leak and `node:*` imports would fail to bundle.
 */
import { serve } from '@hono/node-server';
import { LRUCache } from 'lru-cache';
import { createApp } from './server';
import { createPrivyClientFactory } from './privy';
import type { AdapterDeps, PollarPrivyAdapter, PollarPrivyAdapterConfig, ResolvedAdapterConfig, WalletCache } from './types';

const DEFAULT_PORT = 3001;
const DEFAULT_CACHE_TTL_MS = 5 * 60 * 1000;
const DEFAULT_REQUEST_TIMEOUT_MS = 10_000;
const DEFAULT_MAX_BODY_BYTES = 64 * 1024;
const WALLET_CACHE_TTL_MS = 10 * 60 * 1000;
const WALLET_CACHE_MAX = 1000;

export const createPollarPrivyAdapter = (config: PollarPrivyAdapterConfig): PollarPrivyAdapter => {
  const resolvedConfig: ResolvedAdapterConfig = {
    ...config,
    port: config.port ?? DEFAULT_PORT,
    cacheTtlMs: config.cacheTtlMs ?? DEFAULT_CACHE_TTL_MS,
    requestTimeoutMs: config.requestTimeoutMs ?? DEFAULT_REQUEST_TIMEOUT_MS,
    maxBodyBytes: config.maxBodyBytes ?? DEFAULT_MAX_BODY_BYTES,
  };

  const getPrivy = createPrivyClientFactory(resolvedConfig);

  const walletCache: WalletCache = new LRUCache<string, string>({
    max: WALLET_CACHE_MAX,
    ttl: WALLET_CACHE_TTL_MS,
  });

  const deps: AdapterDeps = {
    config: resolvedConfig,
    getPrivy,
    walletCache,
  };

  const app = createApp(deps);

  let server: ReturnType<typeof serve> | null = null;

  return {
    async start(): Promise<void> {
      if (server) return;
      await new Promise<void>((resolve, reject) => {
        const s = serve(
          {
            fetch: app.fetch,
            port: resolvedConfig.port,
          },
          () => resolve(),
        );
        s.once('error', (err: Error) => {
          server = null;
          reject(err);
        });
        server = s;
      });
    },
    async stop(): Promise<void> {
      if (!server) return;
      const s = server;
      server = null;
      await new Promise<void>((resolve, reject) => {
        s.close((err?: Error) => (err ? reject(err) : resolve()));
      });
    },
  };
};

export type { PollarPrivyAdapter, PollarPrivyAdapterConfig, StellarNetwork } from './types';
export { SuccessCode, ErrorCode } from './types';

export const withTimeout = <T>(promise: Promise<T>, timeoutMs: number): Promise<T> => {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => {
      reject(new Error(`Operation timed out after ${timeoutMs}ms`));
    }, timeoutMs);

    promise.then(
      (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      (error: unknown) => {
        clearTimeout(timer);
        reject(error instanceof Error ? error : new Error(String(error)));
      },
    );
  });
};

import { ConflictError, NotFoundError, type LinkedAccount, type PrivyClient, type User } from '@privy-io/node';
import { withTimeout } from './timeout';

export interface PrivyUserResolution {
  user: User;
  created: boolean;
}

// Privy stores the Pollar-userId -> did:privy:... mapping natively in
// linked_accounts[type=custom_auth]. We never persist it on the adapter side:
// every resolution round-trips to Privy. On miss, we create the Privy user
// atomically with a stellar embedded wallet so the next call already has
// everything we need in linked_accounts.
export const getOrCreatePrivyUser = async (
  privy: PrivyClient,
  customUserId: string,
  options: { ensureStellarWallet: boolean; timeoutMs: number },
): Promise<PrivyUserResolution> => {
  try {
    const user = await withTimeout(privy.users().getByCustomAuthID({ custom_user_id: customUserId }), options.timeoutMs);
    return { user, created: false };
  } catch (err) {
    if (!(err instanceof NotFoundError)) throw err;
  }

  try {
    const user = await withTimeout(
      privy.users().create({
        linked_accounts: [{ type: 'custom_auth', custom_user_id: customUserId }],
        ...(options.ensureStellarWallet ? { wallets: [{ chain_type: 'stellar' as const }] } : {}),
      }),
      options.timeoutMs,
    );
    return { user, created: true };
  } catch (err) {
    // Lost a race against a concurrent create - the user exists now.
    if (err instanceof ConflictError) {
      const user = await withTimeout(privy.users().getByCustomAuthID({ custom_user_id: customUserId }), options.timeoutMs);
      return { user, created: false };
    }
    throw err;
  }
};

// Stellar wallets created via users.create show up in linked_accounts as a
// LinkedAccountCurveSigningEmbeddedWallet (type='wallet', chain_type='stellar').
// The Privy type permits id: string | null, so we defensively skip null ids.
export const findStellarWalletInUser = (user: User): { id: string; address: string } | null => {
  for (const account of user.linked_accounts as LinkedAccount[]) {
    if (account.type !== 'wallet') continue;
    if (!('chain_type' in account) || account.chain_type !== 'stellar') continue;
    if (!account.id || !account.address) continue;
    return { id: account.id, address: account.address };
  }
  return null;
};

import { timingSafeEqual } from 'node:crypto';
import type { Context, Next } from 'hono';
import { ErrorCode, type AppEnv } from '../types';

const WWW_AUTH_MISSING = 'Bearer realm="pollar-privy-adapter"';
const WWW_AUTH_INVALID = 'Bearer realm="pollar-privy-adapter", error="invalid_token"';

export const createBearerMiddleware = (pollarApiSecret: string) => {
  const expected = Buffer.from(pollarApiSecret, 'utf8');

  return async (c: Context<AppEnv>, next: Next): Promise<Response | void> => {
    const auth = c.req.header('Authorization');
    if (!auth || !auth.startsWith('Bearer ')) {
      c.header('WWW-Authenticate', WWW_AUTH_MISSING);
      return c.var.error(ErrorCode.FORBIDDEN, 401);
    }

    const provided = Buffer.from(auth.slice(7), 'utf8');
    // timingSafeEqual throws on length mismatch - guard first.
    if (provided.length !== expected.length || !timingSafeEqual(provided, expected)) {
      c.header('WWW-Authenticate', WWW_AUTH_INVALID);
      return c.var.error(ErrorCode.FORBIDDEN, 401);
    }

    await next();
  };
};

import type { Context, Next } from 'hono';
import type { AppEnv, PaginationMeta } from '../types';
import { ErrorCode, SuccessCode } from '../types';

export const responseMiddleware = async (c: Context<AppEnv>, next: Next) => {
  c.set('content', <T>(code: SuccessCode, content: T, status?: number) =>
    c.json({ content, code, success: true }, (status ?? 200) as never),
  );

  c.set('contents', <T>(contents: T[], meta: PaginationMeta) => c.json({ contents, success: true, meta }));

  c.set('error', (code: ErrorCode, status?: number, extra?: Record<string, unknown>) => {
    return c.json({ code, success: false, ...extra }, (status ?? 400) as never);
  });

  await next();
};

import { createHash } from 'node:crypto';
import { PrivyClient } from '@privy-io/node';
import type { ResolvedAdapterConfig } from './types';

interface CacheEntry {
  fingerprint: string;
  client: PrivyClient;
  expiresAt: number;
}

export const createPrivyClientFactory = (config: ResolvedAdapterConfig) => {
  let entry: CacheEntry | null = null;
  // Coalesce concurrent expired-cache calls. Without this, two requests
  // arriving while `entry` is null/expired would each call
  // `config.getCredentials()` and `new PrivyClient(...)`, with the second
  // overwriting the first - wasted creds fetch + an orphaned client.
  let pending: Promise<PrivyClient> | null = null;

  return async (): Promise<PrivyClient> => {
    const now = Date.now();

    if (entry && entry.expiresAt > now) {
      return entry.client;
    }

    if (pending) return pending;

    pending = (async () => {
      try {
        const { appId, appSecret } = await config.getCredentials();
        const fingerprint = createHash('sha256').update(`${appId}:${appSecret}`).digest('hex');

        if (entry && entry.fingerprint === fingerprint) {
          // Credentials unchanged - extend TTL, keep client to avoid reconnect overhead.
          entry.expiresAt = Date.now() + config.cacheTtlMs;
          return entry.client;
        }

        const client = new PrivyClient({ appId, appSecret, timeout: config.requestTimeoutMs });
        entry = { fingerprint, client, expiresAt: Date.now() + config.cacheTtlMs };
        return client;
      } finally {
        pending = null;
      }
    })();

    return pending;
  };
};

import { Hono } from 'hono';
import { type AppEnv, SuccessCode } from '../types';

export const createHealthRoute = () => {
  const app = new Hono<AppEnv>();

  app.get('/', (c) =>
    c.var.content(SuccessCode.PRIVY_ADAPTER_HEALTH_OK, {
      ok: true,
      timestamp: Date.now(),
    }),
  );

  return app;
};

import { Hono } from 'hono';
import { type AdapterDeps, type AppEnv, ErrorCode, SuccessCode } from '../types';
import { withTimeout } from '../lib/timeout';

export const createWalletsAddressRoute = (deps: AdapterDeps) => {
  const app = new Hono<AppEnv>();

  app.get('/:userId/address', async (c) => {
    const userId = c.req.param('userId');
    if (!userId) {
      return c.var.error(ErrorCode.VALIDATION_ERROR, 400);
    }

    try {
      const privy = await deps.getPrivy();
      const list = await withTimeout(
        privy.wallets().list({ chain_type: 'stellar', user_id: userId }),
        deps.config.requestTimeoutMs,
      );

      const wallet = list.data[0];
      if (!wallet) {
        return c.var.error(ErrorCode.WALLET_NOT_FOUND, 404);
      }

      deps.walletCache.set(wallet.address, wallet.id);

      return c.var.content(SuccessCode.PRIVY_ADAPTER_WALLET_ADDRESS, { address: wallet.address });
    } catch (error) {
      const err = error instanceof Error ? error : new Error(String(error));
      // Raw error to `onError` (server-side logs); HTTP response is code-only.
      deps.config.onError?.(err, { endpoint: `GET /wallets/${userId}/address`, body: null });
      return c.var.error(ErrorCode.WALLET_LOOKUP_FAILED, 502);
    }
  });

  return app;
};

import { Hono } from 'hono';
import { z } from 'zod';
import { type AdapterDeps, type AppEnv, ErrorCode, SuccessCode } from '../types';
import { withTimeout } from '../lib/timeout';
import { findStellarWalletInUser, getOrCreatePrivyUser } from '../lib/user-mapping';

const BodySchema = z.object({
  userId: z.string().min(1),
});

export const createWalletsCreateRoute = (deps: AdapterDeps) => {
  const app = new Hono<AppEnv>();

  /**
   * In-process dedupe of concurrent create requests for the same userId.
   *
   * `getOrCreatePrivyUser` already handles the user-creation race (Privy
   * returns `ConflictError` on the second `users.create`, we fall back to
   * fetch). But for an EXISTING user without a stellar wallet, both
   * requests fall through `findStellarWalletInUser -> null` and both call
   * `wallets().create(...)` - Privy doesn't dedupe by user, so you get two
   * stellar wallets attached to the same Privy user, with the second
   * overwriting the first in `walletCache`.
   *
   * The mutex is per-process: scaling the adapter to N replicas reintroduces
   * the race across instances. That's an accepted trade-off - the adapter is
   * documented as stateless beyond in-memory caches.
   */
  const inflight = new Map<string, Promise<{ address: string; walletCreated: boolean }>>();

  app.post('/', async (c) => {
    let parsed: z.infer<typeof BodySchema>;
    try {
      const body = (await c.req.json()) as unknown;
      parsed = BodySchema.parse(body);
    } catch (e) {
      const issues = e instanceof z.ZodError ? e.flatten() : { message: 'invalid JSON' };
      return c.var.error(ErrorCode.VALIDATION_ERROR, 400, { issues });
    }

    const { userId } = parsed;

    try {
      let promise = inflight.get(userId);
      if (!promise) {
        promise = (async () => {
          try {
            const privy = await deps.getPrivy();

            // Privy's API requires owner.user_id to be a did:privy: identifier, not
            // Pollar's SDK user CUID. We resolve (or create) the Privy user via
            // custom_auth linked_accounts; users.create returns the wallet inline.
            const { user, created } = await getOrCreatePrivyUser(privy, userId, {
              ensureStellarWallet: true,
              timeoutMs: deps.config.requestTimeoutMs,
            });

            let stellar = findStellarWalletInUser(user);
            let walletCreated = created && stellar !== null;

            // Existing user with no stellar wallet (pre-stellar account, or wallet
            // detached). Provision one now, owned by the resolved DID.
            if (!stellar) {
              const wallet = await withTimeout(
                privy.wallets().create({ chain_type: 'stellar', owner: { user_id: user.id } }),
                deps.config.requestTimeoutMs,
              );
              stellar = { id: wallet.id, address: wallet.address };
              walletCreated = true;
            }

            deps.walletCache.set(stellar.address, stellar.id);
            // Fire `onWalletCreated` inside the de-duplicated block so it
            // emits exactly once per actual creation, not once per coalesced
            // request awaiter.
            if (walletCreated) {
              deps.config.onWalletCreated?.(userId, stellar.address);
            }
            return { address: stellar.address, walletCreated };
          } finally {
            inflight.delete(userId);
          }
        })();
        inflight.set(userId, promise);
      }

      const { address, walletCreated } = await promise;
      if (walletCreated) {
        return c.var.content(SuccessCode.PRIVY_ADAPTER_WALLET_CREATED, { address }, 201);
      }
      return c.var.content(SuccessCode.PRIVY_ADAPTER_WALLET_EXISTS, { address });
    } catch (error) {
      const err = error instanceof Error ? error : new Error(String(error));
      // Raw error to `onError` (server-side logs); HTTP response is code-only
      // so Privy internals don't leak to the caller.
      deps.config.onError?.(err, { endpoint: 'POST /wallets/create', body: parsed });
      return c.var.error(ErrorCode.WALLET_CREATION_FAILED, 502);
    }
  });

  return app;
};

import { Hono } from 'hono';
import type { Transaction } from '@stellar/stellar-sdk';
import { NotFoundError } from '@privy-io/node';
import { z } from 'zod';
import { type AdapterDeps, type AppEnv, ErrorCode, SuccessCode } from '../types';
import { withTimeout } from '../lib/timeout';
import { findStellarWalletInUser } from '../lib/user-mapping';
import { assembleSignedXdr, parseTx, validateTxOperations } from '../stellar';

const BodySchema = z.object({
  userId: z.string().min(1),
  walletAddress: z.string().min(1),
  txXdr: z.string().min(1),
});

export const createWalletsSignRoute = (deps: AdapterDeps) => {
  const app = new Hono<AppEnv>();

  app.post('/', async (c) => {
    let parsed: z.infer<typeof BodySchema>;
    try {
      const body = (await c.req.json()) as unknown;
      parsed = BodySchema.parse(body);
    } catch (e) {
      const issues = e instanceof z.ZodError ? e.flatten() : { message: 'invalid JSON' };
      return c.var.error(ErrorCode.VALIDATION_ERROR, 400, { issues });
    }

    const { userId, walletAddress, txXdr } = parsed;

    let tx: Transaction;
    try {
      tx = parseTx(txXdr, deps.config.network);
    } catch {
      return c.var.error(ErrorCode.TX_INVALID_SIGNED_XDR, 400);
    }

    // Operation allowlist gate. Privy can't apply per-operation policy (it only
    // ever sees the tx hash via rawSign), so this is the only enforcement point.
    // Runs before any Privy round-trip so a disallowed tx never reaches signing.
    const policyCheck = validateTxOperations(tx, {
      allowedOperations: deps.config.allowedOperations,
      restrictToTrustlines: deps.config.restrictToTrustlines,
    });
    if (!policyCheck.ok) {
      return c.var.error(ErrorCode.TX_OPERATION_NOT_ALLOWED, 403, { reason: policyCheck.reason });
    }

    try {
      let walletId = deps.walletCache.get(walletAddress);

      if (!walletId) {
        // Cache miss: resolve userId -> did:privy: and inspect linked_accounts
        // to find the matching wallet. We do NOT auto-create here; sign without
        // a pre-existing wallet must surface as WALLET_NOT_FOUND so the caller
        // can route through the create flow first.
        const privy = await deps.getPrivy();

        let user;
        try {
          user = await withTimeout(privy.users().getByCustomAuthID({ custom_user_id: userId }), deps.config.requestTimeoutMs);
        } catch (err) {
          if (err instanceof NotFoundError) {
            return c.var.error(ErrorCode.WALLET_NOT_FOUND, 404);
          }
          throw err;
        }

        const stellar = findStellarWalletInUser(user);
        if (!stellar || stellar.address !== walletAddress) {
          return c.var.error(ErrorCode.WALLET_NOT_FOUND, 404);
        }
        walletId = stellar.id;
        deps.walletCache.set(walletAddress, walletId);
      }

      const privy = await deps.getPrivy();
      const hashHex = '0x' + tx.hash().toString('hex');

      let result;
      try {
        result = await withTimeout(
          privy.wallets().rawSign(walletId, { params: { hash: hashHex } }),
          deps.config.requestTimeoutMs,
        );
      } catch (err) {
        // Cache may have a stale walletId (wallet detached / deleted on
        // Privy side between resolution and now). Evict so the next request
        // re-resolves from Privy - this request still fails, but we don't
        // keep returning errors for the same stale entry until TTL expires.
        if (err instanceof NotFoundError) {
          deps.walletCache.delete(walletAddress);
          return c.var.error(ErrorCode.WALLET_NOT_FOUND, 404);
        }
        throw err;
      }

      const sigHex = result.signature.startsWith('0x') ? result.signature.slice(2) : result.signature;
      const sigBytes = Buffer.from(sigHex, 'hex');

      const signedTxXdr = assembleSignedXdr(tx, walletAddress, sigBytes);

      deps.config.onTransactionSigned?.(walletAddress);

      return c.var.content(SuccessCode.PRIVY_ADAPTER_TX_SIGNED, { signedTxXdr });
    } catch (error) {
      const err = error instanceof Error ? error : new Error(String(error));
      // Raw error goes to the host's `onError` callback for server-side logging
      // (Privy SDK errors can include user IDs, rate-limit context, internal
      // identifiers - none of which the caller should see). The HTTP response
      // is intentionally code-only.
      deps.config.onError?.(err, { endpoint: 'POST /wallets/sign', body: parsed });
      return c.var.error(ErrorCode.TX_SIGN_FAILED, 502);
    }
  });

  return app;
};

import { Hono } from 'hono';
import { bodyLimit } from 'hono/body-limit';
import { type AdapterDeps, type AppEnv, ErrorCode } from './types';
import { responseMiddleware } from './middleware/response';
import { createBearerMiddleware } from './middleware/bearer';
import { createHealthRoute } from './routes/health';
import { createWalletsCreateRoute } from './routes/wallets-create';
import { createWalletsSignRoute } from './routes/wallets-sign';
import { createWalletsAddressRoute } from './routes/wallets-address';

export const createApp = (deps: AdapterDeps): Hono<AppEnv> => {
  const app = new Hono<AppEnv>();

  app.use('*', responseMiddleware);

  app.use(
    '*',
    bodyLimit({
      maxSize: deps.config.maxBodyBytes,
      onError: (c) => c.var.error(ErrorCode.VALIDATION_ERROR, 413, { reason: 'body too large' }),
    }),
  );

  app.route('/health', createHealthRoute());

  const auth = createBearerMiddleware(deps.config.pollarApiSecret);
  app.use('/wallets/*', auth);

  app.route('/wallets/create', createWalletsCreateRoute(deps));
  app.route('/wallets/sign', createWalletsSignRoute(deps));
  app.route('/wallets', createWalletsAddressRoute(deps));

  app.onError((error, c) => {
    deps.config.onError?.(error, { endpoint: c.req.path, body: null });
    return c.var.error(ErrorCode.INTERNAL_SERVER_ERROR, 500);
  });

  return app;
};

import { FeeBumpTransaction, Keypair, Networks, Transaction, TransactionBuilder, xdr } from '@stellar/stellar-sdk';
import type { StellarNetwork } from './types';

const passphraseFor = (network: StellarNetwork): string => (network === 'mainnet' ? Networks.PUBLIC : Networks.TESTNET);

export const parseTx = (txXdr: string, network: StellarNetwork): Transaction => {
  const tx = TransactionBuilder.fromXDR(txXdr, passphraseFor(network));
  if (tx instanceof FeeBumpTransaction) {
    throw new Error('Fee-bump transactions are not supported by this adapter');
  }
  return tx;
};

/**
 * Operation types implied by `restrictToTrustlines`: a `changeTrust` plus the
 * optional reserve-sponsorship sandwich that wraps it.
 */
export const TRUSTLINE_OPERATION_ALLOWLIST = [
  'changeTrust',
  'beginSponsoringFutureReserves',
  'endSponsoringFutureReserves',
] as const;

export interface OperationPolicy {
  allowedOperations?: string[] | undefined;
  restrictToTrustlines?: boolean | undefined;
}

export interface OperationValidation {
  ok: boolean;
  reason?: string;
}

/**
 * Enforces the configured operation allowlist on a parsed transaction.
 *
 * Precedence:
 *  - If neither field is set -> no restriction (legacy behavior): `{ ok: true }`.
 *  - `allowedOperations` (when set) is the base allowlist of stellar-sdk
 *    operation type names.
 *  - `restrictToTrustlines: true` adds the trustline preset
 *    (`TRUSTLINE_OPERATION_ALLOWLIST`) to the allowlist - so the effective set is
 *    the UNION of `allowedOperations` and the preset - and additionally requires
 *    the transaction to contain at least one `changeTrust` operation.
 *
 * Returns `{ ok: false, reason }` on the first violation; `reason` is safe to
 * surface to the caller (it names only the offending operation type).
 */
export const validateTxOperations = (tx: Transaction, policy: OperationPolicy): OperationValidation => {
  const restrict = policy.restrictToTrustlines === true;

  // No allowlist configured at all -> legacy: sign any (non-fee-bump) tx.
  if (!restrict && !policy.allowedOperations) {
    return { ok: true };
  }

  const allowed = new Set<string>(policy.allowedOperations ?? []);
  if (restrict) {
    for (const op of TRUSTLINE_OPERATION_ALLOWLIST) allowed.add(op);
  }

  for (const op of tx.operations) {
    if (!allowed.has(op.type)) {
      return { ok: false, reason: `Operation '${op.type}' is not allowed` };
    }
  }

  if (restrict && !tx.operations.some((op) => op.type === 'changeTrust')) {
    return { ok: false, reason: 'Transaction must contain at least one changeTrust operation' };
  }

  return { ok: true };
};

export const assembleSignedXdr = (tx: Transaction, walletAddress: string, signatureBytes: Buffer): string => {
  const keypair = Keypair.fromPublicKey(walletAddress);
  const decorated = new xdr.DecoratedSignature({
    hint: keypair.signatureHint(),
    signature: signatureBytes,
  });
  tx.signatures.push(decorated);
  return tx.toEnvelope().toXDR('base64');
};

import type { LRUCache } from 'lru-cache';
import type { PrivyClient } from '@privy-io/node';

export type StellarNetwork = 'mainnet' | 'testnet';

export interface PaginationMeta {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
}

export enum SuccessCode {
