const coreExamples: Record<FeatureName, string> = {
  authentication: 'client.beginEmailLogin();\nclient.sendEmailCode(email);\nclient.verifyEmailCode(code);',
  logout: 'await client.logout();',
  wallet: 'const data = await client.getWalletBalance(publicKey);',
  receive: 'const wallets = client.getWallets();\n// Render the selected wallet address as a native QR.',
  chains: 'const wallets = client.getWallets();',
  send: "const result = await client.runTx('payment', {\n  destination, amount: '1', asset: { type: 'native' }\n});",
  assets:
    "await client.refreshAssets();\nconst assets = client.getEnabledAssetsState();\nawait client.setTrustline({ code: 'USDC', issuer });",
  history: 'await client.fetchTxHistory();\nconst history = client.getTxHistoryState();',
  sessions: 'await client.fetchSessions();\nconst sessions = client.getSessionsState();\nawait client.revokeSession(familyId);',
  transactions:
    "await client.buildTx('payment', { destination, amount: '1', asset: { type: 'native' } });\nconst state = client.getTransactionState();",
  kyc: '// KYC is a preview only. No backend approval is emitted.',
  ramp: "import { describeRampAction } from '@pollar/core';\n\n// Choose a route from the authenticated catalog.\nconst { routes } = await client.getRampRoutes();\nconst route = routes[0]; // Replace with the user's selection.\nif (!route) throw new Error('No executable ramp routes are available.');\n\nconst amountExact = '20.00';\nconst { quotes } = await client.getRampsQuote({\n  routeId: route.routeId,\n  chain: route.asset.chain,\n  country: route.country,\n  currency: route.fiatCurrency,\n  direction: route.direction,\n  amount: Number(amountExact), // Existing compatibility field.\n  amountExact,\n  amountDenomination: 'fiat',\n});\nconst quote = quotes[0];\nif (!quote) throw new Error('No quote is available.');\n\n// Show quote.terms, quote.expiresAt and quote.requiredFields.\n// Call this only after review; fields come from the user's form.\nasync function acceptQuote(fields: Record<string, string>) {\n  const body = {\n    quoteId: quote.quoteId,\n    country: route.country,\n    currency: route.fiatCurrency,\n    amount: quote.fiatAmount ?? Number(amountExact),\n    amountExact: quote.terms?.fiatAmount ?? amountExact,\n    fields,\n  };\n  return route.direction === 'onramp'\n    ? client.createOnRamp(body)\n    : client.createOffRamp(body);\n}\n\n// Resume with the saved transaction ID; reads never authorize payment.\nasync function readStatus(txId: string) {\n  const saved = await client.getRampTransaction(txId);\n  // Render saved.terms, saved.nextAction and saved.milestones.\n  return saved;\n}\n\n// Call only from an explicit Continue / Authorize button.\nasync function continueFromButton(txId: string, fields: Record<string, string> = {}) {\n  const saved = await readStatus(txId);\n  const view = describeRampAction(saved);\n  if (view.canSign) return client.signRampAction(txId, saved);\n  if (view.canContinue && saved.nextAction && saved.transactionVersion !== undefined) {\n    return client.continueRamp(txId, {\n      actionId: saved.nextAction.actionId,\n      transactionVersion: saved.transactionVersion,\n      fields,\n    });\n  }\n}",
  swap: "const quotes = await client.getSwapQuote({ sellAsset, buyAsset, amount: '1' });\n// Review a quote before client.swap(quote).",
  earn: 'const providers = await client.getEarnProviders();\nconst opportunities = await client.getEarnOpportunities(providers[0]);\n// Inspect a position before depositing or withdrawing.',
  distribution:
    'const rules = await client.listDistributionRules();\n// Review eligibility before client.claimDistributionRule({ ruleId }).',
};
export function FeatureExample({
