    !t.issuer || t.issuer === '0'
      ? { type: 'native' as const }
      : {
          type: t.code.length <= 4 ? ('credit_alphanum4' as const) : ('credit_alphanum12' as const),
          code: t.code,
          issuer: t.issuer,
