          void action.run(async () => {
            const q = await p.getSwapQuote({
              sellAsset: swapAsset(tokens.find((t) => tokenKey(t) === sell)!),
              buyAsset: swapAsset(tokens.find((t) => tokenKey(t) === buy)!),
              amount,
              slippageBps: 50,
            });
            setQuotes(q);
            return q;
          })
