import type { RampQuoteRequirement } from '@pollar/core';
import { kycReviewMessage } from '../kyc-modal/kyc-messages';

/**
 * A requirement step the user must complete before a route: a KYC option, a form, a
 * registry option, or (for PROVIDER_REGISTRATION) the registration of `corridorId`.
 */
export type PendingRequirement = {
  rampProviderId: string;
  corridorId: string;
  type: 'KYC' | 'FORM' | 'REGISTRY_CHECK' | 'PROVIDER_REGISTRATION';
  optionId: string;
  /** Known when it comes from the quote; the start gate does not say. */
  progress?: { position: number; total: number };
};

const nonEmpty = (value: unknown): value is string => typeof value === 'string' && !!value.trim();

/**
 * The step the backend's start gate names, or null for any other error. v2 says
 * `requirementType` and `optionId`; a KYC-only body names the option as `kycProviderId`.
 */
export function requiredRampKyc(error: unknown): PendingRequirement | null {
  if (!error || typeof error !== 'object') return null;
  const { code, body } = error as { code?: unknown; body?: unknown };
  if (code !== 'SDK_RAMPS_KYC_REQUIRED' || !body || typeof body !== 'object') return null;
  const { rampProviderId, corridorId, requirementType, optionId, kycProviderId } = body as Record<string, unknown>;
  if (!nonEmpty(rampProviderId) || !nonEmpty(corridorId)) return null;
  if (
    (requirementType === 'FORM' || requirementType === 'REGISTRY_CHECK' || requirementType === 'PROVIDER_REGISTRATION') &&
    nonEmpty(optionId)
  ) {
    return { rampProviderId, corridorId, type: requirementType, optionId };
  }
  const kyc = nonEmpty(optionId) && requirementType === 'KYC' ? optionId : kycProviderId;
  return nonEmpty(kyc) ? { rampProviderId, corridorId, type: 'KYC', optionId: kyc } : null;
}

/** The step a locked route names in the quote. */
export function pendingFromQuote(requirement: RampQuoteRequirement): PendingRequirement {
  return {
    rampProviderId: requirement.rampProviderId,
    corridorId: requirement.corridorId,
    type: requirement.type,
    optionId: requirement.optionId,
    progress: { position: requirement.completed + 1, total: requirement.total },
  };
}

/**
 * What a route held back by a requirement step says, and the button it offers. A verification
 * held for review (`reviewReason`) or rejected has nothing the user can do from
 * here, so those rows carry no button.
 */
export function lockedRouteCopy(requirement: Pick<RampQuoteRequirement, 'status' | 'reviewReason'> & { type?: string }): {
  message: string;
  action: string | null;
} {
  if (requirement.type === 'FORM') return { message: 'Answer a few questions to see this route', action: 'Continue' };
  if (requirement.type === 'PROVIDER_REGISTRATION') {
    return { message: 'Register with the provider to see this route', action: 'Continue' };
  }
  if (requirement.type === 'REGISTRY_CHECK') {
    return requirement.status === 'pending'
      ? { message: 'Your details are under review', action: null }
      : { message: 'Confirm your details to see this route', action: 'Confirm' };
  }
  switch (requirement.status) {
    case 'expired':
      return { message: 'Your verification expired', action: 'Verify again' };
    case 'pending':
      if (!requirement.reviewReason) return { message: 'Verification in progress', action: 'Continue' };
      return {
        message:
          requirement.reviewReason === 'DUPLICATE_DOCUMENT'
            ? kycReviewMessage(requirement.reviewReason)
            : 'Your verification is under review',
        action: null,
      };
    case 'rejected':
      return { message: 'Verification was not approved', action: null };
    default:
      return { message: 'Verify your identity to see this route', action: 'Verify' };
  }
}

import React, { useEffect, useMemo, useRef, useState } from 'react';
import { ActivityIndicator, ScrollView, StyleSheet, Text, TextInput, TouchableOpacity, View } from 'react-native';
import type { RegistryCheck, RegistryCheckPrefill } from '@pollar/core';
import { usePollar } from '../../context';
import { PollarModalFooter } from '../commons';
import { formLanguage } from '../requirement-form-modal/form-fields';
import { errorCode, REGISTRY_COPY } from './registry-copy';

export interface RegistryCheckModalProps {
  optionId: string;
  /** Position of this step over the route's steps, when known. */
  progress?: { position: number; total: number } | undefined;
  onClose: () => void;
  /** Called once the registry confirmed the data. */
  onApproved: () => void;
}

/**
 * One REGISTRY_CHECK step (SEGIP): the user's verified data, prefilled and read-only
 * except for the surname split and the CI complement, sent to the registry on confirm.
 */
export function RegistryCheckModal({ optionId, progress, onClose, onApproved }: RegistryCheckModalProps) {
  const { getClient, styles: pollarStyles } = usePollar();
  const { theme = 'light', accentColor = '#005DB4' } = pollarStyles;
  const client = getClient();
  const language = useMemo(formLanguage, []);
  const copy = REGISTRY_COPY[language];
  const isDark = theme === 'dark';
  const colors = {
    text: isDark ? '#ffffff' : '#111827',
    muted: isDark ? '#9ca3af' : '#6b7280',
    error: isDark ? '#f87171' : '#dc2626',
    border: isDark ? '#374151' : '#e5e7eb',
    itemBg: isDark ? '#262626' : '#f9fafb',
  };

  const [check, setCheck] = useState<RegistryCheck | null>(null);
  const [surname1, setSurname1] = useState('');
  const [surname2, setSurname2] = useState('');
  const [complement, setComplement] = useState('');
  const [error, setError] = useState<string | null>(null);
  /** Fields the registry did not confirm on the last check, outlined until the next try. */
  const [rejected, setRejected] = useState<string[]>([]);
  const [review, setReview] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const mounted = useRef(true);
  useEffect(() => {
    // Set on every mount: development mounts components twice, and the cleanup of the
    // first mount would otherwise leave this false and drop every response.
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  useEffect(() => {
    client
      .getRegistryCheck(optionId)
      .then((loaded) => {
        if (!mounted.current) return;
        if (loaded.status === 'approved') return onApproved();
        setCheck(loaded);
        if (loaded.status === 'pending') setReview(true);
        // A check the registry did not confirm on the surnames or the complement: say which, keep the form open.
        if (loaded.status === 'rejected') showRejected(loaded.rejectedFields);
        if (loaded.prefill.applies) {
          setSurname1(loaded.prefill.surname1);
          setSurname2(loaded.prefill.surname2 ?? '');
          setComplement(loaded.prefill.complementNumber ?? '');
        }
      })
      .catch((e: unknown) => {
        if (!mounted.current) return;
        setError(errorCode(e) === 'KYC_REGISTRY_IDENTITY_REQUIRED' ? copy.identityRequired : copy.loadError);
      });
    // The client instance and the copy do not change while the modal is open.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [optionId]);

  const prefill: RegistryCheckPrefill | null = check?.prefill.applies ? check.prefill : null;

  /** Say which fields the registry did not confirm and outline them; the form stays open. */
  function showRejected(fields: string[] | undefined) {
    const labels: Record<string, string> = {
      surname1: copy.surname1,
      surname2: copy.surname2,
      complementNumber: copy.complement,
    };
    const named = fields?.length ? fields : ['surname2'];
    setRejected(named);
    setError(copy.rejected.replace('{fields}', named.map((field) => labels[field] ?? field).join(', ')));
  }

  async function submit() {
    if (!prefill) return;
    setSubmitting(true);
    setError(null);
    setRejected([]);
    try {
      const result = await client.submitRegistryCheck(optionId, {
        surname1: surname1.trim(),
        ...(surname2.trim() ? { surname2: surname2.trim() } : {}),
        ...(complement.trim() ? { complementNumber: complement.trim() } : {}),
      });
      if (!mounted.current) return;
      if (result.status === 'approved') onApproved();
      else if (result.status === 'rejected') showRejected(result.rejectedFields);
      else setReview(true);
    } catch (e) {
      if (!mounted.current) return;
      const code = errorCode(e);
      // A check recorded while this screen was open (a slow answer the client gave up on) is the approval.
      if (code === 'SDK_KYC_ALREADY_APPROVED') return onApproved();
      if (code === 'KYC_REGISTRY_NAME_MISMATCH') {
        setError(copy.nameMismatch.replace('{full}', [prefill.surname1, prefill.surname2].filter(Boolean).join(' ')));
      } else if (code === 'SDK_KYC_UNDER_REVIEW') setReview(true);
      else setError(copy.submitError);
    } finally {
      if (mounted.current) setSubmitting(false);
    }
  }

  const input = [styles.input, { borderColor: colors.border, backgroundColor: colors.itemBg, color: colors.text }];
  const readOnly = (label: string, value: string) => (
    <View style={styles.field}>
      <Text style={[styles.label, { color: colors.text }]}>{label}</Text>
      <TextInput style={[input, { opacity: 0.6 }]} value={value} editable={false} />
    </View>
  );
  const editable = (
    label: string,
    value: string,
    onChange: (value: string) => void,
    extra: { maxLength?: number; invalid?: boolean } = {},
  ) => (
    <View style={styles.field}>
      <Text style={[styles.label, { color: colors.text }]}>{label}</Text>
      <TextInput
        style={[input, extra.invalid ? { borderColor: colors.error } : null]}
        value={value}
        editable={!submitting}
        autoCapitalize="characters"
        onChangeText={onChange}
        maxLength={extra.maxLength}
      />
    </View>
  );

  return (
    <View style={styles.overlay}>
      <View style={styles.modalWrapper}>
        <View style={[styles.card, { backgroundColor: isDark ? '#1a1a1a' : '#ffffff', borderColor: colors.border }]}>
          <View style={styles.header}>
            <Text style={[styles.title, { color: colors.text }]}>{copy.title}</Text>
            {progress && (
              <Text style={{ color: colors.muted, fontSize: 14, marginTop: 4 }}>
                {copy.step.replace('{n}', String(progress.position)).replace('{total}', String(progress.total))}
              </Text>
            )}
          </View>
          <TouchableOpacity
            style={[styles.closeBtn, { borderColor: colors.border }]}
            onPress={onClose}
            accessibilityLabel={copy.close}
          >
            <Text style={{ color: colors.muted, fontSize: 16 }}>✕</Text>
          </TouchableOpacity>

          {!!error && (
            <View style={[styles.notice, { borderColor: colors.border, borderLeftColor: accentColor }]}>
              <Text style={{ color: colors.text, fontSize: 14, lineHeight: 20 }} accessibilityRole="alert">
                {error}
              </Text>
            </View>
          )}

          {!check && !error && (
            <View style={styles.loadingBox}>
              <ActivityIndicator size="large" color={accentColor} />
            </View>
          )}

          {check && (review || !prefill) && (
            <View style={[styles.notice, { borderColor: colors.border, borderLeftColor: accentColor }]}>
              <Text style={{ color: colors.text, fontSize: 14, lineHeight: 20 }}>
                {review ? copy.review : copy.notApplicable}
              </Text>
            </View>
          )}

          {prefill && !review && (
            <ScrollView style={{ maxHeight: 420 }} keyboardShouldPersistTaps="handled">
              <Text style={{ color: colors.muted, fontSize: 14, marginBottom: 12 }}>{copy.intro}</Text>
              {readOnly(copy.givenNames, prefill.givenNames)}
              {editable(`${copy.surname1} *`, surname1, setSurname1, { invalid: rejected.includes('surname1') })}
              {editable(copy.surname2, surname2, setSurname2, { invalid: rejected.includes('surname2') })}
              {readOnly(copy.birthdate, prefill.birthdate)}
              {readOnly(copy.documentNumber, prefill.documentNumber)}
              {editable(copy.complement, complement, (value) => setComplement(value.toUpperCase().replace(/[^0-9A-Z]/g, '')), {
                maxLength: 3,
                invalid: rejected.includes('complementNumber'),
              })}
            </ScrollView>
          )}

          {prefill && !review && (
            <TouchableOpacity
              style={[styles.primaryBtn, { backgroundColor: accentColor, opacity: submitting || !surname1.trim() ? 0.6 : 1 }]}
              onPress={() => void submit()}
              disabled={submitting || !surname1.trim()}
            >
              <Text style={styles.primaryBtnText}>{submitting ? copy.submitting : copy.submit}</Text>
            </TouchableOpacity>
          )}
          <TouchableOpacity
            style={[styles.secondaryBtn, { borderColor: colors.border }]}
            onPress={onClose}
            disabled={submitting}
          >
            <Text style={{ color: colors.text, fontWeight: '600' }}>{copy.close}</Text>
          </TouchableOpacity>
          <PollarModalFooter />
        </View>
      </View>
    </View>
  );
}

