'use client';

import { EnabledAssetRecord, WalletChain } from '@pollar/core';
import { useCallback, useEffect, useState } from 'react';
import { usePollar } from '../../context';
import { useChains } from '../../useChains';
import { addressForChain } from '../ChainSelect';
import '../shared.css';
import './EnabledAssetsModal.css';
import { CustomTrustlineModalTemplate, EnabledAssetsModalTemplate } from './EnabledAssetsModalTemplate';
import { modalChrome } from '../modal-theme';

interface EnabledAssetsModalProps {
  onClose: () => void;
}

function assetKey(record: { code: string; issuer?: string }): string {
  return record.code + (record.issuer ?? '');
}

export function EnabledAssetsModal({ onClose }: EnabledAssetsModalProps) {
  const { enabledAssets, refreshAssets, setTrustline, wallets, styles } = usePollar();
  const { theme, accentColor, styleOverrides, overlayStyle } = modalChrome(styles);

  const { chains } = useChains();
  const [selectedChain, setSelectedChain] = useState<WalletChain | null>(null);
  // Default to the app's first configured network. Runs as an effect because
  // `wallets` is empty on the first render of a cold-start session.
  useEffect(() => {
    if (selectedChain === null && chains.length > 0) setSelectedChain(chains[0]!);
  }, [chains, selectedChain]);

  const walletAddress = addressForChain(wallets, selectedChain);

  const [view, setView] = useState<'list' | 'custom'>('list');
  // Key of the in-flight asset (`code+issuer`), or 'custom' for the custom form.
  const [busyKey, setBusyKey] = useState<string | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);

  useEffect(() => {
    void refreshAssets();
  }, [refreshAssets]);

  const runAction = useCallback(
    async (
      key: string,
      asset: { code: string; issuer: string },
      opts: { limit?: string; skipSponsorship?: boolean },
    ): Promise<boolean> => {
      setBusyKey(key);
      setActionError(null);
      const res = await setTrustline(asset, opts);
      if (res.status === 'error') {
        setActionError(res.details || 'Trustline update failed. Please try again.');
        setBusyKey(null);
        return false;
      }
      await refreshAssets();
      setBusyKey(null);
      return true;
    },
    [setTrustline, refreshAssets],
  );

  const handleToggle = useCallback(
    (record: EnabledAssetRecord) => {
      const removing = record.trustlineEstablished;
      // Sponsorship is derived automatically from the app config now - no flag.
      void runAction(
        assetKey(record),
        { code: record.code, issuer: record.issuer ?? '' },
        { ...(removing ? { limit: '0' } : {}) },
      );
    },
    [runAction],
  );

  const handleCustomSubmit = useCallback(
    async (input: { code: string; issuer: string; limit?: string }) => {
      // Custom (non-configured) assets are never app-sponsored - the user pays.
      const ok = await runAction(
        'custom',
        { code: input.code, issuer: input.issuer },
        { ...(input.limit ? { limit: input.limit } : {}), skipSponsorship: true },
      );
      if (ok) setView('list');
    },
    [runAction],
  );

  return (
    <div className="pollar-overlay" style={overlayStyle} onClick={onClose}>
      {view === 'list' ? (
        <EnabledAssetsModalTemplate
          theme={theme}
          accentColor={accentColor}
          styleOverrides={styleOverrides}
          enabledAssets={enabledAssets}
          walletAddress={walletAddress}
          chains={chains}
          selectedChain={selectedChain}
          onSelectChain={setSelectedChain}
          busyKey={busyKey}
          actionError={actionError}
          onRefresh={() => refreshAssets()}
          onClose={onClose}
          onToggleTrustline={handleToggle}
          onAddCustom={() => {
            setActionError(null);
            setView('custom');
          }}
        />
      ) : (
        <CustomTrustlineModalTemplate
          theme={theme}
          accentColor={accentColor}
          styleOverrides={styleOverrides}
          busy={busyKey === 'custom'}
          actionError={actionError}
          onBack={() => {
            setActionError(null);
            setView('list');
          }}
          onClose={onClose}
          onSubmit={handleCustomSubmit}
        />
      )}
    </div>
  );
}

'use client';

import { EnabledAssetRecord, EnabledAssetsState, WalletChain } from '@pollar/core';
import { useState } from 'react';
import { ChainSelect, resolveChain } from '../ChainSelect';
import { BusyOverlay, CopyButton, cropAddress, PollarModalFooter, Toggle, useStickyData } from '../commons';
import { buildModalCssVars, type ModalStyleOverrides } from '../modal-theme';

function assetKey(record: { code: string; issuer?: string }): string {
  return record.code + (record.issuer ?? '');
}

/** Row key. Chain-qualified: the same code+issuer can exist on two chains. */
function rowKey(record: EnabledAssetRecord): string {
  return (record.chain ?? '') + assetKey(record);
}

function AssetItem({
  record,
  busy,
  disabled,
  onToggle,
}: {
  record: EnabledAssetRecord;
  busy: boolean;
  disabled: boolean;
  onToggle: (record: EnabledAssetRecord) => void;
}) {
  // Absent means "not established": an unknown trustline must never render as
  // an on switch, which would read as already enabled.
  const established = record.trustlineEstablished ?? false;
  const isNative = record.type === 'native';
  // A trustline is a Stellar concept. On Polygon/Solana a token is simply held,
  // so those rows are informational: no label, no switch.
  const isStellar = resolveChain(record.chain) === 'STELLAR';

  return (
    <div className="pollar-asset-item">
      <div className="pollar-asset-info">
        <div className="pollar-asset-code-row">
          <span className="pollar-asset-code">{record.code}</span>
          {record.enabledInApp && <span className="pollar-asset-tag">App</span>}
        </div>
        {record.name && <span className="pollar-asset-name">{record.name}</span>}
        {record.issuer && (
          <span className="pollar-issuer">
            <span className="pollar-issuer-addr">{cropAddress(record.issuer)}</span>
            <CopyButton value={record.issuer} label="Copy issuer address" className="pollar-copy-btn-sm" />
          </span>
        )}
        {isStellar && !isNative && record.enabledInApp && (
          <span className="pollar-asset-sponsor">
            {record.sponsored ? 'Reserve sponsored by the app' : 'You pay the reserve (~0.5 XLM)'}
          </span>
        )}
      </div>
      {isStellar && (
        <div className="pollar-asset-actions">
          <span className="pollar-asset-trustline-label">Trustline</span>
          {/* Native XLM needs no trustline - it is implicit and can't be removed,
              so the switch shows the state but stays locked on. */}
          <Toggle
            checked={established}
            busy={busy}
            disabled={isNative || disabled}
            onChange={() => onToggle(record)}
            label={`${established ? 'Disable' : 'Enable'} ${record.code} trustline`}
          />
        </div>
      )}
    </div>
  );
}

export interface EnabledAssetsModalTemplateProps {
  theme: string;
  accentColor: string;
  /** Per-app modal chrome overrides (background, card + button radius). */
  styleOverrides?: ModalStyleOverrides;
  enabledAssets: EnabledAssetsState;
  /** Address of the wallet on {@link selectedChain}. */
  walletAddress: string;
  /** Networks the user holds a wallet on; the first one is the default. */
  chains: WalletChain[];
  selectedChain: WalletChain | null;
  onSelectChain: (chain: WalletChain) => void;
  /** Key (`code+issuer`) of the asset whose trustline action is in flight. */
  busyKey: string | null;
  actionError: string | null;
  onRefresh: () => void;
  onClose: () => void;
  onToggleTrustline: (record: EnabledAssetRecord) => void;
  onAddCustom: () => void;
}

export function EnabledAssetsModalTemplate({
  theme,
  accentColor,
  styleOverrides,
  enabledAssets,
  walletAddress,
  chains,
  selectedChain,
  onSelectChain,
  busyKey,
  actionError,
  onRefresh,
  onClose,
  onToggleTrustline,
  onAddCustom,
}: EnabledAssetsModalTemplateProps) {
  const cssVars = buildModalCssVars(theme, accentColor, styleOverrides);

  const isLoading = enabledAssets.step === 'loading';
  // Keep the previous payload on screen while refreshing; the overlay below
  // blocks interaction so nothing is acted on against data that is changing.
  const data = useStickyData(enabledAssets.step === 'loaded' ? enabledAssets.data : null);
  const busy = busyKey !== null;
  // Only the picked network's assets. The backend returns every chain in one
  // payload, so this is a local filter - switching networks costs no request.
  const assets = (data?.assets ?? []).filter((a) => resolveChain(a.chain) === selectedChain);
  // Trustlines are Stellar-only, so the custom-trustline form is offered only
  // while Stellar is the selected network.
  const isStellarSelected = selectedChain === 'STELLAR';

  return (
    <div
      className="pollar-modal-card pollar-asset-modal"
      data-theme={theme}
      style={cssVars}
      onClick={(e) => e.stopPropagation()}
    >
      {isLoading && data && <BusyOverlay label="Refreshing assets…" />}

      <div className="pollar-modal-header">
        <h2 className="pollar-modal-title">Assets</h2>
        <div className="pollar-modal-header-actions">
          <button
            type="button"
            className="pollar-modal-close"
            onClick={onRefresh}
            disabled={isLoading || busy}
            aria-label="Refresh"
            title="Refresh"
          >
            <svg
              className={isLoading ? 'pollar-modal-refresh-icon pollar-spinning' : 'pollar-modal-refresh-icon'}
              width="16"
              height="16"
              viewBox="0 0 16 16"
              fill="none"
              aria-hidden
            >
              <path
                d="M13.5 8a5.5 5.5 0 1 1-1.6-3.9M13.5 2v3h-3"
                stroke="currentColor"
                strokeWidth="1.6"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
          <button className="pollar-modal-close" onClick={onClose} aria-label="Close">
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
              <path d="M2 2l12 12M14 2L2 14" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
            </svg>
          </button>
        </div>
      </div>

      <ChainSelect value={selectedChain} options={chains} onChange={onSelectChain} disabled={isLoading || busy} />

      {walletAddress && (
        <div className="pollar-address-row">
          <span className="pollar-address">{cropAddress(walletAddress)}</span>
          <CopyButton value={walletAddress} label="Copy wallet address" />
        </div>
      )}

      {/* First load only - a refresh keeps the old list under the overlay. */}
      {isLoading && !data && (
        <div className="pollar-loading-block">
          <div className="pollar-spinner" />
          <span>Loading…</span>
        </div>
      )}

      {enabledAssets.step === 'error' && <div className="pollar-modal-error">{enabledAssets.message}</div>}

      {actionError && <div className="pollar-modal-action-error">{actionError}</div>}

      {data && !data.exists && <div className="pollar-modal-empty">Account not found on {data.network}.</div>}

      {data && assets.length === 0 && <div className="pollar-modal-empty">No assets found on this network.</div>}

      {data && assets.length > 0 && (
        <div className="pollar-asset-list">
          {assets.map((a) => (
            <AssetItem
              key={rowKey(a)}
              record={a}
              busy={busyKey === assetKey(a)}
              disabled={busy && busyKey !== assetKey(a)}
              onToggle={onToggleTrustline}
            />
          ))}
        </div>
      )}

      {isStellarSelected && (
        <button className="pollar-asset-add-custom" onClick={onAddCustom} disabled={busy}>
          + Add custom trustline
        </button>
      )}

      <PollarModalFooter />
    </div>
  );
}

export interface CustomTrustlineModalTemplateProps {
  theme: string;
  accentColor: string;
  /** Per-app modal chrome overrides (background, card + button radius). */
  styleOverrides?: ModalStyleOverrides;
  busy: boolean;
  actionError: string | null;
  onBack: () => void;
  onClose: () => void;
  onSubmit: (input: { code: string; issuer: string; limit?: string }) => void;
}

function isValidIssuer(issuer: string): boolean {
  return issuer.length === 56 && issuer.startsWith('G');
}

export function CustomTrustlineModalTemplate({
  theme,
  accentColor,
  styleOverrides,
  busy,
  actionError,
  onBack,
  onClose,
  onSubmit,
}: CustomTrustlineModalTemplateProps) {
  const cssVars = buildModalCssVars(theme, accentColor, styleOverrides);

  const [code, setCode] = useState('');
  const [issuer, setIssuer] = useState('');
  const [limit, setLimit] = useState('');

  const codeOk = code.trim().length >= 1 && code.trim().length <= 12;
  const issuerOk = isValidIssuer(issuer.trim());
  const canSubmit = codeOk && issuerOk && !busy;

  const submit = () => {
    if (!canSubmit) return;
    const trimmedLimit = limit.trim();
    onSubmit({ code: code.trim(), issuer: issuer.trim(), ...(trimmedLimit ? { limit: trimmedLimit } : {}) });
  };

  return (
    <div
      className="pollar-modal-card pollar-asset-modal"
      data-theme={theme}
      style={cssVars}
      onClick={(e) => e.stopPropagation()}
    >
      <div className="pollar-modal-header">
        <div className="pollar-modal-header-actions">
          <button className="pollar-modal-close" onClick={onBack} disabled={busy} aria-label="Back">
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
              <path d="M10 3L5 8l5 5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </button>
          <h2 className="pollar-modal-title">Add custom trustline</h2>
        </div>
        <button className="pollar-modal-close" onClick={onClose} aria-label="Close">
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
            <path d="M2 2l12 12M14 2L2 14" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          </svg>
        </button>
      </div>

      <p className="pollar-asset-custom-hint">
        Custom trustlines aren&apos;t sponsored — your wallet pays the 0.5 XLM reserve and the transaction fee.
      </p>

      <div className="pollar-field">
        <label className="pollar-label" htmlFor="pollar-trustline-code">
          Asset code
        </label>
        <input
          id="pollar-trustline-code"
          className="pollar-input"
          value={code}
          onChange={(e) => setCode(e.target.value)}
          placeholder="USDC"
          maxLength={12}
          autoComplete="off"
          spellCheck={false}
          disabled={busy}
        />
      </div>

      <div className="pollar-field">
        <label className="pollar-label" htmlFor="pollar-trustline-issuer">
          Issuer
        </label>
        <input
          id="pollar-trustline-issuer"
          className="pollar-input"
          value={issuer}
          onChange={(e) => setIssuer(e.target.value)}
          placeholder="G…"
          autoComplete="off"
          spellCheck={false}
          disabled={busy}
        />
        {issuer.trim().length > 0 && !issuerOk && (
          <span className="pollar-field-error">Issuer must be a 56-character Stellar address starting with G.</span>
        )}
      </div>

      <div className="pollar-field">
        <label className="pollar-label" htmlFor="pollar-trustline-limit">
          Limit <span className="pollar-label-optional">(optional)</span>
        </label>
        <input
          id="pollar-trustline-limit"
          className="pollar-input"
          value={limit}
          onChange={(e) => setLimit(e.target.value)}
          placeholder="Maximum"
          inputMode="decimal"
          autoComplete="off"
          spellCheck={false}
          disabled={busy}
        />
      </div>

      {actionError && <div className="pollar-modal-action-error">{actionError}</div>}

      <div className="pollar-modal-actions">
        <button type="button" className="pollar-btn-primary" onClick={submit} disabled={!canSubmit}>
          {busy ? (
            <>
              <span className="pollar-spinner pollar-spinner-sm" />
              Enabling…
            </>
          ) : (
            'Enable trustline'
          )}
        </button>
      </div>

      <PollarModalFooter />
    </div>
  );
}

'use client';

import type { AppRequirementStep } from '@pollar/core';
import { useCallback, useEffect, useRef, useState } from 'react';
import { usePollar } from '../../context';
import { RequirementFormModal } from '../requirement-form-modal/RequirementFormModal';
import { KycModal } from './KycModal';

interface AppKycFlowProps {
  onClose: () => void;
  country?: string;
  level?: 'basic' | 'intermediate' | 'enhanced';
  /** Called once every step of the app's own KYC is complete. */
  onApproved?: () => void;
}

type FlowState =
  | { kind: 'loading' }
  /** The app has no steps: the KYC modal lists its enabled options, as it always did. */
  | { kind: 'options' }
  | { kind: 'step'; step: AppRequirementStep }
  /** Every step was already complete on open; the KYC modal shows the verified state on the option the user passed. */
  | { kind: 'done'; providerId: string };

/**
 * The app's own KYC, step by step: the user completes every step the app configured,
 * in order, and only the pending one is shown. A KYC step opens the KYC modal on its
 * option; a form step opens the form. After each one the steps are read again.
 */
export function AppKycFlow({ onClose, country, level, onApproved }: AppKycFlowProps) {
  const { getClient } = usePollar();
  const client = getClient();
  const [state, setState] = useState<FlowState>({ kind: 'loading' });
  const kycStepDone = useRef(false);
  // On the first read a complete flow shows its verified state; after a step it just closes.
  const firstRead = useRef(true);
  // One read at a time: development runs the mount effect twice, and the second read
  // would see the first one's `firstRead` and close the flow instead of showing it.
  const loading = useRef(false);
  const mounted = useRef(true);
  useEffect(() => {
    // Set on every mount: development mounts components twice, and the cleanup of the
    // first mount would otherwise leave this false and drop every response.
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  /**
   * The KYC option the user holds an approval on, among the ones a step accepts. A
   * status read never opens a vendor session; opening an option the user did not pass
   * would start (and bill) one.
   */
  async function approvedOption(steps: { type: string; optionIds: string[] }[]): Promise<string | null> {
    for (const step of steps) {
      if (step.type !== 'KYC') continue;
      for (const optionId of step.optionIds) {
        const status = await client.getKycStatus(optionId).catch(() => null);
        if (status?.status === 'approved') return optionId;
      }
    }
    return null;
  }

  const load = useCallback(async () => {
    if (loading.current) return;
    loading.current = true;
    kycStepDone.current = false;
    try {
      const requirements = await client.getAppRequirements();
      if (!mounted.current) return;
      if (!requirements.total) return setState({ kind: 'options' });
      const first = firstRead.current;
      firstRead.current = false;
      if (requirements.next) return setState({ kind: 'step', step: requirements.next });
      onApproved?.();
      const providerId = first ? await approvedOption(requirements.steps) : null;
      if (!mounted.current) return;
      if (providerId) setState({ kind: 'done', providerId });
      else onClose();
    } catch {
      // Without the steps the modal still works as it did: it lists the enabled options.
      if (mounted.current) setState({ kind: 'options' });
    } finally {
      loading.current = false;
    }
    // The client instance and the callback are fixed while the flow is open.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  if (state.kind === 'loading') return null;

  if (state.kind === 'options') {
    return (
      <KycModal
        onClose={onClose}
        {...(country !== undefined && { country })}
        {...(level !== undefined && { level })}
        {...(onApproved !== undefined && { onApproved })}
      />
    );
  }

  if (state.kind === 'done') {
    return <KycModal onClose={onClose} providerId={state.providerId} {...(country !== undefined && { country })} />;
  }

  const { step } = state;
  const progress = { position: step.completed + 1, total: step.total };
  if (step.type === 'FORM') {
    return (
      <RequirementFormModal
        key={step.optionId}
        formId={step.optionId}
        progress={progress}
        onClose={onClose}
        onSubmitted={() => void load()}
      />
    );
  }
  // The KYC modal shows its own result; closing it after an approval moves to the next step.
  return (
    <KycModal
      key={step.optionId}
      providerId={step.optionId}
      {...(country !== undefined && { country })}
      {...(level !== undefined && { level })}
      onApproved={() => {
        kycStepDone.current = true;
      }}
      onClose={() => {
        if (kycStepDone.current) void load();
        else onClose();
      }}
    />
  );
}

