'use client';

import {
  isPollarApiError,
  type KycProvider,
  type KycStartResponse,
  type KycStatus as KycStatusValue,
  type KycStatusContent,
} from '@pollar/core';
import { useCallback, useEffect, useRef, useState } from 'react';
import { usePollar } from '../../context';
import type { KycStep } from './KycModalTemplate';
import { KycModalTemplate } from './KycModalTemplate';
import { kycErrorMessage } from './kyc-messages';
import '../shared.css';
import './KycModal.css';
import { modalChrome } from '../modal-theme';

interface KycModalProps {
  corridorId?: string;
  /** A card provider's steps, in place of a route's. */
  cardProviderId?: string;
  /** Open this option directly instead of listing the choices (the one a ramp's KYC gate names). */
  providerId?: string;
  onClose: () => void;
  /** ISO 3166-1 alpha-2 country code to filter providers. Defaults to 'MX'. */
  country?: string;
  /** Legacy fallback for older backends. Named options select their own workflow. */
  level?: 'basic' | 'intermediate' | 'enhanced';
  /** Called when KYC is successfully approved. */
  onApproved?: () => void;
}

function newIdempotencyKey(): string {
  const c = globalThis.crypto;
  if (c && typeof c.randomUUID === 'function') return c.randomUUID();
  return `kyc-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 12)}`;
}

export function KycModal({
  onClose,
  country = 'MX',
  level = 'basic',
  onApproved,
  corridorId,
  cardProviderId,
  providerId,
}: KycModalProps) {
  const { getClient, styles } = usePollar();

  const [step, setStep] = useState<KycStep>('select_provider');
  const [providers, setProviders] = useState<KycProvider[]>([]);
  const [selectedProvider, setSelectedProvider] = useState<KycProvider | null>(null);
  const [session, setSession] = useState<KycStartResponse | null>(null);
  const [kycStatus, setKycStatus] = useState<KycStatusValue>('none');
  const [reviewReason, setReviewReason] = useState<string | null>(null);
  const [processing, setProcessing] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  // One key per option for this modal: a retried start returns the vendor session
  // already opened instead of creating (and billing) another one.
  const idempotencyKeys = useRef<Record<string, string>>({});
  const autoOpened = useRef(false);

  const client = getClient();
  const { theme, accentColor, styleOverrides, overlayStyle } = modalChrome(styles);

  function finish(status: KycStatusValue, reason: string | null = null, isProcessing = false) {
    setKycStatus(status);
    setReviewReason(reason);
    setProcessing(isProcessing);
    setStep('done');
    if (status === 'approved') onApproved?.();
  }

  function finishWith(read: KycStatusContent) {
    if (read.status === 'pending' && read.decisionStatus === 'approved') finish('pending', null, true);
    else if (read.decisionStatus === 'manual_review') finish('pending', read.reviewReason ?? null);
    else finish(read.decisionStatus === 'expired' ? 'expired' : read.status);
  }

  function readStatus(providerId: string) {
    return corridorId || cardProviderId
      ? client.getKycStatus(undefined, corridorId, cardProviderId)
      : client.getKycStatus(providerId);
  }

  // One session request at a time: a second one for the same key would only wait on
  // the first, and the auto-open path can fire alongside a click.
  const starting = useRef(false);

  /** `listed`: the option came from the country-filtered list. Off it, the backend picks the option's own country. */
  async function handleSelectProvider(provider: KycProvider, listed = true) {
    if (starting.current) return;
    starting.current = true;
    setSelectedProvider(provider);
    setError(null);
    setIsLoading(true);
    const key = (idempotencyKeys.current[provider.id] ??= newIdempotencyKey());
    try {
      const result = await client.resolveKyc(
        provider.id,
        provider.levels?.[0] ?? level,
        listed ? country : undefined,
        corridorId,
        key,
        cardProviderId,
      );
      if (result.alreadyApproved) {
        finish('approved');
        return;
      }
      setSession(result as KycStartResponse);
      setStep('verifying');
    } catch (e) {
      const code = isPollarApiError(e) ? e.code : undefined;
      if (code === 'SDK_KYC_ALREADY_APPROVED') {
        finish('approved');
        return;
      }
      // A session of this user is in the provider's review, or approved and still being
      // recorded: show which one instead of opening another session.
      if (code === 'SDK_KYC_UNDER_REVIEW') {
        await readStatus(provider.id).then(finishWith, () => finish('pending'));
        return;
      }
      if (code === 'SDK_KYC_SESSION_EXPIRED') delete idempotencyKeys.current[provider.id];
      setError(kycErrorMessage(e, 'start'));
      setStep('select_provider');
    } finally {
      starting.current = false;
      setIsLoading(false);
    }
  }

  const loadProviders = useCallback(() => {
    setIsLoading(true);
    setError(null);
    return getClient()
      .getKycProviders(country, corridorId, cardProviderId)
      .then((result) => {
        setProviders(result.providers);
        return result.providers;
      })
      .catch((e: unknown) => {
        setProviders([]);
        setError(kycErrorMessage(e, 'load'));
        return [] as KycProvider[];
      })
      .finally(() => setIsLoading(false));
  }, [getClient, country, corridorId, cardProviderId]);

  useEffect(() => {
    void loadProviders().then((list) => {
      if (!providerId || autoOpened.current) return;
      autoOpened.current = true;
      const target = list.find((p) => p.id === providerId);
      // The option a gate or a step names was chosen by the backend for this user: the
      // country this list was filtered by must not hide it behind "no providers".
      if (target) void handleSelectProvider(target);
      else
        void handleSelectProvider(
          { id: providerId, name: 'Identity verification', flow: 'iframe', levels: [level] } as KycProvider,
          false,
        );
    });
    // handleSelectProvider reads the latest props on each call; listing it would reload providers every render.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loadProviders, providerId]);

  async function handleDoneVerifying() {
    if (!selectedProvider) return;
    setError(null);
    setStep('polling');
    try {
      const read = await client.pollKycDecision(selectedProvider.id, {
        intervalMs: 3000,
        timeoutMs: 120_000,
        ...(corridorId ? { corridorId } : {}),
        ...(cardProviderId ? { cardProviderId } : {}),
      });
      finishWith(read);
    } catch {
      setError('We could not confirm your result yet. Check again shortly; this does not mean your verification was rejected.');
      setStep('verifying');
    }
  }

  function handleStartAgain() {
    if (selectedProvider) delete idempotencyKeys.current[selectedProvider.id];
    setSession(null);
    setKycStatus('none');
    setReviewReason(null);
    setProcessing(false);
    if (selectedProvider) void handleSelectProvider(selectedProvider);
    else setStep('select_provider');
  }

  return (
    <div className="pollar-overlay" style={overlayStyle} onClick={onClose}>
      <KycModalTemplate
        theme={theme}
        accentColor={accentColor}
        styleOverrides={styleOverrides}
        step={step}
        providers={providers}
        selectedProvider={selectedProvider}
        session={session}
        kycStatus={kycStatus}
        reviewReason={reviewReason}
        processing={processing}
        isLoading={isLoading}
        error={error}
        onSelectProvider={handleSelectProvider}
        onDoneVerifying={handleDoneVerifying}
        onStartAgain={handleStartAgain}
        onRefresh={() => void loadProviders()}
        onClose={onClose}
      />
    </div>
  );
}

'use client';

import type { KycProvider, KycStartResponse, KycStatus as KycStatusValue } from '@pollar/core';
import { PollarModalFooter } from '../commons';
import { buildModalCssVars, type ModalStyleOverrides } from '../modal-theme';
import { KycStatus as KycStatusBadge } from './KycStatus';
import { kycProcessingMessage, kycReviewMessage } from './kyc-messages';

export type KycStep = 'select_provider' | 'verifying' | 'polling' | 'done';

interface KycModalTemplateProps {
  theme: string;
  accentColor: string;
  /** Per-app modal chrome overrides (background, card + button radius). */
  styleOverrides?: ModalStyleOverrides;
  step: KycStep;
  providers: KycProvider[];
  selectedProvider: KycProvider | null;
  session: KycStartResponse | null;
  kycStatus: KycStatusValue;
  /** Set when the decision is held for manual review (e.g. DUPLICATE_DOCUMENT). */
  reviewReason?: string | null;
  /** The vendor approved and Pollar is still recording it (`kycStatus` stays `pending`). */
  processing?: boolean;
  isLoading: boolean;
  error?: string | null;
  onSelectProvider: (provider: KycProvider) => void;
  onDoneVerifying: () => void;
  /** Open a new session after the previous one expired. */
  onStartAgain?: () => void;
  onRefresh: () => void;
  onClose: () => void;
}

export function KycModalTemplate({
  theme,
  accentColor,
  styleOverrides,
  step,
  providers,
  selectedProvider,
  session,
  kycStatus,
  reviewReason,
  processing = false,
  isLoading,
  error,
  onSelectProvider,
  onDoneVerifying,
  onStartAgain,
  onRefresh,
  onClose,
}: KycModalTemplateProps) {
  const cssVars = buildModalCssVars(theme, accentColor, styleOverrides, 'hero');

  return (
    <div
      className={`pollar-modal-card pollar-kyc-modal ${step === 'verifying' ? 'pollar-kyc-modal--verifying' : ''}`}
      role="dialog"
      aria-modal="true"
      aria-label="Identity verification"
      style={cssVars}
      onClick={(e) => e.stopPropagation()}
    >
      <div className="pollar-modal-header">
        <div className="pollar-kyc-header-text">
          <h2 className="pollar-modal-title">Identity verification</h2>
          <p className="pollar-kyc-subtitle">
            {step === 'select_provider' && 'Choose your verification provider'}
            {step === 'verifying' && `Complete the steps below with ${selectedProvider?.name}`}
            {step === 'polling' && 'Waiting for verification result'}
            {step === 'done' && (kycStatus === 'approved' ? 'You’re ready to continue' : 'Your verification status')}
          </p>
        </div>
        <div className="pollar-modal-header-actions">
          {step === 'select_provider' && (
            <button
              type="button"
              className="pollar-modal-close"
              onClick={onRefresh}
              disabled={isLoading}
              aria-label="Refresh"
              title="Refresh providers"
            >
              <svg
                className={isLoading ? 'pollar-modal-refresh-icon pollar-spinning' : 'pollar-modal-refresh-icon'}
                width="16"
                height="16"
                viewBox="0 0 16 16"
                fill="none"
                aria-hidden
              >
                <path
                  d="M13.5 8a5.5 5.5 0 1 1-1.6-3.9M13.5 2v3h-3"
                  stroke="currentColor"
                  strokeWidth="1.6"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </button>
          )}
          <button type="button" className="pollar-modal-close" onClick={onClose} aria-label="Close">
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
              <path d="M2 2l12 12M14 2L2 14" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
            </svg>
          </button>
        </div>
      </div>

      {error && (
        <p className="pollar-kyc-error" role="alert">
          {error}
        </p>
      )}

      {step === 'select_provider' &&
        (isLoading && providers.length === 0 ? (
          <div className="pollar-loading-block">
            <div className="pollar-spinner" />
            <span>Loading providers…</span>
          </div>
        ) : (
          <div className="pollar-kyc-providers">
            {providers.length === 0 && (
              <p style={{ color: 'var(--pollar-muted)', textAlign: 'center' }}>No providers available for your country.</p>
            )}
            {providers.map((p) => (
              <button
                key={p.id}
                type="button"
                className="pollar-kyc-provider-btn"
                disabled={isLoading}
                onClick={() => onSelectProvider(p)}
              >
                <span className="pollar-kyc-provider-name">{p.name}</span>
                <span className="pollar-kyc-provider-flow">
                  {isLoading && selectedProvider?.id === p.id
                    ? 'Opening…'
                    : p.flow === 'redirect'
                      ? 'Continue in a new tab'
                      : 'Continue here'}
                </span>
              </button>
            ))}
          </div>
        ))}

      {step === 'verifying' && selectedProvider && (
        <>
          <div className="pollar-kyc-session-bar">
            <span className="pollar-kyc-session-label">
              <span className="pollar-kyc-session-dot" />
              Verification in progress
            </span>
            {session?.kycUrl && (
              <a href={session.kycUrl} target="_blank" rel="noopener noreferrer">
                Open in new tab ↗
              </a>
            )}
          </div>
          <div className="pollar-kyc-iframe-wrap">
            {session?.kycUrl && selectedProvider.flow === 'redirect' ? (
              <div className="pollar-kyc-iframe-mock">
                <p>Complete verification in a separate tab, then return here to check your status.</p>
                <a className="pollar-btn-primary" href={session.kycUrl} target="_blank" rel="noopener noreferrer">
                  Open verification
                </a>
              </div>
            ) : session?.kycUrl ? (
              <iframe className="pollar-kyc-iframe" src={session.kycUrl} title="KYC verification" allow="camera; microphone" />
            ) : (
              <div className="pollar-kyc-iframe-mock">
                <span>
                  {selectedProvider.flow === 'form'
                    ? 'The identity verification form will appear here.'
                    : 'Identity verification will open here.'}
                </span>
              </div>
            )}
          </div>
          <div className="pollar-kyc-footer">
            <p>Finished the steps? Check your status to continue.</p>
            <div className="pollar-modal-actions">
              <button type="button" className="pollar-btn-secondary" onClick={onClose}>
                Close
              </button>
              <button type="button" className="pollar-btn-primary" onClick={onDoneVerifying}>
                Check status
              </button>
            </div>
          </div>
        </>
      )}

      {step === 'polling' && (
        <div className="pollar-kyc-polling">
          <div className="pollar-spinner" />
          <p className="pollar-kyc-polling-text">Checking verification status…</p>
        </div>
      )}

      {step === 'done' && (
        <div className="pollar-kyc-result">
          <span className={`pollar-kyc-result-icon pollar-kyc-result-icon--${kycStatus}`} aria-hidden="true">
            <svg
              width="28"
              height="28"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              {kycStatus === 'approved' ? (
                <path d="m5 12 4 4L19 6" />
              ) : kycStatus === 'rejected' ? (
                <path d="m7 7 10 10M17 7 7 17" />
              ) : (
                <>
                  <circle cx="12" cy="12" r="8" />
                  <path d="M12 7v5l3 2" />
                </>
              )}
            </svg>
          </span>
          <KycStatusBadge status={kycStatus} {...(processing ? { label: 'Approved' } : {})} />
          <p className="pollar-kyc-result-text">
            {kycStatus === 'approved'
              ? 'Your identity has been verified successfully.'
              : kycStatus === 'rejected'
                ? 'Your verification was not approved. Contact support for the next steps.'
                : kycStatus === 'expired'
                  ? 'Your verification expired. Start again to verify your identity.'
                  : processing
                    ? kycProcessingMessage()
                    : kycReviewMessage(reviewReason)}
          </p>
          <div className="pollar-modal-actions">
            {kycStatus === 'expired' && onStartAgain && (
              <button type="button" className="pollar-btn-secondary" onClick={onStartAgain} disabled={isLoading}>
                Start again
              </button>
            )}
            {kycStatus !== 'approved' && kycStatus !== 'rejected' && kycStatus !== 'expired' && (
              <button type="button" className="pollar-btn-secondary" onClick={onDoneVerifying}>
                Check again
              </button>
            )}
            <button type="button" className="pollar-btn-primary" onClick={onClose}>
              Close
            </button>
          </div>
        </div>
      )}
      <PollarModalFooter />
    </div>
  );
}

'use client';

import type { KycStatus as KycStatusValue } from '@pollar/core';
import type { CSSProperties } from 'react';

interface KycStatusProps {
  status: KycStatusValue;
  /** Replaces the status label, keeping its color. */
  label?: string;
  className?: string;
}

const STATUS_CONFIG: Record<KycStatusValue, { label: string; color: string; dot: boolean }> = {
  none: { label: 'Not started', color: '#6b7280', dot: false },
  pending: { label: 'Pending review', color: '#f59e0b', dot: true },
  approved: { label: 'Verified', color: '#10b981', dot: false },
  rejected: { label: 'Rejected', color: '#ef4444', dot: false },
  expired: { label: 'Expired', color: '#6b7280', dot: false },
};

export function KycStatus({ status, label, className }: KycStatusProps) {
  const config = STATUS_CONFIG[status] ?? STATUS_CONFIG.none;
  return (
    <span
      className={`pollar-kyc-badge${className ? ` ${className}` : ''}`}
      style={{ '--pollar-kyc-color': config.color } as CSSProperties}
    >
      {config.dot && <span className="pollar-kyc-badge-dot" />}
      {label ?? config.label}
    </span>
  );
}

/** What a failed KYC call means for the user, by backend code. */
export function kycErrorMessage(error: unknown, phase: 'load' | 'start'): string {
  const code = (error as { code?: unknown } | null)?.code;
  switch (code) {
    case 'SDK_KYC_NOT_CONFIGURED':
      return 'Identity verification is not available for this app yet.';
    case 'SDK_KYC_PROVIDER_ERROR':
      return 'The verification service is not responding right now. Please try again in a moment.';
    case 'SDK_KYC_SESSION_EXPIRED':
      return 'Your previous verification session expired. Select the provider to start a new one.';
    case 'SDK_KYC_PROVIDER_NOT_FOUND':
    case 'SDK_KYC_PROVIDER_NOT_ENABLED':
      return 'This verification option is no longer available. Refresh to see the current options.';
    case 'SDK_RAMPS_PROVIDER_NOT_CONFIGURED':
      return 'This route is not set up for identity verification yet.';
    case 'VALIDATION_ERROR':
      return 'This verification option is not available for your country.';
    default:
      return phase === 'load'
        ? 'Could not load verification options. Please refresh to try again.'
        : 'Could not start verification. Please try again.';
  }
}

/** Why a verification is held for a person to review, in the user's terms. */
export function kycReviewMessage(reviewReason: string | null | undefined): string {
  if (reviewReason === 'DUPLICATE_DOCUMENT') {
    return 'This document is already linked to another account, so our team is reviewing it. You can check again later.';
  }
  return 'Your verification is still being reviewed. You can check again shortly.';
}

/** A decision the vendor approved that Pollar is still recording. */
export function kycProcessingMessage(): string {
  return 'Your verification was approved. We are finishing setting it up; check again in a minute.';
}

import { useRef, useState } from 'react';

interface EmailCodeInputProps {
  email?: string;
  onSubmit: (code: string) => void;
}

export function EmailCodeInput({ email, onSubmit }: EmailCodeInputProps) {
  const [digits, setDigits] = useState(['', '', '', '', '', '']);
  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);

  function submit(next: string[]) {
    if (next.every(Boolean)) onSubmit(next.join(''));
  }

  function handleChange(index: number, value: string) {
    const cleaned = value.replace(/\D/g, '').slice(-1);
    const next = digits.map((d, i) => (i === index ? cleaned : d));
    setDigits(next);
    if (cleaned && index < 5) inputRefs.current[index + 1]?.focus();
    submit(next);
  }

  function handleKeyDown(index: number, e: React.KeyboardEvent<HTMLInputElement>) {
    if (e.key === 'Backspace' && !digits[index] && index > 0) {
      inputRefs.current[index - 1]?.focus();
    }
  }

  function handlePaste(e: React.ClipboardEvent<HTMLInputElement>) {
    e.preventDefault();
    const text = e.clipboardData.getData('text').replace(/\D/g, '').slice(0, 6);
    const next = Array.from({ length: 6 }, (_, i) => text[i] ?? '');
    setDigits(next);
    inputRefs.current[Math.min(text.length - 1, 5)]?.focus();
    submit(next);
  }

  return (
    <div className="pollar-code-section">
      <p className="pollar-code-label">Enter the 6-digit code sent to {email ? <strong>{email}</strong> : 'your email'}</p>
      <div className="pollar-code-inputs">
        {digits.map((digit, i) => (
          <input
            key={i}
            ref={(el) => {
              inputRefs.current[i] = el;
            }}
            type="text"
            inputMode="numeric"
            maxLength={2}
            value={digit}
            className="pollar-code-input"
            onChange={(e) => handleChange(i, e.target.value)}
            onKeyDown={(e) => handleKeyDown(i, e)}
            onPaste={handlePaste}
          />
        ))}
      </div>
    </div>
  );
}

