'use client';

import {
  AUTH_ERROR_CODES,
  AuthState,
  InteractiveAuthAdapter,
  isInteractiveAuthAdapter,
  PollarLoginOptions,
  WalletId,
} from '@pollar/core';
import { useEffect, useMemo, useRef, useState } from 'react';
import { usePollar } from '../../context';
import { modalChrome } from '../modal-theme';
import { LoginModalStatus, LoginModalTemplate } from './LoginModalTemplate';
import { PrivyLoginSubmodal } from './PrivyLoginSubmodal';
import '../shared.css';
import './LoginModal.css';

type TimeoutHandle = ReturnType<typeof setTimeout>;

interface LoginModalProps {
  onClose: () => void;
}

export function LoginModal({ onClose }: LoginModalProps) {
  const [email, setEmail] = useState('');
  const { getClient, styles, appConfig: config, configStatus, retryConfig } = usePollar();
  const [authState, setAuthState] = useState<AuthState>(() => getClient().getAuthState());
  // Registered wallet adapters (built-ins + config) -> one login button each.
  const walletAdapters = useMemo(() => getClient().listWalletAdapters(), [getClient]);
  const [codeInputKey, setCodeInputKey] = useState(0);
  const pendingEmail = useRef<string | null>(null);
  // When set, an interactive adapter (e.g. Privy) takes over the modal with its
  // own login sub-view instead of going straight to login({ provider }).
  const [interactiveAdapter, setInteractiveAdapter] = useState<InteractiveAuthAdapter | null>(null);

  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;
  const autoCloseTimer = useRef<TimeoutHandle | null>(null);

  useEffect(() => {
    const unsubscribe = getClient().onAuthStateChange((next) => {
      setAuthState(next);
      if (next.step === 'entering_email' && pendingEmail.current) {
        getClient().sendEmailCode(pendingEmail.current);
        pendingEmail.current = null;
      }
      if (next.step === 'error' && next.errorCode === AUTH_ERROR_CODES.EMAIL_CODE_INVALID) {
        setCodeInputKey((k) => k + 1);
      }
      if (next.step === 'authenticated') {
        // Clear any timer already pending - if `authenticated` fires more than
        // once, overwriting the handle would orphan the previous timeout
        // (cleanup only tracks the latest).
        if (autoCloseTimer.current !== null) {
          clearTimeout(autoCloseTimer.current);
        }
        autoCloseTimer.current = setTimeout(() => {
          autoCloseTimer.current = null;
          onCloseRef.current();
        }, 1000);
      }
    });
    return () => {
      unsubscribe();
      if (autoCloseTimer.current !== null) {
        clearTimeout(autoCloseTimer.current);
        autoCloseTimer.current = null;
      }
    };
  }, [getClient]);

  const { logoUrl, emailEnabled, embeddedWallets, smartWallet, providers } = styles;
  const { theme, accentColor, styleOverrides, overlayStyle } = modalChrome(styles);
  // Opt-in: the Smart Wallet (passkey) option only shows when the dashboard
  // explicitly enables it. Absent -> hidden.
  const smartWalletEnabled = smartWallet ?? false;
  // The heading is the app's name unless Branding set a custom one. Blank counts
  // as unset, which is what the dashboard sends when the field is cleared.
  const modalTitle = styles.modalTitle?.trim() || config.application?.name || 'Pollar';

  function handleClose() {
    setEmail('');
    getClient().cancelLogin();
    onClose();
  }

  function handleEmailSubmit() {
    if (!email) return;
    pendingEmail.current = email;
    getClient().beginEmailLogin();
  }

  function handleSocialLogin(provider: 'google' | 'github') {
    getClient().login({ provider });
  }

  function handleWalletConnect(type: WalletId) {
    // Interactive adapters (e.g. Privy) drive their own multi-step login that we
    // render as a sub-modal; open it instead of going straight to login().
    const adapter = getClient().getWalletAdapter(type);
    if (isInteractiveAuthAdapter(adapter)) {
      setInteractiveAdapter(adapter);
      return;
    }
    // Any other registered wallet adapter (freighter/albedo/swk...). The adapter
    // opens its own connect/auth UI; the SDK wraps the generic SEP-10 flow.
    getClient().login({ provider: type } as PollarLoginOptions);
  }

  function handleLoginSmartWallet() {
    getClient().loginSmartWallet();
  }

  function handleCreateSmartWallet() {
    getClient().createSmartWallet();
  }

  function handleVerifyCode(code: string) {
    getClient().verifyEmailCode(code);
  }

  function handleBack() {
    setEmail('');
    getClient().cancelLogin();
  }

  function handleRetry() {
    getClient().logout();
    if (styles.emailEnabled) {
      getClient().beginEmailLogin();
    }
  }

  function handleInteractiveAuthenticated() {
    const provider = interactiveAdapter?.type;
    setInteractiveAdapter(null);
    if (provider) {
      // Provider login (Privy) is done; run the normal flow so connect() + SEP-10
      // execute against the now-authenticated wallet.
      getClient().login({ provider } as PollarLoginOptions);
    }
  }

  return (
    <div className="pollar-overlay" style={overlayStyle} onClick={handleClose}>
      {configStatus !== 'ready' ? (
        <LoginModalStatus
          status={configStatus === 'error' ? 'error' : 'loading'}
          theme={theme}
          accentColor={accentColor}
          styleOverrides={styleOverrides}
          logoUrl={logoUrl ?? null}
          appName={modalTitle}
          onRetry={retryConfig}
          onCancel={handleClose}
        />
      ) : interactiveAdapter ? (
        <PrivyLoginSubmodal
          adapter={interactiveAdapter}
          theme={theme}
          accentColor={accentColor}
          styleOverrides={styleOverrides}
          logoUrl={logoUrl ?? null}
          appName={modalTitle}
          onBack={() => setInteractiveAdapter(null)}
          onCancel={handleClose}
          onAuthenticated={handleInteractiveAuthenticated}
        />
      ) : (
        <LoginModalTemplate
          theme={theme}
          accentColor={accentColor}
          styleOverrides={styleOverrides}
          logoUrl={logoUrl ?? null}
          emailEnabled={!!emailEnabled}
          embeddedWallets={!!embeddedWallets}
          smartWallet={smartWalletEnabled}
          providers={{
            google: !!providers?.google,
            discord: !!providers?.discord,
            x: !!providers?.x,
            github: !!providers?.github,
            apple: !!providers?.apple,
          }}
          walletAdapters={walletAdapters}
          appName={modalTitle}
          email={email}
          onEmailChange={setEmail}
          onEmailSubmit={handleEmailSubmit}
          onSocialLogin={handleSocialLogin}
          onWalletConnect={handleWalletConnect}
          onLoginSmartWallet={handleLoginSmartWallet}
          onCreateSmartWallet={handleCreateSmartWallet}
          authState={authState}
          codeInputKey={codeInputKey}
          onCodeSubmit={handleVerifyCode}
          onBack={handleBack}
          onCancel={handleClose}
          onRetry={handleRetry}
        />
      )}
    </div>
  );
}

'use client';

import { AUTH_ERROR_CODES, AuthState, WalletId } from '@pollar/core';

type StateStatus = 'NONE' | 'LOADING' | 'SUCCESS' | 'ERROR';
import { useState } from 'react';
import { LOGO_POLLAR } from '../../constants';
import { ModalStatusBanner, PollarModalFooter } from '../commons';
import { buildModalCssVars, type ModalStyleOverrides } from '../modal-theme';
import { EmailCodeInput } from './EmailCodeInput';
import { GithubButton } from './GithubButton';
import { GoogleButton } from './GoogleButton';

// Re-exported from its old home so consumers that imported it from this module
// (the dashboard's branding preview, among others) keep working.
export { buildModalCssVars } from '../modal-theme';
export type { ModalStyleOverrides } from '../modal-theme';

type WalletAdapterEntry = { id: WalletId; meta: { label: string; iconUrl?: string; group?: string } };

function WalletAdapterButtons({
  walletAdapters,
  onConnect,
  isLoading,
  variant = 'list',
}: {
  walletAdapters: WalletAdapterEntry[];
  onConnect: (id: WalletId) => void;
  isLoading: boolean;
  // 'list'  -> borderless rows for inside a group sub-picker (large icon + name).
  // 'entry' -> bordered buttons that match the root-level entries (Google, Wallet,
  //           Smart Wallet) so a root adapter like Privy doesn't read as bare text.
  variant?: 'list' | 'entry';
}) {
  if (variant === 'entry') {
    return (
      <>
        {walletAdapters.map((a) => (
          <button
            key={a.id}
            type="button"
            disabled={isLoading}
            className="pollar-wallet-entry-btn"
            onClick={() => onConnect(a.id)}
          >
            {a.meta.iconUrl && <img src={a.meta.iconUrl} alt={a.meta.label} className="pollar-wallet-icon" />}
            {a.meta.label}
          </button>
        ))}
      </>
    );
  }
  return (
    <div className="pollar-wallet-list">
      {walletAdapters.map((a) => (
        <button
          key={a.id}
          type="button"
          disabled={isLoading}
          className="pollar-wallet-list-btn"
          onClick={() => onConnect(a.id)}
        >
          {a.meta.iconUrl && <img src={a.meta.iconUrl} alt={a.meta.label} className="pollar-wallet-list-icon" />}
          <span className="pollar-wallet-list-name">{a.meta.label}</span>
        </button>
      ))}
    </div>
  );
}

const AUTH_STATE_MESSAGES: Record<AuthState['step'], string> = {
  idle: '',
  creating_session: 'Initializing…',
  entering_email: '',
  sending_email: 'Sending…',
  entering_code: 'Code sent — check your inbox',
  verifying_email_code: 'Verifying…',
  opening_oauth: 'Redirecting…',
  connecting_wallet: 'Connecting wallet…',
  signing_wallet_challenge: 'Confirm in your wallet…',
  wallet_not_installed: 'Wallet not installed',
  authenticating_wallet: 'Signing in with wallet…',
  creating_passkey: 'Waiting for passkey…',
  deploying_smart_account: 'Creating your wallet…',
  authenticating: 'Authenticating…',
  authenticated: 'Welcome!',
  error: '',
};

function authStateToStatus(step: AuthState['step']): StateStatus {
  const loading: AuthState['step'][] = [
    'creating_session',
    'sending_email',
    'verifying_email_code',
    'opening_oauth',
    'connecting_wallet',
    'signing_wallet_challenge',
    'authenticating_wallet',
    'creating_passkey',
    'deploying_smart_account',
    'authenticating',
  ];
  const success: AuthState['step'][] = ['authenticated', 'entering_code'];
  const error: AuthState['step'][] = ['error', 'wallet_not_installed'];

  if (loading.includes(step)) return 'LOADING';
  if (success.includes(step)) return 'SUCCESS';
  if (error.includes(step)) return 'ERROR';
  return 'NONE';
}

interface LoginModalTemplateProps {
  theme: string;
  accentColor: string;
  /** Per-app modal chrome overrides (background, card + button radius). */
  styleOverrides?: ModalStyleOverrides;
  logoUrl: string | null;
  emailEnabled: boolean;
  embeddedWallets: boolean;
  /** Show the "Smart Wallet" (passkey) option. Optional & defaults to off so
   *  adding it isn't a breaking change for existing template consumers. */
  smartWallet?: boolean;
  providers: {
    google: boolean;
    discord: boolean;
    x: boolean;
    github: boolean;
    apple: boolean;
  };
  /** Registered wallet adapters to render as buttons (Freighter, Albedo, Privy, ...). */
  walletAdapters: WalletAdapterEntry[];
  appName: string;
  email?: string;
  onEmailChange?: (email: string) => void;
  onEmailSubmit?: () => void;
  onSocialLogin?: (provider: 'google' | 'github') => void;
  onWalletConnect?: (id: WalletId) => void;
  /** Log in with an existing passkey (returning user). */
  onLoginSmartWallet?: () => void;
  /** Create a new passkey + smart wallet (new user). */
  onCreateSmartWallet?: () => void;
  authState: AuthState;
  codeInputKey?: number;
  onCodeSubmit?: (code: string) => void;
  onBack: () => void;
  onCancel: () => void;
  onRetry: () => void;
}

export function LoginModalTemplate({
  theme,
  accentColor,
  styleOverrides,
  logoUrl,
  emailEnabled,
  embeddedWallets,
  smartWallet = false,
  providers,
  walletAdapters,
  appName,
  email = '',
  onEmailChange,
  onEmailSubmit,
  onSocialLogin,
  onWalletConnect,
  onLoginSmartWallet,
  onCreateSmartWallet,
  authState,
  codeInputKey,
  onCodeSubmit,
  onBack,
  onCancel,
  onRetry,
}: LoginModalTemplateProps) {
  const [showPasskeyChooser, setShowPasskeyChooser] = useState(false);
  // Which wallet group's sub-picker is open (gateway label), or null for the root view.
  const [activeGroup, setActiveGroup] = useState<string | null>(null);

  const enabledSocial = Object.entries(providers).filter(([, enabled]) => enabled);

  // Split registered adapters into root-level buttons (no `meta.group`, e.g. Privy)
  // and gateway groups (adapters sharing a `meta.group` collapse behind one button
  // that opens a sub-picker - e.g. the Stellar Wallets Kit wallets under "Wallet").
  const rootAdapters = walletAdapters.filter((a) => !a.meta.group);
  const walletGroups = walletAdapters
    .filter((a) => a.meta.group)
    .reduce<{ label: string; adapters: WalletAdapterEntry[] }[]>((acc, a) => {
      const label = a.meta.group as string;
      const existing = acc.find((g) => g.label === label);
      if (existing) existing.adapters.push(a);
      else acc.push({ label, adapters: [a] });
      return acc;
    }, []);
  const activeGroupAdapters = walletGroups.find((g) => g.label === activeGroup)?.adapters ?? [];

  const cssVars = buildModalCssVars(theme, accentColor, styleOverrides, 'hero');

  const status = authStateToStatus(authState.step);
  const isLoading = status === 'LOADING';
  const isEmailCodeError =
    authState.step === 'error' &&
    (authState.errorCode === AUTH_ERROR_CODES.EMAIL_CODE_EXPIRED ||
      authState.errorCode === AUTH_ERROR_CODES.EMAIL_CODE_INVALID);
  const awaitingEmailCode = authState.step === 'entering_code' || authState.step === 'verifying_email_code' || isEmailCodeError;
  const statusMessage = authState.step === 'error' ? authState.message : AUTH_STATE_MESSAGES[authState.step];

  const BackButton = ({ onClick }: { onClick: () => void }) => (
    <button type="button" className="pollar-back-btn" onClick={onClick} aria-label="Back">
      <svg
        width="20"
        height="20"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="2.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <path d="M15 19l-7-7 7-7" />
      </svg>
    </button>
  );

  return (
    <div className="pollar-modal-card pollar-modal" style={cssVars} onClick={(e) => e.stopPropagation()}>
      <button type="button" className="pollar-close-btn" onClick={onCancel} aria-label="Close">
        <svg
          width="18"
          height="18"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path d="M18 6L6 18M6 6l12 12" />
        </svg>
      </button>
      <div className="pollar-header">
        <div className="pollar-logo-wrap">
          <img src={logoUrl ?? LOGO_POLLAR} alt="Logo" className="pollar-logo" />
        </div>
        <h2 className="pollar-title">{appName}</h2>
        <p className="pollar-subtitle">Log in or sign up</p>
      </div>

      {awaitingEmailCode ? (
        <>
          <BackButton onClick={onBack} />
          <EmailCodeInput key={codeInputKey} email={email} onSubmit={onCodeSubmit ?? (() => {})} />
        </>
      ) : activeGroup ? (
        <>
          <BackButton onClick={() => setActiveGroup(null)} />
          <WalletAdapterButtons
            walletAdapters={activeGroupAdapters}
            onConnect={onWalletConnect ?? (() => {})}
            isLoading={isLoading}
          />
        </>
      ) : showPasskeyChooser ? (
        <>
          <BackButton onClick={() => setShowPasskeyChooser(false)} />
          <div className="pollar-wallet-section">
            <button type="button" disabled={isLoading} className="pollar-btn-primary" onClick={onCreateSmartWallet}>
              Create a new wallet
            </button>
            <button type="button" disabled={isLoading} className="pollar-wallet-entry-btn" onClick={onLoginSmartWallet}>
              Log in with an existing wallet
            </button>
          </div>
        </>
      ) : (
        <>
          {emailEnabled && (
            <div className="pollar-email-section">
              <input
                type="email"
                placeholder="you@email.com"
                value={email}
                disabled={isLoading}
                className="pollar-input"
                onChange={(e) => onEmailChange?.(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && onEmailSubmit?.()}
              />
              <button
                type="button"
                disabled={isLoading || !email}
                className="pollar-btn-primary"
                style={{ marginTop: '0.75rem' }}
                onClick={onEmailSubmit}
              >
                Submit
              </button>
            </div>
          )}

          {emailEnabled && enabledSocial.length > 0 && (
            <div className="pollar-divider">
              <div className="pollar-divider-line" />
              <div className="pollar-divider-label">
                <span className="pollar-divider-text">or continue with</span>
              </div>
            </div>
          )}

          {enabledSocial.length > 0 && (
            <div className="pollar-social-list">
              {enabledSocial.some(([key]) => key === 'google') && (
                <GoogleButton disabled={isLoading} onClick={() => onSocialLogin?.('google')} />
              )}
              {enabledSocial.some(([key]) => key === 'github') && (
                <GithubButton disabled={isLoading} onClick={() => onSocialLogin?.('github')} />
              )}
            </div>
          )}

          {(embeddedWallets || smartWallet) && (
            <div className="pollar-wallet-section">
              {embeddedWallets && (
                <>
                  {walletGroups.map((g) => (
                    <button
                      key={g.label}
                      type="button"
                      disabled={isLoading}
                      className="pollar-wallet-entry-btn"
                      onClick={() => setActiveGroup(g.label)}
                    >
                      <svg
                        width="18"
                        height="20"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="2"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      >
                        <path d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z" />
                      </svg>
                      {g.label}
                    </button>
                  ))}
                  {rootAdapters.length > 0 && (
                    <WalletAdapterButtons
                      walletAdapters={rootAdapters}
                      onConnect={onWalletConnect ?? (() => {})}
                      isLoading={isLoading}
                      variant="entry"
                    />
                  )}
                </>
              )}

              {smartWallet && (
                <button
                  type="button"
                  disabled={isLoading}
                  className="pollar-wallet-entry-btn"
                  onClick={() => setShowPasskeyChooser(true)}
                >
                  <svg
                    width="18"
                    height="20"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  >
                    <path d="M16 8V6a4 4 0 00-8 0v2M5 8h14a1 1 0 011 1v10a1 1 0 01-1 1H5a1 1 0 01-1-1V9a1 1 0 011-1zm7 5v2" />
                  </svg>
                  Smart Wallet
                </button>
              )}
            </div>
          )}
        </>
      )}

      <ModalStatusBanner
        message={statusMessage}
        status={status}
        onCancel={onCancel}
        onRetry={isEmailCodeError ? undefined : onRetry}
      />

      <PollarModalFooter />
    </div>
  );
}

/** Placeholder shown inside the login modal while the app config is loading, or
 *  when its remote fetch failed - instead of the empty shell that renders when
 *  `styles` is still the default `{}`. Mirrors the template's card chrome (logo,
 *  title, footer) so the swap to the real form isn't jarring. */
export function LoginModalStatus({
  status,
  theme,
  accentColor,
  styleOverrides,
  logoUrl,
  appName,
  onRetry,
  onCancel,
}: {
  status: 'loading' | 'error';
  theme: string;
  accentColor: string;
  styleOverrides?: ModalStyleOverrides;
  logoUrl: string | null;
  appName: string;
  onRetry: () => void;
  onCancel: () => void;
}) {
  const cssVars = buildModalCssVars(theme, accentColor, styleOverrides, 'hero');
  return (
    <div className="pollar-modal-card pollar-modal" style={cssVars} onClick={(e) => e.stopPropagation()}>
      <button type="button" className="pollar-close-btn" onClick={onCancel} aria-label="Close">
        <svg
          width="18"
          height="18"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path d="M18 6L6 18M6 6l12 12" />
        </svg>
      </button>
      <div className="pollar-header">
        <div className="pollar-logo-wrap">
          <img src={logoUrl ?? LOGO_POLLAR} alt="Logo" className="pollar-logo" />
        </div>
        <h2 className="pollar-title">{appName}</h2>
        <p className="pollar-subtitle">Log in or sign up</p>
      </div>

      {status === 'loading' ? (
        <div className="pollar-loading-block">
          <div className="pollar-spinner" />
          <span>Loading...</span>
        </div>
      ) : (
        <div className="pollar-wallet-section">
          <p className="pollar-modal-error">Could not load sign-in options. Check your connection and try again.</p>
          <button type="button" className="pollar-btn-primary" onClick={onRetry}>
            Try again
          </button>
        </div>
      )}

      <PollarModalFooter />
    </div>
  );
}

'use client';

import { useMemo, useState } from 'react';
import type { InteractiveAuthAdapter } from '@pollar/core';
import { LOGO_POLLAR } from '../../constants';
import { ModalStatusBanner, PollarModalFooter } from '../commons';
import { EmailCodeInput } from './EmailCodeInput';
import { GithubButton } from './GithubButton';
import { GoogleButton } from './GoogleButton';
import { buildModalCssVars, type ModalStyleOverrides } from '../modal-theme';

type StateStatus = 'NONE' | 'LOADING' | 'SUCCESS' | 'ERROR';

interface PrivyLoginSubmodalProps {
  /** The interactive adapter whose login (email/oauth) we drive. */
  adapter: InteractiveAuthAdapter;
  theme: string;
  accentColor: string;
  /** Per-app modal chrome overrides (background, card + button radius). */
  styleOverrides?: ModalStyleOverrides;
  logoUrl: string | null;
  appName: string;
  /** Return to the root login view. */
  onBack: () => void;
  /** Close the whole login modal. */
  onCancel: () => void;
  /** The provider login finished - hand off to `login({ provider })`. */
  onAuthenticated: () => void;
}

/**
 * Sub-modal for an {@link InteractiveAuthAdapter} (e.g. `@pollar/privy-adapter`).
 * It renders the adapter's `getAuthOptions()` (email / Google / GitHub), runs the
 * provider login by calling the adapter's methods, then signals
 * {@link PrivyLoginSubmodalProps.onAuthenticated} so the host triggers the normal
 * `login({ provider })` (which runs `connect()` + SEP-10).
 *
 * Owned by `@pollar/react`; reuses the login-modal CSS classes/vars.
 */
export function PrivyLoginSubmodal({
  adapter,
  theme,
  accentColor,
  styleOverrides,
  logoUrl,
  appName,
  onBack,
  onCancel,
  onAuthenticated,
}: PrivyLoginSubmodalProps) {
  const options = useMemo(() => adapter.getAuthOptions(), [adapter]);
  const [email, setEmail] = useState('');
  const [view, setView] = useState<'root' | 'email-code'>('root');
  const [status, setStatus] = useState<StateStatus>('NONE');
  const [message, setMessage] = useState('');

  const isLoading = status === 'LOADING';

  const cssVars = buildModalCssVars(theme, accentColor, styleOverrides, 'hero');

  function fail(error: unknown) {
    setStatus('ERROR');
    setMessage(error instanceof Error ? error.message : 'Something went wrong. Please try again.');
  }

  async function handleEmailSubmit() {
    if (!email) return;
    setStatus('LOADING');
    setMessage('');
    try {
      await adapter.sendEmailCode(email);
      setStatus('SUCCESS');
      setMessage('Code sent — check your inbox');
      setView('email-code');
    } catch (error) {
      fail(error);
    }
  }

  async function handleCodeSubmit(code: string) {
    setStatus('LOADING');
    setMessage('Verifying…');
    try {
      await adapter.verifyEmailCode(code);
      onAuthenticated();
    } catch (error) {
      fail(error);
    }
  }

  async function handleOAuth(provider: 'google' | 'github') {
    setStatus('LOADING');
    setMessage('');
    try {
      // On web Privy may redirect for OAuth; completion then arrives after the
      // round-trip. Email login resolves in-session and is the robust path.
      await adapter.loginWithOAuth(provider);
      onAuthenticated();
    } catch (error) {
      fail(error);
    }
  }

  const BackButton = ({ onClick }: { onClick: () => void }) => (
    <button type="button" className="pollar-back-btn" onClick={onClick} aria-label="Back">
      <svg
        width="20"
        height="20"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="2.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <path d="M15 19l-7-7 7-7" />
      </svg>
    </button>
  );

  const showEmail = options.includes('email');
  const showGoogle = options.includes('google');
  const showGithub = options.includes('github');

  return (
    <div className="pollar-modal-card pollar-modal" style={cssVars} onClick={(e) => e.stopPropagation()}>
      <button type="button" className="pollar-close-btn" onClick={onCancel} aria-label="Close">
        <svg
          width="18"
          height="18"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path d="M18 6L6 18M6 6l12 12" />
        </svg>
      </button>

      <div className="pollar-header">
        <div className="pollar-logo-wrap">
          <img src={logoUrl ?? LOGO_POLLAR} alt="Logo" className="pollar-logo" />
        </div>
        <h2 className="pollar-title">{appName}</h2>
        <p className="pollar-subtitle">{adapter.meta.label}</p>
      </div>

      {view === 'email-code' ? (
        <>
          <BackButton onClick={() => setView('root')} />
          <EmailCodeInput email={email} onSubmit={handleCodeSubmit} />
        </>
      ) : (
        <>
          <BackButton onClick={onBack} />
          {showEmail && (
            <div className="pollar-email-section">
              <input
                type="email"
                placeholder="you@email.com"
                value={email}
                disabled={isLoading}
                className="pollar-input"
                onChange={(e) => setEmail(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleEmailSubmit()}
              />
              <button
                type="button"
                disabled={isLoading || !email}
                className="pollar-btn-primary"
                style={{ marginTop: '0.75rem' }}
                onClick={handleEmailSubmit}
              >
                Submit
              </button>
            </div>
          )}

          {showEmail && (showGoogle || showGithub) && (
            <div className="pollar-divider">
              <div className="pollar-divider-line" />
              <div className="pollar-divider-label">
                <span className="pollar-divider-text">or continue with</span>
              </div>
            </div>
          )}

          {(showGoogle || showGithub) && (
            <div className="pollar-social-list">
              {showGoogle && <GoogleButton disabled={isLoading} onClick={() => handleOAuth('google')} />}
              {showGithub && <GithubButton disabled={isLoading} onClick={() => handleOAuth('github')} />}
            </div>
          )}
        </>
      )}

      <ModalStatusBanner message={message} status={status} onCancel={onCancel} onRetry={undefined} />
      <PollarModalFooter />
    </div>
  );
}

import type { CSSProperties } from 'react';
import type { PollarStyles } from '../types';

/** Per-app overrides for the modal chrome, configured in the dashboard's
 *  Branding screen. Every field is optional: absent means "use the value the
 *  theme derives", which is what every modal rendered before these existed. */
export interface ModalStyleOverrides {
  /** Card background. Overrides the theme's white / #1a1a1a. */
  backgroundColor?: string | null | undefined;
  /** Body text. Overrides the theme's #111827 / white. Secondary ("muted") text
   *  keeps its theme color, so the two stay distinguishable. */
  textColor?: string | null | undefined;
  /** Fill of the SECONDARY buttons (the wallet / social / provider entries, the
   *  retry button). The primary button is the accent's job. Unset => the theme's
   *  own surface color, which is what these buttons always used. */
  buttonColor?: string | null | undefined;
  /** Radius of the modal card itself, in px. */
  modalBorderRadius?: number | null | undefined;
  /** Radius of the buttons inside the modal, in px. Independent of the card's. */
  buttonBorderRadius?: number | null | undefined;
}

/** The card radius the modals used before it was configurable (1rem). */
const DEFAULT_MODAL_BORDER_RADIUS = 16;
/** Same, for the buttons. */
const DEFAULT_BUTTON_BORDER_RADIUS = 6;
/** Stacking order of the fixed overlay, before it was configurable. */
const DEFAULT_OVERLAY_Z_INDEX = 50;

/** A configured length, as a CSS px string. Anything that isn't a finite,
 *  non-negative number falls back to `fallback` - a malformed stored value must
 *  not collapse the card's chrome. */
function px(value: number | null | undefined, fallback: number): string {
  return `${typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : fallback}px`;
}

/** A configured color, or the theme's own when unset. Empty string counts as
 *  unset: that's what the dashboard sends when the field is cleared. */
function color(value: string | null | undefined, fallback: string): string {
  return typeof value === 'string' && value.trim() !== '' ? value : fallback;
}

/** `#rgb` / `#rrggbb` as 0-255 channels, or null for anything else (a named
 *  color, a `color-mix()`, a typo). */
function parseHex(value: string): [number, number, number] | null {
  const hex = value.trim().replace(/^#/, '');
  const full = hex.length === 3 ? [...hex].map((c) => c + c).join('') : hex;
  if (!/^[0-9a-f]{6}$/i.test(full)) return null;
  return [Number.parseInt(full.slice(0, 2), 16), Number.parseInt(full.slice(2, 4), 16), Number.parseInt(full.slice(4, 6), 16)];
}

/** Text color that stays legible on `background`. The primary button's label was
 *  hardcoded white, which a light fill (the Amber accent preset, say) turns
 *  invisible - so it follows the fill's luminance instead. Unparseable colors
 *  keep white, the pre-existing behavior. */
export function readableTextOn(background: string): string {
  const rgb = parseHex(background);
  if (!rgb) return '#ffffff';
  // Relative luminance, sRGB coefficients (WCAG). The 0.6 cut lands white on
  // Pollar blue (#005DB4) exactly as before, and dark on a pale fill.
  const [r, g, b] = rgb;
  return (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255 > 0.6 ? '#111827' : '#ffffff';
}

/** How much room a modal gives its header. 'hero' is the identity-forward set
 *  (login, KYC, ramp, the Privy sub-modal): roomier padding and a larger
 *  centered heading. 'compact' is every utility modal (send, balance, history,
 *  ...), which keeps the card's own 1.75rem padding. */
export type ModalVariant = 'hero' | 'compact';

/** Theme-derived CSS custom properties shared by every Pollar modal, plus the
 *  per-app overrides on top. One definition so the whole modal family stays
 *  visually in lockstep - a var added here reaches all of them at once. */
export function buildModalCssVars(
  theme: string,
  accentColor: string,
  overrides: ModalStyleOverrides = {},
  variant: ModalVariant = 'compact',
): CSSProperties {
  const isDark = theme === 'dark';
  const textColor = color(overrides.textColor, isDark ? '#ffffff' : '#111827');
  // Only emitted when actually configured. Left out, the secondary buttons fall
  // back inside the CSS to whatever each already used - the theme surface for
  // the filled ones, `transparent` for the ghost one - so an unset field can't
  // flatten those two into the same look.
  const secondaryBg = color(overrides.buttonColor, '');
  return {
    '--pollar-accent': accentColor,
    '--pollar-bg': color(overrides.backgroundColor, isDark ? '#1a1a1a' : '#ffffff'),
    '--pollar-border': isDark ? '#374151' : '#e5e7eb',
    '--pollar-text': textColor,
    '--pollar-muted': isDark ? '#9ca3af' : '#6b7280',
    // The primary button is the accent's, straight up; its label follows the
    // accent's luminance so a pale accent doesn't render white-on-white.
    '--pollar-btn-primary-fg': readableTextOn(accentColor),
    ...(secondaryBg
      ? {
          '--pollar-btn-secondary-bg': secondaryBg,
          '--pollar-btn-secondary-fg': readableTextOn(secondaryBg),
        }
      : {}),
    '--pollar-input-bg': isDark ? '#374151' : '#f9fafb',
    '--pollar-error-bg': isDark ? '#2a1515' : '#fef2f2',
    '--pollar-error-border': isDark ? '#7f1d1d' : '#fecaca',
    '--pollar-error-text': isDark ? '#f87171' : '#dc2626',
    '--pollar-success-text': isDark ? '#4ade80' : '#16a34a',
    '--pollar-modal-border-radius': px(overrides.modalBorderRadius, DEFAULT_MODAL_BORDER_RADIUS),
    '--pollar-buttons-border-radius': px(overrides.buttonBorderRadius, DEFAULT_BUTTON_BORDER_RADIUS),
    '--pollar-buttons-height': '44px',
    '--pollar-input-height': '44px',
    '--pollar-input-border-radius': '0.5rem',
    '--pollar-card-border-radius': '10px',
    ...(variant === 'hero'
      ? {
          '--pollar-modal-padding': '2rem',
          '--pollar-modal-heading-size': '1.375rem',
          '--pollar-modal-subtitle-size': '0.9rem',
        }
      : {}),
  } as CSSProperties;
}

/** Everything a modal wrapper needs to dress itself from the app's branding:
 *  the theme pair its template already took, the overrides to forward to that
 *  template, and the inline style for the fixed overlay behind it. */
export interface ModalChrome {
  theme: string;
  accentColor: string;
  styleOverrides: ModalStyleOverrides;
  overlayStyle: CSSProperties;
}

/** Resolve the branding config into the props/styles a modal wrapper applies.
 *  Called by every `.pollar-overlay` renderer so the z-index and the card
 *  overrides can't drift apart between modals. */
export function modalChrome(styles: PollarStyles): ModalChrome {
  const zIndex = styles.modalZIndex;
  return {
    theme: styles.theme ?? 'light',
    accentColor: styles.accentColor ?? '#005DB4',
    styleOverrides: {
      backgroundColor: styles.backgroundColor,
      textColor: styles.textColor,
      buttonColor: styles.buttonColor,
      modalBorderRadius: styles.modalBorderRadius,
      buttonBorderRadius: styles.buttonBorderRadius,
    },
    overlayStyle: {
      '--pollar-overlay-z-index': typeof zIndex === 'number' && Number.isFinite(zIndex) ? zIndex : DEFAULT_OVERLAY_Z_INDEX,
    } as CSSProperties,
  };
}

'use client';

import type { ProviderRegistration } from '@pollar/core';
import { useEffect, useMemo, useRef, useState } from 'react';
import { usePollar } from '../../context';
import { PollarModalFooter } from '../commons';
import { buildModalCssVars, modalChrome } from '../modal-theme';
import { formLanguage } from '../requirement-form-modal/form-fields';
import {
  errorCode,
  missingFieldsOf,
  REGISTRATION_COPY,
  registrationFixOf,
  SHARED_FIELD_LABELS,
} from '../registry-check-modal/registry-copy';
import { RequirementFormModal } from '../requirement-form-modal/RequirementFormModal';
import '../shared.css';
import '../requirement-form-modal/RequirementFormModal.css';

interface ProviderRegistrationModalProps {
  /** The route whose ramp the user registers with. */
  corridorId?: string;
  /** Or the card provider. One of the two. */
  cardProviderId?: string;
  /** Position of this step over the route's steps, when known. */
  progress?: { position: number; total: number };
  onClose: () => void;
  /** Called once the user is registered with the provider. */
  onRegistered: () => void;
}

/**
 * One PROVIDER_REGISTRATION step: what the ramp provider receives, listed before the
 * user consents. Registering is the consent; nothing is sent until then.
 */
export function ProviderRegistrationModal({
  corridorId,
  cardProviderId,
  progress,
  onClose,
  onRegistered,
}: ProviderRegistrationModalProps) {
  const { getClient, styles } = usePollar();
  const client = getClient();
  const { theme, accentColor, styleOverrides, overlayStyle } = modalChrome(styles);
  const cssVars = buildModalCssVars(theme, accentColor, styleOverrides, 'hero');
  const language = useMemo(formLanguage, []);
  const copy = REGISTRATION_COPY[language];
  const labels = SHARED_FIELD_LABELS[language];

  const [registration, setRegistration] = useState<
    (Pick<ProviderRegistration, 'ready' | 'fields'> & { status: ProviderRegistration['status'] | 'incomplete' }) | null
  >(null);
  const [termsUrl, setTermsUrl] = useState<string | null>(null);
  const [consent, setConsent] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  // The form holding answers the registration could not use: reopened to fix them, then the registration is sent again.
  const [fixForm, setFixForm] = useState<string | null>(null);
  const [fixing, setFixing] = useState<string | null>(null);
  const mounted = useRef(true);
  useEffect(() => {
    // Set on every mount: development mounts components twice, and the cleanup of the
    // first mount would otherwise leave this false and drop every response.
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  useEffect(() => {
    const load = cardProviderId
      ? client.getCardProviderRegistration(cardProviderId).then((loaded) => {
          setTermsUrl(loaded.termsUrl);
          return loaded;
        })
      : client.getProviderRegistration(corridorId ?? '');
    load
      .then((loaded) => {
        if (!mounted.current) return;
        if (loaded.status === 'registered') onRegistered();
        else setRegistration(loaded);
      })
      .catch(() => mounted.current && setError(copy.loadError));
    // The client instance, the copy and the callback do not change while the modal is open.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [corridorId, cardProviderId]);

  async function submit() {
    setSubmitting(true);
    setError(null);
    setFixForm(null);
    try {
      if (cardProviderId) await client.submitCardProviderRegistration(cardProviderId);
      else await client.submitProviderRegistration(corridorId ?? '');
      if (mounted.current) onRegistered();
    } catch (e) {
      if (!mounted.current) return;
      const code = errorCode(e);
      if (code === 'KYC_REGISTRATION_MISSING_DATA') {
        const fix = registrationFixOf(e);
        const named = (keys: string[]) => keys.map((key) => labels[key] ?? key).join(', ');
        const missing = missingFieldsOf(e).filter((key) => !fix.invalid.includes(key));
        setError(
          [
            fix.invalid.length ? copy.invalid.replace('{fields}', named(fix.invalid)) : null,
            missing.length ? copy.missing.replace('{fields}', named(missing)) : null,
          ]
            .filter(Boolean)
            .join(' '),
        );
        setFixForm(fix.forms[0]?.formId ?? null);
      } else if (code === 'KYC_REGISTRATION_STEPS_PENDING') setError(copy.notReady);
      else if (code === 'SDK_CARDS_PROVIDER_ERROR') setError(copy.providerDown);
      else if (code === 'SDK_CARDS_IP_NOT_SUPPORTED') setError(copy.ipNotSupported);
      else if (code === 'SDK_CARDS_PROVIDER_USER_TAKEN') setError(copy.emailTaken);
      else setError(copy.submitError);
    } finally {
      if (mounted.current) setSubmitting(false);
    }
  }

  if (fixing) {
    return (
      <RequirementFormModal
        formId={fixing}
        onClose={() => setFixing(null)}
        onSubmitted={() => {
          setFixing(null);
          void submit();
        }}
      />
    );
  }

  return (
    <div className="pollar-overlay" style={overlayStyle} onClick={onClose}>
      <div
        className="pollar-modal-card pollar-form-modal"
        role="dialog"
        aria-modal="true"
        aria-label={copy.title}
        style={cssVars}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="pollar-modal-header">
          <div className="pollar-form-header-text">
            <h2 className="pollar-modal-title">{copy.title}</h2>
            {progress && (
              <p className="pollar-form-subtitle">
                {copy.step.replace('{n}', String(progress.position)).replace('{total}', String(progress.total))}
              </p>
            )}
          </div>
          <button type="button" className="pollar-modal-close" onClick={onClose} aria-label={copy.close}>
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
              <path d="M2 2l12 12M14 2L2 14" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
            </svg>
          </button>
        </div>

        {error && (
          <p className="pollar-form-error" role="alert">
            {error}
          </p>
        )}
        {fixForm && !submitting && (
          <div className="pollar-modal-actions">
            <button type="button" className="pollar-btn-primary" onClick={() => setFixing(fixForm)}>
              {copy.fix}
            </button>
          </div>
        )}

        {!registration && !error && (
          <div className="pollar-loading-block">
            <div className="pollar-spinner" />
          </div>
        )}

        {registration && (
          <form
            className="pollar-form-body"
            onSubmit={(e) => {
              e.preventDefault();
              void submit();
            }}
          >
            {registration.ready ? (
              <>
                {registration.status === 'incomplete' && (
                  <p className="pollar-form-error" role="status">
                    {copy.incomplete}
                  </p>
                )}
                <p className="pollar-form-description">{copy.intro}</p>
                <ul className="pollar-form-description">
                  {registration.fields.map((key) => (
                    <li key={key}>{labels[key] ?? key}</li>
                  ))}
                </ul>
                {termsUrl && (
                  <p className="pollar-form-description">
                    <a href={termsUrl} target="_blank" rel="noreferrer">
                      {copy.terms}
                    </a>
                  </p>
                )}
                <label className="pollar-form-choice">
                  <input
                    type="checkbox"
                    checked={consent}
                    disabled={submitting}
                    onChange={(e) => setConsent(e.target.checked)}
                  />
                  {copy.consent}
                </label>
              </>
            ) : (
              <p className="pollar-form-error" role="status">
                {copy.notReady}
              </p>
            )}
            <div className="pollar-modal-actions">
              <button type="button" className="pollar-btn-secondary" onClick={onClose} disabled={submitting}>
                {copy.close}
              </button>
              {registration.ready && (
                <button type="submit" className="pollar-btn-primary" disabled={submitting || !consent}>
                  {submitting ? copy.submitting : copy.submit}
                </button>
              )}
            </div>
          </form>
        )}
        <PollarModalFooter />
      </div>
    </div>
  );
}

/* --- Widget container -------------------------------------------------------- */
.pollar-ramp-modal {
  max-width: 480px;
}

/* --- Header ------------------------------------------------------------------ */
.pollar-ramp-header-text {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  min-width: 0;
}

.pollar-ramp-subtitle {
  margin: 0;
  font-size: var(--pollar-modal-subtitle-size, 0.9rem);
  color: var(--pollar-muted);
}

/* --- Step indicator --------------------------------------------------------
   One segment per step of THIS run - the count varies by route, so the track is
   a flex row of equal shares rather than a percentage-filled bar. */
.pollar-ramp-steps {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-bottom: 1.25rem;
}

.pollar-ramp-steps-label {
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--pollar-muted);
}

.pollar-ramp-steps-track {
  display: flex;
  gap: 0.375rem;
}

.pollar-ramp-steps-segment {
  flex: 1;
  height: 4px;
  border-radius: 999px;
  background: var(--pollar-border);
  transition: background-color 0.2s;
}

.pollar-ramp-steps-segment[data-done] {
  background: var(--pollar-accent);
}

/* The country <select> loading placeholder uses the shared .pollar-select-loading
   (spinner + label inside a select-shaped box), consistent with all the modals. */

/* Direction tabs use the shared segmented control (.pollar-tabs / .pollar-tab). */

/* --- Input group ------------------------------------------------------------- */
.pollar-ramp-field {
  margin-bottom: 1rem;
}

.pollar-ramp-label {
  display: block;
  margin-bottom: 0.375rem;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--pollar-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.pollar-ramp-input {
  width: 100%;
  height: var(--pollar-input-height, 44px);
  padding: 0 1rem;
  border-radius: var(--pollar-input-border-radius, 0.5rem);
  border: 1px solid var(--pollar-border);
  background-color: var(--pollar-input-bg);
  color: var(--pollar-text);
  font-size: 1rem;
  outline: none;
  box-sizing: border-box;
}

.pollar-ramp-input:focus {
  box-shadow: 0 0 0 2px var(--pollar-accent);
  border-color: transparent;
}

.pollar-ramp-field-error {
  display: block;
  margin-top: 0.375rem;
  font-size: 0.75rem;
  color: var(--pollar-error-text, #dc2626);
}

.pollar-ramp-field-hint {
  display: block;
  margin-top: 0.375rem;
  font-size: 0.75rem;
  color: var(--pollar-muted);
}

/* Rides inside the label, so it reads as part of the field name rather than as
   another line competing with the hint below. */
.pollar-ramp-field-optional {
  font-weight: 400;
  text-transform: none;
  color: var(--pollar-muted);
}

.pollar-ramp-input-row {
  display: flex;
  gap: 0.625rem;
}

.pollar-ramp-input-row .pollar-ramp-field {
  flex: 1;
}

/* --- Loading quote ----------------------------------------------------------- */
.pollar-ramp-loading {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
  padding: 1.5rem 0;
}

.pollar-ramp-loading-spinner {
  align-self: center;
  margin-bottom: 0.5rem;
}

.pollar-ramp-loading-row {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  font-size: 0.875rem;
  color: var(--pollar-muted);
  opacity: 0;
  transform: translateY(4px);
  animation: pollar-ramp-appear 0.3s ease forwards;
}

.pollar-ramp-loading-row:nth-child(1) {
  animation-delay: 0ms;
}
.pollar-ramp-loading-row:nth-child(2) {
  animation-delay: 400ms;
}
.pollar-ramp-loading-row:nth-child(3) {
  animation-delay: 800ms;
}

@keyframes pollar-ramp-appear {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

