'use client';

import type {
  RampCountry,
  RampDepositInstructions,
  RampDirection,
  RampQuote,
  RampQuoteRequirement,
  RampsOfframpBody,
  RampsOnrampBody,
  RampTxStatus,
} from '@pollar/core';
import { mergeRampCountries, mergeRampSnapshot, type RampSnapshot, type RampRoute } from '@pollar/core';
import { RampWorkflow } from './RampWorkflow';
import { useEffect, useRef, useState } from 'react';
import { usePollar } from '../../context';
import type { RampFieldSpec, RampStep } from './RampWidgetTemplate';
import { RampWidgetTemplate } from './RampWidgetTemplate';
import '../shared.css';
import './RampWidget.css';
import { modalChrome } from '../modal-theme';
import { KycModal } from '../kyc-modal/KycModal';
import { RequirementFormModal } from '../requirement-form-modal/RequirementFormModal';
import { RegistryCheckModal } from '../registry-check-modal/RegistryCheckModal';
import { ProviderRegistrationModal } from '../provider-registration-modal/ProviderRegistrationModal';
import { pendingFromQuote, requiredRampKyc, type PendingRequirement } from './ramp-kyc';

interface RampWidgetProps {
  onClose: () => void;
}

const TERMINAL: RampTxStatus[] = ['completed', 'failed'];

/** Fields the quote declares the client must collect (empty for SEP-24). */
function requiredFieldsOf(quote: RampQuote): RampFieldSpec[] {
  return (quote as { requiredFields?: RampFieldSpec[] }).requiredFields ?? [];
}

/**
 * The steps a run actually goes through. Not fixed: 'Details' only exists when
 * the chosen route asks for fields (Bridge wants a name and email; SEP-24
 * anchors collect everything on their own hosted page), so a progress bar that
 * always said "of 4" would lie to half the providers.
 *
 * Before a route is picked the total is a forecast: if any offered route would
 * ask for details, the step is shown, and choosing one settles it.
 */
function flowStepsOf(quotes: RampQuote[], selected: RampQuote | null): string[] {
  const needsDetails =
    selected != null ? requiredFieldsOf(selected).length > 0 : quotes.some((q) => requiredFieldsOf(q).length > 0);
  return needsDetails ? ['Amount', 'Provider', 'Details', 'Complete'] : ['Amount', 'Provider', 'Complete'];
}

/** Which of those steps the current widget step sits on. `error` belongs to no
 *  step - the flow stopped rather than advanced - so the bar hides there. */
const STEP_LABEL: Partial<Record<RampStep, string>> = {
  input: 'Amount',
  loading_quote: 'Amount',
  select_route: 'Provider',
  contact: 'Details',
  status: 'Complete',
};

/** A bound the amount broke, or null when it fits. Providers declare their
 *  limits on the quote (`minAmount` / `maxAmount`); the ones that don't simply
 *  never trip this, and the backend stays the last word either way. */
function brokenLimitOf(amount: number, quote: RampQuote): { limit: 'min' | 'max'; value: number } | null {
  const { minAmount, maxAmount } = quote as { minAmount?: number; maxAmount?: number };
  if (!Number.isFinite(amount)) return null;
  if (minAmount != null && amount < minAmount) return { limit: 'min', value: minAmount };
  if (maxAmount != null && amount > maxAmount) return { limit: 'max', value: maxAmount };
  return null;
}

/** "The minimum amount is 11 ARS" - one phrasing, used both when we catch the
 *  limit before submitting and when the backend is the one to report it. */
function limitMessage(limit: 'min' | 'max', value: number, currency: string): string {
  return `The ${limit === 'min' ? 'minimum' : 'maximum'} amount for this route is ${value} ${currency}.`;
}

/** Ramp failures a user can act on. Anything unlisted keeps the raw code, which
 *  is still the most useful thing to show for a cause we can't phrase. */
const RAMP_ERROR_MESSAGES: Record<string, string> = {
  SDK_RAMPS_QUOTE_EXPIRED: 'This quote expired. Request a new one and try again.',
  SDK_RAMPS_ASSET_NOT_ENABLED: 'This currency is not available for that route right now.',
  SDK_RAMPS_KYC_REQUIRED: 'The provider needs to verify your identity before continuing.',
  SDK_RAMPS_WALLET_UNSUPPORTED: 'This wallet type cannot be used for this ramp.',
  SDK_RAMPS_PROVIDER_NOT_CONFIGURED: 'This ramp provider is not configured for this app yet.',
  SDK_RAMPS_ANCHOR_ERROR: 'The provider rejected the request. Please try again in a moment.',
  SDK_RAMPS_BRIDGE_ERROR: 'The provider rejected the request. Please try again in a moment.',
  SDK_RAMPS_ETHERFUSE_ERROR: 'The provider rejected the request. Please try again in a moment.',
  SDK_RAMPS_INSUFFICIENT_BALANCE: 'This wallet does not hold enough to cover that amount. Try a smaller one.',
  // Nothing moved on-chain, so the balance is untouched. Almost always no XLM
  // for the network fee on a wallet the app does not sponsor.
  SDK_RAMPS_ONCHAIN_SUBMIT_FAILED:
    'The network rejected the transaction, so nothing was sent. The wallet may need XLM for the fee.',
};

/**
 * Turn a thrown ramp error into something worth reading. An out-of-range amount
 * arrives with the bound as fields (`limit` / `limitAmount` / `limitCurrency`),
 * so the exact figure gets stated rather than the bare code the modal used to
 * show. Every provider that reports the range gets this for free.
 */
function rampErrorMessage(e: unknown, fallback: string): string {
  const body = (e as { body?: Record<string, unknown> } | undefined)?.body;
  const code = (e as { code?: unknown } | undefined)?.code;
  if (typeof code !== 'string') return e instanceof Error ? e.message : fallback;

  const limit = body?.limit;
  const value = body?.limitAmount;
  const currency = body?.limitCurrency;
  if ((limit === 'min' || limit === 'max') && typeof value === 'number' && typeof currency === 'string') {
    return limitMessage(limit, value, currency);
  }
  return RAMP_ERROR_MESSAGES[code] ?? (e instanceof Error ? e.message : fallback);
}

// Common shape of the on/off-ramp, complete and signature responses.
interface RampResult {
  txId: string;
  provider: string;
  status: RampTxStatus;
  kycUrl?: string;
  // Bridge splits onboarding into two hosted steps: KYC (identity) and ToS
  // acceptance. Both must be completed before the customer activates.
  tosUrl?: string;
  // The provider gated the flow on identity verification and offers no hosted
  // URL (Abroad, and Bridge while it provisions). Nothing was built or signed.
  kycRequired?: boolean;
  // Which part of onboarding is outstanding. `awaiting_provider` means the user
  // has nothing left to do and the provider is working through its own steps -
  // there is no page to open and no status of theirs to poll.
  onboardingStatus?: 'kyc' | 'endorsement' | 'awaiting_provider';
  stellarTxHash?: string;
  pendingSignature?: { unsignedXdr: string; action: 'sep10' | 'withdraw_payment' };
  // REST providers (Bridge) return deposit instructions as data (e.g. a Pix
  // `br_code` / bank details for on-ramp) instead of an interactive URL.
  depositInstructions?: RampDepositInstructions;
}

export function RampWidget({ onClose }: RampWidgetProps) {
  const { getClient, wallet, styles, network } = usePollar();
  const walletAddress = wallet?.address ?? '';
  const client = getClient();
  const { theme, accentColor, styleOverrides, overlayStyle } = modalChrome(styles);

  const [step, setStep] = useState<RampStep>('input');
  const [direction, setDirection] = useState<RampDirection>('onramp');
  const [amount, setAmount] = useState('');
  const [currency, setCurrency] = useState('');
  const [country, setCountry] = useState('');
  // Values for the fields a provider declares via the quote's `requiredFields`
  // (e.g. Bridge on-ramp: full name + email; off-ramp: + Pix key). Keyed by
  // field key; only collected when the selected route needs them.
  const [fieldValues, setFieldValues] = useState<Record<string, string>>({});
  const setFieldValue = (key: string, value: string) => setFieldValues((v) => ({ ...v, [key]: value }));
  const [legacyCountries, setCountries] = useState<RampCountry[]>([]);
  const [countriesLoading, setCountriesLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [quotes, setQuotes] = useState<RampQuote[]>([]);
  const [requirementsRequired, setRequirementsRequired] = useState<RampQuoteRequirement[]>([]);
  const [selectedQuote, setSelectedQuote] = useState<RampQuote | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [pendingKyc, setPendingKyc] = useState<PendingRequirement | null>(null);
  const [noticeMsg, setNoticeMsg] = useState<string | null>(null);
  const kycAttempt = useRef<typeof pendingKyc>(null);
  useEffect(
    () => () => {
      kycAttempt.current = null;
    },
    [],
  );

  // status step
  const [txId, setTxId] = useState<string | null>(null);
  const [provider, setProvider] = useState('');
  const [kycUrl, setKycUrl] = useState<string | null>(null);
  const [tosUrl, setTosUrl] = useState<string | null>(null);
  // Link-less KYC gate (Abroad): `kycPending` is what the provider told us on
  // start; `kycApproved` is what polling has since learned.
  const [kycPending, setKycPending] = useState(false);
  const [kycApproved, setKycApproved] = useState(false);
  const [onboardingStatus, setOnboardingStatus] = useState<RampResult['onboardingStatus']>(undefined);
  const [txStatus, setTxStatus] = useState<RampTxStatus | null>(null);
  const [stellarTxHash, setStellarTxHash] = useState<string | null>(null);
  const [depositInstructions, setDepositInstructions] = useState<RampDepositInstructions | null>(null);
  const [workflow, setWorkflow] = useState<RampSnapshot | null>(null);
  const workflowRef = useRef<RampSnapshot | null>(null);
  const [legacySignature, setLegacySignature] = useState<RampResult['pendingSignature']>(undefined);
  function acceptWorkflow(incoming: RampSnapshot) {
    const next = mergeRampSnapshot(workflowRef.current, incoming);
    workflowRef.current = next;
    setWorkflow(next);
    return next === incoming;
  }
  const [routes, setRoutes] = useState<RampRoute[]>([]);
  const [routeId, setRouteId] = useState('');
  const selectedRoute = routes.find((route) => route.routeId === routeId);
  const countries = mergeRampCountries(legacyCountries, routes);
  useEffect(() => {
    if (!country && countries[0]) {
      setCountry(countries[0].code);
      setCurrency(countries[0].currency ?? '');
    }
  }, [countries, country]);
  useEffect(() => {
    let active = true;
    void client
      .getRampRoutes()
      .then((result) => {
        if (active) setRoutes(result.routes);
      })
      .catch(() => {});
    return () => {
      active = false;
    };
  }, [client]);
  const [completing, setCompleting] = useState(false);
  const completionLocked = useRef(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const directionRef = useRef(direction);
  directionRef.current = direction;

  const workflowTerminal =
    !!workflow && ['completed', 'failed', 'refunded'].includes(workflow.lifecycleState ?? workflow.status);

  // Poll the anchor transaction status while on the status step until terminal.
  useEffect(() => {
    if (step !== 'status' || !txId) return;
    if (workflowTerminal || (txStatus && TERMINAL.includes(txStatus))) return;
    let active = true;
    const id = setInterval(async () => {
      try {
        const tx = await client.getRampTransaction(txId);
        if (!active) return;
        if (tx.transactionVersion !== undefined && !acceptWorkflow(tx)) return;
        setTxStatus(tx.status);
        if (tx.stellarTxHash) setStellarTxHash(tx.stellarTxHash);
        if (tx.kycUrl) setKycUrl(tx.kycUrl);
        // depositInstructions is returned by REST providers (Bridge) - e.g. a Pix
        // `br_code` / bank details for on-ramp.
        if (tx.depositInstructions) setDepositInstructions(tx.depositInstructions);
        if (TERMINAL.includes(tx.status)) clearInterval(id);
      } catch {
        /* transient - keep polling */
      }
    }, 5000);
    return () => {
      active = false;
      clearInterval(id);
    };
  }, [step, txId, txStatus, workflowTerminal, client]);

  // A link-less KYC gate has nothing to open, so poll the provider until the user
  // clears it elsewhere. Stops as soon as it's approved.
  //
  // Not for `awaiting_provider`: that gate is not the user's verification and
  // `getRampKycStatus` answers for a different provider entirely, so polling it
  // would ask the wrong question every ten seconds and never get an answer. The
  // transaction poll above is what surfaces movement there.
  useEffect(() => {
    if (workflow || step !== 'status' || !kycPending || kycApproved) return;
    if (onboardingStatus === 'awaiting_provider') return;
    let active = true;
    const check = async () => {
      try {
        const { hasApproved } = await client.getRampKycStatus();
        if (active && hasApproved) setKycApproved(true);
      } catch {
        /* transient - keep polling */
      }
    };
    void check();
    const id = setInterval(check, 10000);
    return () => {
      active = false;
      clearInterval(id);
    };
  }, [step, kycPending, kycApproved, onboardingStatus, workflow, client]);

  /**
   * Fetch the ramp countries supported on the app's network. When `resetSelection`
   * is set (initial load) - or the current selection is no longer offered - pick
   * the first country and adopt its primary currency.
   */
  async function loadCountries(resetSelection: boolean) {
    setCountriesLoading(true);
    try {
      const { countries: list } = await client.getRampCountries();
      setCountries(list);
      const available = mergeRampCountries(list, routes);
      const first = available[0];
      const stillValid = available.some((c) => c.code === country);
      if (first && (resetSelection || !stillValid)) {
        setCountry(first.code);
        if (first.currency) setCurrency(first.currency);
      }
    } catch {
      setCountries([]);
    } finally {
      setCountriesLoading(false);
    }
  }

  // Load the supported countries when the widget opens.
  useEffect(() => {
    loadCountries(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function handleCountryChange(code: string) {
    setRouteId('');
    setCountry(code);
    const match = countries.find((c) => c.code === code);
    if (match?.currency) setCurrency(match.currency);
  }

  // Refresh the data backing the current step: always the country list, plus the
  // quotes (select_route) or the anchor transaction (status).
  async function handleRefresh() {
    if (refreshing) return;
    setRefreshing(true);
    try {
      await loadCountries(false);
      if (step === 'select_route') {
        const result = await client.getRampsQuote({
          country,
          amount: Number(amount),
          amountExact: amount,
          currency,
          direction,
          ...(selectedRoute ? { routeId: selectedRoute.routeId, chain: selectedRoute.asset.chain } : {}),
        });
        setQuotes(result.quotes ?? []);
        setRequirementsRequired(result.requirementsRequired ?? []);
      } else if (step === 'status' && txId) {
        const tx = await client.getRampTransaction(txId);
        if (tx.transactionVersion !== undefined && !acceptWorkflow(tx)) return;
        setTxStatus(tx.status);
        if (tx.stellarTxHash) setStellarTxHash(tx.stellarTxHash);
        if (tx.kycUrl) setKycUrl(tx.kycUrl);
        if (tx.depositInstructions) setDepositInstructions(tx.depositInstructions);
      }
    } catch {
      /* transient - leave the current data in place */
    } finally {
      setRefreshing(false);
    }
  }

  /** Back to the amount step. `keepMessage` carries the reason forward: when the
   *  user steps back because the amount missed a route's minimum, dropping the
   *  figure would leave them correcting it blind. A plain retry clears it. */
  function resetToInput({ keepMessage = false }: { keepMessage?: boolean } = {}) {
    setStep('input');
    setQuotes([]);
    setRequirementsRequired([]);
    setSelectedQuote(null);
    // Clear the collected provider fields (name/email/etc.) so a retry re-shows
    // the 'contact' step. Otherwise a stale (possibly invalid) value keeps the
    // field non-empty, `handleSelectQuote` treats it as complete, skips the step
    // and replays the same failing request.
    setFieldValues({});
    setWorkflow(null);
    workflowRef.current = null;
    setLegacySignature(undefined);
    setTxId(null);
    setProvider('');
    setKycUrl(null);
    setTosUrl(null);
    setTxStatus(null);
    setStellarTxHash(null);
    setDepositInstructions(null);
    setKycPending(false);
    setKycApproved(false);
    setNoticeMsg(null);
    if (!keepMessage) setErrorMsg(null);
  }

  /**
   * EXTERNAL wallets (Freighter/Albedo): the backend returns an unsigned XDR the
   * user must sign locally, then we resume the flow. `sep10` yields the anchor
   * session (kycUrl); `withdraw_payment` broadcasts the on-chain withdrawal.
   */
  async function resumeWithSignature(id: string, ps: NonNullable<RampResult['pendingSignature']>) {
    const outcome = await client.signTx(ps.unsignedXdr, { skipSponsorship: ps.action === 'sep10' });
    if (outcome.status !== 'signed') {
      setErrorMsg(outcome.message ?? outcome.details ?? 'Signing was cancelled.');
      setStep('error');
      return;
    }
    const result = (await client.submitRampSignature(id, {
      signedXdr: outcome.signedXdr,
      action: ps.action,
    })) as RampResult;
    await applyResult(result);
  }

  async function applyResult(result: RampResult) {
    const generic = result as RampResult & RampSnapshot;
    if (generic.transactionVersion !== undefined && !acceptWorkflow(generic)) return;
    setTxId(result.txId);
    setProvider(result.provider);
    setLegacySignature(result.pendingSignature);
    setKycUrl(result.kycUrl ?? null);
    setTosUrl(result.tosUrl ?? null);
    setOnboardingStatus(result.onboardingStatus);
    setKycPending(result.kycRequired === true);
    if (result.kycRequired) setKycApproved(false);
    setTxStatus(result.status);
    setStellarTxHash(result.stellarTxHash ?? null);
    setDepositInstructions(result.depositInstructions ?? null);
    setStep('status');
  }

  /**
   * Quote the current input. A route held back by a requirement step still counts as an answer:
   * it is shown locked, so "no providers" only means nothing came back at all.
   */
  async function loadQuotes(): Promise<boolean> {
    const result = await client.getRampsQuote({
      country,
      amount: Number(amount),
      amountExact: amount,
      currency,
      direction,
      ...(selectedRoute ? { routeId: selectedRoute.routeId, chain: selectedRoute.asset.chain } : {}),
    });
    const list = result.quotes ?? [];
    const locked = result.requirementsRequired ?? [];
    if (list.length === 0 && locked.length === 0) {
      // A provider that serves the route but is down is not "no providers".
      const down = (result.unavailable ?? []).map((u) => u.provider);
      setErrorMsg(
        down.length > 0
          ? `${down.join(', ')} ${down.length === 1 ? 'is' : 'are'} temporarily unavailable. Please try again later.`
          : `No ramp providers available for ${country} yet.`,
      );
      setStep('error');
      return false;
    }
    setQuotes(list);
    setRequirementsRequired(locked);
    return true;
  }

  async function handleFindRoute() {
    setStep('loading_quote');
    setIsLoading(true);
    setErrorMsg(null);
    try {
      if (!(await loadQuotes())) return;
      setStep('select_route');
    } catch (e) {
      setErrorMsg(rampErrorMessage(e, 'Failed to fetch quotes.'));
      setStep('error');
    } finally {
      setIsLoading(false);
    }
  }

  // Each quote declares the fields it needs (`requiredFields`). If any are unset,
  // collect them in the 'contact' step first; otherwise start immediately.
  function handleSelectQuote(quote: RampQuote) {
    setSelectedQuote(quote);
    setErrorMsg(null);
    setNoticeMsg(null);
    // The limits are per route, and the amount was typed before the routes were
    // known - so this is the first moment we can check it. Catching it here
    // states the figure without spending a round trip on a certain rejection.
    const broken = brokenLimitOf(Number(amount), quote);
    if (broken) {
      setErrorMsg(limitMessage(broken.limit, broken.value, currency));
      return;
    }
    const fields = requiredFieldsOf(quote);
    // An `optional` field left blank is not missing (Abroad's tax id) - it must
    // not drag the user into the details step on its own.
    const missing = fields.some((f) => !f.optional && !(fieldValues[f.key] ?? '').trim());
    if (fields.length > 0 && missing) {
      setStep('contact');
      return;
    }
    void startRamp(quote);
  }

  function handleContactContinue() {
    if (selectedQuote) void startRamp(selectedQuote);
  }

  async function startRamp(quote: RampQuote) {
    setIsLoading(true);
    setErrorMsg(null);
    try {
      const base: Record<string, unknown> = {
        quoteId: quote.quoteId,
        amount: quote.fiatAmount ?? Number(amount),
        ...(quote.terms ? { amountExact: quote.terms.fiatAmount } : {}),
        currency,
        country,
      };
      if (walletAddress) base.walletAddress = walletAddress;
      // Map each declared field to the request body: a field with `bankType`
      // becomes `bankDetails`; the standard body fields map by name; any other
      // provider-specific field (e.g. Stereum's bankCode / account holder) goes
      // into `fields`, which the backend reads per provider.
      const STANDARD_BODY_KEYS = new Set(['email', 'fullName', 'taxId', 'qrCode']);
      const extraFields: Record<string, string> = {};
      for (const f of requiredFieldsOf(quote)) {
        const val = (fieldValues[f.key] ?? '').trim();
        if (!val) continue;
        if (f.bankType) base.bankDetails = { type: f.bankType, value: val };
        else if (STANDARD_BODY_KEYS.has(f.key)) base[f.key] = val;
        else extraFields[f.key] = val;
      }
      if (quote.route)
        base.fields = Object.fromEntries(
          requiredFieldsOf(quote)
            .map((field) => [field.key, (fieldValues[field.key] ?? '').trim()])
            .filter(([, value]) => value),
        );
      else if (Object.keys(extraFields).length > 0) base.fields = extraFields;
      const result = (
        direction === 'onramp'
          ? await client.createOnRamp(base as RampsOnrampBody)
          : await client.createOffRamp(base as RampsOfframpBody)
      ) as RampResult;
      await applyResult(result);
    } catch (e) {
      const requirement = requiredRampKyc(e);
      if (requirement) {
        setStep(requiredFieldsOf(quote).length ? 'contact' : 'select_route');
        setErrorMsg(
          requirement.type === 'KYC'
            ? 'Identity verification is required before continuing.'
            : 'A few more details are required before continuing.',
        );
        kycAttempt.current = requirement;
        setPendingKyc(requirement);
        return;
      }
      setErrorMsg(rampErrorMessage(e, 'Failed to start the ramp.'));
      setStep('error');
    } finally {
      setIsLoading(false);
    }
  }

  /**
   * Back to the route list with fresh prices for the same input. A verification
   * takes minutes and quotes live about as long, so the one that hit the gate is
   * usually expired by now; the user picks again rather than an order starting on
   * a price they did not see.
   */
  async function requoteAfterKyc(completed: PendingRequirement['type'] = 'KYC') {
    setStep('loading_quote');
    setIsLoading(true);
    setErrorMsg(null);
    setSelectedQuote(null);
    try {
      if (!(await loadQuotes())) return;
      setNoticeMsg(
        completed === 'KYC'
          ? 'Your identity is verified. Prices may have changed, so choose a route to continue.'
          : 'Thanks, your details are saved. Prices may have changed, so choose a route to continue.',
      );
      setStep('select_route');
    } catch (e) {
      setErrorMsg(rampErrorMessage(e, 'Failed to fetch quotes.'));
      setStep('error');
    } finally {
      setIsLoading(false);
    }
  }

  /** Open the step a locked route names (KYC, form, registry check or registration); completing it re-quotes like the start gate does. */
  function handleVerifyRoute(requirement: RampQuoteRequirement) {
    const attempt = pendingFromQuote(requirement);
    setErrorMsg(null);
    setNoticeMsg(null);
    kycAttempt.current = attempt;
    setPendingKyc(attempt);
  }

  function handleOpenKyc() {
    if (kycUrl) window.open(kycUrl, '_blank', 'noopener,noreferrer');
  }

  function handleOpenTos() {
    if (tosUrl) window.open(tosUrl, '_blank', 'noopener,noreferrer');
  }

  async function handleLegacySignature() {
    if (!txId || !legacySignature || completionLocked.current) return;
    completionLocked.current = true;
    setCompleting(true);
    setErrorMsg(null);
    try {
      await resumeWithSignature(txId, legacySignature);
    } catch (e) {
      setErrorMsg(rampErrorMessage(e, 'Failed to submit the signature.'));
      setStep('error');
    } finally {
      completionLocked.current = false;
      setCompleting(false);
    }
  }

  async function handleCompleteWithdraw() {
    if (!txId || completionLocked.current) return;
    completionLocked.current = true;
    setCompleting(true);
    setErrorMsg(null);
    try {
      const result = (await client.completeWithdraw(txId)) as RampResult;
      if (result.pendingSignature) {
        await resumeWithSignature(txId, result.pendingSignature);
        return;
      }
      setTxStatus(result.status);
      setStellarTxHash(result.stellarTxHash ?? null);
    } catch (e) {
      const msg = e instanceof Error ? e.message : '';
      setErrorMsg(
        msg.includes('KYC') ? 'Finish KYC at the provider first, then try again.' : msg || 'Failed to complete the withdrawal.',
      );
    } finally {
      completionLocked.current = false;
      setCompleting(false);
    }
  }

  // A link-less KYC gate blocks the withdraw for good: the provider consumed the
  // quote when it answered `kycRequired`, so completing would either fail or -
  // worse - move real funds into a deposit it cannot pay out. Approval clears the
  // gate for the NEXT quote, not for this transaction, so `kycPending` (not
  // `kycBlocking`) is what keeps the button away.
  const kycBlocking = kycPending && !kycApproved;
  const canComplete =
    !workflow &&
    !legacySignature &&
    direction === 'offramp' &&
    step === 'status' &&
    txStatus !== 'completed' &&
    txStatus !== 'failed' &&
    !stellarTxHash &&
    !kycPending;

  const flowSteps = flowStepsOf(quotes, selectedQuote);
  const flowStepIndex = flowSteps.indexOf(STEP_LABEL[step] ?? '');

  // Keep this widget's state while a step is open so cancelling preserves the form.
  if (pendingKyc?.type === 'FORM') {
    return (
      <RequirementFormModal
        formId={pendingKyc.optionId}
        {...(pendingKyc.progress ? { progress: pendingKyc.progress } : {})}
        onClose={() => {
          kycAttempt.current = null;
          setPendingKyc(null);
        }}
        onSubmitted={() => {
          if (kycAttempt.current !== pendingKyc) return;
          kycAttempt.current = null;
          setPendingKyc(null);
          void requoteAfterKyc('FORM');
        }}
      />
    );
  }

  if (pendingKyc?.type === 'REGISTRY_CHECK' || pendingKyc?.type === 'PROVIDER_REGISTRATION') {
    const close = () => {
      kycAttempt.current = null;
      setPendingKyc(null);
    };
    const done = () => {
      if (kycAttempt.current !== pendingKyc) return;
      close();
      void requoteAfterKyc(pendingKyc.type);
    };
    const progress = pendingKyc.progress ? { progress: pendingKyc.progress } : {};
    return pendingKyc.type === 'REGISTRY_CHECK' ? (
      <RegistryCheckModal optionId={pendingKyc.optionId} {...progress} onClose={close} onApproved={done} />
    ) : (
      <ProviderRegistrationModal corridorId={pendingKyc.corridorId} {...progress} onClose={close} onRegistered={done} />
    );
  }

  if (pendingKyc) {
    return (
      <KycModal
        country={country}
        corridorId={pendingKyc.corridorId}
        providerId={pendingKyc.optionId}
        onClose={() => {
          kycAttempt.current = null;
          setPendingKyc(null);
        }}
        onApproved={() => {
          // Ignore duplicate approvals or polling that finishes after cancellation.
          if (kycAttempt.current !== pendingKyc) return;
          kycAttempt.current = null;
          setPendingKyc(null);
          void requoteAfterKyc();
        }}
      />
    );
  }

  return (
    <div className="pollar-overlay" style={overlayStyle} onClick={onClose}>
      <RampWidgetTemplate
        routeSelector={
          step === 'input' &&
          routes.length > 0 && (
            <label onClick={(e) => e.stopPropagation()}>
              Asset and payment route
              <select
                disabled={countriesLoading || refreshing}
                value={routeId}
                onChange={(e) => {
                  const route = routes.find((item) => item.routeId === e.target.value);
                  setRouteId(e.target.value);
                  if (route) {
                    setCountry(route.country);
                    setCurrency(route.fiatCurrency);
                    setDirection(route.direction);
                  }
                }}
              >
                <option value="">Choose a route</option>
                {routes.map((route) => (
                  <option key={route.routeId} value={route.routeId}>
                    {route.direction} · {route.fiatCurrency} / {route.asset.code} · {route.asset.chain} · {route.rail}
                  </option>
                ))}
              </select>
            </label>
          )
        }
        workflowContent={
          workflow ? (
            <RampWorkflow
              client={client}
              snapshot={workflow}
              onChange={(next) => {
                if (acceptWorkflow(next)) setTxStatus(next.status);
              }}
            />
          ) : legacySignature && step === 'status' && txStatus !== 'completed' && txStatus !== 'failed' ? (
            <button type="button" disabled={completing} onClick={() => void handleLegacySignature()}>
              Authorize wallet request
            </button>
          ) : undefined
        }
        theme={theme}
        accentColor={accentColor}
        styleOverrides={styleOverrides}
        step={step}
        flowSteps={flowSteps}
        flowStepIndex={flowStepIndex}
        startingQuoteId={isLoading && selectedQuote ? selectedQuote.quoteId : null}
        direction={direction}
        amount={amount}
        currency={currency}
        country={country}
        requiredFields={selectedQuote ? requiredFieldsOf(selectedQuote) : []}
        fieldValues={fieldValues}
        countries={countries}
        countriesLoading={countriesLoading}
        refreshing={refreshing}
        quotes={quotes}
        kycRequired={requirementsRequired}
        isLoading={isLoading}
        provider={provider}
        txStatus={txStatus}
        kycUrl={kycUrl}
        tosUrl={tosUrl}
        kycBlocking={kycBlocking}
        onboardingStatus={onboardingStatus ?? null}
        kycJustApproved={kycPending && kycApproved}
        stellarTxHash={stellarTxHash}
        explorerUrl={
          stellarTxHash
            ? `https://stellar.expert/explorer/${network === 'mainnet' ? 'public' : 'testnet'}/tx/${stellarTxHash}`
            : null
        }
        depositInstructions={depositInstructions}
        canComplete={canComplete}
        completing={completing}
        errorMsg={errorMsg}
        noticeMsg={noticeMsg}
        onDirectionChange={(next) => {
          setDirection(next);
          setRouteId('');
        }}
        onAmountChange={(next) => {
          // Editing the amount is the user acting on the limit message, so it
          // stops applying the moment they type.
          setAmount(next);
          setErrorMsg(null);
        }}
        onFieldChange={setFieldValue}
        onCountryChange={handleCountryChange}
        onFindRoute={handleFindRoute}
        onSelectQuote={handleSelectQuote}
        onVerifyRoute={handleVerifyRoute}
        onContactContinue={handleContactContinue}
        onOpenKyc={handleOpenKyc}
        onOpenTos={handleOpenTos}
        onCompleteWithdraw={handleCompleteWithdraw}
        onBack={() => resetToInput({ keepMessage: true })}
        onRetry={() => resetToInput()}
        onRefresh={handleRefresh}
        onClose={onClose}
      />
    </div>
  );
}

'use client';

import type {
  RampCountry,
  RampDepositInstructions,
  RampDirection,
  RampInstructionField,
  RampQuote,
  RampQuoteRequirement,
  RampScannable,
  RampTxStatus,
} from '@pollar/core';
import { LockedRouteDisplay, RouteDisplay } from './RouteDisplay';
import { CopyButton, PollarModalFooter } from '../commons';
import { buildModalCssVars, type ModalStyleOverrides } from '../modal-theme';

export type RampStep = 'input' | 'loading_quote' | 'select_route' | 'contact' | 'status' | 'error';

// Basic client-side email check so an invalid address never round-trips to the
// provider (which rejects it with a generic VALIDATION_ERROR).
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/**
 * A collected field is complete when it's non-empty and (for email) well-formed.
 * An `optional` field is complete while blank, but still has to be well-formed
 * once something is typed into it.
 */
function isFieldValid(spec: RampFieldSpec, raw: string | undefined): boolean {
  const value = (raw ?? '').trim();
  if (!value) return spec.optional === true;
  if (spec.type === 'email') return EMAIL_RE.test(value);
  return true;
}

/**
 * The `src` for a scannable that is not inline-safe. `encoding` and `inlineSafe`
 * are independent in the contract: an SVG a provider sent (so not inline-safe)
 * still arrives as `utf8`, and base64-wrapping that text yields a data URL the
 * browser cannot decode - a blank QR on the payment screen.
 */
function scannableImageSrc(image: RampScannable['image']): string {
  return image.encoding === 'base64'
    ? `data:${image.mediaType};base64,${image.data}`
    : `data:${image.mediaType};charset=utf-8,${encodeURIComponent(image.data)}`;
}

/** A field a provider declares (via the quote) that the client must collect. */
export interface RampFieldSpec {
  key: string;
  label: string;
  type: 'text' | 'email' | 'tel' | 'select';
  bankType?: string;
  /** For `type: 'select'` - dropdown choices (e.g. Stereum's Bolivian banks). */
  options?: { value: string; label: string; placeholder?: string }[];
  /** Declared but not mandatory (Abroad's tax id). Blank must not block Continue. */
  optional?: boolean;
  /** Example of the expected shape, for formats a user cannot guess. */
  placeholder?: string;
  /**
   * Key of a sibling `select` whose chosen option supplies the placeholder. One
   * Pix field can then show a CPF mask, an email or a +55 number as the user
   * switches kind, without this component knowing what a Pix key is.
   */
  placeholderFrom?: string;
  /** Secondary line under the field, for a rule the label has no room for. */
  hint?: string;
}

/** "a", "a and b", "a, b and c" - for naming what a step is asking for. */
function listOf(items: string[]): string {
  const last = items[items.length - 1];
  if (last === undefined) return 'a few details';
  if (items.length === 1) return last;
  return `${items.slice(0, -1).join(', ')} and ${last}`;
}

/** The placeholder to show: the one a sibling select dictates, else the static one. */
function placeholderFor(field: RampFieldSpec, fields: RampFieldSpec[], values: Record<string, string>): string | undefined {
  if (field.placeholderFrom) {
    const source = fields.find((f) => f.key === field.placeholderFrom);
    const chosen = source?.options?.find((o) => o.value === values[field.placeholderFrom as string]);
    if (chosen?.placeholder) return chosen.placeholder;
  }
  return field.placeholder;
}

interface RampWidgetTemplateProps {
  workflowContent?: React.ReactNode;
  routeSelector?: React.ReactNode;
  theme: string;
  accentColor: string;
  /** Per-app modal chrome overrides (background, card + button radius). */
  styleOverrides?: ModalStyleOverrides;
  step: RampStep;
  /** Labels of the steps this run goes through. Length varies by route: only
   *  providers that collect fields add a 'Details' step. */
  flowSteps: string[];
  /** Index into `flowSteps`, or -1 when the current step is outside the flow
   *  (the error step) and the progress bar should be hidden. */
  flowStepIndex: number;
  /** Quote whose start request is in flight, so its row can show it. */
  startingQuoteId: string | null;
  direction: RampDirection;
  amount: string;
  currency: string;
  country: string;
  requiredFields: RampFieldSpec[];
  fieldValues: Record<string, string>;
  countries: RampCountry[];
  countriesLoading: boolean;
  refreshing: boolean;
  quotes: RampQuote[];
  /** Routes not quoted until the user completes the requirement step their corridor names (KYC, form, registry check or provider registration). */
  kycRequired: RampQuoteRequirement[];
  isLoading: boolean;
  // status step
  provider: string;
  txStatus: RampTxStatus | null;
  kycUrl: string | null;
  tosUrl: string | null;
  /** Provider gated the flow on KYC and published no link; nothing was signed. */
  kycBlocking: boolean;
  /**
   * Which part of provider onboarding is outstanding, when any is. Optional
   * because this template is exported for integrators who render their own
   * chrome: a required prop would break every one of them on upgrade. Omitted,
   * the gate falls back to the identity-verification wording.
   */
  onboardingStatus?: 'kyc' | 'endorsement' | 'awaiting_provider' | null;
  /** The gate has since cleared - the user needs a fresh quote to continue. */
  kycJustApproved: boolean;
  stellarTxHash: string | null;
  /** Stellar Expert URL for `stellarTxHash` (network-aware); null when unknown. */
  explorerUrl: string | null;
  depositInstructions: RampDepositInstructions | null;
  canComplete: boolean;
  completing: boolean;
  errorMsg: string | null;
  /** Neutral guidance on the route list, e.g. after identity verification sent the user back to it. */
  noticeMsg?: string | null;
  onDirectionChange: (d: RampDirection) => void;
  onAmountChange: (v: string) => void;
  onFieldChange: (key: string, value: string) => void;
  onCountryChange: (v: string) => void;
  onFindRoute: () => void;
  onSelectQuote: (q: RampQuote) => void;
  onVerifyRoute: (requirement: RampQuoteRequirement) => void;
  onContactContinue: () => void;
  onOpenKyc: () => void;
  onOpenTos: () => void;
  onCompleteWithdraw: () => void;
  /** Step back to the amount, keeping what was entered. Distinct from `onRetry`
   *  (which restarts a failed flow) so a "Back" button reads as navigation. */
  onBack: () => void;
  onRetry: () => void;
  onRefresh: () => void;
  onClose: () => void;
}

const LOADING_STEPS = ['Detecting your country…', 'Consulting providers…', 'Route found!'];

/**
 * Flag emoji from a 2-letter ISO 3166-1 alpha-2 country code by mapping each
 * letter to its Regional Indicator Symbol code point (U+1F1E6 = 'A'). Returns an
 * empty string for anything that isn't a pair of ASCII letters.
 */
function flagEmoji(code: string): string {
  const cc = code.trim().toUpperCase();
  if (!/^[A-Z]{2}$/.test(cc)) return '';
  const base = 0x1f1e6;
  return String.fromCodePoint(base + (cc.charCodeAt(0) - 65), base + (cc.charCodeAt(1) - 65));
}

const STATUS_LABEL: Record<RampTxStatus, string> = {
  pending: 'Pending',
  processing: 'Processing',
  completed: 'Completed',
  failed: 'Failed',
};

/**
 * A timestamp field arrives as ISO-8601; render it in the viewer's locale.
 * Anything unparseable falls back to the raw string rather than showing
 * "Invalid Date".
 */
function displayValue(field: RampInstructionField): string {
  if (field.type !== 'datetime') return field.value;
  const at = new Date(field.value);
  return Number.isNaN(at.getTime()) ? field.value : at.toLocaleString();
}

export function RampWidgetTemplate({
  workflowContent,
  routeSelector,
  theme,
  accentColor,
  styleOverrides,
  step,
  flowSteps,
  flowStepIndex,
  startingQuoteId,
  direction,
  amount,
  currency,
  country,
  requiredFields,
  fieldValues,
  countries,
  countriesLoading,
  refreshing,
  quotes,
  kycRequired,
  isLoading,
  provider,
  txStatus,
  kycUrl,
  tosUrl,
  kycBlocking,
  onboardingStatus,
  kycJustApproved,
  stellarTxHash,
  explorerUrl,
  depositInstructions,
  canComplete,
  completing,
  errorMsg,
  noticeMsg,
  onDirectionChange,
  onAmountChange,
  onFieldChange,
  onCountryChange,
  onFindRoute,
  onSelectQuote,
  onVerifyRoute,
  onContactContinue,
  onOpenKyc,
  onOpenTos,
  onCompleteWithdraw,
  onBack,
  onRetry,
  onRefresh,
  onClose,
}: RampWidgetTemplateProps) {
  const cssVars = buildModalCssVars(theme, accentColor, styleOverrides, 'hero');

  const stepTitle: Record<RampStep, string> = {
    input: direction === 'onramp' ? 'Buy crypto' : 'Sell crypto',
    loading_quote: 'Finding best route',
    select_route: 'Select provider',
    contact: 'Your details',
    status: direction === 'onramp' ? 'Complete your deposit' : 'Complete your withdrawal',
    error: 'Something went wrong',
  };

  const stepSubtitle: Record<RampStep, string> = {
    input: direction === 'onramp' ? 'Enter the amount you want to deposit' : 'Enter the amount you want to withdraw',
    loading_quote: 'Comparing providers in real time…',
    select_route: 'All prices include fees',
    // What this step actually asks for is whatever the route declared, and that
    // is rarely a name and an email: an Abroad off-ramp asks where to send the
    // money, not who you are. Say which, rather than asserting the Bridge case
    // over every provider.
    contact: `${provider || 'This provider'} needs ${listOf(requiredFields.filter((f) => !f.optional).map((f) => f.label.toLowerCase()))} to continue`,
    status: `Finish the flow at ${provider || 'the provider'} to continue`,
    error: 'Please try again',
  };

  return (
    <div className="pollar-modal-card pollar-ramp-modal" style={cssVars} onClick={(e) => e.stopPropagation()}>
      <div className="pollar-modal-header">
        <div className="pollar-ramp-header-text">
          <h2 className="pollar-modal-title">{stepTitle[step]}</h2>
          <p className="pollar-ramp-subtitle">{stepSubtitle[step]}</p>
        </div>
        <div className="pollar-modal-header-actions">
          <button type="button" className="pollar-modal-close" onClick={onRefresh} disabled={refreshing} aria-label="Refresh">
            <svg
              className={refreshing ? 'pollar-modal-refresh-icon pollar-spinning' : 'pollar-modal-refresh-icon'}
              width="16"
              height="16"
              viewBox="0 0 16 16"
              fill="none"
              aria-hidden
            >
              <path
                d="M13.5 8a5.5 5.5 0 1 1-1.6-3.9M13.5 2v3h-3"
                stroke="currentColor"
                strokeWidth="1.6"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
          <button type="button" className="pollar-modal-close" onClick={onClose} aria-label="Close">
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
              <path d="M2 2l12 12M14 2L2 14" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
            </svg>
          </button>
        </div>
      </div>

      {/* How far along the run is. The segment count comes from the route, not
          from a constant: a provider that collects no fields genuinely has one
          step fewer. Hidden on the error step, which is not part of the flow. */}
      {flowStepIndex >= 0 && flowSteps.length > 0 && (
        <div className="pollar-ramp-steps">
          <span className="pollar-ramp-steps-label">
            Step {flowStepIndex + 1} of {flowSteps.length}
          </span>
          <div
            className="pollar-ramp-steps-track"
            role="progressbar"
            aria-valuenow={flowStepIndex + 1}
            aria-valuemin={1}
            aria-valuemax={flowSteps.length}
            aria-label={flowSteps[flowStepIndex]}
          >
            {flowSteps.map((label, i) => (
              <span key={label} className="pollar-ramp-steps-segment" data-done={i <= flowStepIndex || undefined} />
            ))}
          </div>
        </div>
      )}

      {step === 'input' && (
        <>
          <div className="pollar-tabs">
            <button
              type="button"
              className="pollar-tab"
              data-active={direction === 'onramp'}
              onClick={() => onDirectionChange('onramp')}
            >
              Buy
            </button>
            <button
              type="button"
              className="pollar-tab"
              data-active={direction === 'offramp'}
              onClick={() => onDirectionChange('offramp')}
            >
              Sell
            </button>
          </div>

          <div className="pollar-ramp-field">
            <label className="pollar-ramp-label">Country</label>
            {countriesLoading ? (
              <div className="pollar-ramp-input pollar-select-loading">
                <span className="pollar-spinner pollar-spinner-sm" />
                <span>Loading countries…</span>
              </div>
            ) : countries.length === 0 ? (
              <div className="pollar-modal-error">No ramp providers available on this network yet.</div>
            ) : (
              <select className="pollar-ramp-input" value={country} onChange={(e) => onCountryChange(e.target.value)}>
                {countries.map((c) => (
                  <option key={c.code} value={c.code}>
                    {flagEmoji(c.code)} {c.code}
                    {c.currency ? ` — ${c.currency}` : ''}
                  </option>
                ))}
              </select>
            )}
          </div>

          <div className="pollar-ramp-field">
            <label className="pollar-ramp-label">Amount{currency ? ` (${currency})` : ''}</label>
            <input
              type="number"
              className="pollar-ramp-input"
              placeholder="0.00"
              value={amount}
              min="0"
              onChange={(e) => onAmountChange(e.target.value)}
            />
            {/* Why the user was sent back here (e.g. the route's minimum), kept
                under the field they came to fix. Clears as soon as they type. */}
            {errorMsg && <span className="pollar-ramp-field-error">{errorMsg}</span>}
          </div>

          <div className="pollar-modal-actions">
            <button type="button" className="pollar-btn-secondary" onClick={onClose}>
              Cancel
            </button>
            <button
              type="button"
              className="pollar-btn-primary"
              disabled={!amount || isLoading || countriesLoading || countries.length === 0}
              onClick={onFindRoute}
            >
              Find best route
            </button>
          </div>
        </>
      )}

      {step === 'loading_quote' && (
        <div className="pollar-ramp-loading">
          <div className="pollar-spinner pollar-ramp-loading-spinner" />
          {LOADING_STEPS.map((text, i) => (
            <div key={i} className="pollar-ramp-loading-row">
              <div className="pollar-ramp-loading-dot" />
              <span>{text}</span>
            </div>
          ))}
        </div>
      )}

      {step === 'select_route' && (
        <>
          {noticeMsg && <p className="pollar-ramp-payment-note">{noticeMsg}</p>}
          <div className="pollar-ramp-route-list">
            {quotes.map((q, i) => (
              <RouteDisplay
                key={i}
                quote={q}
                busy={startingQuoteId != null && q.quoteId === startingQuoteId}
                disabled={startingQuoteId != null && q.quoteId !== startingQuoteId}
                onSelect={onSelectQuote}
              />
            ))}
            {kycRequired.map((r) => (
              <LockedRouteDisplay
                key={`${r.rampProviderId}:${r.corridorId}`}
                requirement={r}
                disabled={startingQuoteId != null}
                onVerify={onVerifyRoute}
              />
            ))}
          </div>
          {/* A route whose limits the amount breaks reports it here, so the user
              can pick another route or go back and edit - without leaving the
              list for the error step. */}
          {errorMsg && (
            <p className="pollar-ramp-payment-note" style={{ color: 'var(--pollar-error-text)' }}>
              {errorMsg}
            </p>
          )}
          {/* Back returns to the amount, which is the only way out of a route
              whose minimum the amount misses - so it takes the primary weight
              while that message is up. The header's X still closes the modal. */}
          <button type="button" className={errorMsg ? 'pollar-btn-primary' : 'pollar-btn-secondary'} onClick={onBack}>
            Back
          </button>
        </>
      )}

      {step === 'contact' && (
        <>
          {requiredFields.map((f) => (
            <div key={f.key} className="pollar-ramp-field">
              <label className="pollar-ramp-label">
                {f.label}
                {f.optional && <span className="pollar-ramp-field-optional"> (optional)</span>}
              </label>
              {f.type === 'select' ? (
                <select
                  className="pollar-ramp-input"
                  value={fieldValues[f.key] ?? ''}
                  onChange={(e) => onFieldChange(f.key, e.target.value)}
                >
                  <option value="" disabled>
                    Select…
                  </option>
                  {(f.options ?? []).map((o) => (
                    <option key={o.value} value={o.value}>
                      {o.label}
                    </option>
                  ))}
                </select>
              ) : (
                <input
                  type={f.type}
                  className="pollar-ramp-input"
                  value={fieldValues[f.key] ?? ''}
                  placeholder={placeholderFor(f, requiredFields, fieldValues)}
                  autoComplete={f.type === 'email' ? 'email' : 'off'}
                  onChange={(e) => onFieldChange(f.key, e.target.value)}
                />
              )}
              {f.hint && <span className="pollar-ramp-field-hint">{f.hint}</span>}
              {f.type === 'email' && (fieldValues[f.key] ?? '').trim() !== '' && !isFieldValid(f, fieldValues[f.key]) && (
                <span className="pollar-ramp-field-error">Enter a valid email address.</span>
              )}
            </div>
          ))}

          <div className="pollar-modal-actions">
            <button type="button" className="pollar-btn-secondary" onClick={onBack}>
              Back
            </button>
            <button
              type="button"
              className="pollar-btn-primary"
              disabled={requiredFields.some((f) => !isFieldValid(f, fieldValues[f.key])) || isLoading}
              onClick={onContactContinue}
            >
              {isLoading ? (
                <>
                  <span className="pollar-spinner pollar-spinner-sm" />
                  Starting…
                </>
              ) : (
                'Continue'
              )}
            </button>
          </div>
        </>
      )}

      {step === 'input' && routeSelector}
      {step === 'status' && workflowContent}
      {step === 'status' && !workflowContent && (
        <div className="pollar-ramp-payment">
          <div className="pollar-ramp-payment-field">
            <span className="pollar-ramp-payment-label">Provider</span>
            <div className="pollar-ramp-payment-value">
              <code>{provider}</code>
            </div>
          </div>

          <div className="pollar-ramp-payment-field">
            <span className="pollar-ramp-payment-label">Status</span>
            <div className="pollar-ramp-payment-value">
              <code style={{ color: txStatus === 'completed' ? 'var(--pollar-success-text)' : undefined }}>
                {txStatus ? STATUS_LABEL[txStatus] : 'Processing'}
              </code>
              {txStatus !== 'completed' && txStatus !== 'failed' && (
                <span className="pollar-spinner pollar-spinner-sm" aria-label="Checking status" />
              )}
            </div>
          </div>

          {stellarTxHash && (
            <div className="pollar-ramp-payment-field">
              <span className="pollar-ramp-payment-label">Stellar tx</span>
              <div className="pollar-ramp-payment-value" style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                <code style={{ flex: 1, wordBreak: 'break-all' }}>
                  {stellarTxHash.slice(0, 8)}…{stellarTxHash.slice(-8)}
                </code>
                <CopyButton value={stellarTxHash} label="Copy transaction hash" />
                {explorerUrl && (
                  <a
                    href={explorerUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="pollar-copy-btn"
                    aria-label="View on Stellar Expert"
                    title="View on Stellar Expert"
                  >
                    <svg width="13" height="13" viewBox="0 0 14 14" fill="none" aria-hidden>
                      <path
                        d="M6 3H3v8h8V8"
                        stroke="currentColor"
                        strokeWidth="1.5"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                      <path
                        d="M8.5 2.5h3v3M11 3L6.5 7.5"
                        stroke="currentColor"
                        strokeWidth="1.5"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                    </svg>
                  </a>
                )}
              </div>
            </div>
          )}

          {/* The code to scan. The server sends it rendered, so there is no QR
              library here and no per-provider branch: a Pollar-made SVG is
              inlined (it uses `currentColor`, so it follows the modal's theme),
              and a provider's own bitmap goes through an <img>. */}
          {depositInstructions?.scannable && txStatus !== 'completed' && (
            <div className="pollar-ramp-payment-field">
              <span className="pollar-ramp-payment-label">Payment QR</span>
              <div className="pollar-ramp-payment-value">
                {depositInstructions.scannable.image.inlineSafe ? (
                  <div
                    className="pollar-ramp-qr"
                    aria-label="Payment QR"
                    dangerouslySetInnerHTML={{ __html: depositInstructions.scannable.image.data }}
                  />
                ) : (
                  <img
                    src={scannableImageSrc(depositInstructions.scannable.image)}
                    alt="Payment QR"
                    style={{ width: '100%', maxWidth: 220, height: 'auto', display: 'block', margin: '0 auto' }}
                  />
                )}
              </div>
            </div>
          )}

          {/* The payload as text, when it is worth pasting. On the phone holding
              the screen there is nothing to scan, and a Pix code is designed to
              be pasted. The server decides by setting `payloadLabel`. */}
          {depositInstructions?.scannable?.payload &&
            depositInstructions.scannable.payloadLabel &&
            txStatus !== 'completed' && (
              <div className="pollar-ramp-payment-field">
                <span className="pollar-ramp-payment-label">{depositInstructions.scannable.payloadLabel}</span>
                <div className="pollar-ramp-payment-value">
                  <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                    <code style={{ flex: 1, wordBreak: 'break-all' }}>{depositInstructions.scannable.payload}</code>
                    <CopyButton
                      value={depositInstructions.scannable.payload}
                      label={`Copy ${depositInstructions.scannable.payloadLabel}`}
                    />
                  </span>
                </div>
              </div>
            )}

          {/* Everything else. Labelled and formatted server-side, so this only
              iterates - it knows nothing about which provider served the route. */}
          {depositInstructions &&
            txStatus !== 'completed' &&
            depositInstructions.fields.map((f) => (
              <div key={f.key} className="pollar-ramp-payment-field">
                <span className="pollar-ramp-payment-label">{f.label}</span>
                <div className="pollar-ramp-payment-value">
                  {f.copyable ? (
                    <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                      <code style={{ flex: 1, wordBreak: 'break-all' }}>{f.value}</code>
                      <CopyButton value={f.value} label={`Copy ${f.label}`} />
                    </span>
                  ) : f.type === 'url' ? (
                    <a href={f.value} target="_blank" rel="noopener noreferrer">
                      {f.value}
                    </a>
                  ) : (
                    <span>{displayValue(f)}</span>
                  )}
                </div>
              </div>
            ))}

          {/* KYC / ToS onboarding steps at the provider. Hidden once deposit
              instructions exist - by then onboarding is done and the only
              remaining action is to pay using the instructions above. */}
          {tosUrl && !depositInstructions && txStatus !== 'completed' && (
            <button type="button" className="pollar-btn-primary" onClick={onOpenTos}>
              Accept terms at {provider}
            </button>
          )}

          {kycUrl && !depositInstructions && txStatus !== 'completed' && (
            <button type="button" className="pollar-btn-primary" onClick={onOpenKyc}>
              Continue at {provider}
            </button>
          )}

          {/* Link-less gate: there is nowhere to send the user, so say what is
              blocking and keep the withdraw button out of reach. No funds have
              moved and nothing was signed.

              Two different situations reach this, and telling the user the wrong
              one is worse than saying nothing: `awaiting_provider` means their
              verification is already done and the provider is finishing its own
              setup, so asking them to "complete verification" sends them back
              through a flow that cannot change anything. */}
          {kycBlocking && onboardingStatus === 'awaiting_provider' && (
            <p className="pollar-ramp-payment-note">
              {provider} is still setting up your account for this payment method. Your verification is complete and there is
              nothing left for you to do — nothing has been sent, and this will update on its own once {provider} is ready.
            </p>
          )}

          {kycBlocking && onboardingStatus !== 'awaiting_provider' && (
            <p className="pollar-ramp-payment-note">
              {provider} needs to verify your identity before this payout. Nothing has been sent yet — complete verification
              with {provider}, and this will update on its own.
            </p>
          )}

          {/* Approval unblocks the next quote, not this one: the provider consumed
              this transaction's quote when it asked for KYC. So the withdraw stays
              out of reach and the only way forward is a fresh quote. */}
          {kycJustApproved && (
            <>
              <p className="pollar-ramp-payment-note">
                {provider} approved your verification. Request a new quote to continue — the previous one was consumed.
              </p>
              <button type="button" className="pollar-btn-primary" onClick={onRetry}>
                Request a new quote
              </button>
            </>
          )}

          {canComplete && (
            <button type="button" className="pollar-btn-primary" disabled={completing} onClick={onCompleteWithdraw}>
              {completing ? (
                <>
                  <span className="pollar-spinner pollar-spinner-sm" />
                  Submitting…
                </>
              ) : (
                "I've completed KYC — withdraw"
              )}
            </button>
          )}

          {errorMsg && (
            <p className="pollar-ramp-payment-note" style={{ color: 'var(--pollar-error-text)' }}>
              {errorMsg}
            </p>
          )}

          <button type="button" className="pollar-btn-secondary" onClick={onClose}>
            {txStatus === 'completed' ? 'Done' : 'Close'}
          </button>
        </div>
      )}

      {step === 'error' && (
        <div className="pollar-ramp-payment">
          <p className="pollar-ramp-payment-note" style={{ color: 'var(--pollar-error-text)' }}>
            {errorMsg ?? 'Unexpected error.'}
          </p>
          <div className="pollar-modal-actions">
            <button type="button" className="pollar-btn-secondary" onClick={onClose}>
              Close
            </button>
            <button type="button" className="pollar-btn-primary" onClick={onRetry}>
              Try again
            </button>
          </div>
        </div>
      )}
      <PollarModalFooter />
    </div>
  );
}

'use client';
import { describeRampAction, type PollarClient, type RampSnapshot } from '@pollar/core';
import { QRCode } from '../../lib/qr-code';
import { useState, useRef, useEffect } from 'react';
export function RampWorkflow({
  client,
  snapshot,
  onChange,
}: {
  client: PollarClient;
  snapshot: RampSnapshot;
  onChange: (next: RampSnapshot) => void;
}) {
  const model = describeRampAction(snapshot);
  const locked = useRef(false);
  useEffect(() => {
    setFields({});
  }, [model.action?.actionId]);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [fields, setFields] = useState<Record<string, string>>({});
  async function continueAction() {
    if (!model.action || locked.current) return;
    locked.current = true;
    setBusy(true);
    setError(null);
    try {
      onChange(
        model.canSign
          ? await client.signRampAction(snapshot.txId, snapshot)
          : await client.continueRamp(snapshot.txId, {
              actionId: model.action.actionId,
              transactionVersion: snapshot.transactionVersion!,
              ...(model.action.kind === 'collect_information' ? { fields } : {}),
            }),
      );
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Unable to continue.');
    } finally {
      locked.current = false;
      setBusy(false);
    }
  }
  return (
    <section aria-label="Ramp progress" aria-live="polite">
      <h3>{model.title}</h3>
      {snapshot.terms && (
        <p>
          {snapshot.terms.fiatAmount} {snapshot.terms.fiatCurrency} · {snapshot.terms.cryptoAmount} {snapshot.terms.assetCode}
          <br />
          Includes {snapshot.terms.feeAmount} {snapshot.terms.feeCurrency} fee
        </p>
      )}
      {model.details.map((item, index) => (
        <p key={index}>
          <strong>{item.label}: </strong>
          {item.value}
        </p>
      ))}
      {model.links.map((link, index) => (
        <p key={index}>
          <a href={link.url} target="_blank" rel="noopener noreferrer">
            {link.label}
          </a>
        </p>
      ))}
      {model.qr && <QRCode value={model.qr} size={180} />}
      {model.qr && (
        <button type="button" onClick={() => void navigator.clipboard.writeText(model.qr!)}>
          Copy payment code
        </button>
      )}
      {model.action?.kind === 'collect_information' &&
        model.action.fields.map((field) => (
          <label key={field.key}>
            {field.label}
            {field.optional ? ' (optional)' : ''}
            {field.type === 'select' ? (
              <select
                value={fields[field.key] ?? ''}
                onChange={(e) => setFields((previous) => ({ ...previous, [field.key]: e.target.value }))}
              >
                <option value="">Choose</option>
                {field.options?.map((option) => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
            ) : (
              <input
                type={field.type}
                placeholder={field.placeholder}
                value={fields[field.key] ?? ''}
                onChange={(e) => setFields((previous) => ({ ...previous, [field.key]: e.target.value }))}
              />
            )}
            {field.hint && <small>{field.hint}</small>}
          </label>
        ))}
      {(model.canContinue || model.canSign) && (
        <button type="button" disabled={busy} onClick={() => void continueAction()}>
          {model.canSign ? 'Authorize' : 'Continue'}
        </button>
      )}
      {snapshot.milestones?.map((milestone, index) => (
        <p key={index}>
          {milestone.kind.replace(/_/g, ' ')} · {milestone.verifiedAt}
        </p>
      ))}
      {error && <p role="alert">{error}</p>}
      <small>Reference: {snapshot.txId}</small>
    </section>
  );
}

'use client';

import type { RampQuote, RampQuoteRequirement } from '@pollar/core';
import { lockedRouteCopy } from './ramp-kyc';

interface RouteDisplayProps {
  quote: RampQuote;
  /** This route is the one being started - it owns the in-flight request. */
  busy?: boolean;
  /** Another route is starting, so this one is not selectable meanwhile. */
  disabled?: boolean;
  onSelect: (quote: RampQuote) => void;
}

const RAIL_LABELS: Record<string, string> = {
  SPEI: 'SPEI (Mexico)',
  PIX: 'PIX (Brazil)',
  PSE: 'PSE (Colombia)',
  ACH: 'ACH (US)',
};

export function RouteDisplay({ quote, busy = false, disabled = false, onSelect }: RouteDisplayProps) {
  // Picking a route fires a request that can take seconds (the provider is
  // contacted server-side). Without this the card looked inert and the only
  // hint that anything happened was the network tab.
  const inert = busy || disabled;
  const select = () => {
    if (!inert) onSelect(quote);
  };
  return (
    <div
      className="pollar-ramp-route-card"
      data-recommended={quote.recommended}
      data-busy={busy || undefined}
      data-disabled={disabled || undefined}
      role="button"
      aria-busy={busy}
      aria-disabled={inert}
      tabIndex={inert ? -1 : 0}
      onClick={select}
      onKeyDown={(e) => e.key === 'Enter' && select()}
    >
      <div className="pollar-ramp-route-left">
        <span className="pollar-ramp-route-provider">{quote.provider}</span>
        <span className="pollar-ramp-route-meta">
          {busy ? 'Starting…' : `${RAIL_LABELS[quote.rail] ?? quote.rail} · ${quote.protocol} · ${quote.estimatedTime}`}
        </span>
      </div>
      <div className="pollar-ramp-route-right">
        {busy ? (
          <span className="pollar-spinner pollar-spinner-sm" />
        ) : (
          <>
            <span className="pollar-ramp-route-fee">
              {quote.terms
                ? `${quote.terms.fiatAmount} ${quote.terms.fiatCurrency} · ${quote.terms.cryptoAmount} ${quote.terms.assetCode} · Includes ${quote.terms.feeAmount} ${quote.terms.feeCurrency}`
                : `${quote.fee}% fee`}
            </span>
            {quote.recommended && <span className="pollar-ramp-route-badge">Best rate</span>}
          </>
        )}
      </div>
    </div>
  );
}

interface LockedRouteDisplayProps {
  requirement: RampQuoteRequirement;
  /** A route is starting, so verification cannot be opened meanwhile. */
  disabled?: boolean;
  onVerify: (requirement: RampQuoteRequirement) => void;
}

/** A route the backend did not quote because its corridor has a requirement step the user has not completed. */
export function LockedRouteDisplay({ requirement, disabled = false, onVerify }: LockedRouteDisplayProps) {
  const { message, action } = lockedRouteCopy(requirement);
  return (
    <div
      className="pollar-ramp-route-card"
      data-locked
      data-kyc-status={requirement.status}
      data-disabled={disabled || undefined}
    >
      <div className="pollar-ramp-route-left">
        <span className="pollar-ramp-route-provider">{requirement.provider}</span>
        <span className="pollar-ramp-route-meta">{message}</span>
      </div>
      {action && (
        <div className="pollar-ramp-route-right">
          <button
            type="button"
            className="pollar-btn-secondary pollar-ramp-route-verify"
            disabled={disabled}
            onClick={() => onVerify(requirement)}
          >
            {action}
          </button>
        </div>
      )}
    </div>
  );
}

import type { RampQuoteRequirement } from '@pollar/core';
import { kycReviewMessage } from '../kyc-modal/kyc-messages';

/**
 * A requirement step the user must complete before a route: a KYC option, a form, a
 * registry option, or (for PROVIDER_REGISTRATION) the registration of `corridorId`.
 */
export type PendingRequirement = {
  rampProviderId: string;
  corridorId: string;
  type: 'KYC' | 'FORM' | 'REGISTRY_CHECK' | 'PROVIDER_REGISTRATION';
  optionId: string;
  /** Known when it comes from the quote; the start gate does not say. */
  progress?: { position: number; total: number };
};

const nonEmpty = (value: unknown): value is string => typeof value === 'string' && !!value.trim();

/**
 * The step the backend's start gate names, or null for any other error. v2 says
 * `requirementType` and `optionId`; a KYC-only body names the option as `kycProviderId`.
 */
export function requiredRampKyc(error: unknown): PendingRequirement | null {
  if (!error || typeof error !== 'object') return null;
  const { code, body } = error as { code?: unknown; body?: unknown };
  if (code !== 'SDK_RAMPS_KYC_REQUIRED' || !body || typeof body !== 'object') return null;
  const { rampProviderId, corridorId, requirementType, optionId, kycProviderId } = body as Record<string, unknown>;
  if (!nonEmpty(rampProviderId) || !nonEmpty(corridorId)) return null;
  if (
    (requirementType === 'FORM' || requirementType === 'REGISTRY_CHECK' || requirementType === 'PROVIDER_REGISTRATION') &&
    nonEmpty(optionId)
  ) {
    return { rampProviderId, corridorId, type: requirementType, optionId };
  }
  const kyc = nonEmpty(optionId) && requirementType === 'KYC' ? optionId : kycProviderId;
  return nonEmpty(kyc) ? { rampProviderId, corridorId, type: 'KYC', optionId: kyc } : null;
}

/** The step a locked route names in the quote. */
export function pendingFromQuote(requirement: RampQuoteRequirement): PendingRequirement {
  return {
    rampProviderId: requirement.rampProviderId,
    corridorId: requirement.corridorId,
    type: requirement.type,
    optionId: requirement.optionId,
    progress: { position: requirement.completed + 1, total: requirement.total },
  };
}

/**
 * What a route held back by a requirement step says, and the button it offers. A verification
 * held for review (`reviewReason`) or rejected has nothing the user can do from
 * here, so those rows carry no button.
 */
export function lockedRouteCopy(requirement: Pick<RampQuoteRequirement, 'status' | 'reviewReason'> & { type?: string }): {
  message: string;
  action: string | null;
} {
  if (requirement.type === 'FORM') return { message: 'Answer a few questions to see this route', action: 'Continue' };
  if (requirement.type === 'PROVIDER_REGISTRATION') {
    return { message: 'Register with the provider to see this route', action: 'Continue' };
  }
  if (requirement.type === 'REGISTRY_CHECK') {
    return requirement.status === 'pending'
      ? { message: 'Your details are under review', action: null }
      : { message: 'Confirm your details to see this route', action: 'Confirm' };
  }
  switch (requirement.status) {
    case 'expired':
      return { message: 'Your verification expired', action: 'Verify again' };
    case 'pending':
      if (!requirement.reviewReason) return { message: 'Verification in progress', action: 'Continue' };
      return {
        message:
          requirement.reviewReason === 'DUPLICATE_DOCUMENT'
            ? kycReviewMessage(requirement.reviewReason)
            : 'Your verification is under review',
        action: null,
      };
    case 'rejected':
      return { message: 'Verification was not approved', action: null };
    default:
      return { message: 'Verify your identity to see this route', action: 'Verify' };
  }
}

/* ---- Receive modal ---- */
.pollar-receive-modal {
  max-width: 400px;
