'use client';

import { WalletChain } from '@pollar/core';
import { useEffect, useRef, useState } from 'react';
import { usePollar } from '../../context';
import { walletNotReadyReason } from '../../lib/wallet-provisioning';
import { useChains } from '../../useChains';
import { addressForChain } from '../ChainSelect';
import '../shared.css';
import './ReceiveModal.css';
import { ReceiveModalTemplate } from './ReceiveModalTemplate';
import { modalChrome } from '../modal-theme';

interface ReceiveModalProps {
  onClose: () => void;
}

export function ReceiveModal({ onClose }: ReceiveModalProps) {
  const { wallet, wallets, styles } = usePollar();
  const { theme, accentColor, styleOverrides, overlayStyle } = modalChrome(styles);
  const [copied, setCopied] = useState(false);
  const copyTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const { chains } = useChains();
  const [selectedChain, setSelectedChain] = useState<WalletChain | null>(null);
  // Default to the app's first configured network. Runs as an effect because
  // `wallets` is empty on the first render of a cold-start session.
  useEffect(() => {
    if (selectedChain === null && chains.length > 0) setSelectedChain(chains[0]!);
  }, [chains, selectedChain]);

  const walletAddress = addressForChain(wallets, selectedChain);
  // The address is real, but until the account is on the ledger a payment to it
  // is rejected by the network. Handing someone a QR without saying so is the
  // one place this window can cost a user a failed transfer from a third party.
  const notReadyReason = walletNotReadyReason(wallet, selectedChain);

  useEffect(
    () => () => {
      if (copyTimerRef.current !== null) clearTimeout(copyTimerRef.current);
    },
    [],
  );

  function handleCopy() {
    if (!walletAddress) return;
    navigator.clipboard.writeText(walletAddress).then(() => {
      setCopied(true);
      if (copyTimerRef.current !== null) clearTimeout(copyTimerRef.current);
      copyTimerRef.current = setTimeout(() => {
        copyTimerRef.current = null;
        setCopied(false);
      }, 2000);
    });
  }

  return (
    <div className="pollar-overlay" style={overlayStyle} onClick={onClose}>
      <ReceiveModalTemplate
        theme={theme}
        accentColor={accentColor}
        styleOverrides={styleOverrides}
        walletAddress={walletAddress}
        chains={chains}
        selectedChain={selectedChain}
        // The tick belongs to the address that was copied, so switching
        // networks clears it rather than vouching for the new address.
        onSelectChain={(chain) => {
          setCopied(false);
          setSelectedChain(chain);
        }}
        notReadyReason={notReadyReason}
        copied={copied}
        onCopy={handleCopy}
        onClose={onClose}
      />
    </div>
  );
}

'use client';

import { WalletChain } from '@pollar/core';
import { QRCode } from '../../lib/qr-code';
import { ChainSelect } from '../ChainSelect';
import { PollarModalFooter } from '../commons';
import { PollarLogo } from '../PollarLogo';
import { buildModalCssVars, type ModalStyleOverrides } from '../modal-theme';

/** Network name as it reads in a sentence ("Share your Stellar address"). */
const CHAIN_NAME: Record<string, string> = {
  STELLAR: 'Stellar',
  POLYGON: 'Polygon',
  SOLANA: 'Solana',
};

export interface ReceiveModalTemplateProps {
  theme: string;
  accentColor: string;
  /** Per-app modal chrome overrides (background, card + button radius). */
  styleOverrides?: ModalStyleOverrides;
  /** Address of the wallet on {@link selectedChain}. */
  walletAddress: string;
  /**
   * The networks the user holds an address on, in the app's configured order.
   * The picker renders only with two or more, so a single-chain app shows none.
   */
  chains?: WalletChain[];
  selectedChain: WalletChain | null;
  onSelectChain?: (chain: WalletChain) => void;
  copied: boolean;
  /**
   * Why the wallet cannot receive yet (its Stellar account is still being
   * created, or its creation failed), or null when it can.
   *
   * The address itself is valid either way - what is missing is the account
   * behind it, so a payment sent now is rejected by the network. Optional, so a
   * custom template written before this existed keeps compiling.
   */
  notReadyReason?: string | null;
  onCopy: () => void;
  onClose: () => void;
}

export function ReceiveModalTemplate({
  theme,
  accentColor,
  styleOverrides,
  walletAddress,
  chains,
  selectedChain,
  onSelectChain,
  copied,
  notReadyReason,
  onCopy,
  onClose,
}: ReceiveModalTemplateProps) {
  const cssVars = buildModalCssVars(theme, accentColor, styleOverrides);

  const chainName = selectedChain ? (CHAIN_NAME[selectedChain] ?? selectedChain) : 'wallet';

  return (
    <div
      className="pollar-modal-card pollar-receive-modal"
      data-theme={theme}
      style={cssVars}
      onClick={(e) => e.stopPropagation()}
    >
      {/* Header */}
      <div className="pollar-modal-header">
        <h2 className="pollar-modal-title">Receive</h2>
        <div className="pollar-modal-header-actions">
          <button type="button" className="pollar-modal-close" onClick={onClose} aria-label="Close">
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
              <path d="M2 2l12 12M14 2L2 14" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
            </svg>
          </button>
        </div>
      </div>

      {/* Network selector - drives the address and QR below */}
      {chains && onSelectChain && <ChainSelect value={selectedChain} options={chains} onChange={onSelectChain} />}

      {/* QR code */}
      {walletAddress ? (
        <>
          <div className="pollar-receive-qr">
            <div className="pollar-receive-network-badge">
              <span className="pollar-receive-network-dot" aria-hidden />
              {chainName} network
            </div>
            <div className="pollar-receive-qr-frame">
              <QRCode
                value={walletAddress}
                size={220}
                level="H"
                fgColor="#111827"
                bgColor="#ffffff"
                title={`${chainName} wallet QR code`}
              />
              <span className="pollar-receive-qr-mark" aria-hidden>
                <PollarLogo width="22" height="24" />
              </span>
            </div>
          </div>

          {notReadyReason && <div className="pollar-receive-notice">{notReadyReason}</div>}

          {/* Address + copy */}
          <div className="pollar-receive-address-actions">
            <div className="pollar-receive-address-row">
              <span className="pollar-receive-address">{walletAddress}</span>
            </div>
            <button type="button" className="pollar-receive-copy-btn" onClick={onCopy} aria-label="Copy address">
              {copied ? (
                <>
                  <svg width="13" height="13" viewBox="0 0 14 14" fill="none" aria-hidden>
                    <circle cx="7" cy="7" r="7" fill="currentColor" />
                    <path
                      d="M3.5 7l2.5 2.5 4.5-5"
                      stroke="white"
                      strokeWidth="1.5"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                  Copied
                </>
              ) : (
                <>
                  <svg width="13" height="13" viewBox="0 0 13 13" fill="none" aria-hidden>
                    <rect x="4" y="4" width="8" height="8" rx="1.5" stroke="currentColor" strokeWidth="1.5" />
                    <path
                      d="M3 9H2a1 1 0 01-1-1V2a1 1 0 011-1h6a1 1 0 011 1v1"
                      stroke="currentColor"
                      strokeWidth="1.5"
                      strokeLinecap="round"
                    />
                  </svg>
                  Copy
                </>
              )}
            </button>
          </div>
          <p className="pollar-receive-warning">
            <svg width="14" height="14" viewBox="0 0 14 14" fill="none" aria-hidden>
              <circle cx="7" cy="7" r="5.5" stroke="currentColor" strokeWidth="1.25" />
              <path d="M7 6.25V9.25M7 4.5V4.75" stroke="currentColor" strokeWidth="1.25" strokeLinecap="round" />
            </svg>
            <span>Only send {chainName} assets to this address</span>
          </p>
        </>
      ) : (
        <div className="pollar-modal-empty">No wallet connected.</div>
      )}

      <PollarModalFooter shield />
    </div>
  );
}

'use client';

import type { RegistryCheck, RegistryCheckPrefill } from '@pollar/core';
import { useEffect, useMemo, useRef, useState } from 'react';
import { usePollar } from '../../context';
import { PollarModalFooter } from '../commons';
import { buildModalCssVars, modalChrome } from '../modal-theme';
import { formLanguage } from '../requirement-form-modal/form-fields';
import { errorCode, REGISTRY_COPY } from './registry-copy';
import '../shared.css';
import '../requirement-form-modal/RequirementFormModal.css';

interface RegistryCheckModalProps {
  optionId: string;
  /** Position of this step over the route's steps, when known. */
  progress?: { position: number; total: number };
  onClose: () => void;
  /** Called once the registry confirmed the data. */
  onApproved: () => void;
}

/**
 * One REGISTRY_CHECK step (SEGIP): the user's verified data, prefilled and read-only
 * except for the surname split and the CI complement, sent to the registry on confirm.
 */
export function RegistryCheckModal({ optionId, progress, onClose, onApproved }: RegistryCheckModalProps) {
  const { getClient, styles } = usePollar();
  const client = getClient();
  const { theme, accentColor, styleOverrides, overlayStyle } = modalChrome(styles);
  const cssVars = buildModalCssVars(theme, accentColor, styleOverrides, 'hero');
  const language = useMemo(formLanguage, []);
  const copy = REGISTRY_COPY[language];

  const [check, setCheck] = useState<RegistryCheck | null>(null);
  const [surname1, setSurname1] = useState('');
  const [surname2, setSurname2] = useState('');
  const [complement, setComplement] = useState('');
  const [error, setError] = useState<string | null>(null);
  /** Fields the registry did not confirm on the last check, outlined until the next try. */
  const [rejected, setRejected] = useState<string[]>([]);
  const [review, setReview] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const mounted = useRef(true);
  useEffect(() => {
    // Set on every mount: development mounts components twice, and the cleanup of the
    // first mount would otherwise leave this false and drop every response.
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  useEffect(() => {
    client
      .getRegistryCheck(optionId)
      .then((loaded) => {
        if (!mounted.current) return;
        if (loaded.status === 'approved') return onApproved();
        setCheck(loaded);
        if (loaded.status === 'pending') setReview(true);
        // A check the registry did not confirm on the surnames or the complement: say which, keep the form open.
        if (loaded.status === 'rejected') showRejected(loaded.rejectedFields);
        if (loaded.prefill.applies) {
          setSurname1(loaded.prefill.surname1);
          setSurname2(loaded.prefill.surname2 ?? '');
          setComplement(loaded.prefill.complementNumber ?? '');
        }
      })
      .catch((e: unknown) => {
        if (!mounted.current) return;
        setError(errorCode(e) === 'KYC_REGISTRY_IDENTITY_REQUIRED' ? copy.identityRequired : copy.loadError);
      });
    // The client instance and the copy do not change while the modal is open.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [optionId]);

  const prefill: RegistryCheckPrefill | null = check?.prefill.applies ? check.prefill : null;

  /** Say which fields the registry did not confirm and outline them; the form stays open. */
  function showRejected(fields: string[] | undefined) {
    const labels: Record<string, string> = {
      surname1: copy.surname1,
      surname2: copy.surname2,
      complementNumber: copy.complement,
    };
    const named = fields?.length ? fields : ['surname2'];
    setRejected(named);
    setError(copy.rejected.replace('{fields}', named.map((field) => labels[field] ?? field).join(', ')));
  }

  async function submit() {
    if (!prefill) return;
    setSubmitting(true);
    setError(null);
    setRejected([]);
    try {
      const result = await client.submitRegistryCheck(optionId, {
        surname1: surname1.trim(),
        ...(surname2.trim() ? { surname2: surname2.trim() } : {}),
        ...(complement.trim() ? { complementNumber: complement.trim() } : {}),
      });
      if (!mounted.current) return;
      if (result.status === 'approved') onApproved();
      else if (result.status === 'rejected') showRejected(result.rejectedFields);
      else setReview(true);
    } catch (e) {
      if (!mounted.current) return;
      const code = errorCode(e);
      // A check recorded while this screen was open (a slow answer the client gave up on) is the approval.
      if (code === 'SDK_KYC_ALREADY_APPROVED') return onApproved();
      if (code === 'KYC_REGISTRY_NAME_MISMATCH') {
        setError(copy.nameMismatch.replace('{full}', [prefill.surname1, prefill.surname2].filter(Boolean).join(' ')));
      } else if (code === 'SDK_KYC_UNDER_REVIEW') setReview(true);
      else setError(copy.submitError);
    } finally {
      if (mounted.current) setSubmitting(false);
    }
  }

  const readOnly = (label: string, value: string) => (
    <div className="pollar-form-field">
      <span className="pollar-form-label">{label}</span>
      <input className="pollar-input" value={value} readOnly disabled />
    </div>
  );

  return (
    <div className="pollar-overlay" style={overlayStyle} onClick={onClose}>
      <div
        className="pollar-modal-card pollar-form-modal"
        role="dialog"
        aria-modal="true"
        aria-label={copy.title}
        style={cssVars}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="pollar-modal-header">
          <div className="pollar-form-header-text">
            <h2 className="pollar-modal-title">{copy.title}</h2>
            {progress && (
              <p className="pollar-form-subtitle">
                {copy.step.replace('{n}', String(progress.position)).replace('{total}', String(progress.total))}
              </p>
            )}
          </div>
          <button type="button" className="pollar-modal-close" onClick={onClose} aria-label={copy.close}>
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
              <path d="M2 2l12 12M14 2L2 14" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
            </svg>
          </button>
        </div>

        {error && (
          <p className="pollar-form-error" role="alert">
            {error}
          </p>
        )}

        {!check && !error && (
          <div className="pollar-loading-block">
            <div className="pollar-spinner" />
          </div>
        )}

        {check && (review || !prefill) && (
          <div className="pollar-form-body">
            <p className="pollar-form-error" role="status">
              {review ? copy.review : copy.notApplicable}
            </p>
            <div className="pollar-modal-actions">
              <button type="button" className="pollar-btn-secondary" onClick={onClose}>
                {copy.close}
              </button>
            </div>
          </div>
        )}

        {prefill && !review && (
          <form
            className="pollar-form-body"
            onSubmit={(e) => {
              e.preventDefault();
              void submit();
            }}
          >
            <p className="pollar-form-description">{copy.intro}</p>
            {readOnly(copy.givenNames, prefill.givenNames)}
            <div className="pollar-form-field">
              <label htmlFor="pollar-registry-surname1" className="pollar-form-label">
                {copy.surname1}
                <span className="pollar-form-required"> *</span>
              </label>
              <input
                id="pollar-registry-surname1"
                className="pollar-input"
                value={surname1}
                required
                disabled={submitting}
                aria-invalid={rejected.includes('surname1') || undefined}
                onChange={(e) => setSurname1(e.target.value)}
              />
            </div>
            <div className="pollar-form-field">
              <label htmlFor="pollar-registry-surname2" className="pollar-form-label">
                {copy.surname2}
              </label>
              <input
                id="pollar-registry-surname2"
                className="pollar-input"
                value={surname2}
                disabled={submitting}
                aria-invalid={rejected.includes('surname2') || undefined}
                onChange={(e) => setSurname2(e.target.value)}
              />
            </div>
            {readOnly(copy.birthdate, prefill.birthdate)}
            {readOnly(copy.documentNumber, prefill.documentNumber)}
            <div className="pollar-form-field">
              <label htmlFor="pollar-registry-complement" className="pollar-form-label">
                {copy.complement}
              </label>
              <input
                id="pollar-registry-complement"
                className="pollar-input"
                value={complement}
                maxLength={3}
                disabled={submitting}
                aria-invalid={rejected.includes('complementNumber') || undefined}
                onChange={(e) => setComplement(e.target.value.toUpperCase().replace(/[^0-9A-Z]/g, ''))}
              />
            </div>
            <div className="pollar-modal-actions">
              <button type="button" className="pollar-btn-secondary" onClick={onClose} disabled={submitting}>
                {copy.close}
              </button>
              <button type="submit" className="pollar-btn-primary" disabled={submitting || !surname1.trim()}>
                {submitting ? copy.submitting : copy.submit}
              </button>
            </div>
          </form>
        )}
        <PollarModalFooter />
      </div>
    </div>
  );
}

