  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

/* ---- Available balance hint ---- */
.pollar-send-hint {
  font-size: 0.75rem;
  color: var(--pollar-muted);
  text-align: right;
  white-space: nowrap;
}

