.pollar-send-asset-picker {
  position: relative;
}

.pollar-send-asset-selector {
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 68px;
  padding: 0.75rem 0.875rem;
  gap: 0.75rem;
  border: 1px solid var(--pollar-border);
