'use client';

import { toBaseUnits, WalletBalanceRecord, WalletChain } from '@pollar/core';
import { useEffect, useRef, useState } from 'react';
import { usePollar } from '../../context';
import { walletNotReadyReason } from '../../lib/wallet-provisioning';
import { useChains } from '../../useChains';
import { resolveChain } from '../ChainSelect';
import '../shared.css';
import '../transaction-modal/TransactionModal.css';
import './SendModal.css';
import { SendModalTemplate } from './SendModalTemplate';
import { modalChrome } from '../modal-theme';

interface SendModalProps {
  onClose: () => void;
}

function assetParam(record: WalletBalanceRecord) {
  if (record.type === 'native') return { type: 'native' as const };
  if (record.type === 'credit_alphanum4') {
    return { type: 'credit_alphanum4' as const, code: record.code, issuer: record.issuer! };
  }
  return { type: 'credit_alphanum12' as const, code: record.code, issuer: record.issuer! };
}

export function SendModal({ onClose }: SendModalProps) {
  const {
    walletBalance,
    refreshWalletBalance,
    buildTx,
    sendPayment,
    signAndSubmitTx,
    tx: transaction,
    wallet,
    network,
    styles,
  } = usePollar();
  // External-wallet signing-adapter id (freighter/albedo) drives the wallet logo;
  // null for embedded/smart, which fall back to the Pollar logo.
  const walletType = wallet?.custody === 'external' ? wallet.provider : null;
  const { theme, accentColor, styleOverrides, overlayStyle } = modalChrome(styles);

  const [step, setStep] = useState<'form' | 'tx'>('form');
  const [amount, setAmount] = useState('');
  const [destination, setDestination] = useState('');
  const [selectedAsset, setSelectedAsset] = useState<WalletBalanceRecord | null>(null);
  const [showXdr, setShowXdr] = useState(false);
  const [copied, setCopied] = useState(false);
  const [formError, setFormError] = useState('');
  const copyTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const { chains } = useChains();
  const [selectedChain, setSelectedChain] = useState<WalletChain | null>(null);
  // Default to the app's first configured network. Runs as an effect because
  // `wallets` is empty on the first render of a cold-start session.
  useEffect(() => {
    if (selectedChain === null && chains.length > 0) setSelectedChain(chains[0]!);
  }, [chains, selectedChain]);

  // Solana joined Stellar via the atomic endpoint; Polygon has no transfer path
  // in the backend yet, so it can be browsed but not sent from.
  const canSendOnChain = selectedChain === 'STELLAR' || selectedChain === 'SOLANA';
  // A Stellar account still being created cannot source a payment: every
  // operation would come back `op_no_source_account`. The server refuses these
  // with SDK_WALLET_NOT_READY anyway - saying so here turns that into something
  // the user can act on (wait) instead of a failed transaction.
  const notReadyReason = walletNotReadyReason(wallet, selectedChain);
  // Solana amounts are integer base units (lamports / mint units), not decimals.
  const isBaseUnitChain = selectedChain === 'SOLANA';

  useEffect(() => {
    void refreshWalletBalance();
  }, [refreshWalletBalance]);

  useEffect(
    () => () => {
      if (copyTimerRef.current !== null) clearTimeout(copyTimerRef.current);
    },
    [],
  );

  const balanceData = walletBalance.step === 'loaded' ? walletBalance.data : null;
  // Only the picked network's assets. The backend returns every chain in one
  // payload, so this is a local filter - switching networks costs no request.
  const allAssets = (balanceData?.balances ?? []).filter((b) => resolveChain(b.chain) === selectedChain);
  // App assets first, then native XLM (always, even at 0, so the user knows to
  // fund) and any other non-app asset the wallet actually holds.
  const sortedAssets = [
    ...allAssets.filter((b) => b.enabledInApp),
    // An unreadable balance (null) is not a positive one, so it stays out.
    ...allAssets.filter((b) => !b.enabledInApp && (b.type === 'native' || parseFloat(b.balance ?? '0') > 0)),
  ];

  // Auto-select the first asset once balances load (no "Select asset" step).
  // Switching networks strands the previous chain's asset, so it is dropped and
  // re-picked here rather than leaving a selection the form can't spend.
  useEffect(() => {
    const stranded = selectedAsset !== null && resolveChain(selectedAsset.chain) !== selectedChain;
    if (stranded) {
      setSelectedAsset(sortedAssets[0] ?? null);
      return;
    }
    if (!selectedAsset && sortedAssets.length > 0) setSelectedAsset(sortedAssets[0]!);
  }, [sortedAssets, selectedAsset, selectedChain]);

  const hash = transaction.step === 'success' ? transaction.hash : null;
  const buildData = 'buildData' in transaction ? transaction.buildData : null;
  const explorerNetwork = buildData?.summary.network?.toLowerCase().includes('testnet')
    ? 'testnet'
    : buildData
      ? 'public'
      : network === 'testnet'
        ? 'testnet'
        : 'public';
  // Each chain has its own explorer, and its own way of saying "testnet".
  const explorerUrl = !hash
    ? null
    : selectedChain === 'SOLANA'
      ? `https://explorer.solana.com/tx/${hash}${explorerNetwork === 'testnet' ? '?cluster=devnet' : ''}`
      : `https://stellar.expert/explorer/${explorerNetwork}/tx/${hash}`;

  const IN_FLIGHT_STEPS = [
    'building',
    'signing',
    'submitting',
    'submitted',
    'signing-submitting',
    'building-signing-submitting',
  ] as const;
  const isInProgress = (IN_FLIGHT_STEPS as readonly string[]).includes(transaction.step);
  const showBack = step === 'tx' && (transaction.step === 'error' || transaction.step === 'success') && !isInProgress;

  const txTitle = isInProgress
    ? 'Sending…'
    : transaction.step === 'success'
      ? 'Sent!'
      : transaction.step === 'error'
        ? 'Send failed'
        : 'Confirm Send';

  async function handleSubmit() {
    setFormError('');
    if (!canSendOnChain) {
      setFormError('Sending is not available on this network yet.');
      return;
    }
    if (notReadyReason) {
      setFormError(notReadyReason);
      return;
    }
    if (!selectedAsset) {
      setFormError('Select an asset');
      return;
    }
    const parsed = parseFloat(amount);
    if (!amount || isNaN(parsed) || parsed <= 0) {
      setFormError('Enter a valid amount');
      return;
    }
    // A null `available` means the chain could not be read, so it floors to 0 and
    // blocks the send: never let an unreadable balance pass as "enough".
    if (parsed > parseFloat(selectedAsset.available ?? '0')) {
      setFormError('Insufficient balance');
      return;
    }
    if (!destination.trim()) {
      setFormError('Enter a destination address');
      return;
    }

    // A non-native asset needs BOTH its mint (carried in `issuer`) and its own
    // `decimals`, and neither has a safe default: without the mint the payload
    // below drops to a native transfer, so a USDC send would move SOL instead,
    // and the 9-decimal fallback would multiply a 6-decimal token by 1000. The
    // backend always sends both, so this only fires on malformed data - but it
    // fails the send rather than sending the wrong thing.
    const isNativeAsset = selectedAsset.type === 'native';
    if (isBaseUnitChain && !isNativeAsset && (!selectedAsset.issuer || selectedAsset.decimals === undefined)) {
      setFormError('This token is missing its mint or decimals and cannot be sent.');
      return;
    }

    // Solana takes integer base units while the form (like the balance above it)
    // is in decimals, so convert before sending - with the asset's own decimals,
    // and via strings so a 9-decimal amount is not rounded by a float. The
    // fallback is native SOL's 9, reached only on the native row (the guard above
    // rejects any other asset that lacks `decimals`).
    let sendAmount = amount;
    if (isBaseUnitChain) {
      try {
        sendAmount = toBaseUnits(amount, selectedAsset.decimals ?? 9);
      } catch (e) {
        setFormError(e instanceof Error ? e.message : 'Invalid amount');
        return;
      }
    }

    setStep('tx');

    if (selectedChain === 'SOLANA') {
      await sendPayment({
        chain: 'SOLANA',
        destination: destination.trim(),
        amount: sendAmount,
        // Native SOL carries no mint; an SPL token's mint rides in `issuer`,
        // which the guard above proved is present.
        ...(isNativeAsset ? {} : { mint: selectedAsset.issuer }),
      });
      return;
    }

    await buildTx('payment', { destination: destination.trim(), amount, asset: assetParam(selectedAsset) });
  }

  function handleSignAndSend() {
    if (transaction.step === 'built') {
      void signAndSubmitTx(transaction.buildData.unsignedXdr);
    }
  }

  function handleMax() {
    if (selectedAsset?.available !== null && selectedAsset?.available !== undefined) {
      setAmount(selectedAsset.available);
      setFormError('');
    }
  }

  async function handlePaste() {
    if (!navigator.clipboard?.readText) {
      setFormError('Clipboard access is not available. Paste the address manually.');
      return;
    }

    try {
      const value = (await navigator.clipboard.readText()).trim();
      if (!value) {
        setFormError('The clipboard is empty.');
        return;
      }
      setDestination(value);
      setFormError('');
    } catch {
      setFormError('Could not read the clipboard. Paste the address manually.');
    }
  }

  function handleCopyHash() {
    if (!hash) return;
    navigator.clipboard.writeText(hash).then(() => {
      setCopied(true);
      if (copyTimerRef.current !== null) clearTimeout(copyTimerRef.current);
      copyTimerRef.current = setTimeout(() => {
        copyTimerRef.current = null;
        setCopied(false);
      }, 2000);
    });
  }

  async function handleRetry() {
    if (transaction.step === 'error' && transaction.buildData) {
      await signAndSubmitTx(transaction.buildData.unsignedXdr);
    }
  }

  function handleBack() {
    setStep('form');
    setShowXdr(false);
    setCopied(false);
  }

  return (
    <div className="pollar-overlay" style={overlayStyle} onClick={!isInProgress ? onClose : undefined}>
      <SendModalTemplate
        theme={theme}
        accentColor={accentColor}
        styleOverrides={styleOverrides}
        step={step}
        txTitle={txTitle}
        assets={sortedAssets}
        selectedAsset={selectedAsset}
        chains={chains}
        selectedChain={selectedChain}
        canSendOnChain={canSendOnChain}
        notReadyReason={notReadyReason}
        onSelectChain={setSelectedChain}
        amount={amount}
        destination={destination}
        formError={formError}
        isLoadingBalance={walletBalance.step === 'loading'}
        transaction={transaction}
        showXdr={showXdr}
        copied={copied}
        explorerUrl={explorerUrl}
        walletType={walletType}
        showBack={showBack}
        isInProgress={isInProgress}
        onClose={onClose}
        onBack={handleBack}
        onRefresh={() => void refreshWalletBalance()}
        onSelectAsset={setSelectedAsset}
        onAmountChange={setAmount}
        onMax={handleMax}
        onPaste={handlePaste}
        onDestinationChange={setDestination}
        onSubmit={() => void handleSubmit()}
        onSignAndSend={handleSignAndSend}
        onToggleXdr={() => setShowXdr((v) => !v)}
        onCopyHash={handleCopyHash}
        onRetry={() => void handleRetry()}
        onDone={onClose}
      />
    </div>
  );
}

'use client';

import { TransactionState, WalletBalanceRecord, WalletChain, WalletId } from '@pollar/core';
import { useEffect, useRef, useState, type KeyboardEvent } from 'react';
import { ChainSelect } from '../ChainSelect';
import { PollarModalFooter, RefreshIcon } from '../commons';
import { TxStatusView } from '../transaction-modal/TxStatusView';
import { buildModalCssVars, type ModalStyleOverrides } from '../modal-theme';

// A null balance means the chain could not be read; it shows as a dash rather
// than as 0, so an unreadable wallet never looks empty.
function formatBalance(balance: string | null): string {
  if (balance === null) return '—';
  const n = parseFloat(balance);
  return isNaN(n) ? balance : n.toLocaleString(undefined, { maximumFractionDigits: 7 });
}

function assetKey(record: WalletBalanceRecord): string {
  return `${record.code}:${record.issuer ?? 'native'}`;
}

function chainLabel(chain: WalletChain | null): string {
  if (chain === 'STELLAR') return 'Stellar';
  if (chain === 'SOLANA') return 'Solana';
  if (chain === 'POLYGON') return 'Polygon';
  return 'network';
}

function AssetIcon({ code }: { code: string }) {
  return (
    <span className="pollar-send-asset-icon" aria-hidden>
      {code.slice(0, 2).toUpperCase()}
    </span>
  );
}

interface SendAssetSelectorProps {
  assets: WalletBalanceRecord[];
  selectedAsset: WalletBalanceRecord | null;
  loading: boolean;
  onSelectAsset: (asset: WalletBalanceRecord) => void;
}

function SendAssetSelector({ assets, selectedAsset, loading, onSelectAsset }: SendAssetSelectorProps) {
  const [open, setOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!open) return;
    const closeOnOutsideClick = (event: MouseEvent) => {
      if (!(event.target instanceof Node) || !triggerRef.current?.parentElement?.contains(event.target)) setOpen(false);
    };
    document.addEventListener('mousedown', closeOnOutsideClick);
    return () => document.removeEventListener('mousedown', closeOnOutsideClick);
  }, [open]);

  function handleTriggerKeyDown(event: KeyboardEvent<HTMLButtonElement>) {
    if (event.key === 'ArrowDown' || event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      setOpen(true);
    }
  }

  if (loading) {
    return (
      <div className="pollar-send-field">
        <span className="pollar-send-label">Asset</span>
        <div className="pollar-send-asset-selector pollar-send-asset-selector-loading" aria-label="Loading assets">
          <span className="pollar-spinner pollar-spinner-sm" />
          <span>Loading assets…</span>
        </div>
      </div>
    );
  }

  return (
    <div className="pollar-send-field">
      <label className="pollar-send-label" id="pollar-send-asset-label">
        Asset
      </label>
      <div className="pollar-send-asset-picker">
        <button
          ref={triggerRef}
          type="button"
          className="pollar-send-asset-selector"
          aria-labelledby="pollar-send-asset-label"
          aria-haspopup="listbox"
          aria-expanded={open}
          disabled={!selectedAsset}
          onClick={() => setOpen((value) => !value)}
          onKeyDown={handleTriggerKeyDown}
        >
          {selectedAsset ? (
            <>
              <AssetIcon code={selectedAsset.code} />
              <span className="pollar-send-asset-copy">
                <strong>{selectedAsset.code}</strong>
                <small>
                  {selectedAsset.available === null
                    ? 'Balance unavailable'
                    : `${formatBalance(selectedAsset.available)} available`}
                </small>
              </span>
            </>
          ) : (
            <span className="pollar-send-asset-copy">
              <strong>No assets available</strong>
            </span>
          )}
          <svg className="pollar-send-chevron" width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
            <path d="m4 6 4 4 4-4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </button>

        {open && assets.length > 0 && (
          <div className="pollar-send-asset-menu" role="listbox" aria-label="Assets">
            {assets.map((asset) => {
              const key = assetKey(asset);
              const selected = selectedAsset ? key === assetKey(selectedAsset) : false;
              return (
                <button
                  key={key}
                  type="button"
                  role="option"
                  aria-selected={selected}
                  className={`pollar-send-asset-option${selected ? ' is-selected' : ''}`}
                  onClick={() => {
                    onSelectAsset(asset);
                    setOpen(false);
                    triggerRef.current?.focus();
                  }}
                >
                  <AssetIcon code={asset.code} />
                  <span className="pollar-send-asset-copy">
                    <strong>{asset.code}</strong>
                    <small>
                      {asset.available === null ? 'Balance unavailable' : `${formatBalance(asset.available)} available`}
                    </small>
                  </span>
                </button>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

export interface SendModalTemplateProps {
  theme: string;
  accentColor: string;
  /** Per-app modal chrome overrides (background, card + button radius). */
  styleOverrides?: ModalStyleOverrides;
  step: 'form' | 'tx';
  txTitle: string;
  assets: WalletBalanceRecord[];
  selectedAsset: WalletBalanceRecord | null;
  selectedChain: WalletChain | null;
  /**
   * The networks the user can send from, in the app's configured order. The
   * picker renders only with two or more, so a single-chain app shows none.
   */
  chains?: WalletChain[];
  /** @deprecated Kept for compatibility; the sender address is no longer shown. */
  walletAddress?: string;
  /** Can a payment be built on {@link selectedChain}? Stellar and Solana only. */
  canSendOnChain: boolean;
  /**
   * Why the wallet cannot act on-chain right now (its Stellar account is still
   * being created, or its creation failed), or null when it can.
   *
   * Separate from {@link canSendOnChain}: that one is about the NETWORK not
   * having a transfer path, this one about the user's own account. Collapsing
   * them would tell someone waiting on a brand-new wallet that Stellar does not
   * support sending. Optional, so a custom template written before this existed
   * keeps compiling.
   */
  notReadyReason?: string | null;
  onSelectChain?: (chain: WalletChain) => void;
  amount: string;
  destination: string;
  formError: string;
  isLoadingBalance: boolean;
  transaction: TransactionState;
  showXdr: boolean;
  copied: boolean;
  explorerUrl: string | null;
  walletType?: WalletId | null | undefined;
  showBack: boolean;
  isInProgress: boolean;
  onClose: () => void;
  onBack: () => void;
  onRefresh: () => void;
  onSelectAsset: (asset: WalletBalanceRecord) => void;
  onAmountChange: (value: string) => void;
  onMax: () => void;
  onPaste: () => void;
  onDestinationChange: (value: string) => void;
  onSubmit: () => void;
  onSignAndSend: () => void;
  onToggleXdr: () => void;
  onCopyHash: () => void;
  onRetry: () => void;
  onDone: () => void;
}

export function SendModalTemplate({
  theme,
  accentColor,
  styleOverrides,
  step,
  txTitle,
  assets,
  selectedAsset,
  selectedChain,
  canSendOnChain,
  notReadyReason,
  chains,
  onSelectChain,
  amount,
  destination,
  formError,
  isLoadingBalance,
  transaction,
  showXdr,
  copied,
  explorerUrl,
  walletType,
  showBack,
  isInProgress,
  onClose,
  onBack,
  onRefresh,
  onSelectAsset,
  onAmountChange,
  onMax,
  onPaste,
  onDestinationChange,
  onSubmit,
  onSignAndSend,
  onToggleXdr,
  onCopyHash,
  onRetry,
  onDone,
}: SendModalTemplateProps) {
  const cssVars = buildModalCssVars(theme, accentColor, styleOverrides);

  const parsedAmount = amount ? Number(amount) : 0;
  const availableAmount =
    selectedAsset?.available === null || selectedAsset?.available === undefined ? 0 : Number(selectedAsset.available);
  const canSubmit =
    canSendOnChain &&
    !notReadyReason &&
    !!selectedAsset &&
    Number.isFinite(parsedAmount) &&
    parsedAmount > 0 &&
    parsedAmount <= availableAmount &&
    !!destination.trim() &&
    !isLoadingBalance;

  const title = step === 'form' ? 'Send' : txTitle;

  return (
    <div
      className="pollar-modal-card pollar-send-modal"
      data-theme={theme}
      style={cssVars}
      onClick={(e) => e.stopPropagation()}
    >
      {/* Header */}
      <div className="pollar-modal-header">
        <div className="pollar-send-header-left">
          {showBack && (
            <button type="button" className="pollar-modal-close" onClick={onBack} aria-label="Back">
              <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
                <path d="M10 3L5 8l5 5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </button>
          )}
          <div className="pollar-send-title-copy">
            <h2 className="pollar-modal-title">{title}</h2>
            {step === 'form' && (
              <p className="pollar-send-subtitle">Transfer assets to another {chainLabel(selectedChain)} wallet</p>
            )}
          </div>
        </div>
        {!isInProgress && (
          <div className="pollar-modal-header-actions">
            {step === 'form' && (
              <button
                type="button"
                className="pollar-modal-close"
                onClick={onRefresh}
                disabled={isLoadingBalance}
                aria-label="Refresh"
                title="Refresh balances"
              >
                <RefreshIcon spinning={isLoadingBalance} />
              </button>
            )}
            <button type="button" className="pollar-modal-close" onClick={onClose} aria-label="Close">
              <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
                <path d="M2 2l12 12M14 2L2 14" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
              </svg>
            </button>
          </div>
        )}
      </div>

      {/* Form step */}
      {step === 'form' && (
        <>
          {/* Network selector - drives the asset list below */}
          {chains && onSelectChain && (
            <ChainSelect value={selectedChain} options={chains} onChange={onSelectChain} disabled={isLoadingBalance} />
          )}

          {!canSendOnChain && <div className="pollar-modal-empty">Sending is not available on this network yet.</div>}
          {canSendOnChain && notReadyReason && <div className="pollar-modal-empty">{notReadyReason}</div>}

          {/* Asset selector */}
          <SendAssetSelector
            assets={assets}
            selectedAsset={selectedAsset}
            loading={isLoadingBalance}
            onSelectAsset={onSelectAsset}
          />

          {/* Amount */}
          <div className="pollar-send-field">
            <div className="pollar-send-label-row">
              <label className="pollar-send-label">Amount</label>
              {selectedAsset && (
                <span className="pollar-send-hint">
                  Available: {formatBalance(selectedAsset.available)} {selectedAsset.code}
                </span>
              )}
            </div>
            <div className="pollar-send-input-shell">
              <input
                className="pollar-input pollar-send-amount-input"
                type="text"
                inputMode="decimal"
                placeholder="0.00"
                value={amount}
                onChange={(e) => onAmountChange(e.target.value)}
                aria-label="Amount"
              />
              <div className="pollar-send-input-suffix">
                <button
                  type="button"
                  className="pollar-send-inline-action"
                  onClick={onMax}
                  disabled={!selectedAsset?.available}
                >
                  Max
                </button>
                <span>{selectedAsset?.code ?? ''}</span>
              </div>
            </div>
          </div>

          {/* Destination */}
          <div className="pollar-send-field">
            <label className="pollar-send-label">Destination wallet</label>
            <div className="pollar-send-input-shell">
              <input
                className="pollar-input pollar-send-destination-input"
                type="text"
                placeholder="G…"
                value={destination}
                onChange={(e) => onDestinationChange(e.target.value)}
                aria-label="Destination wallet"
              />
              <button type="button" className="pollar-send-inline-action" onClick={onPaste}>
                Paste
              </button>
            </div>
          </div>

          {formError && <div className="pollar-modal-error">{formError}</div>}

          <div className="pollar-modal-actions">
            <button className="pollar-btn-primary" onClick={onSubmit} disabled={!canSubmit}>
              Continue
            </button>
          </div>
        </>
      )}

      {/* Transaction step */}
      {step === 'tx' && (
        <TxStatusView
          transaction={transaction}
          showXdr={showXdr}
          copied={copied}
          explorerUrl={explorerUrl}
          walletType={walletType}
          onSignAndSend={onSignAndSend}
          onToggleXdr={onToggleXdr}
          onCopyHash={onCopyHash}
          onRetry={onRetry}
          onDone={onDone}
        />
      )}

      <PollarModalFooter />
    </div>
  );
}

