'use client';

import { SwapProvider, SwapQuote, SwapQuoteParams, SwapToken, SwapVenue } from '@pollar/core';
import { useCallback, useEffect, useRef, useState } from 'react';
import { usePollar } from '../../context';
import '../shared.css';
import '../transaction-modal/TransactionModal.css';
import '../send-modal/SendModal.css';
import './SwapModal.css';
import { SwapAssetOption, SwapModalTemplate } from './SwapModalTemplate';
import { modalChrome } from '../modal-theme';

interface SwapModalProps {
  onClose: () => void;
}

/** Debounce (ms) before re-quoting as the user edits the amount / assets. */
const QUOTE_DEBOUNCE_MS = 400;

type AssetLike = { type: 'native' | 'credit_alphanum4' | 'credit_alphanum12'; code: string; issuer?: string | undefined };

function toRef(a: AssetLike): SwapQuoteParams['sellAsset'] {
  if (a.type === 'native') return { type: 'native' };
  if (a.type === 'credit_alphanum4') return { type: 'credit_alphanum4', code: a.code, issuer: a.issuer! };
  return { type: 'credit_alphanum12', code: a.code, issuer: a.issuer! };
}

/** A catalog token (code + issuer) -> the asset ref, picking the alphanum width. */
function catalogRef(code: string, issuer: string): SwapQuoteParams['sellAsset'] {
  return code.length <= 4 ? { type: 'credit_alphanum4', code, issuer } : { type: 'credit_alphanum12', code, issuer };
}

export function SwapModal({ onClose }: SwapModalProps) {
  const {
    getSwapConfig,
    getSwapTokens,
    getSwapQuote,
    swap,
    walletBalance,
    refreshWalletBalance,
    enabledAssets,
    refreshAssets,
    tx: transaction,
    wallet,
    network,
    styles,
  } = usePollar();

  const walletType = wallet?.custody === 'external' ? wallet.provider : null;
  const smartUnsupported = wallet?.custody === 'smart';
  const { theme, accentColor, styleOverrides, overlayStyle } = modalChrome(styles);

  const [step, setStep] = useState<'form' | 'tx'>('form');
  const [selectedSell, setSelectedSell] = useState<SwapAssetOption | null>(null);
  const [selectedBuy, setSelectedBuy] = useState<SwapAssetOption | null>(null);
  const [amount, setAmount] = useState('');
  const [provider, setProvider] = useState<SwapProvider>('auto');
  const [venues, setVenues] = useState<SwapVenue[] | null>(null); // null = config loading
  const [catalogTokens, setCatalogTokens] = useState<SwapToken[]>([]);
  // Tokens the user pasted by code+issuer (not in the app catalog). Local only.
  const [customTokens, setCustomTokens] = useState<SwapAssetOption[]>([]);
  const [quotes, setQuotes] = useState<SwapQuote[]>([]);
  const [quoteLoading, setQuoteLoading] = useState(false);
  const [quoteError, setQuoteError] = useState('');
  const [formError, setFormError] = useState('');
  const [showXdr, setShowXdr] = useState(false);
  const [copied, setCopied] = useState(false);
  const copyTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Fixed default slippage (0.5%). Exposed as a constant for now; an advanced
  // control can drive this later without touching the quote/execute wiring.
  const slippageBps = 50;

  useEffect(() => {
    void refreshWalletBalance();
    void refreshAssets();
  }, [refreshWalletBalance, refreshAssets]);

  // Which venues this app exposes (operator config intersected with server capability).
  const loadConfig = useCallback(() => {
    setVenues(null); // back to loading
    return getSwapConfig()
      .then(setVenues)
      .catch(() => setVenues([])); // treat a failed config as "unavailable"
  }, [getSwapConfig]);

  useEffect(() => {
    void loadConfig();
  }, [loadConfig]);

  // Curated "buy" catalog tokens the app opted into (may lack a trustline).
  const loadCatalog = useCallback(
    () =>
      getSwapTokens()
        .then(setCatalogTokens)
        .catch(() => setCatalogTokens([])),
    [getSwapTokens],
  );

  useEffect(() => {
    void loadCatalog();
  }, [loadCatalog]);

  // Re-pull everything the modal shows: balances, app assets, config and catalog.
  function handleRefresh() {
    void refreshWalletBalance();
    void refreshAssets();
    void loadConfig();
    void loadCatalog();
  }

  useEffect(
    () => () => {
      if (copyTimerRef.current !== null) clearTimeout(copyTimerRef.current);
    },
    [],
  );

  const balances = walletBalance.step === 'loaded' ? walletBalance.data.balances : [];
  const assetRecords = enabledAssets.step === 'loaded' ? enabledAssets.data.assets : [];
  const isLoadingData = walletBalance.step === 'loading' || enabledAssets.step === 'loading';
  const availableFor = (code: string, issuer?: string): string | undefined =>
    balances.find((b) => b.code === code && (b.issuer ?? '') === (issuer ?? ''))?.available ?? undefined;

  // Sell: native XLM + every asset the wallet has a trustline for, even at a 0
  // balance - so the user always sees what they hold and knows when to fund
  // (the amount field guards against overselling). Buy: app-enabled assets.
  // Swap is Stellar-only, so the guard drops every non-Stellar balance and
  // narrows `type` for toRef(). It has to test `chain`, not `type`: SOL/POL
  // report `type: 'native'` exactly like XLM, and a Solana/Polygon token reports
  // `type: 'token'` with no `trustlineRemoved`, so neither can be told apart
  // from a Stellar row by `type` alone.
  const sellOptions: SwapAssetOption[] = balances
    .filter(
      (b): b is typeof b & { type: 'native' | 'credit_alphanum4' | 'credit_alphanum12' } =>
        (b.chain === undefined || b.chain === 'STELLAR') &&
        (b.type === 'native' || ((b.type === 'credit_alphanum4' || b.type === 'credit_alphanum12') && !b.trustlineRemoved)),
    )
    // A null `available` (chain unreadable) maps to undefined - "unknown", which
    // the option already models - rather than to a 0 that would read as "empty".
    .map((b) => ({
      ref: toRef(b),
      code: b.code,
      issuer: b.issuer,
      available: b.available ?? undefined,
      enabledInApp: b.enabledInApp,
    }));

  const buyKeyOfSell = selectedSell ? `${selectedSell.code}:${selectedSell.issuer ?? 'native'}` : '';
  const optKey = (o: { code: string; issuer?: string | undefined }) => `${o.code}:${o.issuer ?? 'native'}`;
  // Buy list = the app's enabled assets, plus curated catalog tokens the app
  // opted into (deduped; catalog tokens the wallet may not trust yet). Exclude
  // whatever is being sold.
  // Same Stellar-only guard as the sell list: the enabled-asset catalog is now
  // multichain, and a Polygon/Solana token (type 'token') has no Stellar asset
  // ref to swap with. The predicate both drops them and narrows `type` for toRef().
  const enabledBuy: SwapAssetOption[] = assetRecords
    .filter(
      (a): a is typeof a & { type: 'native' | 'credit_alphanum4' | 'credit_alphanum12' } =>
        (a.chain === undefined || a.chain === 'STELLAR') &&
        (a.type === 'native' || a.type === 'credit_alphanum4' || a.type === 'credit_alphanum12'),
    )
    .map((a) => ({
      ref: toRef(a),
      code: a.code,
      issuer: a.issuer,
      available: availableFor(a.code, a.issuer),
      enabledInApp: a.enabledInApp,
    }));
  const enabledKeys = new Set(enabledBuy.map(optKey));
  const catalogBuy: SwapAssetOption[] = catalogTokens
    .map((tk) => ({
      ref: catalogRef(tk.code, tk.issuer),
      code: tk.code,
      issuer: tk.issuer,
      available: availableFor(tk.code, tk.issuer),
      enabledInApp: false,
    }))
    .filter((o) => !enabledKeys.has(optKey(o)));
  const knownKeys = new Set([...enabledKeys, ...catalogBuy.map(optKey)]);
  const customBuy = customTokens
    .filter((o) => !knownKeys.has(optKey(o)))
    .map((o) => ({ ...o, available: availableFor(o.code, o.issuer) }));
  const buyOptions: SwapAssetOption[] = [...enabledBuy, ...catalogBuy, ...customBuy].filter(
    (o) => optKey(o) !== buyKeyOfSell || optKey(o) === (selectedBuy ? optKey(selectedBuy) : ''),
  );

  // Auto-select the first sell / buy asset once options are available, and keep a
  // valid selection if the list changes - so the pickers never sit empty.
  useEffect(() => {
    if (sellOptions.length === 0) return;
    if (!selectedSell || !sellOptions.some((o) => optKey(o) === optKey(selectedSell))) {
      setSelectedSell(sellOptions[0]!);
    }
  }, [sellOptions, selectedSell]);

  useEffect(() => {
    if (buyOptions.length === 0) return;
    if (!selectedBuy || !buyOptions.some((o) => optKey(o) === optKey(selectedBuy))) {
      setSelectedBuy(buyOptions[0]!);
    }
  }, [buyOptions, selectedBuy]);

  // Add a user-pasted token (code + issuer) to the buy list and select it.
  // Returns an error message, or null on success.
  function addCustomToken(code: string, issuer: string): string | null {
    const c = code.trim().toUpperCase();
    const i = issuer.trim();
    if (c.length < 1 || c.length > 12) return 'Code must be 1-12 characters';
    if (i.length !== 56 || !i.startsWith('G')) return 'Issuer must be a Stellar address (G..., 56 chars)';
    const opt: SwapAssetOption = { ref: catalogRef(c, i), code: c, issuer: i, enabledInApp: false };
    setCustomTokens((prev) => (prev.some((o) => optKey(o) === optKey(opt)) ? prev : [...prev, opt]));
    setSelectedBuy(opt);
    return null;
  }

  // Does buying `selectedBuy` require creating a trustline first? Native never;
  // a credit asset the wallet already trusts (in enabledAssets with
  // trustlineEstablished) doesn't; anything else (incl. catalog tokens) does.
  // Smart wallets hold SAC tokens (no classic trustlines) so it never applies.
  const buyNeedsTrustline = (() => {
    if (!selectedBuy || smartUnsupported) return false;
    if (selectedBuy.ref.type === 'native') return false;
    const rec = assetRecords.find((a) => a.code === selectedBuy.code && a.issuer === selectedBuy.issuer);
    return !rec?.trustlineEstablished;
  })();

  const configLoading = venues === null;
  const swapUnavailable = venues !== null && venues.length === 0;
  // Offer "Auto" (best of the enabled set) plus each configured venue.
  const providers: SwapProvider[] = venues && venues.length > 0 ? (['auto', ...venues] as SwapProvider[]) : [];
  const quote = quotes[0] ?? null;

  // Re-quote (debounced) whenever the pair / amount / route changes.
  useEffect(() => {
    if (
      step !== 'form' ||
      swapUnavailable ||
      configLoading ||
      !selectedSell ||
      !selectedBuy ||
      !amount ||
      parseFloat(amount) <= 0
    ) {
      setQuotes([]);
      setQuoteError('');
      setQuoteLoading(false);
      return;
    }
    let cancelled = false;
    setQuoteLoading(true);
    setQuoteError('');
    const t = setTimeout(async () => {
      try {
        const qs = await getSwapQuote({
          sellAsset: selectedSell.ref,
          buyAsset: selectedBuy.ref,
          amount,
          provider,
          slippageBps,
        });
        if (!cancelled) setQuotes(qs);
      } catch (e) {
        if (!cancelled) {
          setQuotes([]);
          setQuoteError(e instanceof Error ? e.message : 'Failed to fetch quote');
        }
      } finally {
        if (!cancelled) setQuoteLoading(false);
      }
    }, QUOTE_DEBOUNCE_MS);
    return () => {
      cancelled = true;
      clearTimeout(t);
    };
  }, [step, swapUnavailable, configLoading, selectedSell, selectedBuy, amount, provider, getSwapQuote]);

  const hash = transaction.step === 'success' ? transaction.hash : null;
  const buildData = 'buildData' in transaction ? transaction.buildData : null;
  const explorerNetwork = buildData?.summary.network?.toLowerCase().includes('testnet')
    ? 'testnet'
    : buildData
      ? 'public'
      : network === 'testnet'
        ? 'testnet'
        : 'public';
  const explorerUrl = hash ? `https://stellar.expert/explorer/${explorerNetwork}/tx/${hash}` : null;

  const IN_FLIGHT_STEPS = [
    'building',
    'signing',
    'submitting',
    'submitted',
    'signing-submitting',
    'building-signing-submitting',
  ] as const;
  const isInProgress = (IN_FLIGHT_STEPS as readonly string[]).includes(transaction.step);
  const showBack = step === 'tx' && (transaction.step === 'error' || transaction.step === 'success') && !isInProgress;

  const txTitle = isInProgress
    ? 'Swapping…'
    : transaction.step === 'success'
      ? 'Swapped!'
      : transaction.step === 'error'
        ? 'Swap failed'
        : 'Confirm Swap';

  async function handleSwap() {
    setFormError('');
    if (smartUnsupported) {
      setFormError('Swaps are not yet supported for smart (passkey) wallets');
      return;
    }
    if (!selectedSell || !selectedBuy) {
      setFormError('Select both assets');
      return;
    }
    const parsed = parseFloat(amount);
    if (!amount || isNaN(parsed) || parsed <= 0) {
      setFormError('Enter a valid amount');
      return;
    }
    if (selectedSell.available !== undefined && parsed > parseFloat(selectedSell.available)) {
      setFormError('Insufficient balance');
      return;
    }
    if (!quote) {
      setFormError('No route available for this pair');
      return;
    }
    setStep('tx');
    await swap(quote);
  }

  async function handleRetry() {
    if (transaction.step === 'error' && quote) await swap(quote);
  }

  function handleMax() {
    if (selectedSell?.available !== undefined) setAmount(selectedSell.available);
  }

  function handleReverse() {
    if (!selectedSell || !selectedBuy) return;
    const previousSell = selectedSell;
    setSelectedSell(selectedBuy);
    setSelectedBuy(previousSell);
  }

  function handleCopyHash() {
    if (!hash) return;
    navigator.clipboard.writeText(hash).then(() => {
      setCopied(true);
      if (copyTimerRef.current !== null) clearTimeout(copyTimerRef.current);
      copyTimerRef.current = setTimeout(() => {
        copyTimerRef.current = null;
        setCopied(false);
      }, 2000);
    });
  }

  function handleBack() {
    setStep('form');
    setShowXdr(false);
    setCopied(false);
  }

  return (
    <div className="pollar-overlay" style={overlayStyle} onClick={!isInProgress ? onClose : undefined}>
      <SwapModalTemplate
        theme={theme}
        accentColor={accentColor}
        styleOverrides={styleOverrides}
        step={step}
        txTitle={txTitle}
        sellOptions={sellOptions}
        buyOptions={buyOptions}
        selectedSell={selectedSell}
        selectedBuy={selectedBuy}
        amount={amount}
        provider={provider}
        providers={providers}
        quote={quote}
        quoteLoading={quoteLoading}
        quoteError={quoteError}
        formError={formError}
        isLoadingData={isLoadingData}
        smartUnsupported={smartUnsupported}
        configLoading={configLoading}
        swapUnavailable={swapUnavailable}
        buyNeedsTrustline={buyNeedsTrustline}
        transaction={transaction}
        showXdr={showXdr}
        copied={copied}
        explorerUrl={explorerUrl}
        walletType={walletType}
        showBack={showBack}
        isInProgress={isInProgress}
        onClose={onClose}
        onBack={handleBack}
        onRefresh={handleRefresh}
        onSelectSell={setSelectedSell}
        onSelectBuy={setSelectedBuy}
        onReverse={handleReverse}
        onMax={handleMax}
        onAddCustomToken={addCustomToken}
        onAmountChange={setAmount}
        onProviderChange={setProvider}
        onSwap={() => void handleSwap()}
        onToggleXdr={() => setShowXdr((v) => !v)}
        onCopyHash={handleCopyHash}
        onRetry={() => void handleRetry()}
        onDone={onClose}
      />
    </div>
  );
}

'use client';

import { SwapProvider, SwapQuote, SwapQuoteParams, TransactionState, WalletId } from '@pollar/core';
import { useState } from 'react';
import { PollarModalFooter, RefreshIcon } from '../commons';
import { TxStatusView } from '../transaction-modal/TxStatusView';
import { buildModalCssVars, type ModalStyleOverrides } from '../modal-theme';

export interface SwapAssetOption {
  ref: SwapQuoteParams['sellAsset'];
  code: string;
  issuer?: string | undefined;
  available?: string | undefined;
  enabledInApp?: boolean | undefined;
}

export function assetOptionKey(o: SwapAssetOption): string {
  return `${o.code}:${o.issuer ?? 'native'}`;
}

const PROVIDER_LABELS: Record<SwapProvider, string> = {
  auto: 'Best price',
  aquarius: 'Aquarius',
  soroswap: 'Soroswap',
  sdex: 'Stellar DEX',
};

function formatAmount(value: string | undefined): string {
  if (value === undefined) return '—';
  const n = parseFloat(value);
  return isNaN(n) ? value : n.toLocaleString(undefined, { maximumFractionDigits: 7 });
}

/** Decimal division for display only. All intermediate arithmetic stays in BigInt. */
function formatRate(numerator: string, denominator: string): string | null {
  const parse = (value: string) => {
    const trimmed = value.trim();
    if (!/^\d+(\.\d+)?$/.test(trimmed)) return null;
    const [whole = '0', fraction = ''] = trimmed.split('.');
    return { digits: BigInt(`${whole}${fraction}`), scale: fraction.length };
  };
  const top = parse(numerator);
  const bottom = parse(denominator);
  if (!top || !bottom || bottom.digits === 0n || top.digits === 0n) return null;

  const precision = 8;
  const scaledNumerator = top.digits * 10n ** BigInt(bottom.scale + precision);
  const scaledDenominator = bottom.digits * 10n ** BigInt(top.scale);
  const scaled = scaledNumerator / scaledDenominator;
  const whole = scaled / 10n ** BigInt(precision);
  const fraction = (scaled % 10n ** BigInt(precision)).toString().padStart(precision, '0').replace(/0+$/, '');
  return fraction ? `${whole}.${fraction}` : whole.toString();
}

function AssetIcon({ code }: { code: string }) {
  return (
    <span className="pollar-swap-asset-icon" aria-hidden>
      {code.slice(0, 2).toUpperCase()}
    </span>
  );
}

function AssetPill({
  label,
  value,
  options,
  disabled,
  onChange,
}: {
  label: string;
  value: string;
  options: SwapAssetOption[];
  disabled: boolean;
  onChange: (key: string) => void;
}) {
  const selected = options.find((option) => assetOptionKey(option) === value);
  const appAssets = options.filter((option) => option.enabledInApp);
  const otherAssets = options.filter((option) => !option.enabledInApp);

  return (
    <label className="pollar-swap-asset-pill-wrap">
      <span className="sr-only">{label}</span>
      <AssetIcon code={selected?.code ?? '—'} />
      <select
        className="pollar-swap-asset-pill"
        aria-label={label}
        value={value}
        disabled={disabled}
        onChange={(event) => onChange(event.target.value)}
      >
        {value === '' && <option value="" disabled hidden />}
        {appAssets.length > 0 && (
          <optgroup label="App assets">
            {appAssets.map((option) => (
              <option key={assetOptionKey(option)} value={assetOptionKey(option)}>
                {option.code}
              </option>
            ))}
          </optgroup>
        )}
        {otherAssets.length > 0 && (
          <optgroup label="Other assets">
            {otherAssets.map((option) => (
              <option key={assetOptionKey(option)} value={assetOptionKey(option)}>
                {option.code}
              </option>
            ))}
          </optgroup>
        )}
      </select>
      <svg className="pollar-swap-chevron" width="14" height="14" viewBox="0 0 14 14" fill="none" aria-hidden>
        <path
          d="m3.5 5.25 3.5 3.5 3.5-3.5"
          stroke="currentColor"
          strokeWidth="1.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    </label>
  );
}

export interface SwapModalTemplateProps {
  theme: string;
  accentColor: string;
  styleOverrides?: ModalStyleOverrides;
  step: 'form' | 'tx';
  txTitle: string;
  sellOptions: SwapAssetOption[];
  buyOptions: SwapAssetOption[];
  selectedSell: SwapAssetOption | null;
  selectedBuy: SwapAssetOption | null;
  amount: string;
  provider: SwapProvider;
  providers: SwapProvider[];
  quote: SwapQuote | null;
  quoteLoading: boolean;
  quoteError: string;
  formError: string;
  isLoadingData: boolean;
  smartUnsupported: boolean;
  configLoading: boolean;
  swapUnavailable: boolean;
  buyNeedsTrustline: boolean;
  transaction: TransactionState;
  showXdr: boolean;
  copied: boolean;
  explorerUrl: string | null;
  walletType?: WalletId | null | undefined;
  showBack: boolean;
  isInProgress: boolean;
  onClose: () => void;
  onBack: () => void;
  onRefresh: () => void;
  onSelectSell: (o: SwapAssetOption) => void;
  onSelectBuy: (o: SwapAssetOption) => void;
  onReverse: () => void;
  onMax: () => void;
  onAddCustomToken: (code: string, issuer: string) => string | null;
  onAmountChange: (value: string) => void;
  onProviderChange: (p: SwapProvider) => void;
  onSwap: () => void;
  onToggleXdr: () => void;
  onCopyHash: () => void;
  onRetry: () => void;
  onDone: () => void;
}

export function SwapModalTemplate({
  theme,
  accentColor,
  styleOverrides,
  step,
  txTitle,
  sellOptions,
  buyOptions,
  selectedSell,
  selectedBuy,
  amount,
  provider,
  providers,
  quote,
  quoteLoading,
  quoteError,
  formError,
  isLoadingData,
  smartUnsupported,
  configLoading,
  swapUnavailable,
  buyNeedsTrustline,
  transaction,
  showXdr,
  copied,
  explorerUrl,
  walletType,
  showBack,
  isInProgress,
  onClose,
  onBack,
  onRefresh,
  onSelectSell,
  onSelectBuy,
  onAddCustomToken,
  onReverse,
  onMax,
  onAmountChange,
  onProviderChange,
  onSwap,
  onToggleXdr,
  onCopyHash,
  onRetry,
  onDone,
}: SwapModalTemplateProps) {
  const [customOpen, setCustomOpen] = useState(false);
  const [customCode, setCustomCode] = useState('');
  const [customIssuer, setCustomIssuer] = useState('');
  const [customError, setCustomError] = useState('');

  const submitCustomToken = () => {
    const err = onAddCustomToken(customCode, customIssuer);
    if (err) {
      setCustomError(err);
      return;
    }
    setCustomCode('');
    setCustomIssuer('');
    setCustomError('');
    setCustomOpen(false);
  };

  const cssVars = buildModalCssVars(theme, accentColor, styleOverrides);
  const sellKey = selectedSell ? assetOptionKey(selectedSell) : '';
  const buyKey = selectedBuy ? assetOptionKey(selectedBuy) : '';
  const sameAsset = !!selectedSell && !!selectedBuy && sellKey === buyKey;
  const canSwap =
    !smartUnsupported &&
    !sameAsset &&
    !!selectedSell &&
    !!selectedBuy &&
    !!amount &&
    !!quote &&
    !quoteLoading &&
    !isLoadingData;
  const rate = quote && amount ? formatRate(quote.amountOut, amount) : null;
  const title = step === 'form' ? 'Swap' : txTitle;

  const selectSell = (key: string) => {
    const found = sellOptions.find((option) => assetOptionKey(option) === key);
    if (found) onSelectSell(found);
  };
  const selectBuy = (key: string) => {
    const found = buyOptions.find((option) => assetOptionKey(option) === key);
    if (found) onSelectBuy(found);
  };
  return (
    <div
      className="pollar-modal-card pollar-swap-modal"
      data-theme={theme}
      style={cssVars}
      onClick={(event) => event.stopPropagation()}
    >
      <div className="pollar-modal-header">
        <div className="pollar-send-header-left">
          {showBack && (
            <button type="button" className="pollar-modal-close" onClick={onBack} aria-label="Back">
              <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
                <path d="M10 3 5 8l5 5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </button>
          )}
          <h2 className="pollar-modal-title">{title}</h2>
        </div>
        {!isInProgress && (
          <div className="pollar-modal-header-actions">
            {step === 'form' && (
              <button
                type="button"
                className="pollar-modal-close"
                onClick={onRefresh}
                disabled={configLoading || isLoadingData}
                aria-label="Refresh"
                title="Refresh balances and options"
              >
                <RefreshIcon spinning={configLoading || isLoadingData} />
              </button>
            )}
            <button type="button" className="pollar-modal-close" onClick={onClose} aria-label="Close">
              <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
                <path d="M2 2l12 12M14 2L2 14" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
              </svg>
            </button>
          </div>
        )}
      </div>

      {step === 'form' && !configLoading && swapUnavailable && (
        <div className="pollar-modal-error">Swap is not available for this app.</div>
      )}

      {step === 'form' && !swapUnavailable && (
        <>
          {smartUnsupported && (
            <div className="pollar-modal-error">Swaps are not yet available for smart (passkey) wallets.</div>
          )}

          <div className="pollar-swap-panels">
            <section className="pollar-swap-panel" aria-labelledby="pollar-swap-pay-label">
              <div className="pollar-swap-panel-heading">
                <span id="pollar-swap-pay-label" className="pollar-swap-panel-label">
                  You pay
                </span>
                <span className="pollar-swap-balance">Balance: {formatAmount(selectedSell?.available)}</span>
              </div>
              <div className="pollar-swap-panel-main">
                <input
                  className="pollar-swap-amount"
                  type="text"
                  inputMode="decimal"
                  aria-label="Amount to pay"
                  placeholder="0.00"
                  value={amount}
                  disabled={configLoading || isLoadingData}
                  onChange={(event) => onAmountChange(event.target.value)}
                />
                <div className="pollar-swap-panel-selector">
                  <AssetPill
                    label="Asset to pay"
                    value={sellKey}
                    options={sellOptions}
                    disabled={configLoading || isLoadingData}
                    onChange={selectSell}
                  />
                  <button
                    type="button"
                    className="pollar-swap-max"
                    onClick={onMax}
                    disabled={!selectedSell?.available || configLoading || isLoadingData}
                  >
                    Max
                  </button>
                </div>
              </div>
            </section>

            <button
              type="button"
              className="pollar-swap-reverse"
              onClick={onReverse}
              disabled={!selectedSell || !selectedBuy}
              aria-label="Swap pay and receive assets"
              title="Swap pay and receive assets"
            >
              <svg width="17" height="17" viewBox="0 0 17 17" fill="none" aria-hidden>
                <path
                  d="M5 3v10M5 3 2.5 5.5M5 3l2.5 2.5M12 14V4M12 14l2.5-2.5M12 14 9.5 11.5"
                  stroke="currentColor"
                  strokeWidth="1.6"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </button>

            <section className="pollar-swap-panel" aria-labelledby="pollar-swap-receive-label">
              <div className="pollar-swap-panel-heading">
                <span id="pollar-swap-receive-label" className="pollar-swap-panel-label">
                  You receive
                </span>
                <span className="pollar-swap-balance">Balance: {formatAmount(selectedBuy?.available)}</span>
              </div>
              <div className="pollar-swap-panel-main">
                <div className={`pollar-swap-output${quoteLoading ? ' is-loading' : ''}`} aria-live="polite">
                  {quoteLoading ? <span className="pollar-spinner pollar-spinner-sm" /> : formatAmount(quote?.amountOut)}
                </div>
                <div className="pollar-swap-panel-selector">
                  <AssetPill
                    label="Asset to receive"
                    value={buyKey}
                    options={buyOptions}
                    disabled={configLoading || isLoadingData}
                    onChange={selectBuy}
                  />
                  <span className="pollar-swap-panel-note">Quoted amount</span>
                </div>
              </div>
            </section>
          </div>

          {/* A buy token the app has not enabled, by code and issuer */}
          <div className="pollar-swap-custom-area">
            {customOpen ? (
              <div className="pollar-swap-custom">
                <input
                  className="pollar-input"
                  type="text"
                  placeholder="Code (e.g. USDC)"
                  value={customCode}
                  onChange={(e) => setCustomCode(e.target.value)}
                />
                <input
                  className="pollar-input"
                  type="text"
                  placeholder="Issuer (G...)"
                  value={customIssuer}
                  onChange={(e) => setCustomIssuer(e.target.value)}
                />
                {customError && <div className="pollar-modal-error">{customError}</div>}
                <div className="pollar-swap-custom-actions">
                  <button type="button" className="pollar-btn-primary" onClick={submitCustomToken}>
                    Add token
                  </button>
                  <button
                    type="button"
                    className="pollar-swap-custom-cancel"
                    onClick={() => {
                      setCustomOpen(false);
                      setCustomError('');
                    }}
                  >
                    Cancel
                  </button>
                </div>
              </div>
            ) : (
              <button
                type="button"
                className="pollar-swap-custom-toggle"
                disabled={configLoading}
                onClick={() => setCustomOpen(true)}
              >
                + Add a token by code / issuer
              </button>
            )}
          </div>

          <div className="pollar-swap-rate-row">
            <div className="pollar-swap-rate" aria-live="polite">
              {rate && selectedSell && selectedBuy ? (
                <>
                  1 {selectedSell.code} ≈ {rate} {selectedBuy.code}
                </>
              ) : quoteLoading ? (
                'Updating rate…'
              ) : (
                'Exchange rate unavailable'
              )}
            </div>
            {configLoading ? (
              <div className="pollar-swap-route-pill">
                <span className="pollar-spinner pollar-spinner-sm" /> Loading
              </div>
            ) : (
              <label className="pollar-swap-route-wrap">
                <span className="sr-only">Route</span>
                <select
                  className="pollar-swap-route-pill"
                  aria-label="Route"
                  value={provider}
                  disabled={providers.length === 0}
                  onChange={(event) => onProviderChange(event.target.value as SwapProvider)}
                >
                  {providers.length === 0 ? (
                    <option value={provider}>{PROVIDER_LABELS[provider]}</option>
                  ) : (
                    providers.map((p) => (
                      <option key={p} value={p}>
                        {PROVIDER_LABELS[p]}
                      </option>
                    ))
                  )}
                </select>
              </label>
            )}
          </div>

          {!quoteLoading && quoteError && <div className="pollar-modal-error">{quoteError}</div>}
          {!quoteLoading && !quoteError && !quote && selectedSell && selectedBuy && !!amount && (
            <div className="pollar-send-hint">No route found for this pair.</div>
          )}
          {quote && (
            <div className="pollar-swap-quote">
              <div className="pollar-swap-quote-row">
                <span>Minimum received</span>
                <strong>
                  {formatAmount(quote.minReceived)} {selectedBuy?.code}
                </strong>
              </div>
              <div className="pollar-swap-quote-row">
                <span>Price impact</span>
                <strong>{quote.priceImpactPct}%</strong>
              </div>
              <div className="pollar-swap-quote-row">
                <span>Route</span>
                <strong>{PROVIDER_LABELS[quote.provider]}</strong>
              </div>
            </div>
          )}
          {buyNeedsTrustline && selectedBuy && (
            <div className="pollar-swap-trustline-notice">
              To receive {selectedBuy.code} your wallet needs a trustline. Swapping will create it first (~0.5 XLM reserve,
              refundable if you later remove it).
            </div>
          )}
          {sameAsset && <div className="pollar-modal-error">Choose two different assets to swap.</div>}
          {formError && <div className="pollar-modal-error">{formError}</div>}

          <div className="pollar-modal-actions">
            <button type="button" className="pollar-btn-primary" onClick={onSwap} disabled={!canSwap}>
              {buyNeedsTrustline ? 'Create trustline & swap' : 'Swap'}
            </button>
          </div>
        </>
      )}

      {step === 'tx' && (
        <TxStatusView
          transaction={transaction}
          showXdr={showXdr}
          copied={copied}
          explorerUrl={explorerUrl}
          walletType={walletType}
          onSignAndSend={() => {}}
          onToggleXdr={onToggleXdr}
          onCopyHash={onCopyHash}
          onRetry={onRetry}
          onDone={onDone}
        />
      )}
      <PollarModalFooter shield />
    </div>
  );
}

