  transaction: TransactionState;
  showXdr: boolean;
  copied: boolean;
  explorerUrl: string | null;
  walletType?: WalletId | null;
  onClose: () => void;
  onSignAndSend: () => void;
  onToggleXdr: () => void;
  onCopyHash: () => void;
  onRetry?: () => void;
}

export function TransactionModalTemplate({
  theme,
  accentColor,
  styleOverrides,
  transaction,
  showXdr,
  copied,
  explorerUrl,
  walletType,
  onClose,
  onSignAndSend,
  onToggleXdr,
  onCopyHash,
  onRetry,
}: TransactionModalTemplateProps) {
  const cssVars = buildModalCssVars(theme, accentColor, styleOverrides);

  return (
