  align-items: center;
  gap: 2px;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.75rem;
  font-weight: 400;
  color: var(--pollar-muted);
  background: var(--pollar-bg);
  border: 1px solid var(--pollar-border);
  border-radius: 6px;
  padding: 1px 3px 1px 7px;
}

.pollar-hist-item-meta {
  font-size: 0.75rem;
  color: var(--pollar-muted);
  display: flex;
  gap: 0.5rem;
  align-items: center;
  flex-wrap: wrap;
}

.pollar-hist-item-footer {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.75rem;
  color: var(--pollar-muted);
}

.pollar-hist-item-hash {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

.pollar-hist-item-dot {
  opacity: 0.6;
}

.pollar-hist-item-badge {
  align-self: start;
  flex-shrink: 0;
  font-size: 0.6875rem;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 999px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  white-space: nowrap;
}

.pollar-hist-item-badge[data-status='SUCCESS'] {
  background: rgba(22, 163, 74, 0.12);
  color: var(--pollar-success-text, #16a34a);
}

.pollar-hist-item-badge[data-status='FAILED'] {
  background: rgba(220, 38, 38, 0.1);
  color: var(--pollar-error-text, #dc2626);
}

.pollar-hist-item-badge[data-status='PENDING'] {
  background: rgba(107, 114, 128, 0.12);
  color: var(--pollar-muted);
}

.pollar-hist-item-explorer {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  color: var(--pollar-muted);
  text-decoration: none;
  transition: color 150ms;
}

.pollar-hist-item-explorer:hover {
  color: var(--pollar-accent);
}

