.pollar-hist-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.75rem;
}

.pollar-hist-pagination-info {
  font-size: 0.75rem;
  color: var(--pollar-muted);
}

.pollar-hist-pagination-btns {
  display: flex;
  gap: 0.375rem;
}

.pollar-hist-page-btn {
