// --- Internal SVG renderer ----------------------------------------------------

interface QRCodeSvgProps extends SVGProps<SVGSVGElement> {
  bgColor: string;
  bgD: string;
  fgColor: string;
  fgD: string;
  size: number;
  title?: string;
  viewBoxSize: number;
  xmlns?: string | undefined;
}

const QRCodeSvg = forwardRef<SVGSVGElement, QRCodeSvgProps>(function QRCodeSvg(
  { bgColor, bgD, fgD, fgColor, size, title, viewBoxSize, xmlns = 'http://www.w3.org/2000/svg', ...props },
  ref,
) {
  return (
    <svg {...props} height={size} ref={ref} viewBox={`0 0 ${viewBoxSize} ${viewBoxSize}`} width={size} xmlns={xmlns}>
      {title ? <title>{title}</title> : null}
      <path d={bgD} fill={bgColor} />
      <path d={fgD} fill={fgColor} />
    </svg>
  );
});

QRCodeSvg.displayName = 'QRCodeSvg';

// --- Public component ---------------------------------------------------------

export interface QRCodeProps extends SVGProps<SVGSVGElement> {
  value: string;
  size?: number;
  bgColor?: string;
  fgColor?: string;
  level?: 'L' | 'M' | 'Q' | 'H';
  title?: string;
}

function bytesToBinaryString(bytes: number[]): string {
  return bytes.map((b) => String.fromCharCode(b & 0xff)).join('');
}

function encodeStringToUtf8Bytes(input: string): number[] {
  return Array.from(new TextEncoder().encode(input));
}

export const QRCode = forwardRef<SVGSVGElement, QRCodeProps>(function QRCode(
  { bgColor = '#FFFFFF', fgColor = '#000000', level = 'L', size = 256, value, ...props },
  ref,
) {
  const qrcode = new QRCodeImpl(-1, ErrorCorrectLevel[level]);
  const utf8Bytes = encodeStringToUtf8Bytes(value);
  const binaryString = bytesToBinaryString(utf8Bytes);
  qrcode.addData(binaryString, 'Byte');
  qrcode.make();

  const cells: boolean[][] = qrcode.modules;

  return (
    <QRCodeSvg
      {...props}
      bgColor={bgColor}
      bgD={cells
        .map((row, rowIndex) =>
          row.map((cell, cellIndex) => (!cell ? `M ${cellIndex} ${rowIndex} l 1 0 0 1 -1 0 Z` : '')).join(' '),
        )
        .join(' ')}
      fgColor={fgColor}
      fgD={cells
        .map((row, rowIndex) =>
          row.map((cell, cellIndex) => (cell ? `M ${cellIndex} ${rowIndex} l 1 0 0 1 -1 0 Z` : '')).join(' '),
        )
        .join(' ')}
      ref={ref}
      size={size}
      viewBoxSize={cells.length}
    />
  );
});

import type { WalletChain, WalletInfo } from '@pollar/core';

/**
 * The one place the widget decides whether a wallet can act on-chain, and what
 * to say when it cannot.
 *
 * Only STELLAR is gated: `provisioning` describes the Stellar account, and a
 * Solana wallet has nothing to wait for. Only the ACCOUNT is described, never
 * trustlines - an asset the app enabled yesterday is not a reason to stop a
 * user from sending the one they already hold.
 *
 * A `null` chain is "not known yet" (the app's chain order comes from
 * `/config`, which is still in flight on a cold start) and reads as no reason
 * to block. Guessing STELLAR there would tell a Solana-first user their wallet
 * is being prepared, next to a Solana address that sends and receives fine.
 *
 * Returns null when the wallet is usable, so a caller reads it as "no reason to
 * block".
 */
export function walletNotReadyReason(
  wallet: WalletInfo | null | undefined,
  chain: WalletChain | null | undefined,
): string | null {
  if (chain !== 'STELLAR') return null;
  if (wallet?.provisioning === 'CREATING') {
    return 'Your wallet is still being prepared on the network. This usually takes a few seconds.';
  }
  if (wallet?.provisioning === 'FAILED') {
    return 'Your wallet could not be created on the network. Sign in again to retry.';
  }
  return null;
}

