  client.destroy();
  const provStorage = sdk.createMemoryAdapter();
  await provStorage.set(
    sessionKey,
    JSON.stringify({
      clientSessionId: 'cs-prov',
      userId: 'u',
      status: 'CONSUMED',
      token: { accessToken: 'AT', refreshToken: 'RT', expiresAt: Math.floor(Date.now() / 1000) + 600 },
      user: { ready: true },
