  const wsPrevFetch = globalThis.fetch;
  let wsReported = 'CREATING';
  let wsStateCalls = 0;
  globalThis.fetch = async (req) => {
    if (req.url.includes('/wallet/state')) {
      wsStateCalls++;
      return new Response(
        JSON.stringify({
          success: true,
          code: 'SDK_WALLET_STATE',
