      ['https://example.com/v1/foo?q=1#frag', 'https://example.com/v1/foo'],
      ['https://example.com/v1/foo/?q=1#frag', 'https://example.com/v1/foo/'],
      ['https://user:pass@example.com/x', 'https://example.com/x'],
      ['http://[::1]:8080/v1', 'http://[::1]:8080/v1'],
      ['http://[::1]:80/v1', 'http://[::1]/v1'],
    ];
    for (const [input, expected] of cases) {
