// @pollar smoke test — client lifecycle: teardown leaves nothing behind.
//
// Run with `node tests/smoke-lifecycle.cjs` after `npm run build`. For the
// reachability block, run it with `--expose-gc` (the npm script does); without
// the flag that block is skipped, not failed.
//
// Why this file exists: `PollarClient` registers itself in a MODULE-level
// registry (`liveClientsByApiKey`) so a logout can be announced to sibling
// instances in the same document. A module-level map holding client references
// is a leak waiting to happen - registration and deregistration have to agree
// on exactly when they run, and nothing enforced that agreement. These are the
// assertions that do.
//
// Nothing here reaches into private state. The registry is observed through the
// behavior it drives (the "another client is already active" warning) and,
// where the flag allows, through actual reachability.

const path = require('node:path');
const { spawnSync } = require('node:child_process');

const winListeners = { storage: new Set() };
globalThis.window = {
  location: { origin: 'https://x.test', href: 'https://x.test/' },
  addEventListener: (type, cb) => (winListeners[type] ??= new Set()).add(cb),
  removeEventListener: (type, cb) => winListeners[type]?.delete(cb),
  open: () => null,
};
globalThis.localStorage = { getItem: () => null, setItem: () => {}, removeItem: () => {} };
globalThis.document = { addEventListener: () => {}, removeEventListener: () => {}, visibilityState: 'visible' };
globalThis.fetch = async () => new Response(JSON.stringify({ success: true, content: {} }), { status: 200 });

const SDK_DIST = path.resolve(__dirname, '../packages/core/dist/index.js');
const sdk = require(SDK_DIST);

let pass = 0;
let fail = 0;
let skipped = 0;
function check(label, ok, extra) {
  if (ok) {
    pass++;
    console.log(`  OK    ${label}`);
  } else {
    fail++;
    console.log(`  FAIL  ${label}`, extra ?? '');
  }
}
function skip(label, why) {
  skipped++;
  console.log(`  SKIP  ${label} (${why})`);
}

/** A logger that records the "another client is already active" warning. */
function makeLogger() {
  const state = { collisionWarnings: 0, warnings: [] };
  const noop = () => {};
  return {
    state,
    logger: {
      debug: noop,
      info: noop,
      error: noop,
      warn: (msg) => {
        state.warnings.push(String(msg));
        if (String(msg).includes('Another PollarClient is already active')) state.collisionWarnings++;
      },
    },
  };
}

function newClient(apiKey, logger) {
  return new sdk.PollarClient({ apiKey, storage: sdk.createMemoryAdapter(), baseUrl: 'https://x.test', logger });
}

(async () => {
  console.log('── 1. The collision warning actually fires (positive control) ──');
  {
    // Without this, every "no warning" assertion below could pass for the wrong
    // reason (a detector that never fires proves nothing).
    const { state, logger } = makeLogger();
    const a = newClient('pk_lifecycle_control', logger);
    const b = newClient('pk_lifecycle_control', logger);
    check('two live clients on one API key warn', state.collisionWarnings === 1, `warnings=${state.collisionWarnings}`);
    a.destroy();
    b.destroy();
  }

  console.log('\n── 2. destroy() deregisters the client ───────────────────────');
  {
    // The registry is per API key, so a leaked entry from a destroyed client
    // makes the NEXT client on that key look like a collision.
    const { state, logger } = makeLogger();
    for (let i = 0; i < 25; i++) newClient('pk_lifecycle_cycle', logger).destroy();
    const after = newClient('pk_lifecycle_cycle', logger);
    check(
      '25 construct/destroy cycles leave no entry behind',
      state.collisionWarnings === 0,
      `warnings=${state.collisionWarnings}`,
    );
    after.destroy();
  }

  console.log('\n── 3. destroy() is idempotent ────────────────────────────────');
  {
    // A double destroy must not over-deregister and hide a real collision.
    const { state, logger } = makeLogger();
    const a = newClient('pk_lifecycle_idem', logger);
    const b = newClient('pk_lifecycle_idem', logger);
    state.collisionWarnings = 0;
    b.destroy();
    b.destroy();
    b.destroy();
    const c = newClient('pk_lifecycle_idem', logger);
    check(
      'a still-live sibling is still detected after a triple destroy',
      state.collisionWarnings === 1,
      `warnings=${state.collisionWarnings}`,
    );
    a.destroy();
    c.destroy();
  }

  console.log('\n── 4. destroy() detaches the cross-tab storage listener ──────');
  {
    const before = winListeners.storage.size;
    const a = newClient('pk_lifecycle_listener');
    await a.ready();
    check('a live client is listening for `storage`', winListeners.storage.size === before + 1);
    a.destroy();
    check('  destroy() removes the listener', winListeners.storage.size === before, `size=${winListeners.storage.size}`);
  }

  console.log('\n── 5. A destroyed client ignores a sibling teardown ──────────');
  {
    // The in-document logout announcement iterates the registry. A destroyed
    // client must be gone from it; if it lingered, it would run a teardown (and
    // emit auth state) after the host tore it down.
    const a = newClient('pk_lifecycle_sibling');
    const b = newClient('pk_lifecycle_sibling');
    await Promise.all([a.ready(), b.ready()]);
    let statesAfterDestroy = 0;
    b.onAuthStateChange(() => statesAfterDestroy++);
    b.destroy();
    statesAfterDestroy = 0;
    await a.logout();
    await new Promise((r) => setTimeout(r, 30));
    check('no auth state emitted to the destroyed sibling', statesAfterDestroy === 0, `emissions=${statesAfterDestroy}`);
    a.destroy();
  }

  console.log('\n── 6. A destroyed client becomes unreachable ─────────────────');
  {
    if (typeof globalThis.gc !== 'function') {
      skip('destroyed client is garbage-collectable', 'run with --expose-gc');
    } else {
      // Hold the client ONLY through an array we then empty. A plain `const`
      // inside this async function would be kept alive by the function's own
      // context for the rest of the block, and the assertion would then fail on
      // the test's scope rather than on anything the SDK retains.
      let holder = [newClient('pk_lifecycle_gc')];
      await holder[0].ready();
      holder[0].destroy();
      const ref = new WeakRef(holder[0]);
      holder.length = 0;
      holder = null;
      // Two collections with a turn of the loop between them: the first drops
      // the object, the second clears any finalization-pending state.
      await new Promise((r) => setTimeout(r, 20));
      globalThis.gc();
      await new Promise((r) => setTimeout(r, 10));
      globalThis.gc();
      check('a destroyed client is collectable (registry holds no strong ref)', ref.deref() === undefined);
    }
  }

  console.log('\n── 7. A server-side client leaks nothing ─────────────────────');
  {
    // Server-rendered code builds one client per request and never destroys it,
    // so nothing module-level may hold on to it. Today the constructor returns
    // before it would register, which is what makes this hold; the assertion
    // guards that property against a refactor that registers earlier. Run in a
    // child process with NO window/localStorage so `isClientRuntime` is false.
    const child = spawnSync(
      process.execPath,
      [
        '--expose-gc',
        '-e',
        `
        const sdk = require(${JSON.stringify(SDK_DIST)});
        let ref;
        {
          // No window/localStorage here: this is the SSR path.
          const c = new sdk.PollarClient({ apiKey: 'pk_ssr_leak', baseUrl: 'https://x.test',
            logger: { debug(){}, info(){}, warn(){}, error(){} } });
          ref = new WeakRef(c);
        }
        setTimeout(() => {
          gc(); gc();
          console.log(ref.deref() === undefined ? 'COLLECTED' : 'RETAINED');
        }, 20);
        `,
      ],
      { encoding: 'utf8', timeout: 20_000 },
    );
    const out = (child.stdout || '').trim().split('\n').pop();
    if (child.error || (out !== 'COLLECTED' && out !== 'RETAINED')) {
      skip('server-side client is not retained', `child failed: ${child.error?.message ?? child.stderr?.slice(0, 200)}`);
    } else {
      check('a server-side client is not retained by the module registry', out === 'COLLECTED', out);
    }
  }

  console.log('\n── 8. A failing sibling cannot abort our own teardown ───────');
  {
    // The in-document announcement is a courtesy call made on behalf of OTHER
    // instances. It used to run before the clearing client emitted `idle`, and
    // nothing guarded it: a sibling that threw (a logger sink that chokes is
    // the realistic version) left the clearing client reporting `authenticated`
    // with its session row already gone - and `logout()` swallows the error, so
    // nothing pointed at the sibling that caused it.
    const quiet = { debug() {}, info() {}, warn() {}, error() {} };
    const hostile = {
      debug() {},
      warn() {},
      error() {},
      info: (m) => {
        if (String(m).includes('cleared by another client')) throw new Error('sibling logger blew up');
      },
    };
    const storage = sdk.createMemoryAdapter();
    const apiKey = 'pk_lifecycle_hostile_sibling';

    const seed = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test', logger: quiet });
    await seed.ready();
    const sessionKey = `pollar:${seed.apiKeyHash}:session`;
    await storage.set(
      sessionKey,
      JSON.stringify({
        clientSessionId: 'cs1',
        userId: 'u1',
        status: 'CONSUMED',
        token: { accessToken: 'AT', refreshToken: 'RT', expiresAt: Math.floor(Date.now() / 1000) + 600 },
        user: { ready: true },
        wallet: { type: 'internal', address: 'G' },
      }),
    );
    seed.destroy();

    const origin = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test', logger: quiet });
    const sibling = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test', logger: hostile });
    await Promise.all([origin.ready(), sibling.ready()]);
    await new Promise((r) => setTimeout(r, 40));
    check(
      '(baseline) both instances hold the session',
      origin.getAuthState().step === 'authenticated' && sibling.getAuthState().step === 'authenticated',
    );

    await origin.logout();
    await new Promise((r) => setTimeout(r, 40));
    check('the clearing client still converges to idle', origin.getAuthState().step === 'idle', origin.getAuthState().step);
    check('  and its session row is gone', (await storage.get(sessionKey)) == null);
    origin.destroy();
    sibling.destroy();
  }

  console.log(`\n${pass} pass, ${fail} fail${skipped ? `, ${skipped} skip` : ''}`);
  process.exit(fail ? 1 : 0);
})().catch((err) => {
  console.error('FATAL:', err);
  process.exit(1);
});

// @pollar smoke test — built-in auth providers + wallet-adapter dispatch.
//
// Run with `node tests/smoke-providers.cjs` after `pnpm build`. Mocks `fetch`,
// `localStorage` and `window` so PollarClient runs as if in a browser.
//
// NOTE: `config.providers` (registering arbitrary custom auth providers) was
// REMOVED when wallet integrations were unified into `config.walletAdapters`.
// So this file now covers (a) the built-in email provider via `login()` /
// `providerAction()`, and (b) the wallet-adapter dispatch path that replaced
// custom providers (`login({ provider: adapter.type })` -> loginWithAdapter).

const path = require('node:path');

globalThis.window = {
  location: { origin: 'https://x.test', href: 'https://x.test/' },
  addEventListener: () => {},
  removeEventListener: () => {},
  open: () => null,
};
globalThis.localStorage = { getItem: () => null, setItem: () => {}, removeItem: () => {} };

const SDK_DIST = path.resolve(__dirname, '../packages/core/dist/index.js');
const sdk = require(SDK_DIST);

let pass = 0;
let fail = 0;
function check(label, ok, extra) {
  if (ok) {
    pass++;
    console.log(`  OK    ${label}`);
  } else {
    fail++;
    console.log(`  FAIL  ${label}`, extra ?? '');
  }
}

async function waitFor(cond, timeoutMs = 1000) {
  const start = Date.now();
  while (!cond()) {
    if (Date.now() - start > timeoutMs) throw new Error('waitFor: condition not met within timeout');
    await new Promise((r) => setTimeout(r, 5));
  }
}

(async () => {
  const apiKey = 'pk_smoke_providers';

  // fetch mock: only the endpoints the email flow + construction touch.
  const calls = [];
  // One-shot: when set, the next /auth/email/verify-code answers with this server
  // error code (e.g. SDK_EMAIL_CODE_EXPIRED / INVALID_EMAIL_CODE).
  let nextVerifyCode = null;
  // When set, /auth/wallet/challenge returns this XDR (used by the SEP-10 test).
  let walletChallengeXdr = null;
  globalThis.fetch = async (req) => {
    const url = req.url;
    let body = null;
    try {
      body = await req.clone().json();
    } catch {}
    calls.push({ url, method: req.method, body });
    if (url.includes('/auth/session') && !url.includes('/status') && !url.includes('/resume')) {
      return new Response(JSON.stringify({ success: true, content: { clientSessionId: 'cs_test' } }), { status: 200 });
    }
    // Order matters: '/auth/wallet/challenge' contains '/auth/wallet'.
    if (url.includes('/auth/wallet/challenge')) {
      return new Response(JSON.stringify({ success: true, content: { challengeXdr: walletChallengeXdr } }), { status: 200 });
    }
    if (url.includes('/auth/wallet')) {
      return new Response(JSON.stringify({ success: true, content: {} }), { status: 200 });
    }
    if (url.includes('/auth/email/verify-code') && nextVerifyCode) {
      const code = nextVerifyCode;
      nextVerifyCode = null;
      return new Response(JSON.stringify({ success: false, code }), { status: 200 });
    }
    // /auth/email and /auth/email/verify-code: success but NO SDK_EMAIL_CODE_VERIFIED
    // code, so verify lands on the generic EMAIL_VERIFY_FAILED branch (block 4).
    if (url.includes('/auth/email')) {
      return new Response(JSON.stringify({ success: true, content: {} }), { status: 200 });
    }
    return new Response(JSON.stringify({ success: true, content: {} }), { status: 200 });
  };

  // A wallet adapter whose isAvailable() parks at a gate — to prove a cancel
  // during the wallet flow maps to `idle` (AbortError rethrow), not an error.
  let releaseGate;
  const gate = new Promise((r) => {
    releaseGate = r;
  });
  let gatedProbed = false;
  const gatedAdapter = {
    type: 'gated',
    meta: { label: 'Gated' },
    isAvailable: async () => {
      await gate;
      gatedProbed = true;
      return false;
    },
    connect: async () => ({ address: 'G' }),
    signTransaction: async () => ({ signedTxXdr: 'x' }),
    signAuthEntry: async () => ({ signedAuthEntry: 'x' }),
  };

  // A wallet adapter whose isAvailable() throws SYNCHRONOUSLY — must be routed to
  // an error state, not thrown out of login()'s public API.
  const throwingAdapter = {
    type: 'throwing',
    meta: { label: 'Throwing' },
    isAvailable: () => {
      throw new Error('sync boom');
    },
    connect: async () => ({ address: 'G' }),
    signTransaction: async () => ({ signedTxXdr: 'x' }),
    signAuthEntry: async () => ({ signedAuthEntry: 'x' }),
  };

  console.log('── 1. Construction with wallet adapters ──────────────────────');
  const client = new sdk.PollarClient({
    apiKey,
    storage: sdk.createMemoryAdapter(),
    baseUrl: 'https://x.test',
    walletAdapters: [gatedAdapter, throwingAdapter],
  });
  await client.ready();
  check('client.ready() resolves', true);
  check(
    'listWalletAdapters() reports the built-ins + the two custom adapters',
    client
      .listWalletAdapters()
      .map((a) => a.id)
      .sort()
      .join(',') === 'albedo-native,freighter-native,gated,throwing',
    JSON.stringify(client.listWalletAdapters().map((a) => a.id)),
  );

  console.log('\n── 2. built-in email provider works via login() ──────────────');
  calls.length = 0;
  client.login({ provider: 'email', email: 'a@b.test' });
  await waitFor(() => calls.some((c) => c.url.includes('/auth/email')));
  check(
    'email login created a session',
    calls.some((c) => c.url.endsWith('/auth/session')),
  );
  check(
    '  POST /auth/email fired with the address',
    calls.find((c) => c.url.includes('/auth/email'))?.body?.email === 'a@b.test',
  );

  console.log('\n── 3. unknown provider → clean error state ───────────────────');
  client.login({ provider: 'does_not_exist' });
  await waitFor(() => client.getAuthState().step === 'error');
  check('unknown provider sets error state', client.getAuthState().step === 'error');

  console.log('\n── 4. email verify generic failure is retryable (B1) ─────────');
  client.login({ provider: 'email', email: 'retry@b.test' });
  await waitFor(() => client.getAuthState().step === 'entering_code');
  client.verifyEmailCode('000000');
  await waitFor(() => client.getAuthState().errorCode === sdk.AUTH_ERROR_CODES.EMAIL_VERIFY_FAILED);
  check(
    'generic verify failure → EMAIL_VERIFY_FAILED',
    client.getAuthState().errorCode === sdk.AUTH_ERROR_CODES.EMAIL_VERIFY_FAILED,
  );
  check('  error state carries clientSessionId so it can retry', !!client.getAuthState().clientSessionId);
  let verifyThrew = false;
  try {
    client.verifyEmailCode('111111'); // retryable now — no synchronous PollarFlowError
  } catch {
    verifyThrew = true;
  }
  check('  verifyEmailCode is retryable after a generic failure (no throw)', verifyThrew === false);

  console.log('\n── 5. providerAction rejects an unknown action ───────────────');
  let actionThrew = false;
  try {
    client.providerAction('email', 'nope');
  } catch (e) {
    actionThrew = e && e.code === 'INVALID_FLOW';
  }
  check('unknown action throws PollarFlowError(INVALID_FLOW)', actionThrew);

  console.log('\n── 6. cancel during a wallet flow maps to idle, not error ────');
  client.login({ provider: 'gated' }); // parks at adapter.isAvailable()
  client.cancelLogin(); // aborts the signal
  check('cancelLogin set idle', client.getAuthState().step === 'idle', client.getAuthState().step);
  releaseGate(); // adapter.isAvailable() resolves now (flow already aborted)
  await waitFor(() => gatedProbed);
  await new Promise((r) => setTimeout(r, 10));
  check(
    '  the cancelled wallet flow did NOT clobber idle (AbortError → idle)',
    client.getAuthState().step === 'idle',
    client.getAuthState().step,
  );

  console.log('\n── 7. a wallet adapter that throws synchronously is handled ───');
  let loginThrew = false;
  try {
    client.login({ provider: 'throwing' }); // adapter.isAvailable() throws synchronously
  } catch {
    loginThrew = true;
  }
  check('login() did not throw out of the public API', loginThrew === false);
  await waitFor(() => client.getAuthState().errorCode === sdk.AUTH_ERROR_CODES.WALLET_CONNECT_FAILED);
  check(
    '  the synchronous throw was routed to a WALLET_CONNECT_FAILED error state',
    client.getAuthState().step === 'error' && client.getAuthState().errorCode === sdk.AUTH_ERROR_CODES.WALLET_CONNECT_FAILED,
    `${client.getAuthState().step}/${client.getAuthState().errorCode}`,
  );

  console.log('\n── 8. email flow validates a blank email before the API ──────');
  calls.length = 0;
  client.login({ provider: 'email', email: '' }); // missing email
  await waitFor(() => client.getAuthState().errorCode === sdk.AUTH_ERROR_CODES.EMAIL_SEND_FAILED);
  check(
    'blank email → error (EMAIL_SEND_FAILED), not an opaque API 400',
    client.getAuthState().step === 'error' && client.getAuthState().errorCode === sdk.AUTH_ERROR_CODES.EMAIL_SEND_FAILED,
  );
  check(
    '  no blank email was POSTed to /auth/email',
    !calls.some((c) => c.url.includes('/auth/email') && !c.url.includes('verify-code')),
    JSON.stringify(calls.map((c) => c.url)),
  );
  check(
    '  and no orphaned /auth/session was minted (providers.ts up-front guard)',
    !calls.some((c) => c.url.endsWith('/auth/session')),
    JSON.stringify(calls.map((c) => c.url)),
  );

  console.log('\n── 9. listWalletAdapters sanitizes adapter iconUrl (_safeMeta) ──');
  {
    const mk = (type, iconUrl) => ({
      type,
      meta: { label: type, iconUrl },
      isAvailable: async () => true,
      connect: async () => ({ address: 'G' }),
      signTransaction: async () => ({ signedTxXdr: 'x' }),
      signAuthEntry: async () => ({ signedAuthEntry: 'x' }),
    });
    const c = new sdk.PollarClient({
      apiKey: 'pk_safe_meta',
      storage: sdk.createMemoryAdapter(),
      baseUrl: 'https://x.test',
      logLevel: 'silent',
      walletAdapters: [
        mk('a-https', 'https://ok/x.png'),
        mk('b-data', 'data:image/png;base64,AAA'),
        mk('c-http', 'http://evil/x.png'),
        mk('d-js', 'javascript:alert(1)'),
      ],
    });
    await c.ready();
    const byId = Object.fromEntries(c.listWalletAdapters().map((a) => [a.id, a.meta.iconUrl]));
    check('https: iconUrl kept', byId['a-https'] === 'https://ok/x.png');
    check('  data:image/ iconUrl kept', byId['b-data'] === 'data:image/png;base64,AAA');
    check('  http:// iconUrl dropped (anti tracking-beacon)', byId['c-http'] === undefined, byId['c-http']);
    check('  javascript: iconUrl dropped', byId['d-js'] === undefined, byId['d-js']);
    c.destroy();
  }

  console.log('\n── 10. typed email methods throw from the wrong step ─────────');
  {
    const gc = new sdk.PollarClient({
      apiKey: 'pk_guards',
      storage: sdk.createMemoryAdapter(),
      baseUrl: 'https://x.test',
      logLevel: 'silent',
    });
    await gc.ready(); // idle, no session
    let sendThrew = false;
    try {
      gc.sendEmailCode('x@y.z');
    } catch (e) {
      sendThrew = e && e.code === 'INVALID_FLOW';
    }
    check("sendEmailCode() from a non-'entering_email' step throws PollarFlowError", sendThrew, gc.getAuthState().step);
    let verThrew = false;
    try {
      gc.verifyEmailCode('000000');
    } catch (e) {
      verThrew = e && e.code === 'INVALID_FLOW';
    }
    check("  verifyEmailCode() from a non-'entering_code' step throws PollarFlowError", verThrew, gc.getAuthState().step);
    gc.destroy();
  }

  console.log('\n── 11. email verify maps EXPIRED / INVALID server codes ──────');
  {
    client.login({ provider: 'email', email: 'exp@b.test' });
    await waitFor(() => client.getAuthState().step === 'entering_code');
    nextVerifyCode = 'SDK_EMAIL_CODE_EXPIRED';
    client.verifyEmailCode('111111');
    await waitFor(() => client.getAuthState().errorCode === sdk.AUTH_ERROR_CODES.EMAIL_CODE_EXPIRED);
    check(
      'SDK_EMAIL_CODE_EXPIRED → EMAIL_CODE_EXPIRED',
      client.getAuthState().errorCode === sdk.AUTH_ERROR_CODES.EMAIL_CODE_EXPIRED,
    );

    client.login({ provider: 'email', email: 'inv@b.test' });
    await waitFor(() => client.getAuthState().step === 'entering_code');
    nextVerifyCode = 'INVALID_EMAIL_CODE';
    client.verifyEmailCode('222222');
    await waitFor(() => client.getAuthState().errorCode === sdk.AUTH_ERROR_CODES.EMAIL_CODE_INVALID);
    check(
      '  INVALID_EMAIL_CODE → EMAIL_CODE_INVALID',
      client.getAuthState().errorCode === sdk.AUTH_ERROR_CODES.EMAIL_CODE_INVALID,
    );
  }

  console.log('\n── 12. redactDeep surfaces Error message, redacts secret props ──');
  {
    const logs = [];
    const spyLogger = { error: (...a) => logs.push(a), warn() {}, info() {}, debug() {} };
    const boomAdapter = {
      type: 'boom',
      meta: { label: 'Boom' },
      isAvailable: () => {
        const e = new Error('adapter-boom'); // message is a NON-enumerable Error prop
        e.accessToken = 'SUPERSECRET'; // enumerable sensitive prop → must be redacted
        e.code = 'ADAPTER_X'; // diagnostic → must be preserved (response-key semantics)
        throw e;
      },
      connect: async () => ({ address: 'G' }),
      signTransaction: async () => ({ signedTxXdr: 'x' }),
      signAuthEntry: async () => ({ signedAuthEntry: 'x' }),
    };
    const c = new sdk.PollarClient({
      apiKey: 'pk_redact',
      storage: sdk.createMemoryAdapter(),
      baseUrl: 'https://x.test',
      logger: spyLogger,
      walletAdapters: [boomAdapter],
    });
    await c.ready();
    logs.length = 0;
    c.login({ provider: 'boom' });
    await waitFor(() => c.getAuthState().errorCode === sdk.AUTH_ERROR_CODES.WALLET_CONNECT_FAILED);
    const dump = JSON.stringify(logs);
    check('Error.message surfaced from a non-enumerable prop', dump.includes('adapter-boom'), dump.slice(0, 200));
    check('  enumerable sensitive prop redacted (no token leak)', dump.includes('[redacted]') && !dump.includes('SUPERSECRET'));
    check('  diagnostic code preserved', dump.includes('ADAPTER_X'));
    check('  route tagged with the phase', dump.includes('wallet connect (connecting_wallet)'));
    c.destroy();
  }

  console.log('\n── 13. client-side SEP-10 validation refuses a non-zero-seq challenge ──');
  {
    // Craft a v1 (ENVELOPE_TYPE_TX=2) envelope; the only field the client-side
    // check reads is the tx seqNum at byte offset 44 — 0 = real challenge, != 0 =
    // a live submittable tx (must be refused before the wallet signs).
    const makeChallengeXdr = (seqNonZero) => {
      const buf = new Uint8Array(60);
      const dv = new DataView(buf.buffer);
      dv.setUint32(0, 2, false); // envelopeType = TX (v1)
      dv.setUint32(4, 0, false); // MuxedAccount keyType = ED25519
      // 32-byte ed25519 key at 8..40 = zeros
      dv.setUint32(40, 100, false); // fee
      dv.setUint32(44, 0, false); // seqNum high word
      dv.setUint32(48, seqNonZero ? 1 : 0, false); // seqNum low word
      return Buffer.from(buf).toString('base64');
    };
    const adapter = {
      type: 'sep10',
      meta: { label: 'S' },
      isAvailable: async () => true,
      connect: async () => ({ address: 'Gwallet' }),
      signTransaction: async () => ({ signedTxXdr: 'SIGNED' }),
      signAuthEntry: async () => ({ signedAuthEntry: 'x' }),
    };
    const c = new sdk.PollarClient({
      apiKey: 'pk_sep10',
      storage: sdk.createMemoryAdapter(),
      baseUrl: 'https://x.test',
      logLevel: 'silent',
      walletAdapters: [adapter],
    });
    await c.ready();
    const walletSubmitCalled = () => calls.some((x) => x.url.includes('/auth/wallet') && !x.url.includes('challenge'));

    // Negative: non-zero seq → rejected, wallet never asked to sign.
    calls.length = 0;
    walletChallengeXdr = makeChallengeXdr(true);
    c.login({ provider: 'sep10' });
    await waitFor(() => c.getAuthState().step === 'error');
    check(
      'non-zero-seq challenge → WALLET_AUTH_FAILED error',
      c.getAuthState().errorCode === sdk.AUTH_ERROR_CODES.WALLET_AUTH_FAILED,
      c.getAuthState().errorCode,
    );
    check('  previousStep = signing_wallet_challenge', c.getAuthState().previousStep === 'signing_wallet_challenge');
    check('  /auth/wallet NEVER called (wallet not asked to sign a live tx)', !walletSubmitCalled());

    // Positive: seq=0 → validation passes, flow reaches the wallet + POST /auth/wallet.
    calls.length = 0;
    walletChallengeXdr = makeChallengeXdr(false);
    c.login({ provider: 'sep10' });
    await waitFor(() => walletSubmitCalled());
    check('seq=0 challenge → flow proceeds to POST /auth/wallet', walletSubmitCalled());
    c.destroy();
    walletChallengeXdr = null;
  }

  console.log('\n── 14. request-body OTP `code` is masked in logs (redactBody) ──');
  {
    const logs = [];
    const spyLogger = { error: (...a) => logs.push(a), warn() {}, info() {}, debug() {} };
    const c = new sdk.PollarClient({
      apiKey: 'pk_reqmask',
      storage: sdk.createMemoryAdapter(),
      baseUrl: 'https://x.test',
      logger: spyLogger,
    });
    await c.ready();
    c.login({ provider: 'email', email: 'mask@b.test' });
    await waitFor(() => c.getAuthState().step === 'entering_code');
    logs.length = 0;
    c.verifyEmailCode('987654'); // generic failure path logs the request body {clientSessionId, code}
    await waitFor(() => c.getAuthState().errorCode === sdk.AUTH_ERROR_CODES.EMAIL_VERIFY_FAILED);
    const dump = JSON.stringify(logs);
    check(
      'the OTP code is masked in the request-body log',
      dump.includes('"code":"[redacted]"') && !dump.includes('987654'),
      dump.slice(0, 220),
    );
    c.destroy();
  }

  console.log(`\n${fail === 0 ? '✅' : '❌'} providers smoke: ${pass} passed, ${fail} failed`);
  process.exit(fail === 0 ? 0 : 1);
})().catch((err) => {
  console.error('FATAL', err);
  process.exit(1);
});

const assert = require('node:assert/strict');
const path = require('node:path');
const ts = require('typescript');

const program = ts.createProgram([path.join(__dirname, 'ramp-chain.types.ts')], {
  noEmit: true,
  strict: true,
  skipLibCheck: true,
  module: ts.ModuleKind.ESNext,
  moduleResolution: ts.ModuleResolutionKind.Bundler,
  target: ts.ScriptTarget.ES2020,
});
const diagnostics = ts.getPreEmitDiagnostics(program);
assert.equal(
  diagnostics.length,
  0,
  ts.formatDiagnosticsWithColorAndContext(diagnostics, {
    getCurrentDirectory: () => process.cwd(),
    getCanonicalFileName: (file) => file,
    getNewLine: () => '\n',
  }),
);
console.log('Ramp chain types: closed catalog across web, native and all generated ramp API fields passed.');

const assert = require('node:assert/strict');
const sdk = require('../packages/core/dist/index.js');
const native = require('../packages/core/dist/index.rn.js');

const route = { asset: { chain: 'POLYGON', network: 'mainnet' } };
const snapshot = {
  txId: 'enum-fixture',
  status: 'pending',
  transactionVersion: 1,
  chain: 'POLYGON',
  terms: { assetChain: 'POLYGON', cryptoAmount: '9007199254740993.123456789012', fiatAmount: '20.00' },
  nextAction: {
    kind: 'sign_transaction',
    actionId: 'enum-action',
    chain: 'POLYGON',
    network: 'mainnet',
    payload: { encoding: 'fixture-json', value: 'unsigned' },
    expiresAt: new Date(Date.now() + 60_000).toISOString(),
  },
};
const invalid = ['solana', 'polygon', 'SOLONA', 'FUTURE_CHAIN', 'eip155:137', '', null];
const error = /Unsupported ramp chain/;

async function main() {
  assert.deepEqual(sdk.RampChain, { STELLAR: 'STELLAR', POLYGON: 'POLYGON', SOLANA: 'SOLANA' });
  assert.deepEqual(native.RampChain, sdk.RampChain);
  assert.equal(Object.isFrozen(sdk.RampChain), true);
  const client = new sdk.PollarClient({ apiKey: 'fixture', logLevel: 'silent' });
  client.destroy();
  let signs = 0;
  let continuations = 0;
  client.continueRamp = async () => {
    continuations++;
    return snapshot;
  };
  for (const chain of Object.values(sdk.RampChain)) {
    const current = { ...snapshot, chain, nextAction: { ...snapshot.nextAction, chain } };
    client.getRampTransaction = async () => current;
    const cleanup = client.registerRampSigningHandler(chain, 'fixture-json', async () => {
      signs++;
      return 'signed';
    });
    await client.signRampAction(current.txId, current);
    cleanup();
  }
  assert.equal(signs, 3);
  assert.equal(continuations, 3);
  for (const chain of invalid) {
    assert.throws(() => client.registerRampSigningHandler(chain, 'fixture-json', async () => 'signed'), error);
    const current = { ...snapshot, nextAction: { ...snapshot.nextAction, chain } };
    client.getRampTransaction = async () => current;
    await assert.rejects(client.signRampAction(current.txId, current), error);
  }
  assert.equal(signs, 3);
  assert.equal(continuations, 3);

  let content = snapshot;
  let requests = 0;
  const api = {
    GET: async () => {
      requests++;
      return { data: { content } };
    },
    POST: async () => ({ data: { content } }),
  };
  for (const chain of invalid) await assert.rejects(sdk.getRampsQuote(api, { chain }), error);
  assert.equal(requests, 0);
  const transactions = [
    () => sdk.createOnRamp(api, {}),
    () => sdk.createOffRamp(api, {}),
    () => sdk.completeWithdraw(api, snapshot.txId),
    () => sdk.submitRampSignature(api, snapshot.txId, {}),
    () => sdk.getRampTransaction(api, snapshot.txId),
    () => sdk.continueRamp(api, snapshot.txId, {}),
  ];
  for (const chain of Object.values(sdk.RampChain)) {
    content = {
      ...snapshot,
      chain,
      terms: { ...snapshot.terms, assetChain: chain },
      nextAction: { ...snapshot.nextAction, chain },
    };
