      check('  no resume round trip was attempted (dpopJkt precheck)', resumeHits === 0, `hits=${resumeHits}`);
      check('  no phantom authenticated state was emitted', !states.includes('authenticated'), `states=${states.join(',')}`);
      check('  session removed from storage', (await storage.get(`pollar:${b.apiKeyHash}:session`)) == null);
      b.destroy();
    } finally {
      globalThis.indexedDB = savedIdb;
    }
  }

  console.log('\n── 3b. ensurePersisted() only trusts OUR key ──────────────────');
  {
    const apiKey = 'pk_smoke_resume_foreignkey';
    const savedIdb = globalThis.indexedDB;
    try {
      globalThis.indexedDB = makeIndexedDB();
      const km = new sdk.WebCryptoKeyManager(apiKey);
      await km.init();
      check('a freshly persisted keypair reads back as ours', (await km.ensurePersisted()) === true);

      // Another tab rotated the shared row between our put and our get. A shape
      // check accepts it, login binds the in-memory key, and the next reload
      // adopts the other one - the thumbprint-mismatch logout, back again.
      const foreign = await globalThis.crypto.subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, false, [
        'sign',
        'verify',
      ]);
      globalThis.indexedDB = makeIndexedDB({ readAs: foreign });
      check("  a stored keypair that isn't ours is reported as not persisted", (await km.ensurePersisted()) === false);
    } finally {
      globalThis.indexedDB = savedIdb;
    }
  }

  console.log('\n── 4. Non-terminal resume failure backs off (no burst) ────────');
  {
    const apiKey = 'pk_smoke_resume_backoff';
    const storage = sdk.createMemoryAdapter();
    const a = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test' });
    await a.ready();
    await login(a);
    a.destroy();

    resumeMode = 'error-500';
    resumeHits = 0;
    const vis = makeVisibility();
    const b = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test', visibilityProvider: vis.provider });
    await b.ready();
    await waitFor(() => resumeHits >= 1);
    await sleep(50); // let the failure register and arm the backoff
    vis.flap();
    vis.flap();
    await sleep(100);
    check('5xx keeps the optimistic session', b.getAuthState().step === 'authenticated' && !b.getAuthState().verified);
    check('  retriggers during backoff are suppressed', resumeHits === 1, `hits=${resumeHits}`);
    b.destroy();
    resumeMode = 'verify';
  }

  console.log('\n── 6. Cross-tab logout→re-login: stale key cache resyncs ──────');
  {
    // Tab A and tab B share the persisted key (IndexedDB) + session storage.
    // A logs out (rotates the shared key) and logs in again with a NEW key;
    // B — still caching the OLD key in memory — must adopt the new one when
    // the fresh session arrives, not clear it as a binding mismatch.
    const apiKey = 'pk_smoke_resume_xtab';
    const storage = sdk.createMemoryAdapter();
    const a = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test' });
    await a.ready();
    await login(a);
    const sessionKey = `pollar:${a.apiKeyHash}:session`;

    const b = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test' });
    await b.ready(); // the storage handler registers inside async _initialize
    const bHandler = storageHandlers.at(-1);
    await waitFor(() => b.getAuthState().step === 'authenticated' && b.getAuthState().verified === true);
    const jktBeforeLogout = serverBoundJkt;

    // Tab A logs out → key reset + storage removed. Deliver the event to B.
    await a.logout();
    bHandler({ key: sessionKey, newValue: null });
    await waitFor(() => b.getAuthState().step === 'idle');

    // Tab A logs in again → a NEW keypair is generated and bound.
    await login(a);
    check('re-login bound a fresh keypair', serverBoundJkt !== jktBeforeLogout);

    // Deliver the new session to B: it must resync to the new shared key and
    // resume — not clear the session tab A just created.
    bHandler({ key: sessionKey, newValue: await storage.get(sessionKey) });
    await waitFor(() => b.getAuthState().step === 'authenticated' && b.getAuthState().verified === true);
    check('tab B adopts the rotated key and resumes the new session', true);
    check('  resume proof used the NEW key', resumeProofJkts.at(-1) === serverBoundJkt);
    check('  the new session was not cleared from storage', (await storage.get(sessionKey)) != null);
    a.destroy();
    b.destroy();
  }

  console.log('\n── 7. logout() cancels an in-flight login (no resurrection) ───');
  {
    const apiKey = 'pk_smoke_resume_logoutrace';
    const storage = sdk.createMemoryAdapter();
    const a = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test' });
    await a.ready();
    serverBoundJkt = null;
    loginDelayMs = 300; // hold the /auth/login response so logout lands mid-flight
    a.beginEmailLogin();
    await waitFor(() => a.getAuthState().step === 'entering_email');
    a.sendEmailCode('a@b.c');
    await waitFor(() => a.getAuthState().step === 'entering_code');
    a.verifyEmailCode('123456');
    await waitFor(() => serverBoundJkt !== null); // the login POST reached the server
    await a.logout(); // user logs out while the login response is still pending
    await sleep(500); // let the held login response land
    loginDelayMs = 0;
    const sessionKey = `pollar:${a.apiKeyHash}:session`;
    check('state stays idle after the login response lands', a.getAuthState().step === 'idle', a.getAuthState().step);
    check('  no session row was resurrected in storage', (await storage.get(sessionKey)) == null);
    a.destroy();
  }

  console.log('\n── 8. dpopJkt records the BOUND key, not the store-time key ───');
  {
    // A key manager whose getThumbprint LIES at store time models a rotation
    // between the login's bind and its store. The persisted dpopJkt must come
    // from the JWK actually sent to /auth/login (= cnf.jkt), not from this.
    const apiKey = 'pk_smoke_resume_boundjkt';
    const storage = sdk.createMemoryAdapter();
    const real = new sdk.WebCryptoKeyManager(apiKey);
    const lying = {
      init: () => real.init(),
      reset: () => real.reset(),
      getPublicJwk: () => real.getPublicJwk(),
      getThumbprint: async () => 'STORE-TIME-KEY-NOT-THE-BOUND-ONE',
      sign: (payload) => real.sign(payload),
    };
    const a = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test', keyManager: lying });
    await a.ready();
    await login(a);
    const stored = JSON.parse(await storage.get(`pollar:${a.apiKeyHash}:session`));
    check('persisted dpopJkt === server cnf.jkt (bound key wins)', stored.dpopJkt === serverBoundJkt, stored.dpopJkt);
    a.destroy();
  }

  console.log('\n── 9. init() joins a half-built in-flight init ────────────────');
  {
    // _doInit assigns keyPair, THEN awaits the JWK export. Hold the export open
    // and call getThumbprint() inside that window: it must join the in-flight
    // init instead of early-returning into a half-built manager and throwing.
    const realExport = crypto.subtle.exportKey.bind(crypto.subtle);
    crypto.subtle.exportKey = async (...args) => {
      await sleep(50);
      return realExport(...args);
    };
    try {
      const km = new sdk.WebCryptoKeyManager('pk_smoke_resume_halfinit');
      const p1 = km.init();
      const start = Date.now();
      while (!km.keyPair && Date.now() - start < 2000) await sleep(1);
      check('window is open (keyPair set, publicJwk pending)', !!km.keyPair && !km.publicJwk);
      let thumb = null;
      let threw = null;
      try {
        thumb = await km.getThumbprint();
      } catch (e) {
        threw = e.message;
      }
      check('getThumbprint during the window resolves (no half-built throw)', threw === null && !!thumb, threw);
      await p1;
    } finally {
      crypto.subtle.exportKey = realExport;
    }
  }

  console.log('\n── 10. logout() does not destroy a session created during it ──');
  {
    // `logout()` awaits the server call, and consumers routinely do not await it
    // (@pollar/react fires it from the login modal and the wallet button, then
    // opens the login UI). A whole new login can land inside that window: the
    // teardown must recognize it and leave it alone, or the user "logs in" and
    // is thrown straight back out with the key that session was bound to gone.
    const apiKey = 'pk_smoke_resume_logout_race';
    const storage = sdk.createMemoryAdapter();
    const a = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test' });
    await a.ready();
    await login(a);

    logoutDelayMs = 150;
    const pending = a.logout(); // deliberately NOT awaited
    await sleep(10);
    await login(a); // the user signs in again while the logout is still running
    const jktAfterLogin = serverBoundJkt;
    await pending;
    await sleep(20);
    logoutDelayMs = 0;

    check('the session created during the logout survives', a.getAuthState().step === 'authenticated', a.getAuthState().step);
    const row = await storage.get(`pollar:${a.apiKeyHash}:session`);
    check('  its row is still in storage', row != null);
    check(
      '  the keypair it is bound to was not rotated away',
      (await new sdk.WebCryptoKeyManager(apiKey).getThumbprint()) === jktAfterLogin,
    );
    check('  persisted dpopJkt still matches cnf.jkt', row != null && JSON.parse(row).dpopJkt === jktAfterLogin);
    a.destroy();
  }

  console.log('\n── 11. logout() only rotates the key it still owns ────────────');
  {
    // The keypair record is shared per origin + API key, MORE shared than the
    // session row. A client whose session was superseded must not destroy the
    // key the current row's session is bound to.
    const apiKey = 'pk_smoke_resume_logout_owner';
    const storage = sdk.createMemoryAdapter();
    const a = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test' });
    await a.ready();
    await login(a);
    const sharedJkt = await new sdk.WebCryptoKeyManager(apiKey).getThumbprint();

    // Another document logs in later and becomes the owner of the shared row.
    const sessionKey = `pollar:${a.apiKeyHash}:session`;
    const owned = JSON.parse(await storage.get(sessionKey));
    owned.clientSessionId = 'cs_other_document';
    await storage.set(sessionKey, JSON.stringify(owned));

    await a.logout();
    const after = await storage.get(sessionKey);
    check(
      'the row it no longer owns is left alone',
      after != null && JSON.parse(after).clientSessionId === 'cs_other_document',
    );
    check(
      '  and so is the keypair that row is bound to',
      (await new sdk.WebCryptoKeyManager(apiKey).getThumbprint()) === sharedJkt,
    );
    a.destroy();
  }

  console.log('\n── 12. a logout propagates to siblings in the SAME document ───');
  {
    // Browsers never deliver `storage` events to the document that wrote the
    // change, so a second instance in this one (React StrictMode double-invokes
    // the useState initializer and leaves one behind, never destroyed) used to
    // keep its session and re-persist the row after the other logged out.
    const apiKey = 'pk_smoke_resume_siblings';
    const storage = sdk.createMemoryAdapter();
    const a = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test' });
    await a.ready();
    await login(a);
    const b = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test' });
    await b.ready();
    await waitFor(() => b.getAuthState().step === 'authenticated');
    check(
      'both instances hold the session',
      a.getAuthState().step === 'authenticated' && b.getAuthState().step === 'authenticated',
    );

    await a.logout();
    await sleep(30);
    check('  the sibling converges to idle', b.getAuthState().step === 'idle', b.getAuthState().step);
    await b.refresh().catch(() => {});
    await sleep(30);
    check('  and does not re-persist the row', (await storage.get(`pollar:${b.apiKeyHash}:session`)) == null);
    a.destroy();
    b.destroy();
  }

  console.log('\n── 13. the DPoP nonce survives a page load ────────────────────');
  {
    // Every proof needs a server nonce, so without persistence the first
    // authenticated request of EVERY page load is a guaranteed 401 challenge.
    const apiKey = 'pk_smoke_resume_nonce';
    const storage = sdk.createMemoryAdapter();
    const a = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test' });
    await a.ready();
    await login(a);
    a.destroy();
    // A login alone never signs a proof (its calls are pre-auth), so the first
    // nonce arrives on the first RELOAD's resume: challenge + retry = 2 hits.
    resumeHits = 0;
    const b = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test' });
    await b.ready();
    await waitFor(() => b.getAuthState().verified === true);
    check('first reload pays the challenge and learns a nonce', resumeHits === 2, `hits=${resumeHits}`);
    check(
      '  the nonce is persisted under the apiKeyHash namespace',
      (await storage.get(`pollar:${b.apiKeyHash}:dpopNonce`)) === 'N1',
    );
    b.destroy();

    // Every reload after that signs its first proof with the stored nonce.
    resumeHits = 0;
    const c = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test' });
    await c.ready();
    await waitFor(() => c.getAuthState().verified === true);
    check('  the NEXT reload resumes in ONE hit (challenge skipped)', resumeHits === 1, `hits=${resumeHits}`);
    c.destroy();
  }

  console.log('\n── 14. superseded logout leaves the wallet adapter connected ──');
  {
    // Same race as block 10, from an EXTERNAL-wallet session: the logout's
    // adapter disconnect must sit BEHIND the generation guard. Registered
    // adapters are per-type singletons, so the "old" adapter reference can be
    // the very instance a login that lands mid-logout is now using —
    // disconnecting it would cut the new session's provider connection.
    const apiKey = 'pk_smoke_resume_adapter_race';
    const storage = sdk.createMemoryAdapter();
    let disconnects = 0;
    const adapter = {
      type: 'mockwallet',
      meta: { label: 'Mock' },
      chain: 'STELLAR',
      isAvailable: async () => true,
      connect: async () => ({ address: 'GMOCK' }),
      disconnect: async () => {
        disconnects++;
      },
      getPublicKey: async () => 'GMOCK',
      signTransaction: async () => ({ signedTxXdr: 'X' }),
    };

    // Seed an EXTERNAL session bound to the current persisted keypair, plus the
    // walletType row, so the client restores with the adapter attached — the
    // exact state a returning external-wallet user is in when they hit logout.
    const kmJkt = await new sdk.WebCryptoKeyManager(apiKey).getThumbprint();
    serverBoundJkt = kmJkt;
    await storage.set(
      `pollar:${await hashKey(apiKey)}:session`,
      JSON.stringify({
        clientSessionId: 'cs_ext',
        userId: 'u1',
        status: 'CONSUMED',
        token: { accessToken: 'AT_EXT', refreshToken: 'RT_EXT', expiresAt: Math.floor(Date.now() / 1000) + 600 },
        user: { ready: true },
        dpopJkt: kmJkt,
        wallet: { type: 'external', address: 'GMOCK' },
      }),
    );
    await storage.set(`pollar:${await hashKey(apiKey)}:walletType`, 'mockwallet');

    const a = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test', walletAdapters: [adapter] });
    await a.ready();
    await waitFor(() => a.getAuthState().step === 'authenticated' && a.getAuthState().verified === true);
    check('external session restored with the adapter attached', a.getWalletType() === 'mockwallet', a.getWalletType());

    logoutDelayMs = 150;
    const pending = a.logout(); // NOT awaited — the UI pattern
    await sleep(10);
    await login(a); // a new login completes while the logout awaits the server
    await pending;
    await sleep(20);
    logoutDelayMs = 0;

    check('the mid-logout login survives (generation guard)', a.getAuthState().step === 'authenticated');
    check('  the adapter was NOT disconnected by the superseded logout', disconnects === 0, `disconnects=${disconnects}`);

    // Baseline: an owned, un-raced logout of an external session DOES disconnect.
    // Re-seed the external state (the login above switched to an internal session).
    await a.logout();
    await waitFor(() => a.getAuthState().step === 'idle');
    check('  (baseline) the un-raced logout ran to completion', a.getAuthState().step === 'idle');
    a.destroy();

    const b = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test', walletAdapters: [adapter] });
    await b.ready();
    const kmJkt2 = await new sdk.WebCryptoKeyManager(apiKey).getThumbprint();
    serverBoundJkt = kmJkt2;
    await storage.set(
      `pollar:${b.apiKeyHash}:session`,
      JSON.stringify({
        clientSessionId: 'cs_ext2',
        userId: 'u1',
        status: 'CONSUMED',
        token: { accessToken: 'AT_EXT2', refreshToken: 'RT_EXT2', expiresAt: Math.floor(Date.now() / 1000) + 600 },
        user: { ready: true },
        dpopJkt: kmJkt2,
        wallet: { type: 'external', address: 'GMOCK' },
      }),
    );
    await storage.set(`pollar:${b.apiKeyHash}:walletType`, 'mockwallet');
    b.destroy();
    const c = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test', walletAdapters: [adapter] });
    await c.ready();
    await waitFor(() => c.getAuthState().step === 'authenticated' && c.getAuthState().verified === true);
    disconnects = 0;
    await c.logout();
    check(
      '  (baseline) an owned external logout disconnects the adapter once',
      disconnects === 1,
      `disconnects=${disconnects}`,
    );
    c.destroy();
  }

  console.log(`\n${pass} pass, ${fail} fail`);
  process.exit(fail ? 1 : 0);
})().catch((err) => {
  console.error('FATAL:', err);
  process.exit(1);
});

// React Native KYC + ramp gate: the real containers, with react-native mocked as
// plain components so their buttons and inputs can be driven from Node.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const ts = require('typescript');
const { JSDOM } = require('jsdom');

const dom = new JSDOM('<!doctype html><html><body></body></html>', { url: 'https://test.invalid/' });
globalThis.window = dom.window;
globalThis.document = dom.window.document;
// Node 20, the CI runtime, has no global navigator; react-dom reads it on load.
globalThis.navigator = dom.window.navigator;
globalThis.IS_REACT_ACT_ENVIRONMENT = true;
const React = require('react');
const { createRoot } = require('react-dom/client');
const core = require('../packages/core/dist/index.js');

let buttons = [];
let inputs = [];
let routes = [];
const opened = [];
let appStateListener = null;
const passthrough = ({ children }) => React.createElement(React.Fragment, null, children);
const reactNative = {
  View: passthrough,
  ScrollView: passthrough,
  Text: passthrough,
  TouchableOpacity: (props) => {
    buttons.push(props);
    return React.createElement(React.Fragment, null, props.children);
  },
  TextInput: (props) => {
    inputs.push(props);
    return null;
  },
  ActivityIndicator: () => null,
  StyleSheet: { create: (s) => s, absoluteFillObject: {} },
  Linking: { openURL: async (url) => opened.push(url) },
  AppState: {
    addEventListener: (_event, listener) => {
      appStateListener = listener;
      return { remove: () => (appStateListener = null) };
    },
  },
};

let client;
const pollarContext = { getClient: () => client, walletAddress: 'wallet', styles: {}, ramp: null, setRamp() {} };

function load(file) {
  const filename = path.resolve(__dirname, '..', file);
  const output = ts.transpileModule(fs.readFileSync(filename, 'utf8'), {
    compilerOptions: { module: ts.ModuleKind.CommonJS, jsx: ts.JsxEmit.ReactJSX, target: ts.ScriptTarget.ES2022 },
  }).outputText;
  const scope = { exports: {}, setInterval, clearInterval, setTimeout, clearTimeout, globalThis };
  scope.require = (id) => {
    if (id === 'react-native') return reactNative;
    if (id === '@pollar/core') return core;
    if (id === 'react-native-qrcode-svg') return () => null;
    if (id === 'react-native-safe-area-context') return { SafeAreaProvider: passthrough, SafeAreaView: passthrough };
    if (id === '../../context' || id === '../context') return { usePollar: () => pollarContext };
    if (id === '../commons') return { PollarModalFooter: () => null, PollarOverlay: passthrough };
    if (id === './KycStatus') return { KycStatus: () => null };
    if (id === './RouteDisplay') {
      return {
        RouteDisplay: (props) => {
          routes.push(props);
          return null;
        },
      };
    }
    if (id === '../kyc-modal/KycModal') return load('packages/react-native/src/components/kyc-modal/KycModal.tsx');
    if (id.startsWith('.')) {
      // Containers (.tsx) and helpers (.ts) import each other without an extension.
      const base = path.join(path.dirname(file), id);
      return load(fs.existsSync(path.resolve(__dirname, '..', `${base}.tsx`)) ? `${base}.tsx` : `${base}.ts`);
    }
    return require(id);
  };
  vm.runInNewContext(output, scope);
  return scope.exports;
}

const label = (props) => {
  const child = props.children;
  const text = child && child.props ? child.props.children : child;
  return Array.isArray(text) ? text.join('') : String(text);
};
function press(text) {
  const match = [...buttons].reverse().find((b) => label(b) === text);
  assert.ok(match, `button "${text}" not rendered; have: ${[...new Set(buttons.map(label))].join(', ')}`);
  return React.act(async () => match.onPress());
}
const has = (text) => buttons.some((b) => label(b) === text);
async function render(element) {
  const container = document.createElement('div');
  const root = createRoot(container);
  buttons = [];
  await React.act(async () => root.render(element));
  return async () => React.act(async () => root.unmount());
}

const { RampWidget } = load('packages/react-native/src/components/ramp-widget/RampWidget.tsx');
const { KycModal } = load('packages/react-native/src/components/kyc-modal/KycModal.tsx');
const gate = new core.PollarApiError('SDK_RAMPS_KYC_REQUIRED', {
  code: 'SDK_RAMPS_KYC_REQUIRED',
  rampProviderId: 'ramp-a',
  kycProviderId: 'option-a',
  corridorId: 'corridor-a',
});
const option = { id: 'option-a', name: 'Didit', flow: 'iframe', levels: ['basic'] };

(async () => {
  // KYC modal: opens the gate's option, hands the URL to the browser, checks on return.
  let decisions = 0;
  client = {
    getKycProviders: async (_country, corridorId) => {
      assert.equal(corridorId, 'corridor-a');
      return { providers: [option] };
    },
    resolveKyc: async () => ({ alreadyApproved: false, sessionId: 's', kycUrl: 'https://kyc.example/s' }),
    pollKycDecision: async () => {
      decisions++;
      return { status: 'pending', decisionStatus: 'manual_review', reviewReason: 'DUPLICATE_DOCUMENT' };
    },
  };
  let unmount = await render(
    React.createElement(KycModal, { onClose() {}, country: 'BO', corridorId: 'corridor-a', providerId: 'option-a' }),
  );
  await press('Open verification');
  assert.deepEqual(opened, ['https://kyc.example/s']);
  await React.act(async () => appStateListener('active'));
  assert.equal(decisions, 1);
  assert.ok(has('Check again')); // manual review settles into the review result
  await unmount();

  // Ramp: gate -> KYC on the named option -> approval -> fresh quotes -> user picks.
  let quoteCalls = 0;
  const starts = [];
  client = {
    getRampRoutes: async () => ({ routes: [] }),
    getRampCountries: async () => ({ countries: [{ code: 'BO', currency: 'BOB' }] }),
    getRampsQuote: async () => {
      quoteCalls++;
      return { quotes: [{ quoteId: quoteCalls === 1 ? 'first' : 'fresh', provider: 'Stereum' }] };
    },
    createOnRamp: async (body) => {
      starts.push(body);
      if (starts.length === 1) throw gate;
      return { txId: 'tx', provider: 'Stereum', status: 'pending_user_transfer_start' };
    },
    getRampTransaction: async () => ({ status: 'pending_user_transfer_start' }),
    getKycProviders: async () => ({ providers: [option] }),
    resolveKyc: async () => ({ alreadyApproved: true }),
  };
  client.getRampRoutes = async () => ({ routes: [] });
  routes = [];
  unmount = await render(React.createElement(RampWidget, { onClose() {} }));
  await React.act(async () => inputs[inputs.length - 1].onChangeText('10'));
  routes = [];
  await press('Find routes');
  assert.equal(quoteCalls, 1);
  const first = routes[routes.length - 1];
  assert.equal(first.quote.quoteId, 'first');
  routes = [];
  await React.act(async () => first.onSelect(first.quote));
  // The modal auto-opened the named option and it was already approved: back to fresh quotes.
  assert.equal(quoteCalls, 2);
  assert.equal(starts.length, 1); // approval never starts an order by itself
  const fresh = routes[routes.length - 1];
  assert.equal(fresh.quote.quoteId, 'fresh');
  await React.act(async () => fresh.onSelect(fresh.quote));
  assert.equal(starts.length, 2);
  assert.equal(starts[1].quoteId, 'fresh');
  assert.equal(starts[1].amount, 10);
  await unmount();

  // Quote-time gate: a route with a pending step arrives in `requirementsRequired`, not in `quotes`.
  const locked = {
    provider: 'Stereum',
    rampProviderId: 'ramp-b',
    corridorId: 'corridor-b',
    position: 1,
    completed: 0,
    total: 1,
    type: 'KYC',
    optionId: 'option-b',
    status: 'none',
  };
  quoteCalls = 0;
  starts.length = 0;
  const resolved = [];
  client = {
    getRampRoutes: async () => ({ routes: [] }),
    getRampCountries: async () => ({ countries: [{ code: 'BO', currency: 'BOB' }] }),
    getRampsQuote: async () => {
      quoteCalls++;
      return quoteCalls === 1
        ? { quotes: [], requirementsRequired: [locked] }
        : { quotes: [{ quoteId: 'unlocked', provider: 'Stereum' }] };
    },
    createOnRamp: async (body) => {
      starts.push(body);
      return { txId: 'tx', provider: 'Stereum', status: 'pending_user_transfer_start' };
    },
    getRampTransaction: async () => ({ status: 'pending_user_transfer_start' }),
    getKycProviders: async (country, corridorId) => {
      assert.equal(country, 'BO');
      assert.equal(corridorId, 'corridor-b');
      return { providers: [{ ...option, id: 'option-b' }] };
    },
    resolveKyc: async (providerId, _level, _country, corridorId) => {
      resolved.push({ providerId, corridorId });
      return { alreadyApproved: true };
    },
  };
  client.getRampRoutes = async () => ({ routes: [] });
  routes = [];
  unmount = await render(React.createElement(RampWidget, { onClose() {} }));
  await React.act(async () => inputs[inputs.length - 1].onChangeText('10'));
  routes = [];
  await press('Find routes');
  assert.equal(quoteCalls, 1);
  assert.equal(routes.length, 0);
  assert.ok(has('Verify')); // the locked row, not the "no providers" error
  assert.ok(!has('Try again'));
  routes = [];
  await press('Verify');
  assert.deepEqual(resolved, [{ providerId: 'option-b', corridorId: 'corridor-b' }]);
  assert.equal(quoteCalls, 2); // approval re-quotes the same input
  assert.equal(starts.length, 0);
  const unlocked = routes[routes.length - 1];
  assert.equal(unlocked.quote.quoteId, 'unlocked');
  await React.act(async () => unlocked.onSelect(unlocked.quote));
  assert.equal(starts.length, 1);
  assert.equal(starts[0].quoteId, 'unlocked');
  assert.equal(starts[0].amount, 10);
  await unmount();

  console.log('React Native: hosted KYC opens in the browser and checks on return; ramp gate re-quotes after approval');
  console.log('React Native: a route locked by KYC shows instead of "no providers"; Verify opens its option and re-quotes');
  dom.window.close();
})().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

// @pollar smoke test — session-lifecycle race safety (Tier-1 hardening).
//
// Run with `node tests/smoke-session-races.cjs` after `npm run build`. Mocks
// `fetch`/`localStorage`/`window` so PollarClient runs as if in a browser and
// no network is required. Each block exercises one of the concurrency fixes:
//
//   A. destroy() during an in-flight refresh discards the rotated token
//      (no write-after-teardown, no resurrected session).
//   B. refresh() is a no-op after destroy() (no zombie network call).
//   C. getAuthState() returns a defensive clone — mutating it can't corrupt
//      the live _session the request middleware signs with.
//   D. logout() aborts an in-flight /auth/session/resume so it can't re-emit
//      `authenticated` after the client has gone `idle`.
//   E. A concurrent request does NOT inherit/throw a rejecting refresh.

const path = require('node:path');

// Capture DOM event listeners so the cross-tab `storage` handler can be fired
// synthetically (no real multi-tab environment in node).
const winListeners = {};
globalThis.window = {
  location: { origin: 'https://x.test', href: 'https://x.test/' },
  addEventListener: (type, cb) => {
    (winListeners[type] ??= new Set()).add(cb);
  },
  removeEventListener: (type, cb) => {
    winListeners[type]?.delete(cb);
  },
};
function dispatchStorageEvent(key, newValue = null) {
  // newValue === null mimics a cross-tab remove/clear (logout); a string mimics
  // a cross-tab set (login / token rotation).
  for (const cb of winListeners.storage ?? []) cb({ key, newValue });
}
globalThis.localStorage = { getItem: () => null, setItem: () => {}, removeItem: () => {} };

const SDK_DIST = path.resolve(__dirname, '../packages/core/dist/index.js');
const sdk = require(SDK_DIST);

let pass = 0;
let fail = 0;
function check(label, ok, extra) {
  if (ok) {
    pass++;
    console.log(`  OK    ${label}`);
  } else {
    fail++;
    console.log(`  FAIL  ${label}`, extra ?? '');
  }
}

async function waitFor(cond, timeoutMs = 1000) {
  const start = Date.now();
  while (!cond()) {
    if (Date.now() - start > timeoutMs) throw new Error('waitFor: condition not met within timeout');
    await new Promise((r) => setTimeout(r, 5));
  }
}

// A delay that rejects with an AbortError when the request's signal fires, so
// the resume GET behaves like a real cancellable fetch.
function delay(ms, signal) {
  return new Promise((resolve, reject) => {
    const t = setTimeout(resolve, ms);
    if (signal) {
      if (signal.aborted) {
        clearTimeout(t);
        reject(Object.assign(new Error('aborted'), { name: 'AbortError' }));
        return;
      }
      signal.addEventListener('abort', () => {
        clearTimeout(t);
        reject(Object.assign(new Error('aborted'), { name: 'AbortError' }));
      });
    }
  });
}

// Current namespace width is 16 bytes / 32 hex (see lib/api-key-hash.ts).
async function hashOf(apiKey, bytes) {
  const digest = await globalThis.crypto.subtle.digest('SHA-256', new TextEncoder().encode(apiKey));
  return Array.from(new Uint8Array(digest).slice(0, bytes))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}
const apiKeyHashOf = (apiKey) => hashOf(apiKey, 16);
const legacyApiKeyHashOf = (apiKey) => hashOf(apiKey, 4); // pre-0.10 width

function freshSession(accessToken = 'AT', expiresInSec = 600) {
  return JSON.stringify({
    clientSessionId: 'cs',
    userId: 'u',
    status: 'CONSUMED',
    token: { accessToken, refreshToken: 'RT', expiresAt: Math.floor(Date.now() / 1000) + expiresInSec },
    user: { ready: true },
    wallet: { type: 'internal', address: null },
  });
}

// Mutable mock knobs, reset per block.
const mock = {
  calls: [],
  refreshDelayMs: 0,
  refreshStatus: 200,
  // When true, the FIRST /auth/refresh hangs for `refreshSlowDelayMs` (default
  // 3000ms) then later attempts are fast — exercises request-timeout + retry.
  refreshSlowOnce: false,
  refreshSlowDelayMs: 3000,
  resumeDelayMs: 0,
  // When set, the next /tx/history responds with a DPoP nonce challenge (401)
  // using the given WWW-Authenticate value, then succeeds on retry.
  txNonceChallengeWwwAuth: null,
  // Override the expiresAt the refresh endpoint returns (e.g. null to mimic a
  // malformed/NaN value). undefined → a normal future timestamp.
  refreshExpiresAt: undefined,
  // Per-cursor response delays (ms) for /tx/history, keyed by the `cursor` query
  // param, to force a specific response ordering for the concurrent-fetch test.
  txHistoryDelays: {},
  // HTTP status for /auth/session/resume (200 success; 403/410 = revoked;
  // 5xx/404 = transient/not-found).
  resumeStatus: 200,
  // When non-zero, /tx/history responses carry a `Date` header offset from local
  // time by this many seconds, to exercise DPoP clock-skew compensation.
  serverDateOffsetSec: 0,
  // When true, the next /auth/refresh responds with a DPoP nonce challenge (401),
  // then succeeds on retry — to assert the retry resends the POST body.
  refreshNonceChallengeOnce: false,
  // When true, the next /tx/history returns a 500 whose body nests token material
  // — to assert it's redacted in the error log.
  txHistoryErrorWithToken: false,
  // Raw `Date` header string to put on /tx/history responses (overrides the
  // offset-based one). Used to test that an implausible Date is ignored.
  serverDateOverride: null,
  // Marker echoed as /tx/build content (buildData) so a test can tell which tx
  // a buildData belongs to.
  buildMarker: 'BUILD',
  // When true, /tx/submit answers 200 with `{success:false, code, message}` (a
  // failure carried in a 2xx envelope) to assert the code/message is surfaced.
  txSubmitFail2xx: false,
  // Delay (ms) before /tx/submit responds — to keep a submit in flight while a
  // logout lands, for the post-logout tx-state guard test.
  txSubmitDelayMs: 0,
  // When true, the FIRST /tx/history stalls `txHistorySlowDelayMs` (so it times
  // out), then later attempts are fast — to exercise the GET retry path.
  txHistorySlowOnce: false,
  txHistorySlowDelayMs: 3000,
};

globalThis.fetch = async (req) => {
  const headers = {};
  req.headers.forEach((v, k) => (headers[k] = v));
  let body = '';
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    try {
      body = await req.clone().text();
    } catch {}
  }
  mock.calls.push({ url: req.url, method: req.method, headers, body });

  if (req.url.includes('/auth/refresh')) {
    if (mock.refreshNonceChallengeOnce) {
      mock.refreshNonceChallengeOnce = false; // one-shot: the retry below succeeds
      return new Response(JSON.stringify({ success: false }), {
        status: 401,
        headers: { 'WWW-Authenticate': 'DPoP error="use_dpop_nonce"', 'DPoP-Nonce': 'refresh-nonce-1' },
      });
    }
    // One-shot stall: the FIRST refresh hangs past the client's request timeout
    // (so it aborts/times out), then subsequent attempts are fast — used to
    // exercise the request-timeout + retry behavior.
    if (mock.refreshSlowOnce) {
      mock.refreshSlowOnce = false;
      await delay(mock.refreshSlowDelayMs ?? 3000, req.signal);
    }
    if (mock.refreshDelayMs) await delay(mock.refreshDelayMs, req.signal);
    if (mock.refreshStatus !== 200) {
      return new Response(JSON.stringify({ success: false, message: 'nope' }), { status: mock.refreshStatus });
    }
    const expiresAt = mock.refreshExpiresAt !== undefined ? mock.refreshExpiresAt : Math.floor(Date.now() / 1000) + 600;
    return new Response(
      JSON.stringify({
        success: true,
        content: { token: { accessToken: 'NEW_AT', refreshToken: 'NEW_RT', expiresAt } },
      }),
      { status: 200 },
    );
  }
  if (req.url.includes('/auth/session/resume')) {
    if (mock.resumeDelayMs) await delay(mock.resumeDelayMs, req.signal);
    if (mock.resumeStatus !== 200) {
      return new Response(JSON.stringify({ success: false }), { status: mock.resumeStatus });
    }
    return new Response(JSON.stringify({ success: true, content: { mail: 'a@b.c' } }), { status: 200 });
  }
  if (req.url.includes('/tx/history') && mock.txNonceChallengeWwwAuth) {
    const www = mock.txNonceChallengeWwwAuth;
    mock.txNonceChallengeWwwAuth = null; // one-shot: the retry below succeeds
    return new Response(JSON.stringify({ success: false }), {
      status: 401,
      headers: { 'WWW-Authenticate': www, 'DPoP-Nonce': 'srv-nonce-1' },
    });
  }
  if (req.url.includes('/tx/history')) {
    if (mock.txHistorySlowOnce) {
      mock.txHistorySlowOnce = false; // one-shot stall → the retried GET is fast
      await delay(mock.txHistorySlowDelayMs ?? 3000, req.signal);
    }
    if (mock.txHistoryErrorWithToken) {
      mock.txHistoryErrorWithToken = false;
      return new Response(
        JSON.stringify({
          success: false,
          code: 'TX_FEE_LIMIT_EXCEEDED', // diagnostic — must stay visible in logs
          content: { token: { accessToken: 'SECRET_AT', refreshToken: 'SECRET_RT' } },
        }),
        { status: 500, headers: { 'content-type': 'application/json' } },
      );
    }
    // Delay by the `cursor` query param so the test controls response ordering
    // independent of which request reaches the mock first.
    const cursor = new URL(req.url).searchParams.get('cursor');
    const d = (cursor && mock.txHistoryDelays[cursor]) || 0;
    if (d) await delay(d, req.signal);
    const respHeaders = {};
    if (mock.serverDateOverride) respHeaders.Date = mock.serverDateOverride;
    else if (mock.serverDateOffsetSec) respHeaders.Date = new Date(Date.now() + mock.serverDateOffsetSec * 1000).toUTCString();
    return new Response(JSON.stringify({ success: true, content: { ok: true, cursor } }), {
      status: 200,
      headers: respHeaders,
    });
  }
  // NOTE: check the compound custodial paths BEFORE /tx/build and /tx/submit —
  // '/tx/build-sign-submit' contains the substring '/tx/build'.
  if (req.url.includes('/tx/build-sign-submit')) {
    return new Response(JSON.stringify({ success: true, content: { hash: 'HASH_BSS', status: 'SUCCESS' } }), { status: 200 });
  }
  if (req.url.endsWith('/tx/sign')) {
    // Custodial signTx: backend returns the signed XDR + an idempotencyKey.
    return new Response(
      JSON.stringify({ success: true, content: { signedXdr: 'SIGNED_CUSTODIAL', idempotencyKey: 'IDEM_1' } }),
      { status: 200 },
    );
  }
  if (req.url.includes('/tx/build')) {
    return new Response(JSON.stringify({ success: true, content: { marker: mock.buildMarker, amount: '5' } }), { status: 200 });
  }
  if (req.url.includes('/tx/submit')) {
    if (mock.txSubmitDelayMs) await delay(mock.txSubmitDelayMs, req.signal);
    if (mock.txSubmitFail2xx) {
      return new Response(JSON.stringify({ success: false, code: 'TX_FEE_LIMIT_EXCEEDED', message: 'fee too high' }), {
        status: 200,
      });
    }
    // mock.txSubmitStatus (default 'SUCCESS') lets a test exercise the PENDING branch.
    const status = mock.txSubmitStatus ?? 'SUCCESS';
    return new Response(JSON.stringify({ success: true, content: { hash: 'HASH', status } }), { status: 200 });
  }
  // tx/history, logout, everything else.
  return new Response(JSON.stringify({ success: true, content: {} }), { status: 200 });
};

async function makeClient(apiKey, { seed = true, accessToken = 'AT', expiresInSec = 600, waitResume = true } = {}) {
  const storage = sdk.createMemoryAdapter();
  const hash = await apiKeyHashOf(apiKey);
  const sessionKey = `pollar:${hash}:session`;
  if (seed) await storage.set(sessionKey, freshSession(accessToken, expiresInSec));
  const client = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test', logLevel: 'silent' });
  await client.ready();
  if (seed && waitResume) {
    await waitFor(() => mock.calls.some((c) => c.url.includes('/auth/session/resume')));
  }
  return { client, storage, sessionKey };
}

(async () => {
  // ── A. destroy() during in-flight refresh discards the rotated token ───────
  console.log('── A. destroy() mid-refresh discards the result ──────────────');
  {
    mock.calls = [];
    mock.refreshDelayMs = 80;
    mock.refreshStatus = 200;
    const { client, storage, sessionKey } = await makeClient('pk_race_A');
    mock.calls = [];

    const rp = client.refresh(); // in-flight (resolves in ~80ms)
    client.destroy(); // teardown while the refresh is on the wire
    await rp;

    const persisted = JSON.parse(await storage.get(sessionKey));
    check(
      'refresh did NOT write the rotated token after destroy',
      persisted.token.accessToken === 'AT',
      persisted.token.accessToken,
    );

    const before = mock.calls.length;
    await new Promise((r) => setTimeout(r, 30));
    check('no zombie refresh fired after destroy', mock.calls.length === before);
    mock.refreshDelayMs = 0;
  }

  // ── B. refresh() is a no-op after destroy() ────────────────────────────────
  console.log('\n── B. refresh() no-ops after destroy() ───────────────────────');
  {
    mock.calls = [];
    const { client } = await makeClient('pk_race_B');
    client.destroy();
    mock.calls = [];
    await client.refresh();
    const refreshCalls = mock.calls.filter((c) => c.url.includes('/auth/refresh'));
    check('refresh() after destroy fires no network call', refreshCalls.length === 0);
  }

  // ── C. getAuthState() returns a defensive clone ────────────────────────────
  console.log('\n── C. getAuthState() is a defensive clone ────────────────────');
  {
    mock.calls = [];
    const { client } = await makeClient('pk_race_C');
    const a = client.getAuthState();
    const b = client.getAuthState();
    check('two getAuthState() calls return distinct objects', a !== b);
    check(
      '  and distinct session objects',
      a.step === 'authenticated' && b.step === 'authenticated' && a.session !== b.session,
    );

    // Attempt to corrupt the live session through the returned object (token AND
    // the nested user object — R1: the clone must cover `user` too).
    if (a.step === 'authenticated') {
      a.session.token.accessToken = 'HACKED';
      a.session.user.ready = false;
    }
    mock.calls = [];
    await client.fetchTxHistory();
    const auth = mock.calls.find((c) => c.url.includes('/tx/history'))?.headers.authorization;
    check('request still signs with the real token, not the mutated one', auth === 'DPoP AT', auth);
    const live = client.getAuthState();
    check(
      'mutating the returned session.user did not corrupt live state',
      live.step === 'authenticated' && live.session.user.ready === true,
    );
    client.destroy();
  }

  // ── D. logout() aborts an in-flight resume (no authenticated after idle) ───
  console.log('\n── D. logout() aborts in-flight resume ───────────────────────');
  {
    mock.calls = [];
    mock.resumeDelayMs = 120; // resume stays in flight long enough to race logout
    const states = [];
    const storage = sdk.createMemoryAdapter();
    const hash = await apiKeyHashOf('pk_race_D');
    await storage.set(`pollar:${hash}:session`, freshSession());
    const client = new sdk.PollarClient({ apiKey: 'pk_race_D', storage, baseUrl: 'https://x.test', logLevel: 'silent' });
    client.onAuthStateChange((s) => states.push(s.step + (s.step === 'authenticated' ? `:${s.verified}` : '')));
    await client.ready();
    await waitFor(() => mock.calls.some((c) => c.url.includes('/auth/session/resume')));

    await client.logout(); // resume is still in flight (120ms)
    await new Promise((r) => setTimeout(r, 200)); // let the (aborted) resume settle

    check('final auth state is idle', client.getAuthState().step === 'idle', client.getAuthState().step);
    check(
      '  no authenticated emission after logout went idle',
      states.lastIndexOf('idle') === states.length - 1,
      JSON.stringify(states),
    );
    mock.resumeDelayMs = 0;
    client.destroy();
  }

  // ── E. concurrent request does not inherit a rejecting refresh ─────────────
  console.log('\n── E. concurrent request survives a rejecting refresh ────────');
  {
    mock.calls = [];
    mock.refreshDelayMs = 60;
    mock.refreshStatus = 401; // refresh will reject → _doRefresh throws + clears session
    const { client } = await makeClient('pk_race_E');
    mock.calls = [];

    const rp = client.refresh().catch(() => 'refresh-rejected'); // expected to reject internally
    let txThrew = false;
    // Fire a normal request while the refresh is in flight; its onRequest awaits
    // the shared refresh promise. It must NOT re-throw the refresh's rejection.
    const txp = client.fetchTxHistory().catch((err) => {
      txThrew = true;
      return err;
    });
    await Promise.all([rp, txp]);
    check('concurrent request did not throw the refresh rejection', txThrew === false);
    mock.refreshDelayMs = 0;
    mock.refreshStatus = 200;
    client.destroy();
  }

  // ── F. DPoP nonce challenge is classified case-insensitively (N1) ──────────
  console.log('\n── F. DPoP nonce challenge case-insensitive (N1) ─────────────');
  {
    mock.calls = [];
    const { client } = await makeClient('pk_race_F');
    mock.calls = [];
    // Server (or a proxy) returns the challenge in a non-canonical casing.
    mock.txNonceChallengeWwwAuth = 'DPoP error="USE_DPOP_NONCE"';
    await client.fetchTxHistory(); // must transparently retry with the nonce

    const txCalls = mock.calls.filter((c) => c.url.includes('/tx/history'));
    const refreshCalls = mock.calls.filter((c) => c.url.includes('/auth/refresh'));
    check('nonce challenge triggered exactly one retry (2 tx calls)', txCalls.length === 2, txCalls.length);
    check('  classified as nonce, NOT token-expiry → no spurious refresh', refreshCalls.length === 0, refreshCalls.length);
    const retryNonce = txCalls[1]?.headers.dpop
      ? JSON.parse(Buffer.from(txCalls[1].headers.dpop.split('.')[1], 'base64url').toString()).nonce
      : null;
    check('  retry proof carries the server nonce', retryNonce === 'srv-nonce-1', retryNonce);
    client.destroy();
  }

  // ── G. cross-tab token rotation keeps `verified`, skips resume (N2) ────────
  console.log('\n── G. cross-tab rotation keeps verified, no re-resume (N2) ───');
  {
    mock.calls = [];
    const { client, storage, sessionKey } = await makeClient('pk_race_G');
    await waitFor(() => client.getAuthState().verified === true); // resume confirmed it
    const states = [];
    client.onAuthStateChange((s) => states.push(s.step + (s.step === 'authenticated' ? `:${s.verified}` : '')));
    states.length = 0;
    mock.calls = [];

    // Simulate another tab refreshing: same user/session, rotated access token.
    const rotated = freshSession('ROTATED_AT');
    await storage.set(sessionKey, rotated);
    dispatchStorageEvent(sessionKey, rotated); // set event carries the new value
    await new Promise((r) => setTimeout(r, 60));

    check('verified stayed true (no flap to false)', client.getAuthState().verified === true);
    check('  no authenticated:false emitted during rotation', !states.includes('authenticated:false'), JSON.stringify(states));
    check('  picked up the rotated token', client.getAuthState().session.token.accessToken === 'ROTATED_AT');
    const resumeCalls = mock.calls.filter((c) => c.url.includes('/auth/session/resume'));
    check('  no redundant /auth/session/resume fired', resumeCalls.length === 0, resumeCalls.length);
    client.destroy();
  }

  // ── H. legacy 8-hex session is NOT restored on upgrade (intentional logout) ─
  console.log('\n── H. legacy 8-hex session is not restored (clean re-login) ──');
  {
    mock.calls = [];
    const apiKey = 'pk_race_H';
    const storage = sdk.createMemoryAdapter();
    const legacyHash = await legacyApiKeyHashOf(apiKey);
    const newHash = await apiKeyHashOf(apiKey);
    check('hash widened (legacy 8 hex vs new 32 hex)', legacyHash.length === 8 && newHash.length === 32);

    // Seed a session ONLY under the pre-0.10 (8-hex) key — i.e. a user who was
    // logged in on an older SDK. The widened namespace must NOT pick it up: the
    // upgrade intentionally forces a one-time re-login (no migration).
    await storage.set(`pollar:${legacyHash}:session`, freshSession('LEGACY_AT'));

    const client = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test', logLevel: 'silent' });
    await client.ready();

    check(
      'legacy session is NOT restored (user must re-login)',
      client.getAuthState().step === 'idle',
      client.getAuthState().step,
    );
    check('  no session written under the new namespace yet', (await storage.get(`pollar:${newHash}:session`)) === null);
    client.destroy();
  }

  // ── I. cross-tab logout propagates even if this tab can't re-read storage ──
  console.log('\n── I. cross-tab logout propagates when storage degraded ──────');
  {
    mock.calls = [];
    const { client, storage, sessionKey } = await makeClient('pk_race_I');
    await waitFor(() => client.getAuthState().verified === true);

