  // ── EE. restoring a session whose access token is ALREADY expired refreshes
  //       inline before surfacing it — no dead token in the verified:false window (F5)
  console.log('\n── EE. expired-AT restore refreshes before surfacing (F5) ───');
  {
    mock.calls = [];
    mock.refreshStatus = 200; // refresh succeeds → NEW_AT
    const apiKey = 'pk_race_EE';
    const storage = sdk.createMemoryAdapter();
    const hash = await apiKeyHashOf(apiKey);
    await storage.set(
      `pollar:${hash}:session`,
      JSON.stringify({
        clientSessionId: 'cs',
        userId: 'u',
        status: 'CONSUMED',
        // expiresAt in the PAST → the stored access token is already dead.
        token: { accessToken: 'EXPIRED_AT', refreshToken: 'RT', expiresAt: Math.floor(Date.now() / 1000) - 100 },
        user: { ready: true },
        wallet: { type: 'internal', address: null },
      }),
    );
    const client = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test', logLevel: 'silent' });
    // Capture EVERY emission, not just the final state — a transient
    // `authenticated` carrying the dead `EXPIRED_AT` would leak before refresh.
    const authEmissions = [];
    client.onAuthStateChange((s) => {
      authEmissions.push({ step: s.step, verified: s.verified, accessToken: s.session?.token?.accessToken });
    });
    await client.ready();
    const st = client.getAuthState();
    check(
      'surfaced the REFRESHED token, not the expired one',
      st.step === 'authenticated' && st.session?.token?.accessToken === 'NEW_AT',
      JSON.stringify({ step: st.step, at: st.session?.token?.accessToken }),
    );
    check('  verified:true (refresh proved the session is alive)', st.verified === true, st.verified);
    check(
      '  no expired token was emitted during restore',
      authEmissions.every((s) => s.step !== 'authenticated' || (s.verified === true && s.accessToken === 'NEW_AT')),
      JSON.stringify(authEmissions),
    );
    check(
      '  skipped the redundant /auth/session/resume',
      mock.calls.filter((c) => c.url.includes('/auth/session/resume')).length === 0,
    );
    client.destroy();
  }

  // ── FF. a tx that RESOLVES after a logout can't repopulate/emit the old
  //       session's transaction state (F2 — _txStartGen guard)
  console.log('\n── FF. tx resolving after logout does not repopulate state (F2) ──');
  {
    mock.calls = [];
    mock.txSubmitDelayMs = 80; // keep the submit in flight while logout lands
    const apiKey = 'pk_race_FF';
    const storage = sdk.createMemoryAdapter();
    const hash = await apiKeyHashOf(apiKey);
    await storage.set(
      `pollar:${hash}:session`,
      JSON.stringify({
        clientSessionId: 'cs',
        userId: 'u',
        status: 'CONSUMED',
        token: { accessToken: 'AT', refreshToken: 'RT', expiresAt: Math.floor(Date.now() / 1000) + 600 },
        user: { ready: true },
        wallet: { type: 'internal', address: 'Gtest' },
      }),
    );
    const client = new sdk.PollarClient({ apiKey, storage, baseUrl: 'https://x.test', logLevel: 'silent' });
    await client.ready();
    const txStates = [];
    client.onTransactionStateChange((s) => txStates.push(s.step));
    const sp = client.submitTx('SIGNED_XDR'); // in-flight (~80ms)
    await waitFor(() => client.getTransactionState()?.step === 'submitting');
    await client.logout(); // bumps generation + resets _transactionState
    // Snapshot AFTER logout settled: any reset emission is already counted, so
    // the delayed submit resolution must add exactly zero further emissions —
    // regardless of which step it would have carried.
    const emissionsAfterLogout = txStates.length;
    await sp; // submit now resolves SUCCESS — must be dropped (stale generation)
    await new Promise((r) => setTimeout(r, 20));
    check(
      'tx store cleared to idle after logout (getTransactionState)',
      client.getTransactionState()?.step === 'idle',
      JSON.stringify(client.getTransactionState()),
    );
    check(
      '  subscribers were NOTIFIED of the idle reset on logout (not left on the old tx)',
      txStates.includes('idle') && !txStates.includes('success') && !txStates.includes('submitted'),
      JSON.stringify(txStates),
    );
    check(
      '  the delayed submit (stale generation) added no further emission',
      txStates.length === emissionsAfterLogout,
      JSON.stringify(txStates),
    );
    mock.txSubmitDelayMs = 0;
    client.destroy();
  }

  // ── GG. cancelLogin() must NOT flap an already-authenticated session to idle
